EOF_PLUGIN_UNINSTALL_HELPER
    chmod 755 "$helper"

    cat > "$controller" <<'EOF_PLUGIN_UNINSTALL_CONTROLLER'
module("luci.controller.nradio_adv.plugin_uninstall", package.seeall)

local TASK_DIR = "/var/run/nradio-plugin-uninstall/tasks"
local HELPER = "/usr/libexec/nradio-plugin-uninstall"
local GLOBAL_LOCK_DIR = "/var/run/nradio-plugin-assistant.lock"
local TASK_TIMEOUT_SECONDS = 7200
local CODE_OK = 0
local CODE_RUNNING = 2
local CODE_FAILED = 13
local response_capture

function index()
    local function post_entry(path, handler, order)
        local node = entry(path, call(handler), nil, order)
        node.leaf = true
        node.post = true
    end

    local page
    page = entry({"nradioadv", "system", "plugin_uninstall"}, firstchild(), nil, 94)
    page.dependent = false
    post_entry({"nradioadv", "system", "plugin_uninstall", "start"}, "start_uninstall", 95)
    post_entry({"nradioadv", "system", "plugin_uninstall", "check"}, "check_uninstall", 96)
    post_entry({"nradioadv", "system", "plugin_uninstall", "openclash"}, "uninstall_openclash", 97)
    post_entry({"nradioadv", "system", "plugin_uninstall", "webssh"}, "uninstall_webssh", 98)
    post_entry({"nradioadv", "system", "plugin_uninstall", "adguardhome"}, "uninstall_adguardhome", 99)
    post_entry({"nradioadv", "system", "plugin_uninstall", "openlist"}, "uninstall_openlist", 100)
    post_entry({"nradioadv", "system", "plugin_uninstall", "zerotier"}, "uninstall_zerotier", 101)
    post_entry({"nradioadv", "system", "plugin_uninstall", "openvpn"}, "uninstall_openvpn", 102)
    post_entry({"nradioadv", "system", "plugin_uninstall", "easytier"}, "uninstall_easytier", 103)
    post_entry({"nradioadv", "system", "plugin_uninstall", "fanctrl"}, "uninstall_fanctrl", 104)
    post_entry({"nradioadv", "system", "plugin_uninstall", "qiyou"}, "uninstall_qiyou", 105)
    post_entry({"nradioadv", "system", "plugin_uninstall", "leigod"}, "uninstall_leigod", 106)
    post_entry({"nradioadv", "system", "plugin_uninstall", "mosdns"}, "uninstall_mosdns", 107)
    post_entry({"nradioadv", "system", "plugin_uninstall", "ddnsgo"}, "uninstall_ddnsgo", 108)
    post_entry({"nradioadv", "system", "plugin_uninstall", "mt5700"}, "uninstall_mt5700", 109)
    post_entry({"nradioadv", "system", "plugin_uninstall", "docker"}, "uninstall_docker", 110)
end

local function json_response(code, msg, detail)
    local http = require "luci.http"
    local jsonc = require "luci.jsonc"
    local result = { code = code, msg = msg or "" }

    if detail and #detail > 0 then
        result.errro_detail = detail
        result.error_detail = detail
    end

    if response_capture then
        response_capture.result = result
        return
    end

    http.prepare_content("application/json")
    http.write(jsonc.stringify({ result = result }))
end

local function shell_quote(value)
    value = tostring(value or "")
    return "'" .. value:gsub("'", "'\\''") .. "'"
end

local function read_file(path, limit)
    local fp = io.open(path, "r")
    local data

    if not fp then
        return ""
    end

    data = fp:read(limit or 4096) or ""
    fp:close()
    return data
end

local function trim(value)
    value = tostring(value or "")
    value = value:gsub("^%s+", ""):gsub("%s+$", "")
    return value
end

local function plugin_from_name(name)
    name = trim(name)

    if name == "luci-app-openclash" or name == "openclash" then
        return "openclash"
    elseif name == "Open-Box" or name == "openbox" or name == "luci-app-nradio-openbox" then
        return "openbox"
    elseif name == "Web SSH" or name == "webssh" or name == "ttyd" then
        return "webssh"
    elseif name == "luci-app-adguardhome" or name == "adguardhome" then
        return "adguardhome"
    elseif name == "OpenVPN" or name == "openvpn" or name == "luci-app-openvpn" then
        return "openvpn"
    elseif name == "OpenList" or name == "openlist" or name == "luci-app-openlist" then
        return "openlist"
    elseif name == "ZeroTier" or name == "zerotier" then
        return "zerotier"
    elseif name == "EasyTier" or name == "easytier" or name == "luci-app-easytier" then
        return "easytier"
    elseif name == "FanControl Plus" or name == "fanctrl-plus" or name == "FanControl" or name == "fanctrl" then
        return "fanctrl"
    elseif name == "奇游联机宝" or name == "QiYou" or name == "qiyou" or name == "nradio-qiyou" then
        return "qiyou"
    elseif name == "雷神加速器" or name == "Leigod" or name == "LeigodAcc" or name == "leigod" or name == "nradio-leigod" then
        return "leigod"
    elseif name == "MosDNS" or name == "mosdns" then
        return "mosdns"
    elseif name == "DDNS-GO" or name == "DDNS-Go" or name == "ddns-go" or name == "luci-app-ddns-go" or name == "luci-i18n-ddns-go-zh-cn" then
        return "ddnsgo"
    elseif name == "MT5700 WebUI" or name == "at-webserver" or name == "luci-app-at-webserver" or name == "luci-i18n-at-webserver-zh-cn" then
        return "mt5700"
    elseif name == "Docker" or name == "docker" or name == "dockerd" or name == "nradio-docker" then
        return "docker"
    end

    return nil
end

local function task_paths(plugin)
    return TASK_DIR .. "/" .. plugin .. ".status",
        TASK_DIR .. "/" .. plugin .. ".rc",
        TASK_DIR .. "/" .. plugin .. ".log",
        TASK_DIR .. "/" .. plugin .. ".pid",
        TASK_DIR .. "/" .. plugin .. ".started"
end

local function task_lock_path(plugin)
    return TASK_DIR .. "/" .. plugin .. ".lock"
end

local function os_ok(rc)
    return rc == true or rc == 0
end

local function valid_pid(value)
    value = trim(value)
    if value:match("^%d+$") and tonumber(value) and tonumber(value) > 1 then
        return value
    end
    return nil
end

local function process_alive(pid)
    pid = valid_pid(pid)
    if not pid then
        return false
    end
    return os_ok(os.execute("/bin/kill -0 " .. pid .. " >/dev/null 2>&1"))
end

local function uninstall_process_alive(pid)
    local cmdline

    pid = valid_pid(pid)
    if not pid or not process_alive(pid) then
        return false
    end

    cmdline = read_file("/proc/" .. pid .. "/cmdline", 4096):gsub("%z", " ")
    if cmdline == "" then
        return true
    end
    return cmdline:find(HELPER, 1, true) ~= nil
end

local function global_task_pid()
    local pid = valid_pid(read_file(GLOBAL_LOCK_DIR .. "/pid", 64))
    local cmdline

    if not pid or not process_alive(pid) then
        return nil
    end

    cmdline = read_file("/proc/" .. pid .. "/cmdline", 4096):gsub("%z", " ")
    if cmdline == "" then
        return pid
    end
    if cmdline:find(HELPER, 1, true) or
       cmdline:find("ssh-nradio-plugin-installer", 1, true) or
       cmdline:find("nradio-plugin-assistant", 1, true) then
        return pid
    end
    return nil
end

local function mark_stale_task_failed(status_file, rc_file, log_file, pid_file, started_file, lock_dir, reason)
    os.execute("/bin/echo 255 > " .. shell_quote(rc_file))
    os.execute("/bin/echo fail > " .. shell_quote(status_file))
    reason = reason or "卸载后台进程已异常退出或消失，可重新发起卸载。"
    os.execute("/bin/echo " .. shell_quote(reason) .. " >> " .. shell_quote(log_file))
    os.execute("/bin/rm -f " .. shell_quote(pid_file) .. " " .. shell_quote(started_file) .. " >/dev/null 2>&1")
    os.execute("/bin/rmdir " .. shell_quote(lock_dir) .. " >/dev/null 2>&1")
end

local function reconcile_task(status_file, rc_file, log_file, pid_file, started_file, lock_dir)
    local status = trim(read_file(status_file, 64))
    local pid, started_at, age

    if status ~= "running" then
        return status, false
    end

    pid = valid_pid(read_file(pid_file, 64))
    if pid and uninstall_process_alive(pid) then
        started_at = tonumber(trim(read_file(started_file, 64)) or "")
        if started_at then
            age = os.time() - started_at
            if age > TASK_TIMEOUT_SECONDS then
                os.execute("/bin/kill -TERM " .. pid .. " >/dev/null 2>&1")
                os.execute("/bin/sleep 1 >/dev/null 2>&1")
                if uninstall_process_alive(pid) then
                    os.execute("/bin/kill -KILL " .. pid .. " >/dev/null 2>&1")
                end
                mark_stale_task_failed(status_file, rc_file, log_file, pid_file, started_file, lock_dir, "卸载任务运行超过 2 小时，已终止并允许重新发起。")
                return "fail", false
            end
        end
        return status, true
    end

    if pid and process_alive(pid) then
        mark_stale_task_failed(status_file, rc_file, log_file, pid_file, started_file, lock_dir, "卸载任务 PID 已被其他进程复用，旧状态已失效，可重新发起卸载。")
        return "fail", false
    end

    status = trim(read_file(status_file, 64))
    if status ~= "running" then
        return status, false
    end

    started_at = tonumber(trim(read_file(started_file, 64)) or "")
    if not pid and started_at then
        age = os.time() - started_at
        if age >= 0 and age <= 5 then
            return status, true
        end
    end

    mark_stale_task_failed(status_file, rc_file, log_file, pid_file, started_file, lock_dir)
    return "fail", false
end

local function start_plugin_locked(plugin)
    local status_file, rc_file, log_file, pid_file, started_file = task_paths(plugin)
    local lock_dir = task_lock_path(plugin)
    local helper_test = io.open(HELPER, "r")
    local status, running, active_global_pid, launch_ok, launched_pid

    if not helper_test then
        json_response(CODE_FAILED, "卸载失败", "缺少卸载助手：" .. HELPER)
        return
    end
    helper_test:close()

    os.execute("/bin/mkdir -p " .. shell_quote(TASK_DIR) .. " >/dev/null 2>&1")
    status, running = reconcile_task(status_file, rc_file, log_file, pid_file, started_file, lock_dir)
    if running then
        json_response(CODE_RUNNING, "正在卸载")
        return
    end

    active_global_pid = global_task_pid()
    if active_global_pid then
        json_response(CODE_FAILED, "已有其他安装或卸载任务正在运行", "全局任务 pid：" .. active_global_pid .. "；请等待该任务结束后重试。")
        return
    end

    if not os_ok(os.execute("/bin/mkdir " .. shell_quote(lock_dir) .. " >/dev/null 2>&1")) then
        json_response(CODE_RUNNING, "卸载任务正在运行或初始化，请稍后重试")
        return
    end

    status, running = reconcile_task(status_file, rc_file, log_file, pid_file, started_file, lock_dir)
    if running then
        os.execute("/bin/rmdir " .. shell_quote(lock_dir) .. " >/dev/null 2>&1")
        json_response(CODE_RUNNING, "正在卸载")
        return
    end

    os.execute("/bin/rm -f " .. shell_quote(status_file) .. " " .. shell_quote(rc_file) .. " " .. shell_quote(log_file) .. " " .. shell_quote(pid_file) .. " " .. shell_quote(started_file) .. " >/dev/null 2>&1")
    if not os_ok(os.execute("/bin/echo running > " .. shell_quote(status_file))) then
        os.execute("/bin/rmdir " .. shell_quote(lock_dir) .. " >/dev/null 2>&1")
        json_response(CODE_FAILED, "卸载失败", "无法创建卸载状态文件")
        return
    end
    if not os_ok(os.execute("/bin/echo " .. tostring(os.time()) .. " > " .. shell_quote(started_file))) then
        os.execute("/bin/rm -f " .. shell_quote(status_file) .. " >/dev/null 2>&1")
        os.execute("/bin/rmdir " .. shell_quote(lock_dir) .. " >/dev/null 2>&1")
        json_response(CODE_FAILED, "卸载失败", "无法记录卸载任务开始时间")
        return
    end

    local cmd =
        "NRADIO_ASYNC_UNINSTALL=1 UNINSTALL_LOG_FILE=" .. shell_quote(log_file) .. " " ..
        shell_quote(HELPER) .. " " .. shell_quote(plugin) .. " > " .. shell_quote(log_file) .. " 2>&1 & " ..
        "bgpid=$!; /bin/echo $bgpid > " .. shell_quote(pid_file)

    launch_ok = os_ok(os.execute(cmd))
    launched_pid = valid_pid(read_file(pid_file, 64))
    if not launch_ok or not launched_pid then
        if launched_pid and uninstall_process_alive(launched_pid) then
            os.execute("/bin/kill -TERM " .. launched_pid .. " >/dev/null 2>&1")
        end
        os.execute("/bin/echo 126 > " .. shell_quote(rc_file))
        os.execute("/bin/echo fail > " .. shell_quote(status_file))
        os.execute("/bin/echo '无法启动卸载后台进程。' > " .. shell_quote(log_file))
        os.execute("/bin/rm -f " .. shell_quote(pid_file) .. " " .. shell_quote(started_file) .. " >/dev/null 2>&1")
        os.execute("/bin/rmdir " .. shell_quote(lock_dir) .. " >/dev/null 2>&1")
        json_response(CODE_FAILED, "卸载失败", "无法启动卸载后台进程")
        return
    end
    json_response(CODE_RUNNING, "正在卸载")
end

local function with_task_request_lock(plugin, callback)
    local guard = TASK_DIR .. "/" .. plugin .. ".request-lock"
    os.execute("/bin/mkdir -p " .. shell_quote(TASK_DIR) .. " >/dev/null 2>&1")
    if not os_ok(os.execute("/bin/mkdir " .. shell_quote(guard) .. " >/dev/null 2>&1")) then
        json_response(CODE_RUNNING, "卸载请求正在处理；持续占用时请核对请求锁")
        return
    end
    -- LuCI HTTP output yields; emit it after leaving Lua 5.1 pcall.
    local pending = {}
    response_capture = pending
    local ok, err = pcall(callback)
    response_capture = nil
    os.execute("/bin/rmdir " .. shell_quote(guard) .. " >/dev/null 2>&1")
    if not ok then
        json_response(CODE_FAILED, "卸载请求异常", tostring(err))
    elseif pending.result then
        json_response(pending.result.code, pending.result.msg, pending.result.error_detail)
    end
end

local function start_plugin(plugin)
    with_task_request_lock(plugin, function() start_plugin_locked(plugin) end)
end

local function start_by_name(name)
    local plugin = plugin_from_name(name)

    if not plugin then
        json_response(CODE_FAILED, "卸载失败", "未知插件：" .. trim(name))
        return
    end

    start_plugin(plugin)
end

function start_uninstall()
    local http = require "luci.http"
    start_by_name(http.formvalue("name") or http.formvalue("plugin") or "")
end

local function check_uninstall_locked()
    local http = require "luci.http"
    local plugin = plugin_from_name(http.formvalue("name") or http.formvalue("plugin") or "")
    local status_file, rc_file, log_file, pid_file, started_file
    local lock_dir, status, running, rc, detail

    if not plugin then
        json_response(CODE_FAILED, "卸载失败", "未知插件")
        return
    end

    status_file, rc_file, log_file, pid_file, started_file = task_paths(plugin)
    lock_dir = task_lock_path(plugin)
    status, running = reconcile_task(status_file, rc_file, log_file, pid_file, started_file, lock_dir)

    if status == "ok" then
        os.execute("/bin/rm -f " .. shell_quote(status_file) .. " " .. shell_quote(rc_file) .. " " .. shell_quote(log_file) .. " " .. shell_quote(pid_file) .. " " .. shell_quote(started_file) .. " >/dev/null 2>&1")
        os.execute("/bin/rmdir " .. shell_quote(lock_dir) .. " >/dev/null 2>&1")
        json_response(CODE_OK, "卸载完成")
    elseif status == "fail" then
        os.execute("/bin/rm -f " .. shell_quote(pid_file) .. " " .. shell_quote(started_file) .. " >/dev/null 2>&1")
        os.execute("/bin/rmdir " .. shell_quote(lock_dir) .. " >/dev/null 2>&1")
        rc = trim(read_file(rc_file, 64))
        detail = read_file(log_file, 4096)
        if rc ~= "" then
            detail = "退出码：" .. rc .. "\n" .. detail
        end
        json_response(CODE_FAILED, "卸载失败", detail)
    elseif running then
        json_response(CODE_RUNNING, "正在卸载")
    else
        json_response(CODE_FAILED, "卸载状态不可用", "未找到有效的卸载任务；可重新发起卸载。")
    end
end

function check_uninstall()
    local http = require "luci.http"
    local plugin = plugin_from_name(http.formvalue("name") or http.formvalue("plugin") or "")
    if not plugin then
        json_response(CODE_FAILED, "卸载失败", "未知插件")
        return
    end
    with_task_request_lock(plugin, check_uninstall_locked)
end

function uninstall_openclash()
    start_plugin("openclash")
end

function uninstall_webssh()
    start_plugin("webssh")
end

function uninstall_adguardhome()
    start_plugin("adguardhome")
end

