    start_plugin("qiyou")
end

function uninstall_leigod()
    start_plugin("leigod")
end

function uninstall_mosdns()
    start_plugin("mosdns")
end

function uninstall_ddnsgo()
    start_plugin("ddnsgo")
end

function uninstall_mt5700()
    start_plugin("mt5700")
end

function uninstall_docker()
    start_plugin("docker")
end
