<script type="text/javascript">
//<![CDATA[
var NR_CONTROLLER = "<%=controller%>";
var NR_LIST_URL = "<%=url('nradioadv/system/appcenter/list')%>";
var NR_STATUS_URL = "<%=url('nradioadv/system/appcenter/sys_status')%>";
var NR_UPLOAD_URL = "<%=url('nradioadv/system/appcenter/upload')%>";
var NR_UNINSTALL_URL = NR_CONTROLLER + "nradioadv/system/plugin_uninstall/start";
var NR_TOKEN = "<%=require('luci.dispatcher').context.authtoken%>";
var NR_ICON_BASE = "/luci-static/nradio/images/icon/";
function nrEsc(v){return String(v == null ? "" : v).replace(/[&<>"']/g,function(c){return {"&":"&amp;","<":"&lt;",">":"&gt;","\"":"&quot;","'":"&#39;"}[c];});}
function nrJson(url, cb){var x=new XMLHttpRequest();x.open("GET",url,true);x.onreadystatechange=function(){if(x.readyState!==4)return;try{cb(JSON.parse(x.responseText||"{}"));}catch(e){cb({});}};x.send(null);}
function nrRouteUrl(route){if(!route)return "#";if(route.charAt(0)==="/")return route;return NR_CONTROLLER+route;}
function nrIconUrl(icon){return icon ? NR_ICON_BASE + encodeURIComponent(icon) : "";}
function nrAppName(app){return app.name || app.parent || app.pkg_name || "应用";}
function nrEnableFrameScroll(){
    var frame=document.getElementById("sub_frame");
    if(!frame)return;
    try{
        var d=frame.contentWindow.document;
        var nodes=[d.documentElement,d.body];
        for(var i=0;i<nodes.length;i++){
            if(!nodes[i])continue;
            nodes[i].style.setProperty("overflow-y","auto","important");
            nodes[i].style.setProperty("-webkit-overflow-scrolling","touch","important");
            nodes[i].style.setProperty("touch-action","pan-y","important");
            nodes[i].style.setProperty("overscroll-behavior-y","contain","important");
        }
        if(frame.src.indexOf('/nradioadv/system/webssh')!==-1)return;
        var lastY=0;
        var tracking=false;
        var startOptions={passive:true};
        var moveOptions={passive:false};
        if(d.__nrFrameTouchStart)d.removeEventListener("touchstart",d.__nrFrameTouchStart,startOptions);
        if(d.__nrFrameTouchMove)d.removeEventListener("touchmove",d.__nrFrameTouchMove,moveOptions);
        if(d.__nrFrameTouchEnd){d.removeEventListener("touchend",d.__nrFrameTouchEnd,startOptions);d.removeEventListener("touchcancel",d.__nrFrameTouchEnd,startOptions);}
        d.__nrFrameTouchStart=function(e){if(e.touches&&e.touches.length===1){tracking=true;lastY=e.touches[0].clientY;}};
        d.__nrFrameTouchMove=function(e){
            if(!tracking||!e.touches||e.touches.length!==1)return;
            var y=e.touches[0].clientY,delta=lastY-y,target=e.target;lastY=y;
            while(target&&target!==d.body&&target!==d.documentElement){
                var overflow=d.defaultView.getComputedStyle(target).overflowY;
                if(/auto|scroll/.test(overflow)&&target.scrollHeight>target.clientHeight&&
                   (delta<0?target.scrollTop>0:target.scrollTop+target.clientHeight<target.scrollHeight))break;
                target=target.parentElement;
            }
            if(!target||target===d.body||target===d.documentElement)target=d.scrollingElement||d.documentElement||d.body;
            if(Math.abs(delta)<1||!target||target.scrollHeight<=target.clientHeight)return;
            var before=target.scrollTop;target.scrollTop+=delta;
            if(target.scrollTop!==before)e.preventDefault();
        };
        d.__nrFrameTouchEnd=function(){tracking=false;};
        d.addEventListener("touchstart",d.__nrFrameTouchStart,startOptions);
        d.addEventListener("touchmove",d.__nrFrameTouchMove,moveOptions);
        d.addEventListener("touchend",d.__nrFrameTouchEnd,startOptions);
        d.addEventListener("touchcancel",d.__nrFrameTouchEnd,startOptions);
    }catch(e){}
}
function nrOpenFrame(name, route){var url=nrRouteUrl(route);var frame=document.getElementById("sub_frame");document.getElementById("nr-frame-title").textContent=name;document.getElementById("nr-frame-open").href=url;frame.onload=nrEnableFrameScroll;frame.src=url;document.getElementById("nr-frame-modal").className="nr-c2000pro-modal is-open";}
function nrCloseFrame(){document.getElementById("nr-frame-modal").className="nr-c2000pro-modal";document.getElementById("sub_frame").src="about:blank";}
var NR_UNINSTALL_BUSY = false;
function nrUninstall(name){
    if(NR_UNINSTALL_BUSY||!confirm("确认卸载 "+name+" 并移除应用商店入口吗？"))return;
    NR_UNINSTALL_BUSY=true;
    function finish(message){NR_UNINSTALL_BUSY=false;alert(message);nrReloadApps();}
    function request(check){
        var x=new XMLHttpRequest();
        x.open("POST",check?NR_UNINSTALL_URL.replace(/\/start$/,"/check"):NR_UNINSTALL_URL,true);
        x.timeout=30000;
        x.setRequestHeader("Content-Type","application/x-www-form-urlencoded");
        x.onreadystatechange=function(){
            if(x.readyState!==4)return;
            if(x.status<200||x.status>=300){finish("卸载接口失败 HTTP "+x.status);return;}
            var data;
            try{data=JSON.parse(x.responseText);}catch(e){finish("卸载接口返回格式异常");return;}
            var result=data.result||data,code=Number(result.code);
            if(code===2){window.setTimeout(function(){request(true);},2000);return;}
            finish(code===0?(result.msg||"卸载完成"):(result.error_detail||result.errro_detail||result.msg||"卸载失败"));
        };
        x.send("token="+encodeURIComponent(NR_TOKEN)+"&name="+encodeURIComponent(name));
    }
    request(false);
}
var NR_IPK_BUSY = false;
function nrIpkStatus(message, error){
    var node=document.getElementById("nr-ipk-status");
    node.textContent=message;
    node.className="nr-c2000pro-upload-status"+(error?" is-error":"");
}
function nrSyncIpkButton(){
    var input=document.getElementById("nr-ipk-file"),file=input.files&&input.files[0];
    document.getElementById("nr-ipk-submit").disabled=NR_IPK_BUSY||!file||!(/\.ipk$/i).test(file.name)||file.size===0||file.size>32*1024*1024;
}
function nrInstallIpk(event){
    if(event)event.preventDefault();
    if(NR_IPK_BUSY)return false;
    var input=document.getElementById("nr-ipk-file"),button=document.getElementById("nr-ipk-submit");
    var file=input.files&&input.files[0];
    if(!file||!(/\.ipk$/i).test(file.name)){nrIpkStatus("请选择 .ipk 安装包",true);return false;}
    if(file.size===0||file.size>32*1024*1024){nrIpkStatus("IPK 必须大于 0 且不超过 32 MiB",true);return false;}
    var body=new FormData();
    body.append("token",NR_TOKEN);
    body.append("image",file,file.name);
    var xhr=new XMLHttpRequest(),finished=false;
    NR_IPK_BUSY=true;button.disabled=true;input.disabled=true;
    nrIpkStatus("正在上传 "+file.name+"…",false);
    function finish(message,error){
        if(finished)return;
        finished=true;NR_IPK_BUSY=false;input.disabled=false;
        nrIpkStatus(message,error);
        if(!error){input.value="";nrReloadApps();}
        nrSyncIpkButton();
    }
    xhr.open("POST",NR_UPLOAD_URL,true);
    xhr.timeout=300000;
    xhr.upload.onprogress=function(e){if(e.lengthComputable)nrIpkStatus("正在上传 "+Math.floor(e.loaded*100/e.total)+"%",false);};
    xhr.upload.onload=function(){if(!finished)nrIpkStatus("上传完成，正在安装…",false);};
    xhr.onload=function(){
        if(xhr.status<200||xhr.status>=300){finish("安装请求失败：HTTP "+xhr.status,true);return;}
        var data;
        try{data=JSON.parse(xhr.responseText||"{}");}catch(e){finish("安装接口返回格式异常，请确认登录状态",true);return;}
        var result=data.result||data;
        var success=Number(result.code)===0;
        finish((result.msg||(success?"IPK 安装完成":"IPK 安装失败"))+(success?"":(result.detail?"\n"+result.detail:"")),!success);
    };
    xhr.onerror=function(){finish("上传或安装连接中断",true);};
    xhr.ontimeout=function(){finish("安装等待超时，请刷新应用列表确认结果",true);};
    xhr.send(body);
    return false;
}
document.getElementById("nr-ipk-file").addEventListener("change",function(){
    nrSyncIpkButton();
    var file=this.files&&this.files[0];
    nrIpkStatus(file&&document.getElementById("nr-ipk-submit").disabled?"仅支持 0–32 MiB 的 .ipk 文件":"",!!file&&document.getElementById("nr-ipk-submit").disabled);
});
var NR_APPS = [];
function nrBindAppButtons(){var opens=document.querySelectorAll("[data-nr-open]");var uninstalls=document.querySelectorAll("[data-nr-uninstall]");for(var i=0;i<opens.length;i++){opens[i].onclick=function(){var app=NR_APPS[Number(this.getAttribute("data-nr-open"))]||{};nrOpenFrame(nrAppName(app),app.luci_module_route||"");};}for(var j=0;j<uninstalls.length;j++){uninstalls[j].onclick=function(){var app=NR_APPS[Number(this.getAttribute("data-nr-uninstall"))]||{};nrUninstall(nrAppName(app));};}}
function nrRenderApps(resp){var data=resp.result||resp||{};var apps=data.applist||data.apps||[];var grid=document.getElementById("nr-app-grid");var empty=document.getElementById("nr-app-empty");var html=[];NR_APPS=apps;document.getElementById("nr-app-count").textContent=String(apps.length);for(var i=0;i<apps.length;i++){var app=apps[i];var name=nrAppName(app);var route=app.luci_module_route||"";var icon=nrIconUrl(app.icon||"");html.push('<section class="nr-c2000pro-card"><div class="nr-c2000pro-cardtop">'+(icon?'<img class="nr-c2000pro-icon" src="'+nrEsc(icon)+'" onerror="this.style.visibility=&quot;hidden&quot;">':'<div class="nr-c2000pro-icon"></div>')+'<div><div class="nr-c2000pro-name">'+nrEsc(name)+'</div><div class="nr-c2000pro-version">'+nrEsc(app.version||app.pkg_name||"-")+'</div></div></div><div class="nr-c2000pro-route">'+nrEsc(route||"无 LuCI 路由")+'</div><div class="nr-c2000pro-actions">'+(route?'<button class="nr-c2000pro-btn nr-c2000pro-btn-primary" type="button" data-nr-open="'+i+'">打开</button>':'')+'<button class="nr-c2000pro-btn" type="button" data-nr-uninstall="'+i+'">卸载</button></div></section>');}grid.innerHTML=html.join("");empty.style.display=apps.length?"none":"block";nrBindAppButtons();}
function nrReloadApps(){nrJson(NR_LIST_URL,nrRenderApps);nrJson(NR_STATUS_URL,nrRenderStatus);}
function nrFmtMem(kib){if(!kib)return "-";var mib=kib/1024;if(mib>=1024)return (mib/1024).toFixed(1)+" GB";return mib.toFixed(0)+" MB";}
function nrRenderStatus(resp){var d=(resp.result||resp||{});document.getElementById("nr-model").textContent=d.model_name||"-";document.getElementById("nr-cpu").textContent=(d.cpu_percent==null?"-":d.cpu_percent+"%");document.getElementById("nr-load").textContent=d.load1||"-";document.getElementById("nr-temp").textContent=(d.cpu_temp==null?"-":d.cpu_temp+" C");var mem=nrFmtMem(d.mem_used)+" / "+nrFmtMem(d.mem_total);document.getElementById("nr-mem").textContent=(d.mem_percent==null?"-":d.mem_percent+"%");document.getElementById("nr-mem-detail").textContent=mem;}
nrReloadApps();window.setInterval(function(){nrJson(NR_STATUS_URL,nrRenderStatus);},2000);
