verify_c2000pro_compat_appcenter() {
    verify_file_exists "$CFG" "C2000Pro 应用商店配置"
    verify_file_exists "$APPCENTER_CONTROLLER" "C2000Pro 应用商店控制器"
    verify_file_exists "$TPL" "C2000Pro 应用商店模板"
    grep -q 'NRadio C2000Pro compatibility appcenter layer' "$APPCENTER_CONTROLLER" 2>/dev/null || die "C2000Pro appcenter controller verify failed: missing marker"
    grep -q 'NRadio C2000Pro compatibility appcenter layer' "$TPL" 2>/dev/null || die "C2000Pro appcenter template verify failed: missing marker"
    grep -q 'entry({"nradioadv", "system", "appcenter", "memory"}, call("action_memory")' "$APPCENTER_CONTROLLER" 2>/dev/null || die "C2000Pro appcenter controller verify failed: missing memory route"
    grep -q 'entry({"nradioadv", "system", "appcenter", "sys_status"}, call("action_sys_status")' "$APPCENTER_CONTROLLER" 2>/dev/null || die "C2000Pro appcenter controller verify failed: missing sys_status route"
    grep -q 'call("action_upload")' "$APPCENTER_CONTROLLER" 2>/dev/null || die "C2000Pro appcenter controller verify failed: missing IPK upload route"
    grep -q 'function action_list()' "$APPCENTER_CONTROLLER" 2>/dev/null || die "C2000Pro appcenter controller verify failed: missing list action"
    grep -q 'function action_upload()' "$APPCENTER_CONTROLLER" 2>/dev/null || die "C2000Pro appcenter controller verify failed: missing IPK installer"
    grep -q 'installed_package_version("luci-app-openclash")' "$APPCENTER_CONTROLLER" 2>/dev/null || die "C2000Pro appcenter controller verify failed: missing OpenClash runtime version sync"
    grep -q 'route = "admin/services/openclash"' "$APPCENTER_CONTROLLER" 2>/dev/null || die "C2000Pro appcenter controller verify failed: missing OpenClash route fallback"
    grep -q 'NR_LIST_URL' "$TPL" 2>/dev/null || die "C2000Pro appcenter template verify failed: missing list xhr"
    grep -q 'id="nr-ipk-form"' "$TPL" 2>/dev/null || die "C2000Pro appcenter template verify failed: missing IPK form"
    grep -Fq '<svg class="nr-c2000pro-store-logo"' "$TPL" 2>/dev/null || die "C2000Pro appcenter template verify failed: missing store logo"
    grep -q 'sub_frame' "$TPL" 2>/dev/null || die "C2000Pro appcenter template verify failed: missing iframe"
    grep -q 'scrolling="auto"' "$TPL" 2>/dev/null || die "C2000Pro appcenter template verify failed: missing mobile iframe scrolling"
    grep -q 'touch-action:pan-x pan-y' "$TPL" 2>/dev/null || die "C2000Pro appcenter template verify failed: missing mobile touch scrolling"
    grep -q '__nrFrameTouchMove' "$TPL" 2>/dev/null || die "C2000Pro appcenter template verify failed: missing Android WebView touch fallback"
    grep -q 'height:100dvh' "$TPL" 2>/dev/null || die "C2000Pro appcenter template verify failed: missing dynamic viewport height"
    grep -q 'plugin_uninstall/start' "$TPL" 2>/dev/null || die "C2000Pro appcenter template verify failed: missing uninstall endpoint"
}

ensure_c2000pro_compat_appcenter() {
    [ "$(detect_current_nradio_model_quiet 2>/dev/null || true)" = 'NRadio_C2000Pro' ] || return 1

    mkdir -p "$WORKDIR" >/dev/null 2>&1 || true
    ensure_c2000pro_appcenter_config
    write_c2000pro_compat_appcenter_controller
    write_c2000pro_compat_appcenter_template
    verify_c2000pro_compat_appcenter
}

remove_c2000pro_compat_appcenter() {
    removed_any='0'

    if is_c2000pro_compat_appcenter_file "$APPCENTER_CONTROLLER"; then
        backup_file "$APPCENTER_CONTROLLER"
        rm -f "$APPCENTER_CONTROLLER" 2>/dev/null || die "删除 C2000Pro 兼容应用商店控制器失败"
        removed_any='1'
    fi

    if is_c2000pro_compat_appcenter_file "$TPL"; then
        backup_file "$TPL"
        rm -f "$TPL" 2>/dev/null || die "删除 C2000Pro 兼容应用商店模板失败"
        removed_any='1'
    fi

    [ "$removed_any" = '1' ] || log "提示: 未发现脚本生成的 C2000Pro 兼容商店层文件"
}

ak798_appcenter_file_map() {
    printf '%s|%s|%s\n' \
        appcenter "$CFG" 644 \
        appcenter.lua "$APPCENTER_CONTROLLER" 644 \
        appcenter.htm "$TPL" 644 \
        nradio-plugin-uninstall "$PLUGIN_UNINSTALL_HELPER" 755 \
        plugin_uninstall.lua "$PLUGIN_UNINSTALL_CONTROLLER" 644
}

write_ak798_compat_appcenter_assets() (
    stage="$1"
    source_config="$CFG"
    mkdir -p "$stage" || exit 1
    TPL="$stage/appcenter.htm"
    APPCENTER_CONTROLLER="$stage/appcenter.lua"
    PLUGIN_UNINSTALL_HELPER="$stage/nradio-plugin-uninstall"
    PLUGIN_UNINSTALL_CONTROLLER="$stage/plugin_uninstall.lua"
    write_c2000pro_compat_appcenter_controller || exit 1
    write_c2000pro_compat_appcenter_template || exit 1
    write_plugin_uninstall_assets || exit 1
    if [ -f "$source_config" ]; then
        cp "$source_config" "$stage/appcenter" || exit 1
    else
        : > "$stage/appcenter" || exit 1
    fi

    lua - "$stage" <<'EOF_AK798_APPCENTER_ADAPT'
local stage = assert(arg[1])
local marker = "NRadio AK68-798 compatibility appcenter layer"
local function read(name)
    local f = assert(io.open(stage .. "/" .. name, "rb"))
    local text = f:read("*a")
    f:close()
    return text
end
local function write(name, text)
    local f = assert(io.open(stage .. "/" .. name, "wb"))
    assert(f:write(text))
    assert(f:close())
end
local function replace_once(text, old, new)
    local first, last = text:find(old, 1, true)
    assert(first, "AK68-798 adapter missing anchor: " .. old:sub(1, 60))
    assert(not text:find(old, last + 1, true), "AK68-798 adapter ambiguous anchor")
    return text:sub(1, first - 1) .. new .. text:sub(last + 1)
end
local function replace_function(text, first_name, next_name, body)
    local first = assert(text:find("function " .. first_name .. "()", 1, true))
    local last = assert(text:find("function " .. next_name .. "()", first + 1, true))
    return text:sub(1, first - 1) .. body .. "\n\n" .. text:sub(last)
end
local config = read("appcenter")
if not config:find(marker, 1, true) then
    config = config .. "\n# " .. marker .. "\n"
end
write("appcenter", config)

local controller = read("appcenter.lua"):gsub("NRadio C2000Pro compatibility appcenter layer", marker)
controller = replace_function(controller, "index", "action_list", [[function index()
    local page = entry({"nradioadv", "system", "appcenter"}, template("nradio_appcenter/appcenter"), _("应用商店"), 30, true)
    page.dependent = false
    page.icon = "nradio-appcenter"
    page.show = true
    page.sysauth = "root"
    page.sysauth_authenticator = "htmlauth"
    entry({"nradioadv", "system", "appcenter", "list"}, call("action_list"), nil, nil, true).leaf = true
    entry({"nradioadv", "system", "appcenter", "memory"}, call("action_memory"), nil, nil, true).leaf = true
    entry({"nradioadv", "system", "appcenter", "sys_status"}, call("action_sys_status"), nil, nil, true).leaf = true
    local upload = entry({"nradioadv", "system", "appcenter", "upload"}, call("action_upload"), nil, nil, true)
    upload.leaf = true
    -- The upload action checks POST security after installing its file handler.
end]])
controller = replace_function(controller, "action_memory", "action_sys_status", [[function action_memory()
    local stat = require("nixio.fs").statvfs("/overlay")
    if not stat then
        json_response({result = {storage_available = false}})
        return
    end
    local block = tonumber(stat.frsize or stat.bsize) or 0
    local total = math.floor((tonumber(stat.blocks) or 0) * block / 1024)
    local available = math.floor((tonumber(stat.bavail or stat.bfree) or 0) * block / 1024)
    json_response({result = {
        storage_available = block > 0 and total > 0,
        total_memory = total,
        used_memory = math.max(0, total - available),
        available_memory = available,
        reserve_memory = 256,
        storage_limited = true
    }})
end]])
write("appcenter.lua", controller)

local uninstall = read("plugin_uninstall.lua")
uninstall = replace_once(uninstall, "entry(path, call(handler), nil, order)", "entry(path, call(handler), nil, order, true)")
uninstall = replace_once(uninstall,
    'page = entry({"nradioadv", "system", "plugin_uninstall"}, firstchild(), nil, 94)',
    'page = entry({"nradioadv", "system", "plugin_uninstall"}, firstchild(), nil, 94, true)\n    page.sysauth = "root"\n    page.sysauth_authenticator = "htmlauth"')
write("plugin_uninstall.lua", "-- " .. marker .. "\n" .. uninstall)
write("nradio-plugin-uninstall", (read("nradio-plugin-uninstall"):gsub("NRadio C2000Pro compatibility appcenter layer", marker)))

local view = read("appcenter.htm"):gsub("NRadio C2000Pro compatibility appcenter layer", marker)
view = replace_once(view, "C2000Pro 轻量商店，管理已登记插件，可上传本地 IPK 安装。",
    "AK68-798 轻量商店，管理已登记插件。16 MiB 闪存，安装插件前请核对体积与依赖。")
view = replace_once(view,
    '<div class="nr-c2000pro-kv"><span>安装方式</span><strong>本地 IPK</strong></div>',
    '<div class="nr-c2000pro-kv"><span>持久空间</span><strong id="nr-overlay">读取中</strong></div><p id="nr-storage-warning" style="font-size:12px;line-height:1.6;color:#92400e">/tmp 是内存空间，重启后丢失；上传本地 IPK 前请核对体积与依赖。</p>')
view = replace_once(view, 'nrReloadApps();window.setInterval(function(){nrJson(NR_STATUS_URL,nrRenderStatus);},2000);', [[var NR_MEMORY_URL = "<%=url('nradioadv/system/appcenter/memory')%>";
function nrFmtStorage(kib){kib=Number(kib);return kib<1024?kib.toFixed(0)+" KiB":(kib/1024).toFixed(2)+" MiB";}
function nrRenderStorage(resp){
    var d=resp.result||resp||{},el=document.getElementById("nr-overlay"),warning=document.getElementById("nr-storage-warning");
    if(d.storage_available!==true){el.textContent="无法读取 /overlay";return;}
    el.textContent="剩余 "+nrFmtStorage(d.available_memory)+" / "+nrFmtStorage(d.total_memory);
    warning.textContent=(Number(d.available_memory)<Number(d.reserve_memory)?"剩余空间低于 256 KiB，请先释放空间。":"16 MiB 小闪存：大型插件需要额外存储，安装前须核对体积与依赖。")+" /tmp 是内存，重启后丢失；这里支持上传本地 IPK。";
}
nrReloadApps();nrJson(NR_MEMORY_URL,nrRenderStorage);
window.setInterval(function(){nrJson(NR_STATUS_URL,nrRenderStatus);nrJson(NR_MEMORY_URL,nrRenderStorage);},5000);]])
write("appcenter.htm", view)
assert(loadfile(stage .. "/appcenter.lua"))
assert(loadfile(stage .. "/plugin_uninstall.lua"))
EOF_AK798_APPCENTER_ADAPT
)

ak798_appcenter_check_space() {
    local stage="$1" total_bytes=0 name target mode size available needed
    while IFS='|' read -r name target mode; do
        size="$(wc -c < "$stage/$name")" || return 1
        total_bytes=$((total_bytes + size))
    done < "$stage/files.map"
    available="$(get_mount_available_kib /overlay)" || {
        log "AK68-798: 无法读取 /overlay 可用空间，已停止安装"
        return 1
    }
    needed=$(((total_bytes + 1023) / 1024 + 256))
    log "AK68-798 商店文件约 $(((total_bytes + 1023) / 1024)) KiB；额外保留 256 KiB；当前可用 $available KiB"
    [ "$available" -ge "$needed" ] || {
        log "AK68-798: 空间不足，至少需要 $needed KiB 可用空间"
        return 1
    }
}

ak798_appcenter_rollback_files() {
    local stage="$1" name target mode
    while IFS='|' read -r name target mode; do
        rm -f "$target.ak798.$$" 2>/dev/null || true
        if [ -f "$stage/before/$name" ]; then
            cp -p "$stage/before/$name" "$target" || log "AK68-798: 恢复文件失败，请检查 $target"
        elif is_ak798_compat_appcenter_file "$target"; then
            rm -f "$target" || log "AK68-798: 清理未完成文件失败，请检查 $target"
        fi
    done < "$stage/files.map"
}

ak798_appcenter_apply_files() {
    local stage="$1" name target mode
    mkdir -p "$stage/before" || return 1
    while IFS='|' read -r name target mode; do
        if [ -f "$target" ]; then
            cp -p "$target" "$stage/before/$name" || return 1
        fi
    done < "$stage/files.map"
    while IFS='|' read -r name target mode; do
        if ! mkdir -p "$(dirname "$target")" ||
            ! cp "$stage/$name" "$target.ak798.$$" ||
            ! chmod "$mode" "$target.ak798.$$" ||
            ! mv -f "$target.ak798.$$" "$target"; then
            ak798_appcenter_rollback_files "$stage"
            return 1
        fi
    done < "$stage/files.map"
}

refresh_ak798_appcenter() {
    rm -f /tmp/luci-indexcache 2>/dev/null || true
    rm -f /tmp/luci-modulecache/* 2>/dev/null || true
    /etc/init.d/uhttpd reload >/dev/null 2>&1 || true
}

ensure_ak798_compat_appcenter() {
    local stage="$WORKDIR/ak798-appcenter" name target mode tool
    is_current_model_ak798 || return 1
    for tool in lua uci ubus curl; do
        command -v "$tool" >/dev/null 2>&1 || die "AK68-798 缺少运行依赖: $tool"
    done
    lua -e 'require("luci.model.uci"); require("luci.jsonc"); require("nixio.fs"); require("luci.template")' || die "AK68-798 Lua 运行库不完整"
    mkdir -p "$stage" || die "创建 AK68-798 内存工作目录失败"
    ak798_appcenter_file_map > "$stage/files.map" || die "生成 AK68-798 文件清单失败"
    while IFS='|' read -r name target mode; do
        [ ! -L "$target" ] || die "AK68-798 目标为符号链接，请先核对: $target"
        if [ -e "$target" ] && [ "$name" != appcenter ]; then
            is_ak798_compat_appcenter_file "$target" || die "AK68-798 已存在其他来源文件，请先核对: $target"
        fi
    done < "$stage/files.map"
    log_stage 1 4 "在内存目录生成 AK68-798 轻量应用商店"
    write_ak798_compat_appcenter_assets "$stage" || die "生成 AK68-798 应用商店失败"
    log_stage 2 4 "核对商店文件体积与持久空间"
    ak798_appcenter_check_space "$stage" || die "AK68-798 商店容量检查未通过"
    log_stage 3 4 "安装配置、页面与卸载接口"
    ak798_appcenter_apply_files "$stage" || die "AK68-798 商店文件安装失败"
    log_stage 4 4 "刷新 LuCI 并核对商店路由"
    refresh_ak798_appcenter
    verify_luci_route "nradioadv/system/appcenter" "AK68-798 轻量应用商店"
    log "AK68-798 轻量应用商店已创建/更新，入口: /cgi-bin/luci/nradioadv/system/appcenter"
}

remove_ak798_compat_appcenter() {
    local map="$WORKDIR/ak798-remove.map" name target mode
    is_current_model_ak798 || return 1
    mkdir -p "$WORKDIR" || die "创建 AK68-798 内存工作目录失败"
    ak798_appcenter_file_map > "$map" || die "生成 AK68-798 文件清单失败"
    while IFS='|' read -r name target mode; do
        [ "$name" != appcenter ] || continue
        if is_ak798_compat_appcenter_file "$target"; then
            rm -f "$target" || die "移除 AK68-798 商店文件失败: $target"
        fi
    done < "$map"
    refresh_ak798_appcenter
    log "AK68-798 轻量商店已移除；/etc/config/appcenter 插件记录及插件本体保留"
}

set_appcenter_entry() {
    plugin_name="$1"
    pkg_name="$2"
    version="$3"
    size="$4"
    controller="$5"
    route="$6"
    icon_name="${7:-}"

    if is_c2000pro_appcenter_environment; then
        ensure_c2000pro_appcenter_config || true
    fi

    cleanup_appcenter_route_entries "$route"

    pkg_sec="$(find_uci_section package "$plugin_name")"
    if [ -z "$pkg_sec" ]; then
        pkg_sec="$(uci add appcenter package)"
    fi

    list_sec="$(find_uci_section package_list "$plugin_name")"
    if [ -z "$list_sec" ]; then
        list_sec="$(uci add appcenter package_list)"
    fi

    uci set "appcenter.$pkg_sec.name=$plugin_name"
    uci set "appcenter.$pkg_sec.version=$version"
    uci set "appcenter.$pkg_sec.size=$size"
    uci set "appcenter.$pkg_sec.status=1"
    uci set "appcenter.$pkg_sec.has_luci=1"
    uci set "appcenter.$pkg_sec.open=0"
    if [ -n "$icon_name" ]; then
        uci set "appcenter.$pkg_sec.icon=$icon_name"
    else
        uci -q delete "appcenter.$pkg_sec.icon" >/dev/null 2>&1 || true
    fi

    uci set "appcenter.$list_sec.name=$plugin_name"
    uci set "appcenter.$list_sec.pkg_name=$pkg_name"
    uci set "appcenter.$list_sec.parent=$plugin_name"
    uci set "appcenter.$list_sec.size=$size"
    uci set "appcenter.$list_sec.luci_module_file=$controller"
    uci set "appcenter.$list_sec.luci_module_route=$route"
    uci set "appcenter.$list_sec.version=$version"
    uci set "appcenter.$list_sec.has_luci=1"
    uci set "appcenter.$list_sec.type=1"
    if [ -n "$icon_name" ]; then
        uci set "appcenter.$list_sec.icon=$icon_name"
    else
        uci -q delete "appcenter.$list_sec.icon" >/dev/null 2>&1 || true
    fi
}

patch_mt5700_appcenter_list_controller() {
    mt5700_app_list_lua="$WORKDIR/mt5700-appcenter-list.lua"
    mt5700_app_list_tmp="$WORKDIR/mt5700-appcenter-list.tmp"
    mt5700_app_return_tmp="$WORKDIR/mt5700-appcenter-return.tmp"

    cat > "$mt5700_app_list_lua" <<'EOF_MT5700_APPCENTER_LIST_LUA'

-- MT5700 appcenter installed-app preservation v4
local function mt5700_appcenter_preserve_installed_v1(parameter)
	if type(parameter) ~= "table" or type(parameter.applist) ~= "table" then
		return parameter
	end

	-- The daemon's registered application list is authoritative. Only format
	-- the version on an existing MT5700 card; never add or remove cards here.
	local package_version = nradio_appcenter_installed_package_version_v2("at-webserver")
	if package_version ~= "" then
		local ui_version = package_version:gsub("%-r?%d+$", "")
		for _, app in pairs(parameter.applist) do
			if type(app) == "table" and app.name == "MT5700 WebUI" then
				app.version = ui_version
				for _, pkg in pairs(type(app.list) == "table" and app.list or {}) do
					if type(pkg) == "table" and (pkg.pkg_name == "at-webserver" or pkg.name == "at-webserver") then
						pkg.version = package_version
					end
				end
			end
		end
	end
	return parameter
end
EOF_MT5700_APPCENTER_LIST_LUA

    awk -v lua_file="$mt5700_app_list_lua" '
        function insert_helper() {
            while ((getline extra < lua_file) > 0) print extra
            close(lua_file)
            inserted = 1
        }
        /^-- MT5700 appcenter installed-app preservation v[0-9]+$/ {
            insert_helper()
            replacing = 1
            next
        }
        replacing {
            if ($0 == "end") replacing = 0
            next
        }
        /^function action_app_list_data\(\)/ && !inserted { insert_helper() }
        { print }
    ' "$APPCENTER_CONTROLLER" > "$mt5700_app_list_tmp"
    cp "$mt5700_app_list_tmp" "$APPCENTER_CONTROLLER"

    if ! grep -q 'return mt5700_appcenter_preserve_installed_v1(nradio_appcenter_runtime_compat_v2(applist.parameter))' "$APPCENTER_CONTROLLER" 2>/dev/null; then
        awk '
            /^[[:space:]]*return nradio_appcenter_runtime_compat_v2\(applist\.parameter\)[[:space:]]*$/ {
                print "\treturn mt5700_appcenter_preserve_installed_v1(nradio_appcenter_runtime_compat_v2(applist.parameter))"
                next
            }
            { print }
        ' "$APPCENTER_CONTROLLER" > "$mt5700_app_return_tmp"
        cp "$mt5700_app_return_tmp" "$APPCENTER_CONTROLLER"
    fi
}

refresh_mt5700_luci_appcenter() {
    fix_nradio_ai_has_ai_compat
    rm -f /tmp/luci-indexcache 2>/dev/null || true
    rm -f /tmp/luci-modulecache/* 2>/dev/null || true
    /etc/init.d/appcenter restart >/dev/null 2>&1 || true
    sleep 2
}

cleanup_mt5700_appcenter_entries() {
    uci -q delete appcenter.nradio_mt5700 >/dev/null 2>&1 || true
    uci -q delete appcenter.nradio_mt5700_core >/dev/null 2>&1 || true
    cleanup_appcenter_entry "$MT5700_APP_NAME" "$MT5700_PACKAGE_NAME" "$MT5700_ROUTE"
    cleanup_appcenter_entry "luci-app-at-webserver" "luci-app-at-webserver" "$MT5700_ROUTE"
}

set_mt5700_appcenter_entry() {
    mt5700_core_size="$1"

    cleanup_mt5700_appcenter_entries
    set_appcenter_entry "$MT5700_APP_NAME" "$MT5700_PACKAGE_NAME" "$MT5700_UI_VERSION" \
        "$mt5700_core_size" "$MT5700_CONTROLLER" "$MT5700_ROUTE" "$MT5700_ICON_NAME"
    mt5700_pkg_sec="$pkg_sec"
    mt5700_core_sec="$list_sec"
    uci set "appcenter.$mt5700_pkg_sec.des=$MT5700_DESCRIPTION"
    uci set "appcenter.$mt5700_core_sec.version=$MT5700_PACKAGE_VERSION"
}

set_ddnsgo_appcenter_entry() {
    ddnsgo_core_size="$1"
    ddnsgo_luci_size="$2"
    ddnsgo_i18n_size="$3"
    ddnsgo_icon_name="${4:-}"

    cleanup_appcenter_entry "$DDNSGO_APP_NAME" "$DDNSGO_PACKAGE_NAME" "$DDNSGO_ROUTE"
    cleanup_appcenter_entry "$DDNSGO_APP_NAME" "$DDNSGO_LUCI_PACKAGE_NAME" "$DDNSGO_ROUTE"
    cleanup_appcenter_entry "$DDNSGO_APP_NAME" "$DDNSGO_I18N_PACKAGE_NAME" "$DDNSGO_ROUTE"
    cleanup_appcenter_entry "$DDNSGO_APP_NAME" "$DDNSGO_LUCI_PACKAGE_NAME" "$DDNSGO_LEGACY_ROUTE"
