                while ((getline extra < js_file) > 0) print extra
                close(js_file)
                skip = 1
                inserted = 1
                next
            }

            if (skip) {
                if ($0 ~ /^    function app_action\(app_name,action,id,route\)\{$/) {
                    skip = 0
                    print
                }
                next
            }

            if (!inserted && $0 ~ /^    function app_action\(app_name,action,id,route\)\{$/) {
                while ((getline extra < js_file) > 0) print extra
                close(js_file)
