patch_appcenter_status_controller() {
    require_nradio_oem_appcenter
    patch_appcenter_runtime_compat_controller
    verify_file_exists "$APPCENTER_CONTROLLER" "NRadio 应用商店控制器"

    mkdir -p "$WORKDIR"
    backup_file "$APPCENTER_CONTROLLER"
    status_lua_file="$WORKDIR/appcenter-controller.sys-status.lua"
    tmp_controller_status="$WORKDIR/appcenter-controller.sys-status.tmp"

    if ! grep -q 'appcenter", "sys_status"' "$APPCENTER_CONTROLLER" 2>/dev/null; then
        tmp_controller_entry="$WORKDIR/appcenter-controller.sys-status-entry"
        awk '
            {
                print
                if ($0 ~ /"appcenter",[[:space:]]*"memory"/ && !inserted) {
                    print "\tentry({\"nradioadv\", \"system\", \"appcenter\", \"sys_status\"}, call(\"action_sys_status\"), nil, nil, true).leaf = true"
                    inserted = 1
                }
            }
        ' "$APPCENTER_CONTROLLER" > "$tmp_controller_entry"
        cp "$tmp_controller_entry" "$APPCENTER_CONTROLLER"
    fi

    cat > "$status_lua_file" <<'EOF_APPCENTER_SYS_STATUS_LUA'

local function nradio_appcenter_read_first_line(path)
	local fp = io.open(path, "r")
	if not fp then
		return nil
	end
	local line = fp:read("*l")
	fp:close()
	return line
end

local function nradio_appcenter_read_cpu_stat()
	local line = nradio_appcenter_read_first_line("/proc/stat")
	if not line then
		return nil
	end

	local values = {}
	for n in line:gmatch("%d+") do
		values[#values + 1] = tonumber(n) or 0
	end
	if #values < 4 then
		return nil
	end

	local idle = (values[4] or 0) + (values[5] or 0)
	local total = 0
	for _, value in ipairs(values) do
		total = total + value
	end

	return total, idle
end

local function nradio_appcenter_read_cpu_usage_percent()
	local fs = require "nixio.fs"
	local state_path = "/var/run/nradio_appcenter_cpu.stat"
	local now = os.time()
	local min_interval = 2
	local total, idle = nradio_appcenter_read_cpu_stat()
	if not total or not idle then
		return nil
	end

	local prev_time, prev_total, prev_idle, prev_usage
	local previous = fs.readfile(state_path)
	if previous then
		prev_time, prev_total, prev_idle, prev_usage = previous:match("^(%d+)%s+(%d+)%s+(%d+)%s+([%d%.]+)")
		if not prev_time then
			prev_total, prev_idle = previous:match("^(%d+)%s+(%d+)")
		end
		prev_time = tonumber(prev_time)
		prev_total = tonumber(prev_total)
		prev_idle = tonumber(prev_idle)
		prev_usage = tonumber(prev_usage)
	end

	if prev_time and prev_usage and now - prev_time < min_interval then
		return prev_usage
	end

	if not prev_total or not prev_idle then
		fs.writefile(state_path, string.format("%d %d %d %.1f\n", now, total, idle, 0))
		return nil
	end

	local delta_total = total - prev_total
	local delta_idle = idle - prev_idle
	if delta_total <= 0 then
		fs.writefile(state_path, string.format("%d %d %d %.1f\n", now, total, idle, prev_usage or 0))
		return nil
	end

	local usage = (delta_total - delta_idle) * 100 / delta_total
	if usage < 0 then usage = 0 end
	if usage > 100 then usage = 100 end
	usage = math.floor(usage * 10 + 0.5) / 10
	fs.writefile(state_path, string.format("%d %d %d %.1f\n", now, total, idle, usage))
	return usage
end

local function nradio_appcenter_read_temperature_celsius()
	local fs = require "nixio.fs"
	local max_temp = nil
	for i = 0, 8 do
		local path = string.format("/sys/class/thermal/thermal_zone%d/temp", i)
		if fs.access(path) then
			local raw = tonumber(nradio_appcenter_read_first_line(path) or "")
			if raw then
				local temp = raw
				if temp > 1000 then
					temp = temp / 1000
				end
				if not max_temp or temp > max_temp then
					max_temp = temp
				end
			end
		end
	end
	if not max_temp then
		return nil
	end
	return math.floor(max_temp * 10 + 0.5) / 10
end

local function nradio_appcenter_read_system_memory()
	local total, available = 0, 0
	for line in io.lines("/proc/meminfo") do
		local key, value = line:match("^(%w+):%s+(%d+)")
		value = tonumber(value)
		if key == "MemTotal" and value then
			total = value
		elseif key == "MemAvailable" and value then
			available = value
		end
		if total > 0 and available > 0 then
			break
		end
	end

	local used = total - available
	if used < 0 then
		used = 0
	end

	local percent = 0
	if total > 0 then
		percent = math.floor((used * 1000 / total) + 0.5) / 10
	end

	return total, used, percent
end

local function nradio_appcenter_read_model_name()
	local model = nradio_appcenter_read_first_line("/tmp/sysinfo/model") or ""
	local board = nradio_appcenter_read_first_line("/tmp/sysinfo/board_name") or ""
	local text = (model .. " " .. board):upper()
	if text:find("HC-WT9302", 1, true) or text:find("HCMT7987-NAND", 1, true) or text:find("C8-788", 1, true) then
		return "NRadio_C8-788"
	end
	if text:find("HC-WT9500", 1, true) or text:find("C2000ULTRA", 1, true) then
		return "NRadio_C2000Ultra"
	end
	if text:find("HC-WT9303", 1, true) or text:find("C2000", 1, true) then
		return "NRadio_C2000MAX"
	end
	if model ~= "" then
		return model
	end
	return board
end

local function nradio_appcenter_read_swap_memory()
	local total, free = 0, 0
	local total_seen, free_seen = false, false
	for line in io.lines("/proc/meminfo") do
		local key, value = line:match("^(%w+):%s+(%d+)")
		value = tonumber(value)
		if key == "SwapTotal" and value then
			total = value
			total_seen = true
		elseif key == "SwapFree" and value then
			free = value
			free_seen = true
		end
		if total_seen and free_seen then
			break
		end
	end

	local used = total - free
	if used < 0 then
		used = 0
	end

	local percent = 0
	if total > 0 then
		percent = math.floor((used * 1000 / total) + 0.5) / 10
	end

	return total, used, percent
end

function action_sys_status()
	local load_line = nradio_appcenter_read_first_line("/proc/loadavg") or ""
	local load1 = load_line:match("^(%S+)") or "-"
	local mem_total, mem_used, mem_percent = nradio_appcenter_read_system_memory()
	local model_name = nradio_appcenter_read_model_name()
	local is_c2000max = model_name == "NRadio_C2000MAX"
	local supports_swap = is_c2000max or model_name == "NRadio_C2000Ultra"
	local swap_total, swap_used, swap_percent = 0, 0, 0
	if supports_swap then
		swap_total, swap_used, swap_percent = nradio_appcenter_read_swap_memory()
	end

	luci.nradio.luci_call_result({
		cpu_percent = nradio_appcenter_read_cpu_usage_percent(),
		cpu_temp = nradio_appcenter_read_temperature_celsius(),
		mem_total = mem_total,
		mem_used = mem_used,
		mem_percent = mem_percent,
		model_name = model_name,
		is_c2000max = is_c2000max,
		supports_swap = supports_swap,
		swap_total = swap_total,
		swap_used = swap_used,
		swap_percent = swap_percent,
		load1 = load1,
	})
end
EOF_APPCENTER_SYS_STATUS_LUA

    if ! grep -q 'function action_sys_status()' "$APPCENTER_CONTROLLER" 2>/dev/null; then
        cat "$status_lua_file" >> "$APPCENTER_CONTROLLER"
    elif ! grep -q 'swap_total = swap_total' "$APPCENTER_CONTROLLER" 2>/dev/null || \
         ! grep -q 'supports_swap = supports_swap' "$APPCENTER_CONTROLLER" 2>/dev/null || \
         ! grep -q 'local function nradio_appcenter_read_model_name()' "$APPCENTER_CONTROLLER" 2>/dev/null || \
         ! grep -q 'local function nradio_appcenter_read_swap_memory()' "$APPCENTER_CONTROLLER" 2>/dev/null || \
         ! grep -q 'now - prev_time < min_interval' "$APPCENTER_CONTROLLER" 2>/dev/null; then
        awk -v lua_file="$status_lua_file" '
            function emit_status() {
                if (!inserted) {
                    while ((getline extra < lua_file) > 0)
                        print extra
                    close(lua_file)
                    inserted = 1
                }
            }
            /^local function nradio_appcenter_read_first_line\(path\)/ {
                skip_status = 1
                emit_status()
                next
            }
            /^function action_sys_status\(\)/ && !inserted {
                skip_status = 1
                in_action = 1
                emit_status()
                next
            }
            skip_status && /^function action_sys_status\(\)/ {
                in_action = 1
                next
            }
            skip_status && in_action && /^end[[:space:]]*$/ {
                skip_status = 0
                in_action = 0
                next
            }
            !skip_status {
                print
            }
        ' "$APPCENTER_CONTROLLER" > "$tmp_controller_status"
        cp "$tmp_controller_status" "$APPCENTER_CONTROLLER"
    fi

    grep -q 'appcenter", "sys_status"' "$APPCENTER_CONTROLLER" 2>/dev/null || die "appcenter controller verify failed: missing sys_status route"
    grep -q 'function action_sys_status()' "$APPCENTER_CONTROLLER" 2>/dev/null || die "appcenter controller verify failed: missing action_sys_status"
    grep -q 'local function nradio_appcenter_read_model_name()' "$APPCENTER_CONTROLLER" 2>/dev/null || die "appcenter controller verify failed: missing model reader"
    grep -q 'local function nradio_appcenter_read_swap_memory()' "$APPCENTER_CONTROLLER" 2>/dev/null || die "appcenter controller verify failed: missing swap reader"
    grep -q 'now - prev_time < min_interval' "$APPCENTER_CONTROLLER" 2>/dev/null || die "appcenter controller verify failed: missing cpu sampling throttle"
    grep -q 'swap_total = swap_total' "$APPCENTER_CONTROLLER" 2>/dev/null || die "appcenter controller verify failed: missing swap_total"
}

patch_appcenter_card_polish_legacy() {
    require_nradio_oem_appcenter

    mkdir -p "$WORKDIR"
    css_file="$WORKDIR/appcenter-card-polish.css"
    tmp_css="$WORKDIR/appcenter-card-polish.css.tmp"
    tmp_row="$WORKDIR/appcenter-card-polish.row.tmp"
    tmp_status="$WORKDIR/appcenter-card-polish.status.tmp"
    tmp_compose="$WORKDIR/appcenter-card-polish.compose.tmp"
    tmp_panel="$WORKDIR/appcenter-card-polish.panel.tmp"
    tmp_mount="$WORKDIR/appcenter-card-polish.mount.tmp"
    tmp_ready="$WORKDIR/appcenter-card-polish.ready.tmp"
    tmp_icon="$WORKDIR/appcenter-card-polish.icon.tmp"
    tmp_desc="$WORKDIR/appcenter-card-polish.desc.tmp"
    tmp_name="$WORKDIR/appcenter-card-polish.name.tmp"
    status_js_file="$WORKDIR/appcenter-card-polish.status-panel.js"
    empty_js_file="$WORKDIR/appcenter-card-polish.empty-state.js"
    preserved_css_file="$WORKDIR/appcenter-card-polish.preserved-premium.css"

    if grep -q 'NRadio appcenter preserved premium live alignment' "$TPL" 2>/dev/null; then
        awk '
            /NRadio appcenter preserved premium live alignment/ {
                capture = 1
                next
            }
            capture && /^<\/style>$/ {
                exit
            }
            capture {
                print
            }
        ' "$TPL" > "$preserved_css_file"
    else
        awk '
            /NRadio appcenter card polish: visual-only layer/ || /NRadio appcenter premium frontend finish: pass 7 optical depth and motion discipline/ {
                capture = 1
            }
            capture && /^<\/style>$/ {
                exit
            }
            capture {
                print
            }
        ' "$TPL" > "$preserved_css_file"
    fi

    cat > "$css_file" <<'EOF_APPCENTER_CARD_POLISH_CSS'
    /* NRadio appcenter card polish: visual-only layer */
    /* NRadio appcenter card polish V2.0.70 full repair layer */
    /* NRadio appcenter visual polish 1-5 safe refinement */
    /* NRadio appcenter square card calm refinement */
    /* NRadio appcenter large-card proportion repair */
    /* NRadio appcenter status time readability repair */
    /* Keep container_left/app_top_menu layout owned by NRadio OEM CSS. */
    .appcontainer{
        position: relative;
        --nr-status-rail: 21.6%;
        --nr-status-reserve: 15.4%;
        --nr-status-gap: 12px;
        --nr-status-edge: -5.2%;
        --nr-polish-line: rgba(103,232,249,.22);
        --nr-polish-line-soft: rgba(148,163,184,.12);
        --nr-polish-panel: rgba(8,14,24,.76);
        --nr-polish-accent: #23c8e4;
        --nr-polish-ok: #3ddc97;
        --nr-polish-ink: #f4f8ff;
    }
    #app_top_menu{
        display: block;
        max-width: 100%;
        margin-bottom: 12px;
        padding: 0 2px 8px;
        border-bottom: 1px solid rgba(125,211,252,.10);
        overflow: hidden !important;
        overflow-x: hidden !important;
        overflow-y: visible !important;
        white-space: nowrap;
        scrollbar-width: none !important;
        -ms-overflow-style: none;
    }
    #app_top_menu::-webkit-scrollbar{
        width: 0 !important;
        height: 0 !important;
        display: none !important;
    }
    #app_top_menu .top_menu{
        position: relative;
        color: #a9bad2;
        font-size: 15px;
        font-weight: 800;
        letter-spacing: 0;
        line-height: 1.2;
        padding: 0 3px 9px;
        text-shadow: none;
        white-space: nowrap;
        -webkit-background-clip: border-box !important;
        background-clip: border-box !important;
        -webkit-text-fill-color: currentColor !important;
        transition: color .16s ease, border-color .16s ease, box-shadow .16s ease;
    }
    #app_top_menu .top_menu::after{
        content: "";
        position: absolute;
        left: 8px;
        right: 8px;
        bottom: 1px;
