        box-shadow:
            inset 0 .08em 0 rgba(255,255,255,.044),
            inset 0 0 0 .0625rem rgba(103,232,249,.040),
            0 .7em 1.35em rgba(0,0,0,.17);
        -webkit-backdrop-filter: blur(8px) saturate(1.06);
        backdrop-filter: blur(8px) saturate(1.06);
    }
    .app_btn_box .app_btn_group::before{
        content: "";
        position: absolute;
        left: 10px;
        right: 10px;
        top: 0;
        height: 1px;
        background: linear-gradient(90deg, transparent, rgba(35,200,228,.26), transparent);
        pointer-events: none;
    }
    #app_status_mount{
        display: block;
        position: absolute;
        right: var(--nr-status-edge);
        top: 0;
        z-index: 3;
