        background: linear-gradient(180deg, transparent, rgba(125,211,252,.16), rgba(148,163,184,.08), transparent);
        pointer-events: none;
    }
    .container_left .app_menu{
        display: block;
        width: calc(100% - 14px);
        height: 36px;
        line-height: 36px;
