        font-weight: 900;
    }
    .app_status_head{
        /* NRadio appcenter status panel safe polish */
        display: flex;
        align-items: center;
        justify-content: space-between;
        gap: 8px;
        margin-bottom: 10px;
        padding-bottom: 9px;
        border-bottom: 1px solid rgba(125,211,252,.115);
        color: #e6f3ff;
        font-size: 12.5px;
        font-weight: 850;
        white-space: nowrap;
        text-shadow: none;
    }
    .app_status_head span{
        display: inline-flex;
        align-items: center;
        flex: 0 0 auto;
        gap: 6px;
        white-space: nowrap;
    }
    .app_status_head span::before{
        content: "";
        width: 6px;
