    /* NRadio appcenter card content logic finish */
    .container_right .app_card_context{
        position: absolute;
        z-index: 2;
        left: 14px;
        right: 14px;
        bottom: 58px;
        display: grid;
        grid-template-columns: repeat(2, minmax(0, 1fr));
        gap: 8px;
        box-sizing: border-box;
        pointer-events: none;
