    awk '
        function dec(v, s) {
            s = sprintf("%.3f", v)
            sub(/^0/, "", s)
            return s
        }
        BEGIN {
            split("78,150,166|76,118,166|62,138,124|98,142,170|66,124,138|70,120,158|82,134,144|72,138,108|92,102,170|54,142,156|48,132,126|88,128,160|74,130,118|86,116,154|60,136,148|80,126,136", accent, "|")
