                printf "        --nr-card-focus-alpha: %s;\n", dec(.100 + (k % 7) * .002)
                printf "        --nr-card-noise-alpha: %s;\n", dec(.020 + (k % 5) * .001)
                printf "        --nr-card-ambient-alpha: %s;\n", dec(.034 + (k % 7) * .001)
                printf "        --nr-card-emphasis-alpha: %s;\n", dec(.055 + (k % 7) * .001)
