        --nr-v3-text: #edf5fb;
        --nr-v3-text-soft: #c5d2de;
        --nr-v3-muted: #91a5b8;
        --nr-v3-cyan: #4cc6d8;
        --nr-v3-blue: #5f9eea;
        --nr-v3-green: #50c697;
        --nr-v3-amber: #e1ad64;
        --nr-v3-red: #df7d82;
