        position: static !important;
        margin-top: 14px !important;
    }
    #app_top_menu{
        display: flex;
        align-items: center;
        gap: 8px;
        width: 100%;
        min-width: 0;
        height: auto !important;
        max-height: none !important;
        min-height: 52px;
        margin: 0 0 12px !important;
        padding: 6px 10px !important;
