    .container_left .app_menu{
        display: flex;
        align-items: center;
        min-height: 38px;
        margin: 0 0 6px;
        justify-content: space-between;
        gap: 7px;
        padding: 0 9px;
        border: 1px solid transparent;
        border-radius: 8px;
        color: var(--nr-v3-muted);
        font-size: 13px;
        line-height: 1.2;
        white-space: nowrap;
        -webkit-background-clip: border-box !important;
        background-clip: border-box !important;
        -webkit-text-fill-color: currentColor !important;
        cursor: pointer;
    }
    .container_left .app_menu:last-child{
        margin-bottom: 0;
    }
    .container_left .app_menu:hover{
        background: rgba(255,255,255,.025);
        color: var(--nr-v3-text-soft);
    }
    .container_left .app_menu.menu_active{
        border-color: rgba(76,198,216,.28);
        background: rgba(76,198,216,.10);
        color: #e5fbff !important;
        -webkit-text-fill-color: #e5fbff !important;
        box-shadow: inset 3px 0 0 var(--nr-v3-cyan);
    }
    .container_left .nr_menu_count{
        display: inline-flex;
        align-items: center;
        justify-content: center;
        min-width: 22px;
        height: 22px;
        padding: 0 5px;
        border-radius: 999px;
        background: rgba(128,157,184,.08);
        color: var(--nr-v3-muted);
        font-size: 11px;
        font-weight: 700;
        line-height: 22px;
        font-variant-numeric: tabular-nums;
    }
    .container_left .app_menu.menu_active .nr_menu_count{
        background: rgba(76,198,216,.11);
        color: #c8f6fb;
    }
    .container_left .mem_mobile{
        display: none;
    }
    .container_right{
        grid-area: content;
        display: grid;
        grid-template-columns: repeat(3,minmax(0,1fr));
        grid-auto-rows: auto;
        align-items: stretch;
        gap: 16px;
        float: none !important;
        width: auto !important;
        min-width: 0;
        margin: 0 !important;
        padding: 0 !important;
    }
    .container_right.hide{
        display: none !important;
    }
    .container_right .app_box{
        position: relative;
        display: grid;
        grid-template-columns: 52px minmax(0,1fr);
        grid-template-rows: minmax(110px,1fr) auto;
        column-gap: 12px;
        min-width: 0;
        min-height: 210px;
        width: 100% !important;
        max-width: none !important;
        height: auto !important;
        margin: 0 !important;
        float: none !important;
        padding: 16px;
        overflow: hidden;
        border: 1px solid var(--nr-v3-line-soft);
        border-radius: 12px;
        background: var(--nr-v3-panel);
        box-shadow: 0 3px 10px rgba(0,0,0,.10);
        transition: border-color .16s ease, box-shadow .16s ease, background-color .16s ease;
        container-type: inline-size;
    }
    .container_right .app_box:hover,
    .container_right .app_box:focus-within{
        transform: none;
        border-color: var(--nr-v3-line-strong);
        background: #183047;
        box-shadow: 0 5px 14px rgba(0,0,0,.14);
    }
    .container_right .app_icon{
        grid-column: 1;
        grid-row: 1;
        display: flex;
        align-items: flex-start;
        justify-content: center;
        float: none;
        width: auto;
        margin: 0;
    }
    .container_right .app_icon_img{
        display: block;
        width: 52px;
        height: 52px;
        padding: 3px;
        border: 1px solid rgba(128,157,184,.10);
        border-radius: 12px;
        background: rgba(128,157,184,.04);
        object-fit: contain;
        box-shadow: none;
        transition: border-color .16s ease;
    }
    .container_right .app_box:hover .app_icon_img,
    .container_right .app_box:focus-within .app_icon_img{
        transform: none;
        border-color: rgba(76,198,216,.34);
    }
    .container_right .app_info{
        grid-column: 2;
        grid-row: 1;
        float: none;
        width: auto;
        min-width: 0;
        margin: 0;
    }
    .container_right .app_title{
        display: grid;
        grid-template-columns: minmax(0,1fr) auto;
        gap: 5px 8px;
        align-items: start;
        align-content: start;
        min-height: 48px;
        min-width: 0;
    }
    .container_right .app_name{
        grid-column: 1;
        float: none;
        width: auto;
        height: auto;
        min-width: 0;
        overflow: hidden;
        color: var(--nr-v3-text);
        font-size: 17px;
        font-weight: 700;
        line-height: 1.4;
        text-overflow: ellipsis;
        white-space: normal;
        overflow-wrap: anywhere;
        display: -webkit-box;
        -webkit-line-clamp: 2;
        -webkit-box-orient: vertical;
    }
    .container_right .app_version{
        grid-column: 1;
        float: none;
        width: auto;
        height: auto;
        overflow: hidden;
        color: var(--nr-v3-muted);
        font-size: 12px;
        font-weight: 400;
        font-variant-numeric: tabular-nums;
        line-height: 1.4;
        text-overflow: ellipsis;
        white-space: nowrap;
    }
    .container_right .app_name,
    .container_right .app_version,
    .container_right .app_des{
        position: relative;
        padding-right: 20px;
    }
    .container_right .nr_text_expandable{
        cursor: pointer;
    }
    .container_right .nr_text_expandable::after{
        content: "";
        position: absolute;
        top: 5px;
        right: 3px;
        width: 7px;
        height: 7px;
        border-right: 1.5px solid var(--nr-v3-cyan);
        border-bottom: 1.5px solid var(--nr-v3-cyan);
        transform: rotate(45deg);
        pointer-events: none;
    }
    .container_right .nr_text_expanded::after,
    .container_right .nr_desc_expanded::after{
        top: 8px;
        transform: rotate(225deg);
    }
    .container_right .nr_text_expandable:focus-visible{
        outline: 2px solid var(--nr-v3-cyan);
        outline-offset: 2px;
    }
    .container_right .app_name.nr_text_expanded{
        display: block;
        overflow: visible;
        -webkit-line-clamp: unset;
    }
    .container_right .app_version.nr_text_expanded{
        overflow: visible;
        overflow-wrap: anywhere;
        white-space: normal;
    }
    .container_right .app_meta_row{
        grid-column: 2;
        grid-row: 1 / span 2;
        display: flex;
        flex-direction: column;
        align-items: flex-end;
        gap: 4px;
    }
    .container_right .app_state_badge,
    .container_right .app_open_badge{
        display: inline-flex;
        align-items: center;
        min-height: 21px;
        padding: 0 6px;
        border: 1px solid rgba(128,157,184,.14);
        border-radius: 6px;
        background: rgba(128,157,184,.07);
        color: var(--nr-v3-text-soft);
        font-size: 11px;
        font-weight: 500;
        line-height: 19px;
        white-space: nowrap;
    }
    .container_right .app_state_0{
        border-color: rgba(95,158,234,.30);
        background: rgba(95,158,234,.09);
        color: #bcd9fb;
    }
    .container_right .app_state_1{
        border-color: rgba(128,157,184,.22);
        background: rgba(128,157,184,.07);
        color: #b9cad9;
    }
    .container_right .app_open_badge{
        border-color: rgba(80,198,151,.30);
        background: rgba(80,198,151,.09);
        color: #b9efd8;
    }
    .container_right .app_state_2{
        border-color: rgba(225,173,100,.32);
        background: rgba(225,173,100,.09);
        color: #f3d5a5;
    }
    .container_right .app_des{
        float: none;
        width: 100%;
        height: 44px;
        margin: 12px 0 0;
        overflow: hidden;
        color: #b5c5d4;
        font-size: 13px;
        font-weight: 400;
        line-height: 22px;
        display: -webkit-box;
        -webkit-line-clamp: 2;
        -webkit-box-orient: vertical;
    }
    .container_right .app_des[role="button"]{ cursor: pointer; }
    .container_right .app_des.nr_desc_expanded{
        display: block;
        height: auto;
        overflow: visible;
        overflow-wrap: anywhere;
    }
    .appcontainer mark.nr_search_match{
        padding: 0;
        border-radius: 2px;
        color: #effdff;
        background: rgba(76,198,216,.24);
    }
    @container (max-width: 320px){
        .app_title{ grid-template-columns: 1fr !important; }
        .app_meta_row{
            grid-column: 1 !important;
            grid-row: 3 !important;
            flex-direction: row !important;
            flex-wrap: wrap;
            align-items: center !important;
        }
    }
    .container_right .app_action{
        grid-column: 1 / -1;
        grid-row: 2;
        float: none;
        width: 100%;
        align-self: end;
        margin: 14px 0 0;
        padding-top: 12px;
        border-top: 1px solid rgba(128,157,184,.10);
    }
    .container_right .action_list{
        display: flex;
        justify-content: flex-end;
        gap: 10px;
        float: none;
        margin: 0;
        padding: 0;
        list-style: none;
        align-items: center;
    }
    .container_right .action_list_li{
        display: inline-flex;
        align-items: center;
        justify-content: center;
        min-width: 72px;
        min-height: 38px;
        padding: 0 14px;
        border: 1px solid rgba(128,157,184,.24);
        border-radius: 8px;
        background: rgba(128,157,184,.055);
        color: var(--nr-v3-text-soft);
        font-size: 13px;
        font-weight: 600;
        line-height: 36px;
        cursor: pointer;
        -webkit-text-fill-color: currentColor;
        transition: background-color .16s ease, border-color .16s ease, color .16s ease;
    }
    .container_right .action_list_li:hover,
    .container_right .action_list_li:focus-visible{
        border-color: rgba(76,198,216,.42);
        background: rgba(76,198,216,.11);
        color: #e7fbff;
        outline: none;
    }
    .container_right .nr_action_install{
        border-color: var(--nr-v3-cyan);
        color: #06242e;
        background: var(--nr-v3-cyan);
    }
    .container_right .nr_action_open{
        min-width: 76px;
        border-color: rgba(76,198,216,.32);
        color: #b9edf2;
        background: #15333f;
        box-shadow: none;
    }
    .container_right .nr_action_update{
        border-color: rgba(225,173,100,.28);
        color: #eed0a0;
        background: rgba(225,173,100,.10);
    }
    .container_right .nr_action_uninstall{
        margin-right: auto;
        color: #bd929b;
        background: transparent;
        border-color: transparent;
    }
    .container_right .nr_action_install:hover,
    .container_right .nr_action_install:focus-visible{
        border-color: #79e0ea;
        background: #79e0ea;
        color: #06242e;
    }
    .container_right .nr_action_open:hover,
    .container_right .nr_action_open:focus-visible{
        border-color: rgba(76,198,216,.58);
        background: #1b424e;
        color: #e4fbfd;
    }
    .container_right .nr_action_uninstall:hover,
    .container_right .nr_action_uninstall:focus-visible{
        border-color: rgba(223,125,130,.28);
        background: rgba(223,125,130,.09);
        color: #f2b8c0;
    }
    .app_empty_state,
    .nr_search_empty{
        grid-column: 1 / -1;
        display: flex;
        flex-direction: column;
        align-items: center;
        justify-content: center;
        min-height: 180px;
        padding: 24px;
        border: 1px dashed rgba(76,198,216,.25);
        border-radius: 12px;
        background: var(--nr-v3-panel-2);
        color: var(--nr-v3-muted);
        text-align: center;
    }
    .app_empty_state strong,
    .nr_search_empty strong{
        color: var(--nr-v3-text-soft);
        font-size: 14px;
    }
    .nr_empty_icon{
        width: 28px;
        height: 28px;
        margin-bottom: 9px;
        color: var(--nr-v3-cyan);
        opacity: .68;
    }
    .nr_search_empty::before{
        content: "";
        margin-bottom: 7px;
        color: var(--nr-v3-cyan);
        width: 20px;
        height: 20px;
        border: 2px solid currentColor;
        border-radius: 50%;
        line-height: 1;
        opacity: .68;
    }
    .app_empty_state > span,
    .nr_search_empty span{
        margin-top: 4px;
        font-size: 12px;
    }
    .nr_search_reset,
    .nr_browse_apps{
        min-height: 44px;
        margin-top: 12px;
        padding: 0 16px;
        border: 1px solid rgba(76,198,216,.35);
        border-radius: 8px;
        background: rgba(76,198,216,.08);
        color: #c8f6fb;
        cursor: pointer;
    }
    .nr_search_reset:hover,
    .nr_browse_apps:hover{
        background: rgba(76,198,216,.15);
        color: #e7fbff;
    }
    .nr_search_reset:focus-visible,
    .nr_browse_apps:focus-visible{
        outline: 2px solid var(--nr-v3-cyan);
        outline-offset: 2px;
    }
    #app_status_mount{
        grid-area: status;
        position: static;
        min-width: 0;
    }
    .app_status_panel{
        display: grid;
        grid-template-columns: 112px 180px repeat(auto-fit,minmax(130px,1fr));
        gap: 8px;
        align-items: stretch;
        padding: 10px 12px;
        border: 1px solid var(--nr-v3-line-soft);
        border-radius: 10px;
        background: var(--nr-v3-panel-2);
        box-shadow: none;
    }
    .app_status_head{
        display: flex;
        flex-direction: column;
        align-items: center;
        justify-content: center;
        gap: 3px;
        margin: 0;
        padding: 0 5px;
    }
    .app_status_head span{
        color: var(--nr-v3-text);
        font-size: 13px;
        font-weight: 700;
    }
    .app_status_time{
        color: var(--nr-v3-muted);
        font-size: 11px;
        font-style: normal;
        font-variant-numeric: tabular-nums;
    }
    .app_status_grid{
        display: grid;
        grid-template-columns: repeat(3,1fr);
        gap: 4px;
        margin: 0;
    }
    .app_status_tile{
        display: flex;
        flex-direction: column;
        align-items: center;
        justify-content: center;
        min-height: 42px;
        padding: 5px 3px;
        border: 0;
        border-radius: 7px;
        background: transparent;
    }
    .app_status_tile strong{
        color: #f4fbff;
        font-size: 18px;
        line-height: 1.1;
        font-variant-numeric: tabular-nums;
    }
    .app_status_tile span{
        margin-top: 2px;
        color: var(--nr-v3-muted);
        font-size: 11px;
    }
    .app_status_metric{
        display: flex;
        flex-direction: column;
        justify-content: center;
        min-width: 0;
        margin: 0;
        padding: 6px 8px;
        border: 0;
        border-radius: 0;
        background: transparent;
        border-left: 1px solid rgba(128,157,184,.14);
    }
    .app_status_metric_row{
        display: flex;
        align-items: center;
        justify-content: space-between;
        gap: 4px 8px;
        margin-bottom: 5px;
        flex-wrap: wrap;
    }
    .app_status_metric_row span{
        color: var(--nr-v3-muted);
        font-size: 12px;
    }
    .app_status_metric_row strong{
        max-width: 100%;
        overflow: hidden;
        color: var(--nr-v3-text);
        font-size: 16px;
        font-weight: 700;
        text-overflow: ellipsis;
        white-space: nowrap;
        font-variant-numeric: tabular-nums;
    }
    .app_status_metric_detail{
        display: block;
        margin-bottom: 6px;
        color: var(--nr-v3-muted);
        font-size: 11px;
        line-height: 1.4;
        font-variant-numeric: tabular-nums;
        overflow-wrap: anywhere;
    }
    .app_status_metric_detail[hidden]{ display: none; }
    .app_status_bar{
        height: 4px;
        overflow: hidden;
        border-radius: 999px;
        background: rgba(2,7,12,.72);
        box-shadow: inset 0 0 0 1px rgba(128,157,184,.10);
    }
    .app_status_bar span{
        display: block;
        width: 0;
        height: 100%;
        border-radius: inherit;
        transition: width .28s ease;
    }
    .app_status_temp_bar{ background: linear-gradient(90deg,#e1ad64,#df7d82); }
    .app_status_cpu_bar{ background: linear-gradient(90deg,#5f9eea,#4cc6d8); }
    .app_status_mem_bar{ background: linear-gradient(90deg,#50c697,#4cc6d8); }
    .app_status_swap_bar{ background: linear-gradient(90deg,#9b8de3,#5f9eea); }
    .app_status_toggle{
        display: flex;
        flex-direction: column;
        align-items: center;
        justify-content: center;
        gap: 3px;
        width: 100%;
        padding: 0;
        border: 0;
        outline: 0;
        background: transparent;
        color: inherit;
        font: inherit;
        cursor: pointer;
    }
    .app_status_toggle_text{
        color: var(--nr-v3-cyan);
        font-size: 11px;
        font-weight: 700;
    }
    #app_status_mount.nr_status_collapsed .app_status_panel{
        display: flex;
        justify-content: flex-end;
        padding: 0;
        border: 0;
        background: transparent;
        box-shadow: none;
    }
    #app_status_mount.nr_status_collapsed{
        margin-top: -12px;
    }
    #app_status_mount.nr_status_collapsed .app_status_grid,
    #app_status_mount.nr_status_collapsed .app_status_metric{
        display: none !important;
    }
    #app_status_mount.nr_status_collapsed .app_status_head{
        padding: 0;
    }
    #app_status_mount.nr_status_collapsed .app_status_toggle{
        flex-direction: row;
        width: auto;
        padding: 7px 12px;
        border: 1px solid rgba(76,198,216,.23);
        border-radius: 8px;
        background: #0f1d2b;
        box-shadow: none;
    }
    #app_status_mount.nr_status_collapsed .app_status_toggle::before{
        content: "";
        width: 6px;
        height: 6px;
        border-radius: 50%;
        background: var(--nr-v3-muted);
    }
    #app_status_mount.nr_status_ok .app_status_toggle::before{ background: var(--nr-v3-green); }
    #app_status_mount.nr_status_busy .app_status_toggle::before{ background: var(--nr-v3-cyan); }
    #app_status_mount.nr_status_error .app_status_toggle::before{ background: var(--nr-v3-amber); }
    #app_status_mount.nr_status_error .app_status_time{ color: var(--nr-v3-amber); }
    .nr_dialog_result{
        padding: 18px;
        text-align: center;
        overflow-wrap: anywhere;
    }
    .nr_dialog_result_icon{
        display: block;
        margin: 0 auto 12px;
        color: #50c697;
        font-size: 28px;
    }
    .nr_dialog_result_error .nr_dialog_result_icon{ color: #df7d82; }
    .nr_dialog_result .error_box{ text-align: left; }
    .nr_dialog_result strong{ display: block; margin-bottom: 8px; }
    #app_status_mount.nr_status_collapsed .app_status_toggle:hover{
        border-color: rgba(76,198,216,.46);
        background: #132334;
    }
    #app_top_menu .top_menu[role="button"]:focus-visible,
    #app_top_menu .top_menu_inner_icon:focus-visible,
    .nr_app_search_clear:focus-visible,
    .app_btn_group .app_btn_class:focus-visible,
    .container_left .app_menu:focus-visible,
    .container_right .action_list_li:focus-visible,
    .container_right .app_des:focus-visible,
    .nr_search_reset:focus-visible,
    #app_top_menu .nr_store_tab:focus-visible,
    .app_status_toggle:focus-visible{
        outline: 2px solid rgba(76,198,216,.72) !important;
        outline-offset: 2px;
        box-shadow: 0 0 0 4px rgba(76,198,216,.10);
    }
    .nr_app_filtered{
        display: none !important;
    }
    .bootstrap-dialog-message #scan_loading.nr_dialog_loading{
        display: flex;
        flex-direction: column;
        align-items: center;
        justify-content: center;
        min-height: 128px;
        padding: 18px;
        color: #bdcad7;
        text-align: center;
    }
    .bootstrap-dialog-message .nr_dialog_spinner{
        width: 30px;
        height: 30px;
        margin-bottom: 12px;
        border: 3px solid rgba(128,157,184,.20);
        border-top-color: #4cc6d8;
        border-radius: 50%;
        box-shadow: 0 0 16px rgba(76,198,216,.12);
        animation: nr-dialog-spin .72s linear infinite;
    }
    .bootstrap-dialog-message .nr_dialog_loading strong{
        color: #edf5fb;
        font-size: 15px;
        line-height: 1.4;
    }
    .bootstrap-dialog-message .nr_dialog_loading small{
        margin-top: 5px;
        color: #9aaec0;
        font-size: 13px;
        line-height: 1.5;
    }
    .bootstrap-dialog-message .error_box{
        display: flex !important;
        align-items: flex-start;
        gap: 8px;
        width: 100% !important;
        margin: 0 0 8px;
        padding: 10px 12px;
        border: 1px solid rgba(223,125,130,.20);
        border-radius: 9px;
        background: rgba(223,125,130,.055);
        color: #bdcad7;
        line-height: 1.55;
        overflow-wrap: anywhere;
    }
    .bootstrap-dialog-message .error_box + br{
        display: none;
    }
    .bootstrap-dialog-message .error_detail_title{
        flex: 0 0 auto;
        float: none !important;
        color: #df9da1;
        font-weight: 700;
    }
    .bootstrap-dialog-message .error_detail_content{
        min-width: 0;
        float: none !important;
        white-space: pre-wrap;
        word-break: break-word;
    }
    .modal.bootstrap-dialog .modal-content{
        border: 1px solid rgba(128,157,184,.25);
        border-radius: 14px;
        background: #0d1a29;
        color: #edf5fb;
        box-shadow: 0 16px 44px rgba(0,0,0,.32);
    }
    .modal.bootstrap-dialog.in:not(.app_frame){
        display: flex !important;
        align-items: center;
        justify-content: center;
        padding: 16px !important;
        overflow-y: auto;
    }
    .modal.bootstrap-dialog:not(.app_frame) .modal-dialog{
        max-width: 100%;
        margin: auto !important;
    }
    .modal.bootstrap-dialog:not(.app_frame) .bootstrap-dialog-header{
        display: flex;
        flex-direction: row-reverse;
        align-items: center;
