EOF_APPCENTER_V3_CSS

    cat > "$v3_js" <<'EOF_APPCENTER_V3_JS'
    var NR_APP_DISPLAY_NAMES = {};
    var NR_APP_ICON_CACHE_TAG = "__NR_ICON_CACHE_TAG__";
    var NR_UPLOAD_CHECK_SEQ = 0;
    var NR_APP_TOP_NAV = __NR_TOP_NAV_MODEL__ === 1 && typeof top_menu !== "undefined" &&
        Array.isArray(top_menu) && top_menu.some(function(item){ return item && item.name === "appcenter"; });
    function nr_sync_toolbar_height(){
        var toolbar = document.querySelector(".appcontainer > .app_btn_box");
        if(!toolbar) return;
        toolbar.parentNode.style.setProperty("--nr-app-toolbar-height", toolbar.offsetHeight + "px");
    }
    function nr_init_sticky_toolbar(){
        var toolbar = document.querySelector(".appcontainer > .app_btn_box");
        if(!toolbar) return;
        nr_sync_toolbar_height();
        window.addEventListener("resize", nr_sync_toolbar_height);
        if(window.ResizeObserver) new window.ResizeObserver(nr_sync_toolbar_height).observe(toolbar);
    }
    function nr_init_topnav_layout(){
        var main = $(".appcontainer").closest(".main")[0];
        if(!main) return;
        main.classList.add("nr-appcenter-main");
        if(!NR_APP_TOP_NAV) return;
        document.body.classList.add("nr-appcenter-topnav");
        var footer = document.querySelector("body > footer.footer");
        var pending = false;
        function update_height(){
            pending = false;
            if(window.innerWidth < 768){
                main.style.removeProperty("--nr-appcenter-height");
                return;
            }
            var footer_space = 0;
            if(footer){
                var style = window.getComputedStyle(footer);
                footer_space = footer.getBoundingClientRect().height +
                    (parseFloat(style.marginTop) || 0) + (parseFloat(style.marginBottom) || 0);
            }
            var top = main.getBoundingClientRect().top + (window.pageYOffset || 0);
            var bottom = parseFloat(window.getComputedStyle(main).marginBottom) || 0;
            var height = Math.max(160, Math.floor(window.innerHeight - top - bottom - footer_space - 8));
            main.style.setProperty("--nr-appcenter-height", height + "px");
        }
        function schedule_height(){
            if(pending) return;
            pending = true;
            window.requestAnimationFrame(update_height);
        }
        update_height();
        window.addEventListener("resize", schedule_height);
        window.addEventListener("load", schedule_height);
        if(window.ResizeObserver){
            var observer = new window.ResizeObserver(schedule_height);
            var header = document.querySelector("body > header");
            if(header) observer.observe(header);
            if(footer) observer.observe(footer);
        }
    }
    function nr_appcenter_display_name(name, translated){
        var key = (name || "").toLowerCase();
        if(key == "luci-app-openclash" || key == "openclash") return "哈基米";
        if(key == "luci-app-adguardhome") return "AdGuardHome";
        if(key == "luci-app-ddns-go") return "DDNS-GO";
        return translated || NR_APP_DISPLAY_NAMES[key] || name || "未命名应用";
    }

    function nr_escape_html(value){
        return String(value == null ? "" : value).replace(/[&<>"']/g, function(ch){
            return {"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#39;"}[ch];
        });
    }

    function nr_highlight_text(value, query){
        var text = String(value || ""), lower = text.toLowerCase(), result = "", start = 0, found;
        if(!query) return nr_escape_html(text);
        while((found = lower.indexOf(query, start)) >= 0){
            result += nr_escape_html(text.slice(start, found)) + '<mark class="nr_search_match">' +
                nr_escape_html(text.slice(found, found + query.length)) + '</mark>';
            start = found + query.length;
        }
        return result + nr_escape_html(text.slice(start));
    }

    var NR_ACTIVE_APP_NAME = "";
    function nr_update_tab_edges(remeasure){
        var scroller = document.querySelector("#app_top_menu .nr_tabs_scroller");
        if(!scroller) return;
        var menu = $("#app_top_menu");
        if(remeasure === true) menu.removeClass("nr_tabs_overflow");
        menu.toggleClass("nr_tabs_overflow", scroller.scrollWidth > scroller.clientWidth + 2);
        var before = scroller.scrollLeft > 2;
        var after = scroller.scrollLeft + scroller.clientWidth < scroller.scrollWidth - 2;
        $(scroller.parentNode).toggleClass("nr_tabs_before", before).toggleClass("nr_tabs_after", after);
        $("#app_top_menu .nr_tabs_prev").prop("disabled", !before);
        $("#app_top_menu .nr_tabs_next").prop("disabled", !after);
    }

    function nr_sync_top_tabs(id, reveal){
        var selected = null;
        $("#app_top_menu .top_menu_inner").each(function(){
            var link = $(this).find(".top_menu");
            var active = id != null && String(link.attr("data-index")) === String(id);
            $(this).toggleClass("nr_tab_active", active);
            link.toggleClass("top_menu_active", active).attr("aria-current", active ? "page" : "false");
            if(active) selected = this;
        });
        $("#app_top_menu .nr_store_tab").toggleClass("top_menu_active", !selected)
            .attr("aria-current", selected ? "false" : "page");
        NR_ACTIVE_APP_NAME = selected ? $(selected).attr("data-app-name") : "";
        var scroller = document.querySelector("#app_top_menu .nr_tabs_scroller");
        if(reveal && selected && scroller){
            var box = selected.getBoundingClientRect(), view = scroller.getBoundingClientRect();
            if(box.left < view.left + 4) scroller.scrollLeft += box.left - view.left - 4;
            else if(box.right > view.right - 4) scroller.scrollLeft += box.right - view.right + 4;
        }
        nr_update_tab_edges();
    }

    function nr_operation_title(action, name){
        var verb = {install:"安装",uninstall:"卸载",update:"更新",open:"打开",close:"关闭",check:"检测版本"}[action] || "处理";
        return verb + (name ? " " + nr_appcenter_display_name(name) : "");
    }

    function nr_appcenter_loading(action, name){
        return '<div id="scan_loading" class="nr_dialog_loading" role="status" aria-live="polite">' +
            '<span class="nr_dialog_spinner" aria-hidden="true"></span><strong>正在' +
            nr_escape_html(nr_operation_title(action, name)) + '</strong><small>请稍候</small></div>';
    }

    function nr_result_markup(ok, message){
        return '<div class="nr_dialog_result' + (ok ? '' : ' nr_dialog_result_error') + '" role="status">' +
            '<span class="nr_dialog_result_icon" aria-hidden="true">' + (ok ? '✓' : '!') + '</span>' +
            '<strong>' + (ok ? '操作完成' : '操作失败') + '</strong><div>' + (message || '') + '</div></div>';
    }

    function nr_appcenter_result(dialog, ok, action, name, message){
        if(!dialog) return;
        dialog.setTitle(nr_escape_html(nr_operation_title(action, name)) + (ok ? "完成" : "失败"));
        dialog.setType(ok ? BootstrapDialog.TYPE_SUCCESS : BootstrapDialog.TYPE_DANGER);
        dialog.setMessage(nr_result_markup(ok, message));
    }

    var NR_APP_CHECK = null;
    var NR_APP_CHECK_TIMEOUT = 80000;
    function nr_stop_appstore_check(job){
        if(!job) return;
        job.done = true;
        window.clearTimeout(job.pollTimer);
        window.clearTimeout(job.deadlineTimer);
        var xhr = job.xhr;
        job.xhr = null;
        if(xhr && xhr.readyState !== 4) xhr.abort();
    }

    function nr_render_appstore_check(job, state, title, detail){
        var waiting = state === "waiting";
        var failed = state === "error";
        var icon = waiting ? '<span class="nr_dialog_spinner" aria-hidden="true"></span>' : failed ? '!' : '✓';
        var buttons = [{label:"关闭", cssClass:"btn-default", action:function(dialog){ dialog.close(); }}];
        if(failed) buttons.push({label:"重新检测", cssClass:"btn-primary", action:function(){ nr_check_appstore_version(); }});
        job.dialog.setTitle("检测应用更新");
        job.dialog.setType(BootstrapDialog.TYPE_DEFAULT);
        job.dialog.setMessage('<div class="nr_update_check_state nr_update_check_'+state+'" role="status" aria-live="polite">'+
            '<span class="nr_update_check_icon" aria-hidden="true">'+icon+'</span><strong>'+nr_escape_html(title)+'</strong>'+
            (detail ? '<div class="nr_update_check_detail">'+nr_escape_html(detail)+'</div>' : '')+'</div>');
        job.dialog.setButtons(buttons);
    }

    function nr_finish_appstore_check(job, code, message){
        if(NR_APP_CHECK !== job || job.done) return;
        nr_stop_appstore_check(job);
        var ok = code === 0 || code === 5;
        nr_render_appstore_check(job, ok ? "success" : "error",
            code === 5 ? "应用列表已是最新" : code === 0 ? "应用列表已更新" : "检测失败",
            ok ? "" : message || "暂时无法获取应用列表，请重新检测");
        if(ok) refresh_data();
    }

    function nr_request_appstore_check(job, initial){
        if(!job || NR_APP_CHECK !== job || job.done || job.xhr) return;
        var remaining = job.deadline - Date.now();
        if(remaining <= 0){ nr_finish_appstore_check(job, -1, "检测超时，请重新检测"); return; }
        job.xhr = $.ajax({
            type:"POST",
            url:'<%=controller%>nradioadv/system/appcenter/' + (initial ? "appstore" : "check_appstore"),
            data:{token:'<%=token%>'},
            dataType:"json",
            timeout:Math.min(10000, remaining),
            success:function(response){
                if(NR_APP_CHECK !== job || job.done) return;
                var result = response && response.result;
                var raw = result && result.code;
                if((typeof raw !== "number" && typeof raw !== "string") || !/^-?\d+$/.test(String(raw))){
                    nr_finish_appstore_check(job, -1, "检测响应无效，请重新检测");
                    return;
                }
                var code = Number(raw);
                if(code === 13 || code === 14){
                    nr_render_appstore_check(job, "waiting", code === 14 ? "等待更新" : "正在检测",
                        code === 14 ? "服务正在处理请求" : "正在获取应用列表");
                    job.pollTimer = window.setTimeout(function(){ nr_request_appstore_check(job, false); }, 4000);
                } else nr_finish_appstore_check(job, code, result.msg);
            },
            error:function(xhr, status){
                if(NR_APP_CHECK !== job || job.done) return;
                nr_finish_appstore_check(job, -1, status === "timeout" ? "检测请求超时，请重新检测" :
                    status === "parsererror" ? "检测响应无效，请重新检测" : "无法获取检测结果，请检查连接后重试");
            },
            complete:function(){ job.xhr = null; }
        });
    }

    function nr_check_appstore_version(){
        if(NR_APP_CHECK && !NR_APP_CHECK.done) return;
        var dialog = appstore_check_dial;
        if(!dialog || !dialog.isOpened()){
            dialog = BootstrapDialog.show({
                type:BootstrapDialog.TYPE_DEFAULT,
                cssClass:"nr_update_check_dialog",
                closeByBackdrop:false,
                title:"检测应用更新",
                message:"",
                onhide:function(closed){
                    if(NR_APP_CHECK && NR_APP_CHECK.dialog === closed) nr_stop_appstore_check(NR_APP_CHECK);
                }
            });
            appstore_check_dial = dialog;
        }
        var job = {dialog:dialog, done:false, xhr:null, pollTimer:null, deadlineTimer:null,
            deadline:Date.now() + NR_APP_CHECK_TIMEOUT};
        NR_APP_CHECK = job;
        nr_render_appstore_check(job, "waiting", "正在检测", "");
        job.deadlineTimer = window.setTimeout(function(){
            nr_finish_appstore_check(job, -1, "检测超时，请重新检测");
        }, NR_APP_CHECK_TIMEOUT);
        nr_request_appstore_check(job, true);
    }

    function nr_appcenter_display_version(name, version){
        var raw = version || "";
        var key = (name || "").toLowerCase();
        var match = raw.match(/^(git-[0-9]+[.][0-9]+[.][0-9]+)-[0-9a-f]+$/i);
        if(key.indexOf("openvpn") >= 0 && match) return match[1];
        return raw;
    }

    function nr_appcenter_desc_fallback(name){
        var key = (name || "").toLowerCase();
        if(key.indexOf("openclash") >= 0) return "代理规则、节点与网络分流管理";
        if(key.indexOf("adguard") >= 0) return "DNS 广告过滤与查询统计";
        if(key.indexOf("openvpn") >= 0) return "VPN 隧道连接与远程访问";
        if(key.indexOf("zerotier") >= 0) return "异地组网与虚拟局域网";
        if(key.indexOf("ddns") >= 0) return "动态 DNS 解析与公网地址同步";
        if(key.indexOf("docker") >= 0) return "容器服务与应用运行环境";
        return "应用功能与运行入口";
    }

    function nr_appcenter_empty_state(title, browse){
        var icon = '<svg class="nr_empty_icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5" aria-hidden="true" focusable="false"><rect x="3" y="3" width="7" height="7" rx="1.5"/><rect x="14" y="3" width="7" height="7" rx="1.5"/><rect x="3" y="14" width="7" height="7" rx="1.5"/><rect x="14" y="14" width="7" height="7" rx="1.5"/></svg>';
        return '<div class="app_empty_state" role="status">'+icon+'<strong>'+nr_escape_html(title)+'</strong><span>'+
            (browse ? '前往全部应用，选择需要的工具' : '应用列表为空，可刷新后再试')+'</span>'+
            (browse ? '<button type="button" class="nr_browse_apps">浏览全部应用</button>' : '')+'</div>';
    }

    function nr_appcenter_search_empty(){
        return '<div class="nr_search_empty" role="status"><strong>没有找到匹配应用</strong><span>换个名称、版本或功能关键词试试</span><button type="button" class="nr_search_reset">清空搜索</button></div>';
    }

    var NR_APP_LIST_BUSY = false;
    var NR_APP_LIST_PENDING = false;
    var NR_APP_LIST_FEEDBACK_TIMER = null;
    function nr_list_feedback(state){
        var box = $("#nr_app_list_feedback");
        if(!box.length) return;
        if(NR_APP_LIST_FEEDBACK_TIMER) window.clearTimeout(NR_APP_LIST_FEEDBACK_TIMER);
        var message = state === "busy" ? "应用列表刷新中" : state === "error" ?
            "列表刷新失败，当前显示上次结果" : "应用列表已更新";
        box.prop("hidden", false).toggleClass("nr_app_list_error", state === "error");
        box.find(".nr_app_list_message").text(message).attr("title", message);
        box.find(".nr_app_list_retry").prop("hidden", state !== "error");
        nr_sync_toolbar_height();
        if(state === "ok") NR_APP_LIST_FEEDBACK_TIMER = window.setTimeout(function(){
            box.prop("hidden", true);
            nr_sync_toolbar_height();
        }, 2500);
    }
    function nr_refresh_app_list(){
        if(NR_APP_LIST_BUSY){ NR_APP_LIST_PENDING = true; return; }
        NR_APP_LIST_BUSY = true;
        nr_list_feedback("busy");
        $.ajax({
            type: "POST",
            url: '<%=controller%>nradioadv/system/appcenter/list',
            data: {token:'<%=token%>'},
            dataType: "json",
            timeout: 10000,
            success: function(response){
                if(!response || !response.result || !Array.isArray(response.result.applist)){
                    nr_list_feedback("error");
                    return;
                }
                try { show_app_data(response); nr_list_feedback("ok"); }
                catch(e){ nr_list_feedback("error"); }
            },
            error: function(){ nr_list_feedback("error"); },
            complete: function(){
                NR_APP_LIST_BUSY = false;
                if(NR_APP_LIST_PENDING){ NR_APP_LIST_PENDING = false; nr_refresh_app_list(); }
            }
        });
    }

    var NR_APP_STATUS_LAST = null;
    var NR_APP_STATUS_BUSY = false;
    var NR_APP_STATUS_TIMER = null;
    var NR_APP_STATUS_INTERVAL = 5000;
    var NR_APP_STATUS_EXPANDED = false;
    var NR_APP_STATUS_AUTO_EXPANDED = false;
    var NR_APP_STATUS_UPDATED_AT = "";
    var NR_APP_STATUS_STATE = "waiting";

    function nr_status_feedback(state){
        NR_APP_STATUS_STATE = state;
        var label = state === "error" ? "更新失败" : state === "busy" ? "刷新中" : state === "ok" ? "已更新" : "等待刷新";
        if(NR_APP_STATUS_UPDATED_AT && state !== "busy") label += " · " + NR_APP_STATUS_UPDATED_AT;
        $("#app_status_mount").toggleClass("nr_status_ok", state === "ok")
            .toggleClass("nr_status_busy", state === "busy").toggleClass("nr_status_error", state === "error");
        $(".app_status_time").text(label).attr("title", NR_APP_STATUS_UPDATED_AT ? "上次更新 " + NR_APP_STATUS_UPDATED_AT : label);
    }

    function nr_format_kib(kib){
        var mb = Number(kib || 0) / 1024;
        return mb >= 1024 ? (mb / 1024).toFixed(1) + " G" : mb.toFixed(0) + " M";
    }

    function nr_set_status_width(selector, value){
        var percent = Math.max(0, Math.min(100, Number(value || 0)));
        $(selector).css("width", percent.toFixed(1) + "%");
    }

    function nr_build_status_panel(data){
        var installed = 0, opened = 0, all = 0;
        if(data && data.result && data.result.applist){
            $.each(data.result.applist, function(index, db){
                all++;
                if(db.open == 1) opened++;
                if(db.status == APP_STATUS_APP_INSTALLED || db.status == APP_STATUS_APP_UPDATEED) installed++;
            });
        }
        return ''+
        '<aside class="app_status_panel">'+
        '  <div class="app_status_head"><button type="button" class="app_status_toggle" aria-expanded="false"><span>系统状态</span><em class="app_status_time">等待刷新</em><b class="app_status_toggle_text">展开</b></button></div>'+
        '  <div class="app_status_grid">'+
        '    <div class="app_status_tile"><strong>'+installed+'</strong><span>已安装</span></div>'+
        '    <div class="app_status_tile"><strong>'+opened+'</strong><span>后台</span></div>'+
        '    <div class="app_status_tile"><strong>'+all+'</strong><span>全部</span></div>'+
        '  </div>'+
        '  <div class="app_status_metric"><div class="app_status_metric_row"><span>设备最高温度</span><strong class="app_status_temp">--</strong></div><div class="app_status_bar"><span class="app_status_temp_bar"></span></div></div>'+
        '  <div class="app_status_metric"><div class="app_status_metric_row"><span>CPU 使用率</span><strong class="app_status_cpu">采样中</strong></div><div class="app_status_bar"><span class="app_status_cpu_bar"></span></div></div>'+
        '  <div class="app_status_metric"><div class="app_status_metric_row"><span>内存占用</span><strong class="app_status_mem">--</strong></div><small class="app_status_metric_detail app_status_mem_detail">-- / --</small><div class="app_status_bar"><span class="app_status_mem_bar"></span></div></div>'+
        '  <div class="app_status_metric app_status_swap_metric" style="display:none"><div class="app_status_metric_row"><span>Swap 虚拟内存</span><strong class="app_status_swap">--</strong></div><small class="app_status_metric_detail app_status_swap_detail" hidden></small><div class="app_status_bar"><span class="app_status_swap_bar"></span></div></div>'+
        '</aside>';
    }

    function nr_sync_status_panel_state(){
        var mount = $("#app_status_mount");
        mount.toggleClass("nr_status_collapsed", !NR_APP_STATUS_EXPANDED);
        mount.find(".app_status_toggle").attr("aria-expanded", NR_APP_STATUS_EXPANDED ? "true" : "false");
        mount.find(".app_status_toggle_text").text(NR_APP_STATUS_EXPANDED ? "收起" : "展开");
    }

    function nr_render_status_panel(data){
        if(!$("#app_status_mount").length) $(".container_left").before('<div id="app_status_mount"></div>');
        $("#app_status_mount").html(nr_build_status_panel(data));
        nr_sync_status_panel_state();
        if(NR_APP_STATUS_LAST) nr_update_status_panel(NR_APP_STATUS_LAST, true);
        nr_status_feedback(NR_APP_STATUS_STATE);
    }

    function nr_update_status_panel(data, cached){
        if(!data) return;
        NR_APP_STATUS_LAST = data;
        var now = new Date();
        var temp = Number(data.cpu_temp || 0);
        var cpu = data.cpu_percent;
        var memPercent = Number(data.mem_percent || 0);
        var memText = nr_format_kib(data.mem_used) + " / " + nr_format_kib(data.mem_total);
        if(!cached){
            NR_APP_STATUS_UPDATED_AT = ("0"+now.getHours()).slice(-2)+":"+("0"+now.getMinutes()).slice(-2)+":"+("0"+now.getSeconds()).slice(-2);
            nr_status_feedback("ok");
        }
        $(".app_status_temp").text(temp > 0 ? temp.toFixed(1)+" ℃" : "--");
        nr_set_status_width(".app_status_temp_bar", temp > 0 ? temp : 0);
        if(cpu === null || typeof cpu === "undefined" || cpu === ""){
            $(".app_status_cpu").text("采样中");
            nr_set_status_width(".app_status_cpu_bar", 0);
        } else {
            cpu = Number(cpu || 0);
            $(".app_status_cpu").text(cpu.toFixed(1)+"%");
            nr_set_status_width(".app_status_cpu_bar", cpu);
        }
        $(".app_status_mem").text(memPercent.toFixed(1)+"%").attr("title", memText+" · "+memPercent.toFixed(1)+"%");
        $(".app_status_mem_detail").text(memText);
        nr_set_status_width(".app_status_mem_bar", memPercent);
        var supportsSwap = data.supports_swap === true || data.supports_swap == 1 || data.is_c2000max === true || data.is_c2000max == 1 || data.model_name == "NRadio_C2000MAX" || data.model == "NRadio_C2000MAX" || data.model_name == "NRadio_C2000Ultra" || data.model == "NRadio_C2000Ultra";
        if(supportsSwap){
            if(!NR_APP_STATUS_AUTO_EXPANDED){
                NR_APP_STATUS_AUTO_EXPANDED = true;
                NR_APP_STATUS_EXPANDED = true;
                nr_sync_status_panel_state();
            }
            var swapTotal = Number(data.swap_total || 0);
            var swapUsed = Number(data.swap_used || 0);
            var swapPercent = Number(data.swap_percent || 0);
            $(".app_status_swap_metric").show();
            $(".app_status_swap").text(swapTotal > 0 ? swapPercent.toFixed(1)+"%" : "未启用");
            $(".app_status_swap_detail").text(swapTotal > 0 ? nr_format_kib(swapUsed)+" / "+nr_format_kib(swapTotal) : "").prop("hidden", swapTotal <= 0);
            nr_set_status_width(".app_status_swap_bar", swapPercent);
        } else {
            $(".app_status_swap_metric").hide();
        }
    }

    function nr_get_system_status(){
        if(document.hidden || NR_APP_STATUS_BUSY) return;
        NR_APP_STATUS_BUSY = true;
        nr_status_feedback("busy");
        $.ajax({
            type: "POST",
            url: '<%=controller%>nradioadv/system/appcenter/sys_status',
            data: {token:'<%=token%>'},
            dataType: "json",
            timeout: 10000,
            success: function(response){
                if(response && response.result && typeof response.result === "object") nr_update_status_panel(response.result);
                else nr_status_feedback("error");
            },
            error: function(){ nr_status_feedback("error"); },
            complete: function(){ NR_APP_STATUS_BUSY = false; }
        });
    }

    function nr_start_status_polling(){
        nr_get_system_status();
        if(NR_APP_STATUS_TIMER) window.clearInterval(NR_APP_STATUS_TIMER);
        NR_APP_STATUS_TIMER = window.setInterval(nr_get_system_status, NR_APP_STATUS_INTERVAL);
    }

    function nr_update_app_count(){
        var active = $(".container_right:not(.hide)");
        var total = active.find(".app_box").length;
        var visible = active.find(".app_box:not(.nr_app_filtered)").length;
        $("#nr_app_search_count").text(visible+" / "+total).attr("title", "当前显示 "+visible+" 个，共 "+total+" 个应用");
        return {total:total, visible:visible};
    }

    function nr_update_menu_counts(data){
        var installed = 0;
        var all = 0;
        if(data && data.result && data.result.applist){
            $.each(data.result.applist, function(index, db){
                all++;
                if(db.status == APP_STATUS_APP_INSTALLED || db.status == APP_STATUS_APP_UPDATEED) installed++;
            });
        }
        var menus = $(".container_left .app_menu");
        menus.find(".nr_menu_count").remove();
        menus.eq(0).append('<span class="nr_menu_count">'+installed+'</span>');
        menus.eq(1).append('<span class="nr_menu_count">'+all+'</span>');
    }

    function nr_mark_expandable_text(){
        $(".container_right:not(.hide) .app_name, .container_right:not(.hide) .app_version, .container_right:not(.hide) .app_des").each(function(){
            var expanded = this.classList.contains("nr_text_expanded") || this.classList.contains("nr_desc_expanded");
            var clipped = expanded || this.scrollWidth > this.clientWidth + 1 || this.scrollHeight > this.clientHeight + 1;
            $(this).toggleClass("nr_text_expandable", clipped);
            if(clipped){
                var label = this.classList.contains("app_des") ? "应用说明" : this.classList.contains("app_version") ? "版本" : "应用名称";
                $(this).attr({role:"button", tabindex:"0", "aria-expanded":expanded ? "true" : "false",
                    "aria-label":(expanded ? "收起" : "展开")+label+"："+($(this).attr("data-nr-text") || "")});
            } else $(this).removeAttr("role tabindex aria-expanded aria-label");
        });
    }

    function nr_apply_app_search(){
        var query = $.trim($("#nr_app_search_input").val() || "").toLowerCase();
        var active = $(".container_right:not(.hide)");
        active.find(".nr_search_empty").remove();
        active.find(".app_box").each(function(){
            var text = ($(this).attr("data-search") || $(this).text()).toLowerCase();
            $(this).toggleClass("nr_app_filtered", query.length > 0 && text.indexOf(query) < 0);
            $(this).find("[data-nr-text]").each(function(){
                $(this).html(nr_highlight_text($(this).attr("data-nr-text"), query));
            });
        });
        $(".nr_app_search").toggleClass("nr_searching", query.length > 0);
        $("#nr_app_search_clear").attr("aria-hidden", query.length > 0 ? "false" : "true").attr("tabindex", query.length > 0 ? "0" : "-1");
        var count = nr_update_app_count();
        if(query.length > 0 && count.total > 0 && count.visible === 0) active.append(nr_appcenter_search_empty());
        nr_mark_expandable_text();
    }

    function show_app_data(data){
        data = data || {result:{applist:[]}};
        if(!data.result) data.result = {applist:[]};
        if(!data.result.applist) data.result.applist = [];
        var htm = "";
        var htm_installed = "";
        var old_scroller = document.querySelector("#app_top_menu .nr_tabs_scroller");
        var old_scroll = old_scroller ? old_scroller.scrollLeft : 0;
        var active_name = NR_ACTIVE_APP_NAME, active_index = null;
        var store_label = NR_APP_TOP_NAV ? "<%:应用列表%>" : "<%:AppCenterTitle%>";
        var top_menu_ht = '<button type="button" class="top_menu nr_store_tab top_menu_active" aria-current="page">'+nr_escape_html(store_label)+'</button><button type="button" class="nr_tabs_nav nr_tabs_prev" aria-label="向左查看已打开应用" title="向左查看已打开应用">‹</button><div class="nr_tabs_viewport"><div class="nr_tabs_scroller" role="navigation" aria-label="已打开的应用">';
        $.each(data.result.applist, function(index, db){
            var optht = '';
            var icon_name = db.icon && db.icon.length ? db.icon : "app_default.png";
            var open_route = db.luci_module_route || "";
            var translated_name = db.name_lng && db.name_lng.length ? db.name_lng : "";
            NR_APP_DISPLAY_NAMES[(db.name || "").toLowerCase()] = translated_name || db.name || "";
            var display_name = nr_appcenter_display_name(db.name, translated_name);
            var display_version = nr_appcenter_display_version(db.name, db.version);
            var des_info = db.description_lng && db.description_lng.length ? db.description_lng :
                (db.des && db.des.length ? db.des : nr_appcenter_desc_fallback(db.name));
            var status_label = "未知";
            var open_badge = "";
            var icon_fallback = "this.onerror=null;this.src='/luci-static/nradio/images/icon/app_default.png';";
            var open_ht = '<li class="action_list_li nr_action_open" role="button" tabindex="0" onclick="app_action(\''+db.name+'\',\'open\',\''+index+'\',\''+open_route+'\')"><%:AppOpen%></li>';
            if(db.open == 1){
                if(db.name === active_name) active_index = index;
                top_menu_ht += '<div class="top_menu_inner" data-app-name="'+nr_escape_html(db.name)+'"><span class="top_menu" role="button" tabindex="0" data-index="'+index+'" title="'+nr_escape_html(display_name)+'" onclick="'+nr_escape_html("callback("+JSON.stringify(String(index))+","+JSON.stringify(open_route)+")")+'"><img class="nr_top_icon" src="/luci-static/nradio/images/icon/'+nr_escape_html(icon_name)+'?v='+encodeURIComponent(NR_APP_ICON_CACHE_TAG)+'" alt="" onerror="'+nr_escape_html(icon_fallback)+'"><span class="nr_top_name">'+nr_escape_html(display_name)+'</span></span><button type="button" aria-label="'+nr_escape_html("关闭 "+display_name)+'" title="'+nr_escape_html("关闭 "+display_name)+'" onclick="'+nr_escape_html("app_action("+JSON.stringify(db.name)+",\"close\")")+'" class="top_menu_inner_icon">×</button></div>';
                open_ht = '<li class="action_list_li nr_action_open" role="button" tabindex="0" onclick="callback(\''+index+'\',\''+open_route+'\')"><%:AppOpen%></li>';
                open_badge = '<span class="app_open_badge">后台</span>';
            }
            if(db.has_luci != 1) open_ht = '';
            if(db.status == APP_STATUS_APP_NEW){
                status_label = "未安装";
                optht = '<li class="action_list_li nr_action_install" role="button" tabindex="0" onclick="app_action(\''+db.name+'\',\'install\')"><%:AppInstall%></li>';
            } else if(db.status == APP_STATUS_APP_INSTALLED){
                status_label = "已安装";
                optht = '<li class="action_list_li nr_action_uninstall" role="button" tabindex="0" onclick="app_action(\''+db.name+'\',\'uninstall\')"><%:AppUninstall%></li>'+open_ht;
            } else if(db.status == APP_STATUS_APP_UPDATEED){
                status_label = "可更新";
                optht = '<li class="action_list_li nr_action_update" role="button" tabindex="0" onclick="app_action(\''+db.name+'\',\'update\')"><%:AppUpdate%></li><li class="action_list_li nr_action_uninstall" role="button" tabindex="0" onclick="app_action(\''+db.name+'\',\'uninstall\')"><%:AppUninstall%></li>'+open_ht;
            }
            var row = APPTableRow.compose({
                name: db.name,
                display_name: nr_escape_html(display_name),
                version: nr_escape_html(db.version),
                display_version: nr_escape_html(display_version),
                des: nr_escape_html(des_info),
                search_text: nr_escape_html([db.name,display_name,db.version,des_info].join(" ")),
                icon: nr_escape_html(icon_name),
                icon_cache_tag: NR_APP_ICON_CACHE_TAG,
                icon_fallback: nr_escape_html(icon_fallback),
                opt: optht,
                index: index,
                status: db.status,
                status_label: status_label,
                open_badge: open_badge
            });
            if(db.status == APP_STATUS_APP_INSTALLED || db.status == APP_STATUS_APP_UPDATEED) htm_installed += row;
            htm += row;
        });
        if(!htm_installed) htm_installed = nr_appcenter_empty_state("暂无已安装应用", true);
        if(!htm) htm = nr_appcenter_empty_state("暂无应用");
        $("#app_top_menu").removeClass("nr_tabs_overflow").html(top_menu_ht + '</div></div><button type="button" class="nr_tabs_nav nr_tabs_next" aria-label="向右查看已打开应用" title="向右查看已打开应用">›</button>');
        var scroller = document.querySelector("#app_top_menu .nr_tabs_scroller");
        scroller.scrollLeft = old_scroll;
        scroller.addEventListener("scroll", nr_update_tab_edges);
        nr_sync_top_tabs(active_index, false);
        $(".app_all").html(htm);
        $(".app_installed").html(htm_installed);
        nr_update_menu_counts(data);
        $(".container_left .app_menu, .app_btn_group .app_btn_class").attr("role", "button").attr("tabindex", "0");
        nr_render_status_panel(data);
        nr_apply_app_search();
    }

    $(document).on("input", "#nr_app_search_input", nr_apply_app_search);
    $(document).on("click", "#nr_app_search_clear, .nr_search_reset", function(){
        $("#nr_app_search_input").val("").focus();
        nr_apply_app_search();
    });
    $(document).on("click", "#nr_app_list_feedback .nr_app_list_retry", nr_refresh_app_list);
    $(document).on("click", ".nr_browse_apps", function(){
        $("#nr_app_search_input").val("");
        var all_menu = $(".container_left .app_menu").eq(1);
        all_menu.trigger("click").focus();
        nr_apply_app_search();
    });
    $(document).on("click", ".container_right .nr_text_expandable", function(){
        var expanded_class = this.classList.contains("app_des") ? "nr_desc_expanded" : "nr_text_expanded";
        $(this).toggleClass(expanded_class, !this.classList.contains(expanded_class));
        nr_mark_expandable_text();
    });
    $(document).on("click", "#app_top_menu .nr_store_tab", function(){
        if(typeof sub_dialogDeal !== "undefined" && sub_dialogDeal) sub_dialogDeal.close();
        nr_sync_top_tabs(null, false);
    });
    $(document).on("click", "#app_top_menu .nr_tabs_nav", function(){
        var scroller = document.querySelector("#app_top_menu .nr_tabs_scroller");
        if(!scroller || this.disabled) return;
        var direction = this.classList.contains("nr_tabs_prev") ? -1 : 1;
        scroller.scrollLeft += direction * Math.max(160, Math.round(scroller.clientWidth * .7));
        nr_update_tab_edges();
    });
    window.addEventListener("resize", function(){ nr_update_tab_edges(true); nr_mark_expandable_text(); });
    window.addEventListener("load", function(){ nr_update_tab_edges(true); nr_mark_expandable_text(); });
    $(document).on("click", ".app_menu", function(){ window.setTimeout(nr_apply_app_search, 0); });
    $(document).on("click", ".app_status_toggle", function(){
        NR_APP_STATUS_EXPANDED = !NR_APP_STATUS_EXPANDED;
        nr_sync_status_panel_state();
    });
    $(document).on("keydown", "#nr_app_search_input", function(event){
        if(event.key === "Escape"){
            $(this).val("");
            nr_apply_app_search();
            event.preventDefault();
        }
    });
    $(document).on("keydown", ".action_list_li, .app_menu, .app_btn_class, .app_des[role='button'], .nr_text_expandable, #app_top_menu .top_menu[role='button']", function(event){
        if(event.key === "Enter" || event.key === " "){
            event.preventDefault();
            $(this).trigger("click");
        }
    });
    document.addEventListener("visibilitychange", function(){ if(!document.hidden) nr_get_system_status(); });

EOF_APPCENTER_V3_JS

    cat > "$v3_lua" <<'EOF_APPCENTER_V3_LUA'
local tpl_path, css_path, js_path, icon_cache_tag, top_nav_model = arg[1], arg[2], arg[3], arg[4], arg[5]
assert(tpl_path and css_path and js_path and icon_cache_tag, "missing transform arguments")
assert(icon_cache_tag:match("^[%w._-]+$"), "invalid icon cache tag")
assert(top_nav_model == "0" or top_nav_model == "1", "invalid top navigation model flag")

local function read_all(path)
    local file = assert(io.open(path, "rb"), "open failed: " .. path)
    local data = file:read("*a")
    file:close()
    return data
end

local html = read_all(tpl_path)
local css = read_all(css_path)
local renderer = read_all(js_path)
local icon_marker_count
renderer, icon_marker_count = renderer:gsub("__NR_ICON_CACHE_TAG__", icon_cache_tag)
assert(icon_marker_count == 1, "icon cache tag marker not found")
local top_nav_marker_count
renderer, top_nav_marker_count = renderer:gsub("__NR_TOP_NAV_MODEL__", top_nav_model)
assert(top_nav_marker_count == 1, "top navigation model marker not found")

local function strip_style_from(marker)
    local start_pos = html:find(marker, 1, true)
    if not start_pos then return end
    local end_pos = assert(html:find("</style>", start_pos, true), "style close not found for " .. marker)
    html = html:sub(1, start_pos - 1) .. html:sub(end_pos)
end

strip_style_from("    /* NRadio appcenter v3: begin */")
strip_style_from("    /* NRadio appcenter card polish: visual-only layer */")

html = html:gsub("[ \t]*<div id=\"app_status_mount\"></div>\r\n", "")
html = html:gsub("[ \t]*<div id=\"app_status_mount\"></div>\n", "")
html = html:gsub("[ \t]*<div class=\"nr_app_search\">.-</div>\r\n", "")
html = html:gsub("[ \t]*<div class=\"nr_app_search\">.-</div>\n", "")
html = html:gsub("[ \t]*<div id=\"nr_app_list_feedback\".-</div>\r\n", "")
html = html:gsub("[ \t]*<div id=\"nr_app_list_feedback\".-</div>\n", "")

local style_close = assert(html:find("</style>", 1, true), "style close not found")
html = html:sub(1, style_close - 1) .. css .. "\n" .. html:sub(style_close)

local toolbar_anchor = '        <div class="app_btn_group">'
local toolbar_pos = assert(html:find(toolbar_anchor, 1, true), "toolbar anchor not found")
local storage_anchor = '        <div class="mem_track'
local storage_pos = assert(html:find(storage_anchor, 1, true), "storage anchor not found")
local storage_markup = [[        <div class="mem_track nr-storage-track">
            <div class="nr-storage-row nr-storage-system-row">
                <div class="mem_header">
                    <span>系统空间</span>
                    <span id="memory_detail">-- / --</span>
                </div>
                <div class="mem_progress">
                    <div class="mem_progress_inner" id="memory_progress_inner"></div>
                </div>
            </div>
            <div class="nr-storage-row nr-storage-expand-row" id="storage_expand_memory_row">
                <div class="mem_header">
                    <span>存储扩展</span>
                    <span id="storage_expand_memory_detail">-- / --</span>
                </div>
                <div class="mem_progress">
                    <div class="mem_progress_inner" id="storage_expand_memory_progress_inner"></div>
                </div>
            </div>
        </div>
]]
html = html:sub(1, storage_pos - 1) .. storage_markup .. html:sub(toolbar_pos)
toolbar_pos = assert(html:find(toolbar_anchor, storage_pos, true), "toolbar anchor not found after storage rebuild")
local search_markup = '        <div class="nr_app_search"><input id="nr_app_search_input" type="search" autocomplete="off" aria-label="搜索应用" placeholder="搜索应用、版本或功能"><button id="nr_app_search_clear" class="nr_app_search_clear" type="button" aria-label="清除搜索" aria-hidden="true" tabindex="-1" title="清除搜索">×</button><span id="nr_app_search_count" class="nr_app_search_count" aria-live="polite">0 / 0</span></div>\n'
html = html:sub(1, toolbar_pos - 1) .. search_markup .. html:sub(toolbar_pos)
toolbar_pos = assert(html:find(toolbar_anchor, toolbar_pos, true), "toolbar anchor not found after search insertion")
local toolbar_close = assert(html:find("\n    </div>\n", toolbar_pos, true), "toolbar close not found")
local feedback_markup = '\n        <div id="nr_app_list_feedback" class="nr_app_list_feedback" role="status" aria-live="polite" hidden><span class="nr_app_list_message"></span><button type="button" class="nr_app_list_retry" hidden>重试</button></div>'
html = html:sub(1, toolbar_close - 1) .. feedback_markup .. html:sub(toolbar_close)

local menu_anchor = '    <div class="container_left">'
local menu_pos = assert(html:find(menu_anchor, 1, true), "menu anchor not found")
html = html:sub(1, menu_pos - 1) .. '    <div id="app_status_mount"></div>\n' .. html:sub(menu_pos)

local row_start = assert(html:find("    var APPTableRow = ''+", 1, true), "APPTableRow start not found")
local error_start = assert(html:find("    var APPErrorRow = ''+", row_start, true), "APPErrorRow start not found")
local row = [[    var APPTableRow = ''+
    '<div class="app_box app_item{{index}}" data-status="{{status}}" data-search="{{search_text}}">'+
        '    <div class="app_icon"><img class="app_icon_img" src="/luci-static/nradio/images/icon/{{icon}}?v={{icon_cache_tag}}" alt="" onerror="{{icon_fallback}}"></div>'+
        '    <div class="app_info">'+
        '        <div class="app_title">'+
        '            <div class="app_name" title="{{display_name}}" data-nr-text="{{display_name}}">{{display_name}}</div>'+
        '            <div class="app_version" title="{{version}}" data-nr-text="{{display_version}}">{{display_version}}</div>'+
        '            <div class="app_meta_row"><span class="app_state_badge app_state_{{status}}">{{status_label}}</span>{{open_badge}}</div>'+
        '        </div>'+
        '        <div class="app_des" title="{{des}}" data-nr-text="{{des}}">{{des}}</div>'+
        '    </div>'+
        '    <div class="app_action"><ul class="action_list">{{opt}}</ul></div>'+
        '</div>';

]]
html = html:sub(1, row_start - 1) .. row .. html:sub(error_start)

local show_start = assert(html:find("    function show_app_data(data){", 1, true), "show_app_data start not found")
local loading_start = assert(html:find("    var loading_htm = ", show_start, true), "loading_htm start not found")
html = html:sub(1, show_start - 1) .. renderer .. html:sub(loading_start)

local refresh_start = assert(html:find("    function refresh_data(){", 1, true), "refresh_data start not found")
local refresh_end = assert(html:find('\n    $(".app_menu").click', refresh_start, true), "refresh_data end not found")
html = html:sub(1, refresh_start - 1) .. '    function refresh_data(){ nr_refresh_app_list(); }' .. html:sub(refresh_end)

loading_start = assert(html:find("    var loading_htm = ", 1, true), "loading_htm start not found after renderer")
local loading_end = assert(html:find("\n", loading_start, true), "loading_htm end not found")
local loading_markup = [[    var loading_htm = nr_appcenter_loading("", "");]]
html = html:sub(1, loading_start - 1) .. loading_markup .. html:sub(loading_end)

local function replace_plain(text, old, new)
    local pos = 1
    while true do
        local first, last = text:find(old, pos, true)
        if not first then return text end
        text = text:sub(1, first - 1) .. new .. text:sub(last + 1)
        pos = first + #new
    end
end

local function polish_function(name, changes)
    local first = assert(html:find("    function " .. name .. "(", 1, true), "function not found: " .. name)
    local last = html:find("\n    function ", first + 1, true) or html:find("\n</script>", first, true)
    local body = html:sub(first, last - 1)
    for _, change in ipairs(changes) do body = replace_plain(body, change[1], change[2]) end
    html = html:sub(1, first - 1) .. body .. html:sub(last)
end

polish_function("app_action", {
    {"message: loading_htm", "message: nr_appcenter_loading(action, app_name)"},
    {"dialogDeal.setMessage(loading_htm);", "dialogDeal.setTitle(nr_escape_html(nr_operation_title(action, app_name))); dialogDeal.setMessage(nr_appcenter_loading(action, app_name));"}
})
polish_function("import_pkg", {
    {"cssClass: 'list-dialog dialog_box',", "cssClass: 'list-dialog dialog_box nr_import_dialog',"},
    {'type="submit" value="<%:APPImportBTn%>"', 'type="submit" disabled="disabled" value="<%:APPImportBTn%>"'}
})
polish_function("check_upload", {
    {"var data = {};", 'var data = {};\n        var upload_check_id = ++NR_UPLOAD_CHECK_SEQ;\n        var upload_button = $("#import_box_file input[type=submit]");\n        var note = $(obj).closest(".cbi-value").find(".note_info");\n        upload_button.prop("disabled", true);\n        note.text("");'},
    {"if (!obj.files){", "if (!obj.files || !obj.files.length){"},
    {"var filestatus = null;", "if(upload_check_id !== NR_UPLOAD_CHECK_SEQ || !obj.files || !obj.files.length) return;\n            var filestatus = null;"},
    {'$("input[type=submit]")', 'upload_button'},
    {'$(obj).parent().children(".note_info")', 'note'}
})
assert(html:find("cssClass: 'list-dialog dialog_box nr_import_dialog',", 1, true), "import dialog class not found")
assert(html:find('type="submit" disabled="disabled" value="<%:APPImportBTn%>"', 1, true), "initial upload button state not found")
assert(html:find("if (!obj.files || !obj.files.length){", 1, true), "empty file guard not found")
local check_start = assert(html:find("    function check_version(){", 1, true), "check_version start not found")
local check_end = assert(html:find("\n    function check_upload(", check_start, true), "check_version end not found")
html = html:sub(1, check_start - 1) .. "    function check_version(){ nr_check_appstore_version(); }\n" .. html:sub(check_end)
polish_function("request_result", {
    {'check_dial.setMessage(err_info);', 'nr_appcenter_result(check_dial, code == APPCENTER_OK, action, name, err_info);'},
    {'check_dial.setMessage("<%:APPErrorTimeout%>");', 'nr_appcenter_result(check_dial, false, action, name, "<%:APPErrorTimeout%>");'}
})
local poll_start = assert(html:find("    function request_appstore_result(", 1, true), "appstore polling start not found")
local poll_end = assert(html:find("\n    function process_deal(", poll_start, true), "appstore polling end not found")
html = html:sub(1, poll_start - 1) .. "    function request_appstore_result(){ nr_request_appstore_check(NR_APP_CHECK, false); }\n" .. html:sub(poll_end)
polish_function("process_deal", {
    {'refresh_data();', 'if(dialogDeal && !callback) nr_appcenter_result(dialogDeal, true, action, name, nr_escape_html(msg)); refresh_data();'},
    {'var htm = genarate_loading_box(error_info,0);', 'var htm = nr_appcenter_loading(action, name);'},
    {"title: '',", 'title: nr_escape_html(nr_operation_title(action, name)),'},
    {'message: \'<i class="far fa-nradio-note fa-fw icon_disable" ></i>\'+error_info,', 'message: nr_result_markup(false, nr_escape_html(error_info)),'},
    {'if(dialogDeal){\n                    setTimeout(function(){ dialogDeal.close();if(callback)callback(id,route);}, 1000);\n                }', 'if(dialogDeal && (code != 0 || callback)){\n                    setTimeout(function(){ dialogDeal.close(); if(code == 0 && action == "open" && callback) callback(id,route); }, 1000);\n                }'}
})
assert(html:find('if(dialogDeal && (code != 0 || callback))', 1, true), "persistent operation result not found")
polish_function("show_error", {
    {'daillog.setMessage(err_info);', 'nr_appcenter_result(daillog, result.code == APPCENTER_OK, "install", "", err_info);'},
    {'message:err_info,', 'message:nr_result_markup(result.code == APPCENTER_OK, err_info),'},
    {"title: '',", 'title: result.code == APPCENTER_OK ? "安装完成" : "安装失败",'}
})

local ready_count
html, ready_count = html:gsub("        get_memory%(%)%;", "        get_memory();\n        nr_init_topnav_layout();\n        nr_init_sticky_toolbar();\n        nr_start_status_polling();", 1)
assert(ready_count == 1, "document ready hook not found")
html = html:gsub("9%.9 G / 99%.9 G", "-- / --"):gsub("0%.0 G / 0%.0 G", "-- / --")

local tmp_path = tpl_path .. ".nradio-v3.tmp"
local output = assert(io.open(tmp_path, "wb"), "create failed: " .. tmp_path)
output:write(html)
output:close()
assert(os.rename(tmp_path, tpl_path), "atomic template replace failed")
EOF_APPCENTER_V3_LUA

    lua "$v3_lua" "$TPL" "$v3_css" "$v3_js" "${SCRIPT_RELEASE_DATE}-${SCRIPT_VERSION}" "$v3_top_nav_model" || die "应用商店 V3 模板重构失败"
    chmod 644 "$TPL" 2>/dev/null || true

    grep -Fq 'NRadio appcenter v3: begin' "$TPL" 2>/dev/null || die "应用商店 V3 CSS 校验失败"
    grep -Fq 'id="nr_app_search_input"' "$TPL" 2>/dev/null || die "应用商店 V3 搜索框校验失败"
    grep -Fq 'function nr_start_status_polling()' "$TPL" 2>/dev/null || die "应用商店 V3 状态刷新校验失败"
    grep -Fq 'NR_APP_STATUS_INTERVAL = 5000' "$TPL" 2>/dev/null || die "应用商店 V3 采样间隔校验失败"
    grep -Fq 'NR_APP_STATUS_AUTO_EXPANDED = true' "$TPL" 2>/dev/null || die "应用商店 V3 C2000MAX / C2000Ultra 状态自动展开校验失败"
    grep -Fq '<span>Swap 虚拟内存</span>' "$TPL" 2>/dev/null || die "应用商店 V3 C2000MAX / C2000Ultra Swap 标签校验失败"
    grep -Fq 'app_state_badge app_state_{{status}}' "$TPL" 2>/dev/null || die "应用商店 V3 状态徽标校验失败"
    grep -Fq 'function nr_apply_app_search()' "$TPL" 2>/dev/null || die "应用商店 V3 搜索逻辑校验失败"
    grep -Fq 'id="nr_app_search_clear"' "$TPL" 2>/dev/null || die "应用商店 V3 搜索清除按钮校验失败"
    grep -Fq 'cssClass: '"'"'list-dialog dialog_box nr_import_dialog'"'"'' "$TPL" 2>/dev/null || die "应用商店 V3 手动安装弹窗校验失败"
    grep -Fq 'icon_cache_tag: NR_APP_ICON_CACHE_TAG' "$TPL" 2>/dev/null || die "应用商店 V3 图标缓存参数校验失败"
    grep -Fq 'class="nr_search_empty"' "$TPL" 2>/dev/null || die "应用商店 V3 搜索空状态校验失败"
    grep -Fq 'class="top_menu_inner_icon">×</button>' "$TPL" 2>/dev/null || die "应用商店 V3 顶部关闭按钮校验失败"
    grep -Fq 'class="mem_track nr-storage-track"' "$TPL" 2>/dev/null || die "应用商店 V3 双空间容器校验失败"
    grep -Fq 'id="storage_expand_memory_row"' "$TPL" 2>/dev/null || die "应用商店 V3 存储扩展条校验失败"
}

lightweight_appcenter_model_supported() {
    case "$(detect_current_nradio_model_quiet 2>/dev/null || true)" in
        NRadio_C2000Pro|NRadio_AK68-798) return 0 ;;
    esac
    return 1
}

install_lightweight_appcenter() {
    lightweight_appcenter_model_supported || die "轻量应用商店当前仅支持 C2000Pro / AK68-798"
    if is_current_model_ak798; then
        ensure_ak798_compat_appcenter
        return 0
    fi
    if is_c2000pro_appcenter_environment; then
        log_stage 1 5 "检查 C2000Pro 兼容应用商店环境"
        ensure_c2000pro_compat_appcenter

        log_stage 2 5 "写入应用商店异步卸载接口"
        write_plugin_uninstall_assets

        log_stage 3 5 "统一刷新插件图标"
        install_unified_appcenter_icons || die "应用商店统一图标写入失败"

        log_stage 4 5 "刷新 LuCI 与应用商店缓存"
        refresh_luci_appcenter
        /etc/init.d/uhttpd reload >/dev/null 2>&1 || true

        log_stage 5 5 "校验 C2000Pro 兼容应用商店入口"
        verify_c2000pro_compat_appcenter
        verify_luci_route "nradioadv/system/appcenter" "C2000Pro 兼容应用商店"

        log "C2000Pro 兼容应用商店层已创建/刷新"
        log "入口: nradioadv/system/appcenter"
        return 0
    fi
    die "未检测到 C2000Pro / AK68-798 轻量应用商店环境"
}

install_appcenter_polish() {
    if lightweight_appcenter_model_supported; then
        die "完整应用商店美化适用于原厂完整商店；C2000Pro / AK68-798 请使用 4 > 4 > 1"
    fi

    log_stage 1 5 "检查 NRadio 应用商店模板"
    require_nradio_oem_appcenter
    verify_file_exists "$TPL" "NRadio 应用商店模板"

    log_stage 2 5 "更新应用商店页面与系统状态"
    write_plugin_uninstall_assets
    write_original_appcenter_template
    patch_common_template
    patch_appcenter_status_controller
    patch_appcenter_card_polish_v3
    case "${CURRENT_DETECTED_MODEL:-}" in
        NRadio_C8-688|NRadio_C5800-650|NRadio_C5800-688|NRadio_NBCPE)
            patch_appcenter_storage_expand_display
            ;;
    esac

    log_stage 3 5 "统一刷新插件图标"
    install_unified_appcenter_icons || die "应用商店统一图标写入失败"

    log_stage 4 5 "刷新 LuCI 与应用商店缓存"
    refresh_luci_appcenter
    /etc/init.d/uhttpd reload >/dev/null 2>&1 || true

    log_stage 5 5 "校验应用商店页面"
    verify_file_exists "/usr/libexec/nradio-ai-compat.sh" "鲲鹏智能体兼容助手"
    grep -Fq 'NRadio appcenter AI post-install compatibility v1' "$APPCENTER_CONTROLLER" || die "鲲鹏智能体安装后兼容钩子校验失败"
    grep -Fq 'AI_ROUTE_DYNAMIC_V1' "$APPCENTER_CONTROLLER" || die "鲲鹏智能体应用商店动态路由回退校验失败"
    verify_luci_route "nradioadv/system/appcenter" "应用商店美化"

    log "应用商店 V3 更新完成"
}

copy_factory_appcenter_file() {
    factory_src="$1"
    factory_dst="$2"
    factory_label="$3"
    factory_tmp_dst="${factory_dst}.factory.$$"

    [ -f "$factory_src" ] || die "${factory_label}原厂源文件不存在: $factory_src"
    [ -s "$factory_src" ] || die "${factory_label}原厂源文件为空: $factory_src"

    mkdir -p "$(dirname "$factory_dst")" || die "创建${factory_label}目录失败"
    rm -f "$factory_tmp_dst" 2>/dev/null || true
    cp "$factory_src" "$factory_tmp_dst" || {
        rm -f "$factory_tmp_dst" 2>/dev/null || true
        die "暂存${factory_label}失败"
    }
    chmod 644 "$factory_tmp_dst" 2>/dev/null || true
    mv -f "$factory_tmp_dst" "$factory_dst" || {
        rm -f "$factory_tmp_dst" 2>/dev/null || true
        die "写入${factory_label}失败"
    }
}

write_original_appcenter_template() {
    copy_factory_appcenter_file \
        "/rom/usr/lib/lua/luci/view/nradio_appcenter/appcenter.htm" \
        "$TPL" \
        "原厂应用商店模板"
}

write_original_appcenter_controller() {
    copy_factory_appcenter_file \
        "/rom/usr/lib/lua/luci/controller/nradio_adv/appcenter.lua" \
        "$APPCENTER_CONTROLLER" \
        "原厂应用商店控制器"
}

remove_lightweight_appcenter() {
    lightweight_appcenter_model_supported || die "轻量应用商店当前仅支持 C2000Pro / AK68-798"
    if is_current_model_ak798; then
        remove_ak798_compat_appcenter
        return 0
    fi
    if is_c2000pro_appcenter_environment; then
        log_stage 1 4 "检查 C2000Pro 兼容应用商店层"

        log_stage 2 4 "移除脚本生成的 C2000Pro 兼容文件"
        remove_c2000pro_compat_appcenter

        log_stage 3 4 "刷新 LuCI 与应用商店缓存"
        refresh_luci_appcenter
        rm -f /usr/libexec/nradio-ai-compat.sh 2>/dev/null || true
        /etc/init.d/uhttpd reload >/dev/null 2>&1 || true

        log_stage 4 4 "确认插件记录保留"
        if [ -f "$CFG" ]; then
            log "保留: $CFG"
        else
            log "提示: 当前没有 $CFG，未发现可保留的插件记录"
        fi
        log "C2000Pro 兼容应用商店层已移除"
        return 0
    fi
    die "未检测到 C2000Pro / AK68-798 轻量应用商店环境"
}

restore_appcenter_original() {
    if lightweight_appcenter_model_supported; then
        die "完整应用商店还原适用于原厂完整商店；C2000Pro / AK68-798 请使用 4 > 4 > 2"
    fi

    log_stage 1 4 "检查 NRadio 应用商店原厂还原环境"
    require_nradio_oem_appcenter

    log_stage 2 4 "直接回写原厂应用商店文件"
    write_original_appcenter_template
    write_original_appcenter_controller

    log_stage 3 4 "刷新 LuCI 与应用商店缓存"
    refresh_luci_appcenter
    rm -f /usr/libexec/nradio-ai-compat.sh 2>/dev/null || true
    /etc/init.d/uhttpd reload >/dev/null 2>&1 || true

    log_stage 4 4 "校验应用商店入口"
    verify_file_exists "$TPL" "NRadio 应用商店模板"
    verify_file_exists "$APPCENTER_CONTROLLER" "NRadio 应用商店控制器"
    verify_luci_route "nradioadv/system/appcenter" "应用商店还原"

    log "应用商店已还原为 /rom 原厂模板和控制器"
    log "入口: nradioadv/system/appcenter"
}

refresh_luci_appcenter() {
    # Third-party app updates may restore ai.lua and reintroduce a missing has_ai() crash.
    # Re-apply the guarded call before rebuilding the LuCI dispatcher cache.
    fix_nradio_ai_has_ai_compat
    rm -f /tmp/luci-indexcache /tmp/infocd/cache/appcenter 2>/dev/null || true
    rm -f /tmp/luci-modulecache/* 2>/dev/null || true
    /etc/init.d/infocd restart >/dev/null 2>&1 || true
    /etc/init.d/appcenter restart >/dev/null 2>&1 || true
    sleep 2
}

quiesce_service() {
    init_script="$1"
    [ -f "$init_script" ] || return 0
    "$init_script" stop >/dev/null 2>&1 || true
    "$init_script" disable >/dev/null 2>&1 || true
}

enable_init_service_strict() {
    init_script="$1"
    service_label="${2:-$(basename "$init_script")}"
    [ -x "$init_script" ] || {
        log "错误: 缺少 $service_label 启动脚本: $init_script"
        return 1
    }

    "$init_script" disable >/dev/null 2>&1 || true
    "$init_script" enable >/dev/null 2>&1 || {
        log "错误: $service_label 设置开机启动失败"
        return 1
    }

    service_name="$(basename "$init_script")"
    for service_link in /etc/rc.d/S[0-9][0-9]"$service_name"; do
        [ -L "$service_link" ] && return 0
    done
    log "错误: $service_label 未生成有效的 /etc/rc.d 启动链接"
    return 1
}

restart_init_service_strict() {
    init_script="$1"
    service_label="${2:-$(basename "$init_script")}"
    "$init_script" restart >/dev/null 2>&1 || {
        log "错误: $service_label 重启失败"
        return 1
    }
    return 0
}

procfs_hides_other_users() {
    awk '$2 == "/proc" {
        found = 1
        count = split($4, opts, ",")
        for (i = 1; i <= count; i++) {
            if (opts[i] == "hidepid=1" || opts[i] == "hidepid=2" || opts[i] == "hidepid=invisible") exit 0
        }
        exit 1
    }
    END { if (!found) exit 1 }' /proc/mounts 2>/dev/null
}

require_private_procfs_for_secret_argv() {
    secret_label="${1:-敏感参数}"
    procfs_hides_other_users && return 0
    mount -o remount,hidepid=2 /proc >/dev/null 2>&1 || {
        log "错误: 无法为 $secret_label 启用 /proc hidepid=2，拒绝把密钥放入进程参数"
        return 1
    }
    procfs_hides_other_users || {
        log "错误: $secret_label 的 /proc 进程参数保护校验失败"
        return 1
    }
}

verify_luci_route() {
    route="$1"
    expect="$2"
    out="$WORKDIR/verify.$(echo "$route" | tr '/.' '__').html"
    code=''
    route_probe_attempt=1

    while [ "$route_probe_attempt" -le 3 ]; do
        code="$(curl -m 8 -s -o "$out" -w '%{http_code}' "http://127.0.0.1/cgi-bin/luci/$route" 2>/dev/null || true)"
        case "$code" in
            200|302|403)
                break
                ;;
            502|503|504|000|'')
                if [ "$route_probe_attempt" -lt 3 ]; then
                    sleep 2
                fi
                ;;
            *)
                break
                ;;
        esac
        route_probe_attempt=$((route_probe_attempt + 1))
    done

    case "$code" in
        200|302|403)
            ;;
        *)
            log "错误: $expect LuCI 路由不可用，HTTP ${code:-000}: $route"
            return 1
            ;;
    esac

    if grep -Eq 'Failed to execute|error500|Runtime error|not found!|has no parent node|No page is registered at' "$out" 2>/dev/null; then
        log "错误: $expect LuCI 路由返回错误页: $route"
        return 1
    fi

    return 0
}

verify_file_exists() {
    path="$1"
    label="$2"
    [ -f "$path" ] || die "$label verify failed: missing $path"
}

verify_template_marker() {
    pattern="$1"
    label="$2"
    if grep -Fq -- "$pattern" "$TPL" 2>/dev/null; then
        return 0
    fi

    die "appcenter template verify failed: missing $label"
}

get_installed_package_version() {
    pkg_name="$1"
    opkg status "$pkg_name" 2>/dev/null | awk -F': ' '/^Version: /{print $2; exit}'
}

delete_iptables_rule_loop() {
    table_name="$1"
    chain_name="$2"
    shift 2

    command -v iptables >/dev/null 2>&1 || return 0
    while iptables -t "$table_name" -C "$chain_name" "$@" >/dev/null 2>&1; do
        iptables -t "$table_name" -D "$chain_name" "$@" >/dev/null 2>&1 || break
    done
}

cleanup_openvpn_target_policy_rules() {
    target="$1"
    lan_if="$2"
    pri=60
    while [ "$pri" -le 119 ]; do
        ip rule del to "$target" lookup main priority "$pri" 2>/dev/null || true
        ip rule del iif "$lan_if" to "$target" lookup main priority "$pri" 2>/dev/null || true
        pri=$((pri + 1))
    done
}

cleanup_openvpn_target_runtime_rules() {
    target="$1"
    lan_if="$2"
    tun_if="$3"
    lan_subnet="$4"
    nat_flag="$5"
    forward_flag="$6"

    [ -n "$target" ] || return 0
    cleanup_openvpn_target_policy_rules "$target" "$lan_if"
    ip route del "$target" 2>/dev/null || true

    case "$nat_flag" in
        1|y|Y|yes|YES|true|TRUE)
            [ -n "$lan_subnet" ] && [ -n "$tun_if" ] && delete_iptables_rule_loop nat POSTROUTING -s "$lan_subnet" -d "$target" -o "$tun_if" -j MASQUERADE
            ;;
    esac

    case "$forward_flag" in
        1|y|Y|yes|YES|true|TRUE)
            [ -n "$lan_if" ] && [ -n "$tun_if" ] && delete_iptables_rule_loop filter FORWARD -d "$target" -i "$lan_if" -o "$tun_if" -j ACCEPT
            [ -n "$lan_if" ] && [ -n "$tun_if" ] && [ -n "$lan_subnet" ] && delete_iptables_rule_loop filter FORWARD -s "$lan_subnet" -d "$target" -i "$lan_if" -o "$tun_if" -j ACCEPT
            [ -n "$lan_if" ] && [ -n "$tun_if" ] && [ -n "$lan_subnet" ] && delete_iptables_rule_loop filter FORWARD -s "$target" -d "$lan_subnet" -i "$tun_if" -o "$lan_if" -j ACCEPT
            ;;
    esac
}

cleanup_saved_openvpn_runtime_state() {
    [ -n "${OLD_ROUTE_TUN_IF:-}" ] || return 0

    old_lan_if="${OLD_ROUTE_LAN_IF:-br-lan}"
    old_tun_if="${OLD_ROUTE_TUN_IF:-}"
    old_lan_subnet="${OLD_ROUTE_LAN_SUBNET:-}"
    old_route_nat="${OLD_ROUTE_NAT:-n}"
    old_route_forward="${OLD_ROUTE_FORWARD:-n}"

    if [ -s "$ROUTE_MAP_LIST_FILE" ]; then
        while IFS='|' read -r old_peer_target old_peer_gw old_peer_kind_saved; do
            [ -n "$old_peer_target" ] || continue
            [ -n "$old_peer_kind_saved" ] || old_peer_kind_saved="$(infer_map_target_kind "$old_peer_target")"
            if [ "$old_peer_kind_saved" = 'host' ]; then
                old_peer_target="${old_peer_target%/*}"
                ip neigh del proxy "$old_peer_target" dev "$old_lan_if" 2>/dev/null || true
            fi
            cleanup_openvpn_target_runtime_rules "$old_peer_target" "$old_lan_if" "$old_tun_if" "$old_lan_subnet" "$old_route_nat" "$old_route_forward"
        done < "$ROUTE_MAP_LIST_FILE"
    fi

    old_enhanced_pri=196
    if [ -s "$ROUTE_LIST_FILE" ]; then
        while IFS='|' read -r old_subnet old_gw; do
            [ -n "$old_subnet" ] || continue
            cleanup_openvpn_target_runtime_rules "$old_subnet" "$old_lan_if" "$old_tun_if" "$old_lan_subnet" "$old_route_nat" "$old_route_forward"
            case "${OLD_ROUTE_ENHANCED:-n}" in
                1|y|Y|yes|YES|true|TRUE)
                    [ -n "$old_lan_subnet" ] && ip rule del from "$old_lan_subnet" to "$old_subnet" lookup main priority "$old_enhanced_pri" 2>/dev/null || true
                    old_enhanced_pri=$((old_enhanced_pri + 1))
                    ;;
            esac
        done < "$ROUTE_LIST_FILE"
    fi

    case "${OLD_ROUTE_MAP_ENABLE:-n}" in
        1|y|Y|yes|YES|true|TRUE)
            case "${OLD_ROUTE_MAP_KIND:-}" in
                host)
                    if [ -n "${OLD_ROUTE_MAP_HOST:-}" ]; then
                        old_lan_host_ip="${OLD_ROUTE_LAN_HOST_IP:-}"
                        [ -n "$old_lan_host_ip" ] || old_lan_host_ip="$(get_interface_subnet "$old_lan_if" 2>/dev/null | cut -d/ -f1 || true)"
                        [ -n "$old_lan_host_ip" ] || old_lan_host_ip="$(uci -q get network.lan.ipaddr 2>/dev/null || true)"
                        old_lan_host_ip="$(normalize_ipv4_host "$old_lan_host_ip" 2>/dev/null || true)"
                        [ -n "$old_lan_host_ip" ] && delete_iptables_rule_loop nat PREROUTING -i "$old_tun_if" -d "${OLD_ROUTE_MAP_HOST}" -j DNAT --to-destination "$old_lan_host_ip"
                        [ -n "$old_lan_host_ip" ] && delete_iptables_rule_loop nat OUTPUT -d "${OLD_ROUTE_MAP_HOST}" -j DNAT --to-destination "$old_lan_host_ip"
                    fi
                    [ -n "${OLD_ROUTE_MAP_IP:-}" ] && ip addr del "${OLD_ROUTE_MAP_IP}" dev "$old_lan_if" 2>/dev/null || true
                    ;;
                subnet)
                    [ -n "${OLD_ROUTE_MAP_SUBNET:-}" ] && [ -n "$old_lan_subnet" ] && delete_iptables_rule_loop nat PREROUTING -i "$old_tun_if" -d "${OLD_ROUTE_MAP_SUBNET}" -j NETMAP --to "$old_lan_subnet"
                    [ -n "${OLD_ROUTE_MAP_SUBNET:-}" ] && [ -n "$old_lan_subnet" ] && delete_iptables_rule_loop nat OUTPUT -d "${OLD_ROUTE_MAP_SUBNET}" -j NETMAP --to "$old_lan_subnet"
                    ;;
            esac
            ;;
    esac
}

is_adguardhome_luci_ready() {
    current_adg_ver="$(get_installed_package_version luci-app-adguardhome 2>/dev/null || true)"
    [ "$current_adg_ver" = "$ADGUARDHOME_VERSION" ] || return 1

    for needed in \
        /usr/lib/lua/luci/controller/AdGuardHome.lua \
        /usr/lib/lua/luci/model/cbi/AdGuardHome/base.lua \
        /usr/lib/lua/luci/model/cbi/AdGuardHome/manual.lua \
        /usr/lib/lua/luci/model/cbi/AdGuardHome/log.lua \
        /usr/share/AdGuardHome/AdGuardHome_template.yaml; do
        [ -f "$needed" ] || return 1
    done

    return 0
}

print_openvpn_runtime_debug() {
    log "debug: openvpn service status"
    /etc/init.d/openvpn status 2>/dev/null || true
    log "debug: /var/log/nradio-openvpn-client.log"
    sed -n '1,120p' /var/log/nradio-openvpn-client.log 2>/dev/null || true
    log "debug: $WORKDIR/openvpn-runtime-fix.log"
    sed -n '1,120p' "$WORKDIR/openvpn-runtime-fix.log" 2>/dev/null || true
    log "debug: /var/run/openvpn.custom_config.status"
    sed -n '1,120p' /var/run/openvpn.custom_config.status 2>/dev/null || true
    log "debug: recent logread openvpn"
    logread 2>/dev/null | grep -i openvpn | tail -40 || true
}

print_openvpn_runtime_hints() {
    cert_auth="$1"
    tls_mode="$2"
    proto="$3"
    runtime_log="$4"

    case "$runtime_log" in
        *VERIFY\ KU\ ERROR*|*certificate\ verify\ failed*)
            log "hint: server certificate verification failed; rerun option 9 and choose server verify mode 1 (compat mode)"
            return 0
            ;;
        *'/dev/net/tun'*|*'Cannot open TUN/TAP dev'*|*'TUNSETIFF'*|*'No such device'*)
            log "hint: tun driver is missing or unusable; run option 8 to install/fix tun support first"
            return 0
            ;;
        *liblzo2.so.2*|*lzo1x_*|*__lzo_init_v2*)
            log "hint: OpenVPN runtime dependency liblzo2 is missing or broken; run option 8 again after fixing package installation"
            return 0
            ;;
    esac

    log "hint: check whether your server really requires client certificate/private key"
    [ "$cert_auth" = '1' ] && log "hint: if your server only uses username/password, rerun option 9 and choose n for client certificate/private key"
    [ "$tls_mode" = '0' ] && log "hint: if your server uses tls-auth or tls-crypt, rerun option 9 and choose the correct mode"
    case "$proto" in
        udp6|tcp6-client)
            log "hint: if your server or network does not support IPv6 transport well, rerun option 9 and choose ipv4"
            ;;
    esac
}

openvpn_selfcheck_bool() {
    case "$1" in
        1|y|Y|yes|YES|true|TRUE) printf '%s\n' 'yes' ;;
        *) printf '%s\n' 'no' ;;
    esac
}

openvpn_route_via_dev_exists() {
    route_target="$1"
    route_gw="$2"
    route_dev="$3"
    route_target_alt=""
    case "$route_target" in
        */32) route_target_alt="${route_target%/*}" ;;
        */*) ;;
        *) route_target_alt="${route_target}/32" ;;
    esac

    ip route 2>/dev/null | awk -v target="$route_target" -v alt="$route_target_alt" -v gw="$route_gw" -v dev="$route_dev" '
        $2 == "via" && $3 == gw && $4 == "dev" && $5 == dev && ($1 == target || (alt != "" && $1 == alt)) { found = 1 }
        END { exit found ? 0 : 1 }
    '
}

openvpn_ip_rule_to_exists() {
    rule_target="$1"
    rule_target_alt=""
    case "$rule_target" in
        */32) rule_target_alt="${rule_target%/*}" ;;
        */*) ;;
        *) rule_target_alt="${rule_target}/32" ;;
    esac

    ip rule 2>/dev/null | awk -v target="$rule_target" -v alt="$rule_target_alt" '
        {
            has_to = 0
            has_lookup = 0
            for (i = 1; i <= NF; i++) {
                if ($i == "to" && ($(i + 1) == target || (alt != "" && $(i + 1) == alt)))
                    has_to = 1
                if ($i == "lookup" && $(i + 1) == "main")
                    has_lookup = 1
            }
            if (has_to && has_lookup)
                found = 1
        }
        END { exit found ? 0 : 1 }
    '
}

openvpn_ip_rule_iif_to_exists() {
    rule_target="$1"
    rule_iface="$2"
    rule_target_alt=""
    case "$rule_target" in
        */32) rule_target_alt="${rule_target%/*}" ;;
        */*) ;;
        *) rule_target_alt="${rule_target}/32" ;;
    esac

    ip rule 2>/dev/null | awk -v target="$rule_target" -v alt="$rule_target_alt" -v iface="$rule_iface" '
        {
            has_iif = 0
            has_to = 0
            has_lookup = 0
            for (i = 1; i <= NF; i++) {
                if ($i == "iif" && $(i + 1) == iface)
                    has_iif = 1
                if ($i == "to" && ($(i + 1) == target || (alt != "" && $(i + 1) == alt)))
                    has_to = 1
                if ($i == "lookup" && $(i + 1) == "main")
                    has_lookup = 1
            }
            if (has_iif && has_to && has_lookup)
                found = 1
        }
        END { exit found ? 0 : 1 }
    '
}

selfcheck_print_header() {
    log "$1"
    log "------"
}

selfcheck_print_file_state() {
    label="$1"
    path="$2"
    if [ -s "$path" ]; then
        size="$(wc -c < "$path" 2>/dev/null | tr -d ' ' || true)"
        [ -n "$size" ] || size='?'
        log "file:     $label = present ($path, ${size} bytes)"
    elif [ -e "$path" ]; then
        log "file:     $label = present but empty ($path)"
    else
        log "file:     $label = missing ($path)"
    fi
}

openvpn_selfcheck_print_file_state() {
    label="$1"
    path="$2"

    case "$label" in
        "runtime state")
            if [ ! -e "$path" ] && [ "${OVPN_SELFCHECK_RUNTIME_SOURCE:-saved}" = 'profile' ]; then
                log "file:     $label = synthesized from current profile ($path)"
                return 0
            fi
            ;;
        "route state")
            if [ ! -e "$path" ] && [ "${OVPN_SELFCHECK_ROUTE_STATE_SOURCE:-saved}" = 'hotplug' ]; then
                log "file:     $label = synthesized from route hotplug ($path)"
                return 0
            fi
            ;;
        "saved route list")
            if [ ! -e "$path" ] && [ "${OVPN_SELFCHECK_ROUTE_LIST_SOURCE:-saved}" = 'runtime' ]; then
                log "file:     $label = synthesized from active tun routes ($path)"
                return 0
            fi
            ;;
        "saved mapped peers")
            if [ ! -e "$path" ] && [ "${OVPN_SELFCHECK_MAP_LIST_SOURCE:-saved}" = 'runtime' ]; then
                log "file:     $label = synthesized from proxy neighbors ($path)"
                return 0
            fi
            ;;
    esac

    selfcheck_print_file_state "$label" "$path"
}

selfcheck_print_service_state() {
    label="$1"
    init_script="$2"

    if [ ! -x "$init_script" ]; then
        log "service:  $label missing ($init_script)"
        return 0
    fi

    if "$init_script" enabled >/dev/null 2>&1; then
        service_enabled='1'
    else
        service_enabled='0'
    fi
    service_status="$( ( "$init_script" status 2>/dev/null || true ) | tr '\n' ' ' | sed 's/[[:space:]]\+/ /g; s/^ //; s/ $//' )"
    [ -n "$service_status" ] || service_status='stopped'
    log "service:  $label enabled=$(openvpn_selfcheck_bool "$service_enabled") status=$service_status"
}

selfcheck_luci_route_ok() {
    route="$1"
    out="$WORKDIR/selfcheck.$(printf '%s' "$route" | tr '/.' '__').probe"
    code="$(curl -m 8 -s -o "$out" -w '%{http_code}' "http://127.0.0.1/cgi-bin/luci/$route" 2>/dev/null || true)"

    case "$code" in
        200|302|403)
            if grep -Eq 'Failed to execute|error500|Runtime error|not found!|has no parent node|No page is registered at' "$out" 2>/dev/null; then
                return 1
            fi
            return 0
            ;;
    esac

    return 1
}

selfcheck_print_luci_route_state() {
    label="$1"
    route="$2"
    out="$WORKDIR/selfcheck.$(printf '%s' "$route" | tr '/.' '__').html"
    code="$(curl -m 8 -s -o "$out" -w '%{http_code}' "http://127.0.0.1/cgi-bin/luci/$route" 2>/dev/null || true)"

    if selfcheck_luci_route_ok "$route"; then
        log "路由:    $label = 正常 (HTTP ${code:-000})"
        return 0
    fi

    case "$code" in
        200|302|403)
            log "路由:    $label = LuCI 错误页 (HTTP $code)"
            ;;
        *)
            log "路由:    $label = 缺失 (HTTP ${code:-000})"
            ;;
    esac
}

selfcheck_required_paths_present() {
    for needed_path in "$@"; do
        [ -e "$needed_path" ] || return 1
    done
    return 0
}

selfcheck_print_luci_route_state_when_ready() {
    label="$1"
    route="$2"
    shift 2

    for needed_path in "$@"; do
        if [ ! -e "$needed_path" ]; then
            log "路由:    $label = 跳过 (缺少 $needed_path)"
            return 0
        fi
    done

    selfcheck_print_luci_route_state "$label" "$route"
}

selfcheck_luci_route_ok_when_ready() {
    route="$1"
    shift

    selfcheck_required_paths_present "$@" || return 2
    selfcheck_luci_route_ok "$route"
}

selfcheck_appcenter_controller_fallback_matches() {
    plugin_name="$1"
    actual_controller="$2"

    case "$plugin_name" in
        luci-app-openclash) [ "$actual_controller" = "/usr/lib/lua/luci/controller/openclash.lua" ] && return 0 ;;
        luci-app-adguardhome) [ "$actual_controller" = "/usr/lib/lua/luci/controller/AdGuardHome.lua" ] && return 0 ;;
        OpenVPN) [ "$actual_controller" = "/usr/lib/lua/luci/controller/nradio_adv/openvpn_full.lua" ] && return 0 ;;
        DDNS-GO) [ "$actual_controller" = "$DDNSGO_CONTROLLER" ] && return 0 ;;
        MosDNS) [ "$actual_controller" = "$MOSDNS_CONTROLLER" ] && return 0 ;;
        FanControl) [ "$actual_controller" = "$FANCTRL_CONTROLLER" ] && return 0 ;;
        奇游联机宝) [ "$actual_controller" = "/usr/lib/lua/luci/controller/nradio_adv/qiyou.lua" ] && return 0 ;;
        雷神加速器) [ "$actual_controller" = "/usr/lib/lua/luci/controller/nradio_adv/leigod.lua" ] && return 0 ;;
    esac

    return 1
}

selfcheck_appcenter_route_matches() {
    plugin_name="$1"
    expect_route="$2"
    sec_list="$(uci show appcenter 2>/dev/null | while IFS= read -r line; do
        case "$line" in
            "appcenter.@package_list"*".name='${plugin_name}'"|"appcenter.cfg"*".name='${plugin_name}'")
                sec="${line#appcenter.}"
                sec="${sec%%.*}"
                printf '%s\n' "$sec"
                ;;
        esac
    done)"

    if [ "$plugin_name" = "${DDNSGO_APP_NAME:-DDNS-GO}" ]; then
        parent_sec_list="$(uci show appcenter 2>/dev/null | while IFS= read -r line; do
            case "$line" in
                "appcenter.@package_list"*".parent='${plugin_name}'"|"appcenter.cfg"*".parent='${plugin_name}'")
                    sec="${line#appcenter.}"
                    sec="${sec%%.*}"
                    printf '%s\n' "$sec"
                    ;;
            esac
        done)"
        if [ -n "$parent_sec_list" ]; then
            sec_list="$(printf '%s\n%s\n' "$sec_list" "$parent_sec_list" | sed '/^$/d' | sort -u)"
        fi
    fi

    [ -n "$sec_list" ] || return 1

    for sec in $sec_list; do
        [ -n "$sec" ] || continue
        [ "$(uci -q get "appcenter.$sec" 2>/dev/null || true)" = "package_list" ] || continue
        actual_route="$(uci -q get appcenter.$sec.luci_module_route 2>/dev/null || true)"
        [ "$actual_route" = "$expect_route" ] && return 0
        actual_controller="$(uci -q get appcenter.$sec.luci_module_file 2>/dev/null || true)"
        selfcheck_appcenter_controller_fallback_matches "$plugin_name" "$actual_controller" && return 0
    done
    return 1
}

selfcheck_print_appcenter_route_state() {
    label="$1"
    plugin_name="$2"
    expect_route="$3"

    sec="$(find_uci_section package_list "$plugin_name")"
    if [ -z "$sec" ] && [ "$plugin_name" = "${DDNSGO_APP_NAME:-DDNS-GO}" ]; then
        sec="$(uci show appcenter 2>/dev/null | while IFS= read -r line; do
            case "$line" in
                "appcenter.@package_list"*".parent='${plugin_name}'"|"appcenter.cfg"*".parent='${plugin_name}'")
                    candidate="${line#appcenter.}"
                    candidate="${candidate%%.*}"
                    if [ "$(uci -q get "appcenter.$candidate" 2>/dev/null || true)" = "package_list" ]; then
                        printf '%s\n' "$candidate"
                        break
                    fi
                    ;;
            esac
        done)"
    fi
    if [ -z "$sec" ]; then
        log "应用商店: $label = 缺失"
        return 0
    fi

    actual_route="$(uci -q get appcenter.$sec.luci_module_route 2>/dev/null || true)"
    if [ "$actual_route" = "$expect_route" ]; then
        log "应用商店: $label = 正常 ($actual_route)"
    else
        actual_controller="$(uci -q get appcenter.$sec.luci_module_file 2>/dev/null || true)"
        selfcheck_appcenter_controller_fallback_matches "$plugin_name" "$actual_controller" && {
            log "应用商店: $label = 正常 (controller fallback)"
            return 0
        }
        log "应用商店: $label = 不匹配 (${actual_route:-缺失})"
    fi
}

selfcheck_print_process_state() {
    label="$1"
    pattern="$2"
    ps_text="$(pgrep -af "$pattern" 2>/dev/null || true)"
    if [ -n "$ps_text" ]; then
        first_line="$(printf '%s\n' "$ps_text" | sed -n '1p')"
        log "runtime:  $label process present ($first_line)"
    else
        log "runtime:  $label process missing"
    fi
}

selfcheck_finalize_summary() {
    failures="$1"
    warnings="$2"

    NRADIO_LAST_SELFCHECK_ERRORS="$failures"
    NRADIO_LAST_SELFCHECK_WARNINGS="$warnings"

    if [ "$failures" -gt 0 ]; then
        NRADIO_LAST_SELFCHECK_STATUS='FAIL'
        log "summary:  FAIL (errors=$failures warnings=$warnings)"
    elif [ "$warnings" -gt 0 ]; then
        NRADIO_LAST_SELFCHECK_STATUS='WARN'
        log "summary:  WARN (errors=0 warnings=$warnings)"
    else
        NRADIO_LAST_SELFCHECK_STATUS='PASS'
        log "summary:  PASS"
    fi
}

set_last_selfcheck_status() {
    status="$1"
    errors="${2:-0}"
    warnings="${3:-0}"

    NRADIO_LAST_SELFCHECK_ERRORS="$errors"
    NRADIO_LAST_SELFCHECK_WARNINGS="$warnings"
    case "$status" in
        FAIL|PASS|WARN|SKIP)
            NRADIO_LAST_SELFCHECK_STATUS="$status"
            ;;
        *)
            NRADIO_LAST_SELFCHECK_STATUS='WARN'
            ;;
    esac
}

unified_now_s() {
    date +%s 2>/dev/null || printf '%s\n' '0'
}

record_unified_selfcheck_summary() {
    label="$1"
    now_s="$(unified_now_s)"
    elapsed_text=''

    case "${NRADIO_UNIFIED_SECTION_START:-}" in
        ''|*[!0-9]*)
            ;;
        *)
            case "$now_s" in
                ''|*[!0-9]*)
                    ;;
                *)
                    elapsed_s=$((now_s - NRADIO_UNIFIED_SECTION_START))
                    [ "$elapsed_s" -ge 0 ] 2>/dev/null && elapsed_text=" 耗时=${elapsed_s}s"
                    ;;
            esac
            ;;
    esac

    case "${NRADIO_LAST_SELFCHECK_STATUS:-WARN}" in
        FAIL)
            NRADIO_UNIFIED_FAILS=$((NRADIO_UNIFIED_FAILS + 1))
            ;;
        PASS)
            NRADIO_UNIFIED_PASSES=$((NRADIO_UNIFIED_PASSES + 1))
            ;;
        SKIP)
            NRADIO_UNIFIED_SKIPS=$((NRADIO_UNIFIED_SKIPS + 1))
            ;;
        *)
            NRADIO_UNIFIED_WARNS=$((NRADIO_UNIFIED_WARNS + 1))
            NRADIO_LAST_SELFCHECK_STATUS='WARN'
            ;;
    esac
    log "overall:  $label = ${NRADIO_LAST_SELFCHECK_STATUS}${elapsed_text}"
    NRADIO_UNIFIED_SECTION_START="$now_s"
}

run_openclash_cdn_selfcheck() {
    optimize_openclash_cdn_order
    if [ "${OPENCLASH_CDN_RANKED:-0}" = '1' ] && [ -n "${OPENCLASH_MIRRORS:-}" ]; then
        set_last_selfcheck_status PASS 0 0
    else
        log "CDN:      $OPENCLASH_DISPLAY_NAME = 未得出排序"
