    selfcheck_print_luci_route_state_when_ready "OpenList basic" "nradioadv/system/openlist/basic" /usr/lib/lua/luci/controller/nradio_adv/openlist.lua /usr/lib/lua/luci/model/cbi/nradio_adv/openlist_basic.lua
