    [ -L "$OPENLIST_LINK_PATH" ] || [ -x "$OPENLIST_LINK_PATH" ] || openlist_selfcheck_failures=$((openlist_selfcheck_failures + 1))
    for needed in \
        /usr/libexec/openlist-sync-config \
        /etc/config/openlist \
