    mkdir -p /usr/lib/lua/luci/view/openclash
    backup_file /usr/lib/lua/luci/view/openclash/nradio_tabs.htm

    cat > /usr/lib/lua/luci/view/openclash/nradio_tabs.htm <<'EOF'
