EOF_ADG_STATUS

    cat > /usr/lib/lua/luci/model/cbi/AdGuardHome/base.lua <<'EOF_ADG_BASE'
require("luci.sys")
require("io")
local m,s,o,o1
local fs=require"nixio.fs"
local uci=require"luci.model.uci".cursor()
local function shellquote(value)
	value = tostring(value or "")
	return "'" .. value:gsub("'", "'\\''") .. "'"
end
local function adg_read_dns_port(path)
	local data = fs.readfile(path) or ""
	local line
	for line in data:gmatch("[^\r\n]+") do
		local port = line:match("^%s*port:%s*(%d+)")
		if port then
			return port
		end
	end
	return "?"
end
local configpath=uci:get("AdGuardHome","AdGuardHome","configpath") or "/etc/AdGuardHome.yaml"
local binpath=uci:get("AdGuardHome","AdGuardHome","binpath") or "/usr/bin/AdGuardHome/AdGuardHome"
local httpport=uci:get("AdGuardHome","AdGuardHome","httpport") or "3000"
m = Map("AdGuardHome", "AdGuardHome")
m.description = translate("运行状态、统计读取、路径与维护选项集中管理。")
m:section(SimpleSection).template  = "AdGuardHome/AdGuardHome_status"

s = m:section(TypedSection, "AdGuardHome")
s.anonymous=true
s.addremove=false
---- enable
o = s:option(Flag, "enabled", translate("启用"))
o.default = 0
o.optional = false
---- httpport
o =s:option(Value,"httpport",translate("原版管理端口"))
o.placeholder=3000
o.default=3000
o.datatype="port"
o.optional = false
o.description = translate("原版仪表盘 Web 端口；入口位于概览页。")
---- dashboard user
o = s:option(Value, "dashboard_user", translate("仪表盘 API 用户"), translate("状态页用于读取原版仪表盘运行态和 24 小时统计"))
o.default = "admin"
o.datatype = "string"
o.optional = false
o.rmempty = false
---- dashboard password
o = s:option(Value, "dashboard_password", translate("仪表盘 API 密码"), translate("仅用于本页向本机原版仪表盘读取状态和统计"))
o.password = true
o.datatype = "string"
o.optional = false
o.rmempty = false
---- update warning not safe
local binmtime=uci:get("AdGuardHome","AdGuardHome","binmtime") or "0"
local e=""
if not fs.access(configpath) then
	e=e.." "..translate("缺少配置")
end
if not fs.access(binpath) then
	e=e.." "..translate("缺少核心")
else
	local version
	local testtime=fs.stat(binpath,"mtime")
	if testtime~=tonumber(binmtime) then
		local fakeconfig="/var/run/AdGfakeconfig"
		fs.writefile(fakeconfig, "")
		local tmp=luci.sys.exec(shellquote(binpath).." -c "..shellquote(fakeconfig).." --check-config 2>&1")
		fs.remove(fakeconfig)
		version=tmp:match("v[%d%.]+") or ""
		uci:set("AdGuardHome","AdGuardHome","version",version)
		uci:set("AdGuardHome","AdGuardHome","binmtime",testtime)
		uci:save("AdGuardHome")
		uci:commit("AdGuardHome")
	else
		version=uci:get("AdGuardHome","AdGuardHome","version") or ""
	end
	if version == "" then
		version = translate("已安装，版本待识别")
	end
	e=version..e
end
o=s:option(Button,"restart",translate("更新"))
o.inputtitle=translate("检查并更新核心")
o.template = "AdGuardHome/AdGuardHome_check"
o.showfastconfig=(not fs.access(configpath))
o.description=string.format(translate("核心版本：").."<strong><font id=\"updateversion\" color=\"green\">%s </font></strong>",e)
---- port warning not safe
local port=adg_read_dns_port(configpath)
---- Redirect
o = s:option(ListValue, "redirect", port..translate(" DNS 重定向"), translate("选择 AdGuardHome 与 dnsmasq 的接入方式"))
o.placeholder = "none"
o:value("none", translate("不启用"))
o:value("dnsmasq-upstream", translate("作为 dnsmasq 上游"))
o:value("redirect", translate("将 53 端口重定向到 AdGuardHome"))
o:value("exchange", translate("用 53 端口替换 dnsmasq"))
o.default     = "none"
o.optional = true
---- bin path
o = s:option(Value, "binpath", translate("核心路径"), translate("AdGuardHome 核心文件路径，如不存在则自动下载"))
o.default     = "/usr/bin/AdGuardHome/AdGuardHome"
o.datatype    = "string"
o.optional = false
o.rmempty=false
o.validate=function(self, value)
if value=="" then return nil end
if fs.stat(value,"type")=="dir" then
	if (m.message) then
	m.message =m.message.."\n错误：核心路径是目录"
	else
	m.message ="错误：核心路径是目录"
	end
	return nil
end 
return value
end
--- upx
o = s:option(ListValue, "upxflag", translate("下载后使用 upx 压缩核心"))
o:value("", translate("不启用"))
o:value("-1", translate("更快压缩"))
o:value("-9", translate("更高压缩率"))
o:value("--best", translate("最强压缩（大文件会更慢）"))
o:value("--brute", translate("尝试全部压缩方法与过滤器（较慢）"))
o:value("--ultra-brute", translate("尝试更多压缩组合（很慢）"))
o.default     = ""
o.description=translate("核心体积更小，但可能有兼容性问题")
o.rmempty = true
---- config path
o = s:option(Value, "configpath", translate("配置文件路径"), translate("AdGuardHome 配置文件路径"))
o.default     = "/etc/AdGuardHome.yaml"
o.datatype    = "string"
o.optional = false
o.rmempty=false
o.validate=function(self, value)
if value==nil or value=="" then return nil end
if fs.stat(value,"type")=="dir" then
	if m.message then
	m.message =m.message.."\n错误：配置路径是目录"
	else
	m.message ="错误：配置路径是目录"
	end
	return nil
end 
return value
end
---- work dir
o = s:option(Value, "workdir", translate("工作目录"), translate("AdGuardHome 工作目录，包含规则、审计日志和数据库"))
o.default     = "/usr/bin/AdGuardHome"
o.datatype    = "string"
o.optional = false
o.rmempty=false
o.validate=function(self, value)
if value=="" then return nil end
if fs.stat(value,"type")=="reg" then
	if m.message then
	m.message =m.message.."\n错误：工作目录是文件"
	else
	m.message ="错误：工作目录是文件"
	end
	return nil
end 
if string.sub(value, -1)=="/" then
	return string.sub(value, 1, -2)
else
	return value
end
end
---- log file
o = s:option(Value, "logfile", translate("运行日志文件"), translate("AdGuardHome 运行日志文件，填 syslog 写入系统日志，留空则不写日志"))
o.datatype    = "string"
o.rmempty = true
o.validate=function(self, value)
if value==nil or value=="" or value=="syslog" then return value end
local allowed=value=="/tmp/AdGuardHome.log" or value:match("^/tmp/AdGuardHome/[%w%._%-%/]+$") or
    value=="/var/log/AdGuardHome.log" or value:match("^/var/log/AdGuardHome/[%w%._%-%/]+$") or
    value:match("^/usr/bin/AdGuardHome/[%w%._%-%/]+$")
if not allowed or value:find("/../",1,true) or value:find("/./",1,true) or value:find("//",1,true) then
	if m.message then
	m.message =m.message.."\n错误：日志路径必须位于 AdGuardHome 专用目录"
	else
	m.message ="错误：日志路径必须位于 AdGuardHome 专用目录"
	end
	return nil
end
local logfile_stat=fs.lstat(value)
if logfile_stat~=nil and logfile_stat.type~="reg" then return nil end
if logfile_stat~=nil and value:match("^/tmp/") and tonumber(logfile_stat.uid or -1)~=0 then return nil end
return value
end
---- debug
o = s:option(Flag, "verbose", translate("详细日志"))
o.default = 0
o.optional = true
---- gfwlist 
local configtext=fs.readfile(configpath) or ""
local a
if configtext:find("programadd", 1, true) then
a="已加入"
else
a="未加入"
end
o=s:option(Button,"gfwdel",translate("删除 GFWList"),translate(a))
o.optional = false
o.inputtitle=translate("删除")
o.write=function()
	luci.sys.exec("sh /usr/share/AdGuardHome/gfw2adg.sh del 2>&1")
	luci.http.redirect(luci.dispatcher.build_url("admin","services","AdGuardHome"))
end
o=s:option(Button,"gfwadd",translate("加入 GFWList"),translate(a))
o.optional = false
o.inputtitle=translate("添加")
o.write=function()
	luci.sys.exec("sh /usr/share/AdGuardHome/gfw2adg.sh 2>&1")
	luci.http.redirect(luci.dispatcher.build_url("admin","services","AdGuardHome"))
end
o = s:option(Value, "gfwupstream", translate("GFWList 上游 DNS"), translate("GFWList 域名上游 DNS 服务，当前状态：")..translate(a))
o.default     = "tcp://208.67.220.220:5353"
o.datatype    = "string"
o.optional = false
---- chpass
o = s:option(Value, "hashpass", translate("修改浏览器管理密码"), translate("先点读取并计算哈希，最后再保存/应用"))
o.default     = ""
o.datatype    = "string"
o.template = "AdGuardHome/AdGuardHome_chpass"
o.optional = false
---- database protect
o = s:option(Flag, "keepdb", translate("系统升级时保留数据库"))
o.default = 0
o.optional = true
---- wait net on boot
o = s:option(Flag, "waitonboot", translate("开机等待网络就绪"))
o.default = 1
o.optional = true
---- backup workdir on shutdown
local workdir=uci:get("AdGuardHome","AdGuardHome","workdir") or "/usr/bin/AdGuardHome"
o = s:option(MultiValue, "backupfile", translate("关机时备份工作目录文件"))
o1 = s:option(Value, "backupwdpath", translate("工作目录备份路径"))
local name
o:value("filters","filters")
o:value("stats.db","stats.db")
o:value("querylog.json","querylog.json")
o1:depends ("backupfile", "filters")
o1:depends ("backupfile", "stats.db")
o1:depends ("backupfile", "querylog.json")
for name in fs.glob(workdir.."/data/*")
do
	name=fs.basename (name)
	if name~="filters" and name~="stats.db" and name~="querylog.json" then
		o:value(name,name)
		o1:depends ("backupfile", name)
	end
end
o.widget = "checkbox"
o.default = nil
o.optional=false
o.description=translate("当 workdir/data 为空时自动恢复")
----backup workdir path

o1.default     = "/usr/bin/AdGuardHome"
o1.datatype    = "string"
o1.optional = false
o1.validate=function(self, value)
if fs.stat(value,"type")=="reg" then
	if m.message then
	m.message =m.message.."\n错误：备份目录是文件"
	else
	m.message ="错误：备份目录是文件"
	end
	return nil
end 
if string.sub(value,-1)=="/" then
	return string.sub(value, 1, -2)
else
	return value
end
end

----Crontab
o = s:option(MultiValue, "crontab", translate("定时任务"),translate("按需调整定时任务时间和参数"))
o:value("autoupdate",translate("自动更新核心"))
o:value("cutquerylog",translate("自动裁剪 querylog"))
o:value("cutruntimelog",translate("自动裁剪运行日志"))
o:value("autohost",translate("自动更新 IPv6 hosts 并重启 AdGuardHome"))
o:value("autogfw",translate("自动更新 GFWList 并重启 AdGuardHome"))
o.widget = "checkbox"
o.default = nil
o.optional=false

----downloadpath
o = s:option(TextValue, "downloadlinks",translate("核心下载链接"))
o.optional = false
o.rows = 4
o.wrap = "soft"
o.size=111
o.cfgvalue = function(self, section)
	return fs.readfile("/usr/share/AdGuardHome/links.txt")
end
o.write = function(self, section, value)
	fs.writefile("/usr/share/AdGuardHome/links.txt", value:gsub("\r\n", "\n"))
end
fs.writefile("/var/run/lucilogpos","0")
function m.on_commit(map)
	local enabled=uci:get("AdGuardHome","AdGuardHome","enabled")
	if enabled=="1" then
		io.popen("/etc/init.d/AdGuardHome enable >/dev/null 2>&1; /etc/init.d/AdGuardHome restart >/dev/null 2>&1 &")
	else
		io.popen("/etc/init.d/AdGuardHome disable >/dev/null 2>&1; /etc/init.d/AdGuardHome stop >/dev/null 2>&1 &")
	end
end
return m
EOF_ADG_BASE

