storage_expand_select_app_action() {
    local action_name="$1"
    local choice list_file list_count all_choice line app_key

    STORAGE_EXPAND_ACTION_CHANGED=0
    storage_expand_require_active
    while :; do
        mkdir -p "$WORKDIR"
        list_file="$WORKDIR/storage-expand-app-menu.$$"
        if [ "$action_name" = "迁移应用到扩展盘" ]; then
            storage_expand_build_migrate_menu_list "$list_file"
        else
            storage_expand_build_restore_menu_list "$list_file"
        fi
        list_count="$(wc -l < "$list_file" 2>/dev/null | tr -d ' ' || printf '0')"
        case "$list_count" in
            ''|*[!0-9]*)
                list_count=0
                ;;
        esac

        print_menu_header "存储扩展 > $action_name"
        if [ "$list_count" -eq 0 ]; then
            if [ "$action_name" = "迁移应用到扩展盘" ]; then
                log "暂无可迁移应用：应用商店与本机运行文件中没有发现可迁移且源路径存在的应用"
            else
                log "暂无可还原应用：未发现已迁移到扩展盘的应用记录"
            fi
            rm -f "$list_file"
            return 0
        fi

        awk -F '\t' '{ printf "  %2d. %s\n      %s\n", NR, $2, $3 }' "$list_file"
        all_choice=$((list_count + 1))
        print_menu_item "$all_choice" '全部'
        print_menu_item 0 '返回上级'
        print_menu_prompt "0-$all_choice"
        read_category_choice
        choice="$UI_READ_RESULT"
        case "$choice" in
            0)
                rm -f "$list_file"
                return 0
                ;;
            ''|*[!0-9]*)
                rm -f "$list_file"
                die_menu_input_issue "$choice"
                ;;
            *)
                if [ "$choice" -eq "$all_choice" ] 2>/dev/null; then
                    if [ "$action_name" = "还原应用到 overlay" ]; then
                        storage_expand_preflight_restore_all "$list_file"
                    fi
                    while IFS="$(printf '\t')" read -r app_key _label _src; do
                        [ -n "$app_key" ] || continue
                        storage_expand_run_app_action "$action_name" "$app_key"
                        STORAGE_EXPAND_ACTION_CHANGED=1
                    done < "$list_file"
                    rm -f "$list_file"
                    return 0
                fi
                if [ "$choice" -ge 1 ] 2>/dev/null && [ "$choice" -le "$list_count" ] 2>/dev/null; then
                    line="$(sed -n "${choice}p" "$list_file")"
                    app_key="$(printf '%s\n' "$line" | awk -F '\t' '{ print $1 }')"
                    rm -f "$list_file"
                    [ -n "$app_key" ] || die_menu_input_issue "$choice"
                    storage_expand_run_app_action "$action_name" "$app_key"
                    STORAGE_EXPAND_ACTION_CHANGED=1
                    return 0
                fi
                rm -f "$list_file"
                die_menu_input_issue "$choice"
                ;;
        esac
    done
}

manage_rootfs_2nd_storage_expand() {
    while :; do
        print_menu_header '设备维护 > eMMC 存储扩展'
        print_menu_item 1 '查看当前扩展状态'
        print_menu_item 2 '启用 rootfs_2nd 存储扩展'
        print_menu_item 3 '关闭存储扩展' '恢复第二系统烧录入口'
        print_menu_item 4 '修复应用商店存储空间显示'
        print_menu_item 5 '迁移应用到扩展盘'
        print_menu_item 6 '还原应用到 overlay'
        print_menu_item 7 '清空并重新初始化扩展盘' 'rootfs_2nd：用于设备恢复出厂后'
        print_menu_item 0 '返回上级'
        print_menu_prompt '0-7'
        read_category_choice
        case "$UI_READ_RESULT" in
            0) return 0 ;;
            1) storage_expand_status; MENU_ACTION_COMPLETED='1'; return 0 ;;
            2)
                if enable_rootfs_2nd_storage_expand; then
                    record_action_history "5 > 4 > 2" "启用 rootfs_2nd 存储扩展" "PASS" "$BACKUP_DIR"
                    MENU_ACTION_COMPLETED='1'
                fi
                return 0
                ;;
            3)
                disable_rootfs_2nd_storage_expand
                record_action_history "5 > 4 > 3" "关闭 rootfs_2nd 存储扩展" "PASS" "$BACKUP_DIR"
                MENU_ACTION_COMPLETED='1'
                return 0
                ;;
            4)
                patch_appcenter_storage_expand_display
                record_action_history "5 > 4 > 4" "修复应用商店存储空间显示" "PASS" "$BACKUP_DIR"
                MENU_ACTION_COMPLETED='1'
                return 0
                ;;
            5)
                storage_expand_select_app_action "迁移应用到扩展盘"
                [ "${STORAGE_EXPAND_ACTION_CHANGED:-0}" = '1' ] && record_action_history "5 > 4 > 5" "迁移应用到扩展盘" "PASS" "$BACKUP_DIR"
                [ "${STORAGE_EXPAND_ACTION_CHANGED:-0}" = '1' ] && MENU_ACTION_COMPLETED='1'
                return 0
                ;;
            6)
                storage_expand_select_app_action "还原应用到 overlay"
                [ "${STORAGE_EXPAND_ACTION_CHANGED:-0}" = '1' ] && record_action_history "5 > 4 > 6" "还原应用到 overlay" "PASS" "$BACKUP_DIR"
                [ "${STORAGE_EXPAND_ACTION_CHANGED:-0}" = '1' ] && MENU_ACTION_COMPLETED='1'
                return 0
                ;;
            7)
                if reinitialize_rootfs_2nd_storage_expand; then
                    record_action_history "5 > 4 > 7" "清空并重新初始化 rootfs_2nd 扩展盘" "PASS" "$BACKUP_DIR"
                    MENU_ACTION_COMPLETED='1'
                fi
                return 0
                ;;
            *) die_menu_input_issue "$UI_READ_RESULT" ;;
        esac
    done
}

ensure_openclash_swap_setup() {
    ensure_existing_swap_access "$OPENCLASH_DISPLAY_NAME"
}

ensure_swapfile_boot() {
    ensure_swapfile_boot_config "${1:-/overlay/swapfile}" || return 0
}

reduce_openclash_memory_pressure() {
    [ -f /etc/config/openclash ] || return 0

    uci set openclash.config.smart_collect='0' >/dev/null 2>&1 || true
    uci set openclash.config.enable_meta_sniffer='0' >/dev/null 2>&1 || true
    uci set openclash.config.enable_meta_sniffer_pure_ip='0' >/dev/null 2>&1 || true
    uci set openclash.config.enable_meta_sniffer_custom='0' >/dev/null 2>&1 || true
    uci set openclash.config.smart_enable_lgbm='0' >/dev/null 2>&1 || true
    uci set openclash.config.auto_smart_switch='0' >/dev/null 2>&1 || true
    uci set openclash.config.enable_tcp_concurrent='0' >/dev/null 2>&1 || true
    uci set openclash.config.enable_unified_delay='0' >/dev/null 2>&1 || true
    uci set openclash.config.enable_custom_dns='0' >/dev/null 2>&1 || true
    uci set openclash.config.enable_respect_rules='0' >/dev/null 2>&1 || true
    uci commit openclash >/dev/null 2>&1 || true
}

fix_adguard_start_order() {
    local adg_init='/etc/init.d/AdGuardHome' adg_was_enabled='0'
    [ -f "$adg_init" ] || return 0
    "$adg_init" enabled >/dev/null 2>&1 && adg_was_enabled='1'

    # rc.d 按文件名排序；S120 会排到网络服务之前，使用两位序号接在 OpenClash 后。
    set_init_start_order "$adg_init" 99 || return 1
    if [ "$adg_was_enabled" = '1' ] && ! "$adg_init" enabled >/dev/null 2>&1; then
        enable_init_service_strict "$adg_init" 'AdGuardHome' || return 1
    fi

    # rc.common disable 只清理 S??，需单独迁移旧三位链接。
    if [ -L /etc/rc.d/S120AdGuardHome ]; then
        case "$(readlink /etc/rc.d/S120AdGuardHome)" in
            ../init.d/AdGuardHome|/etc/init.d/AdGuardHome)
                rm -f /etc/rc.d/S120AdGuardHome || return 1
                ;;
        esac
    fi
    return 0
}

ensure_adguard_autostart() {
    local adg_binpath adg_configpath
    adg_binpath="$(uci -q get AdGuardHome.AdGuardHome.binpath 2>/dev/null || true)"
    [ -n "$adg_binpath" ] || adg_binpath='/usr/bin/AdGuardHome/AdGuardHome'
    adg_configpath="$(get_adguard_configpath)"
    [ -x /etc/init.d/AdGuardHome ] && [ -x "$adg_binpath" ] && [ -s "$adg_configpath" ] || {
        log "错误: AdGuardHome 启动脚本、核心或配置未就绪"
        return 1
    }
    fix_adguard_start_order || return 1
    if [ "$(uci -q get AdGuardHome.AdGuardHome.enabled 2>/dev/null || true)" != '1' ]; then
        backup_file /etc/config/AdGuardHome
        uci set AdGuardHome.AdGuardHome.enabled='1' >/dev/null 2>&1 || return 1
        uci commit AdGuardHome >/dev/null 2>&1 || return 1
    fi
    enable_init_service_strict /etc/init.d/AdGuardHome 'AdGuardHome' || return 1
    /etc/init.d/AdGuardHome enabled >/dev/null 2>&1 || return 1
    log "AdGuardHome 开机启动已启用（S99AdGuardHome）"
}

install_adguardhome() {
    require_nradio_oem_appcenter

    mkdir -p "$WORKDIR/adguardhome"
    log_stage 1 5 "AdGuardHome 镜像探测与安装规划"
    optimize_adguardhome_cdn_order
    log "下一步将下载 AdGuardHome 安装包并修改系统文件: /etc/config/appcenter, $TPL 和 AdGuardHome LuCI 文件"
    confirm_or_exit "确认继续安装 AdGuardHome 并修改系统吗？"
    adg_luci_reused='0'
    if is_adguardhome_luci_ready; then
        adg_luci_reused='1'
        log "备注:     AdGuardHome LuCI $ADGUARDHOME_VERSION 已存在, 跳过重复安装"
    else
        adg_ipk="$WORKDIR/adguardhome/luci-app-adguardhome.ipk"
        log_stage 2 5 "下载并安装 AdGuardHome LuCI 包"
        log "提示: 正在从 CDN 下载 AdGuardHome 官方发行包..."
        adg_download_stall_time_saved="$DOWNLOAD_STALL_TIME"
        adg_download_stall_speed_saved="$DOWNLOAD_STALL_SPEED"
        adg_download_keep_partial_saved="${DOWNLOAD_KEEP_PARTIAL:-0}"
        DOWNLOAD_KEEP_PARTIAL=1
        adg_download_url=""
        if download_from_urls "$adg_ipk" $ADGUARDHOME_IPK_URLS; then
            adg_download_url="$LAST_DOWNLOAD_SOURCE"
        fi
        if [ -z "$adg_download_url" ]; then
            log "提示: 首轮 AdGuardHome 安装包下载未完成，正在放宽速度阈值后重试..."
            DOWNLOAD_STALL_TIME="$DOWNLOAD_PARTIAL_RETRY_STALL_TIME"
            DOWNLOAD_STALL_SPEED="$DOWNLOAD_PARTIAL_RETRY_STALL_SPEED"
            if download_from_urls "$adg_ipk" $ADGUARDHOME_IPK_URLS; then
                adg_download_url="$LAST_DOWNLOAD_SOURCE"
            else
                adg_download_url=""
            fi
        fi
        DOWNLOAD_STALL_TIME="$adg_download_stall_time_saved"
        DOWNLOAD_STALL_SPEED="$adg_download_stall_speed_saved"
        DOWNLOAD_KEEP_PARTIAL="$adg_download_keep_partial_saved"
        [ -n "$adg_download_url" ] || die "无法从全部 CDN 镜像下载 AdGuardHome 安装包"
        [ -s "$adg_ipk" ] || die "AdGuardHome 安装包下载失败"
        adg_download_size="$(wc -c < "$adg_ipk" | tr -d ' ')"
        log "已下载: AdGuardHome $ADGUARDHOME_VERSION ($adg_download_size bytes)"
        install_ipk_file "$adg_ipk" "AdGuardHome"
    fi

    for needed in \
        /usr/lib/lua/luci/controller/AdGuardHome.lua \
        /usr/lib/lua/luci/model/cbi/AdGuardHome/base.lua \
        /usr/lib/lua/luci/model/cbi/AdGuardHome/manual.lua \
        /usr/lib/lua/luci/model/cbi/AdGuardHome/log.lua \
        /usr/share/AdGuardHome/AdGuardHome_template.yaml; do
        [ -f "$needed" ] || die "AdGuardHome 安装不完整，缺少 $needed"
    done

    log_stage 3 5 "写入 LuCI 包装页与运行时文件"
    backup_file /usr/lib/lua/luci/controller/AdGuardHome.lua
    backup_file /usr/lib/lua/luci/view/AdGuardHome/oem_wrapper.htm
    backup_file /usr/lib/lua/luci/view/AdGuardHome/AdGuardHome_status.htm
    backup_file /usr/lib/lua/luci/model/cbi/AdGuardHome/base.lua

    write_adguard_wrapper_files
    patch_adguard_enable_hook
    fix_adguard_start_order
    normalize_adguard_yaml_defaults /usr/share/AdGuardHome/AdGuardHome_template.yaml
    normalize_adguard_yaml_defaults "$(get_adguard_configpath)"
    cleanup_adguard_placeholder_config
    ensure_adguard_dashboard_auth_defaults
    ensure_adguard_openclash_dns_chain || die "AdGuardHome DNS 链事务失败，已恢复原配置"

    adg_ver="$(opkg status luci-app-adguardhome 2>/dev/null | awk -F': ' '/Version: /{print $2; exit}')"
    [ -n "$adg_ver" ] || adg_ver="$ADGUARDHOME_VERSION"
    adg_size="$(opkg status luci-app-adguardhome 2>/dev/null | awk -F': ' '/Installed-Size: /{print $2; exit}')"
    [ -n "$adg_size" ] || adg_size="91326"
    log_stage 4 5 "写入图标、应用商店入口、虚拟内存并校验 LuCI 路由"
    backup_file "$CFG"
    adg_icon_name=""
    if install_adguardhome_embedded_icon; then
        adg_icon_name="$ADGUARDHOME_ICON_NAME"
    fi
    set_appcenter_entry "luci-app-adguardhome" "luci-app-adguardhome" "$adg_ver" "$adg_size" "/usr/lib/lua/luci/controller/AdGuardHome.lua" "admin/services/AdGuardHome" "$adg_icon_name"
    uci commit appcenter

    write_plugin_uninstall_assets
    patch_common_template
    refresh_luci_appcenter
    ensure_plugin_autostart_order
    fix_adguard_runtime_if_possible
    ensure_adguard_openclash_dns_chain || die "AdGuardHome DNS 链事务失败，已恢复原配置"
    ensure_existing_swap_access "AdGuardHome"
    verify_appcenter_route "luci-app-adguardhome" "admin/services/AdGuardHome"
    verify_file_exists /usr/lib/lua/luci/controller/AdGuardHome.lua "AdGuardHome"
    grep -Fq 'function adgEnableTouchScroll(d)' /usr/lib/lua/luci/view/AdGuardHome/oem_wrapper.htm 2>/dev/null || die "AdGuardHome 手机 iframe 触摸滚动兼容内容缺失"
    verify_luci_route admin/services/AdGuardHome "AdGuardHome"
    verify_luci_route admin/services/AdGuardHome/overview "AdGuardHome"
    verify_luci_route admin/services/AdGuardHome/settings "AdGuardHome"
    verify_luci_route admin/services/AdGuardHome/base "AdGuardHome"
    verify_luci_route admin/services/AdGuardHome/manual "AdGuardHome"
    verify_luci_route admin/services/AdGuardHome/log "AdGuardHome"

    log_stage 5 5 "可选下载核心并完成最终校验"
    adg_core_downloaded='0'
    if confirm_default_yes "是否现在下载 AdGuardHome 核心（CDN）？"; then
        download_adguardhome_core
        adg_core_downloaded='1'
        verify_file_exists /usr/bin/AdGuardHome/AdGuardHome "AdGuardHome core"
        fix_adguard_runtime_if_possible
        ensure_adguard_openclash_dns_chain || die "AdGuardHome DNS 链事务失败，已恢复原配置"
    else
        log "备注:     已跳过 AdGuardHome 核心下载"
    fi

    # 安装内核后引导设置仪表盘账号密码（账号默认 admin，除非用户设置）
    guide_adguard_dashboard_account || die "AdGuardHome 已安装，但 3000 仪表盘账号密码未设置成功；请检查上方错误后重跑 1 > 4"

    adg_installed_bin="$(uci -q get AdGuardHome.AdGuardHome.binpath 2>/dev/null || true)"
    [ -n "$adg_installed_bin" ] || adg_installed_bin='/usr/bin/AdGuardHome/AdGuardHome'
    if [ -x "$adg_installed_bin" ] && [ -s "$(get_adguard_configpath)" ]; then
        ensure_adguard_autostart || die "AdGuardHome 开机启动设置失败"
    fi

    log "安装完成"
    log "插件:   AdGuardHome"
    log "版本:  $adg_ver"
    log "路由:    admin/services/AdGuardHome"
    if [ "$adg_core_downloaded" = '1' ]; then
        log "核心:     AdGuardHome"
        log "核心版本: latest"
        log "核心路径: /usr/bin/AdGuardHome/AdGuardHome"
    elif [ "$adg_luci_reused" = '1' ]; then
        log "备注:     LuCI 安装包已是目标版本，仅刷新包装页和运行时检查"
    elif [ -x /usr/bin/AdGuardHome/AdGuardHome ]; then
        log "备注:     已检测到核心，配置和启动状态已检查"
    else
        log "备注:     LuCI 已装好；核心请在 AdGuardHome 页面里更新后再启动"
    fi
    log "下一步: 关闭应用商店弹窗后按 Ctrl+F5，再重新打开 AdGuardHome"
}

write_openlist_runtime_files() {
    openlist_helper="/usr/libexec/openlist-sync-config"
    openlist_init="/etc/init.d/openlist"

    mkdir -p /usr/libexec
    backup_file "$openlist_helper"
    backup_file "$openlist_init"

    {
        printf '%s\n' '#!/bin/sh'
        printf '%s\n' 'set -e'
        printf '%s\n' '. /lib/functions.sh'
        printf '\n'
        printf 'DEFAULT_DATA_DIR=%s\n' "$(shell_quote "$OPENLIST_DATA_DIR")"
        printf 'DEFAULT_TEMP_DIR=%s\n' "$(shell_quote "$OPENLIST_TEMP_DIR")"
        printf 'DEFAULT_LOG_PATH=%s\n' "$(shell_quote "$OPENLIST_LOG_PATH")"
        printf '%s\n' 'SKIP_FIREWALL_SYNC="${OPENLIST_SKIP_FIREWALL_SYNC:-0}"'
        printf '\n'
        cat <<'EOF_OPENLIST_SYNC'
json_escape() {
    printf '%s' "$1" | sed 's/\\/\\\\/g; s/"/\\"/g'
}

load_old_secret() {
    cfg="$1"
    [ -s "$cfg" ] || return 1
    sed -n 's/^[[:space:]]*"jwt_secret"[[:space:]]*:[[:space:]]*"\([^"]*\)".*/\1/p' "$cfg" | head -n 1
}

generate_secret() {
    if command -v md5sum >/dev/null 2>&1; then
        dd if=/dev/urandom bs=32 count=1 2>/dev/null | md5sum | awk '{print substr($1,1,16)}'
    else
        date +%s | awk '{printf "openlist%s", $1}'
    fi
}

ensure_firewall_rule() {
    port="$1"
    allow_wan="$2"
    firewall_changed='0'

    existing_openlist_rules="$(uci -X show firewall 2>/dev/null | awk '
        /^firewall\.[^.]+=rule$/ {
            sec=$1
            sub(/^firewall\./, "", sec)
            sub(/=.*/, "", sec)
            current=sec
            next
        }
        current != "" && $0 == ("firewall." current ".name='\''nradio_openlist'\''") {
            print current
            current=""
        }
    ')"
    for sec in $existing_openlist_rules; do
        [ -n "$sec" ] || continue
        uci -q delete "firewall.$sec" >/dev/null 2>&1 || true
        firewall_changed='1'
    done

    if [ "$allow_wan" = "1" ]; then
        sec="$(uci -q add firewall rule 2>/dev/null || true)"
        if [ -n "$sec" ]; then
            uci -q set "firewall.$sec.name=nradio_openlist" >/dev/null 2>&1 || true
            uci -q set "firewall.$sec.src=wan" >/dev/null 2>&1 || true
            uci -q set "firewall.$sec.proto=tcp" >/dev/null 2>&1 || true
            uci -q set "firewall.$sec.dest_port=$port" >/dev/null 2>&1 || true
            uci -q set "firewall.$sec.target=ACCEPT" >/dev/null 2>&1 || true
            firewall_changed='1'
        fi
    fi

    if [ "$firewall_changed" = "1" ]; then
        uci -q commit firewall >/dev/null 2>&1 || true
        /etc/init.d/firewall reload >/dev/null 2>&1 || true
    fi
}

config_load openlist
enabled="1"; config_get enabled main enabled '1'
port="5244"; config_get port main port '5244'
allow_wan="0"; config_get allow_wan main allow_wan '0'
data_dir="$DEFAULT_DATA_DIR"; config_get data_dir main data_dir "$DEFAULT_DATA_DIR"
temp_dir="$DEFAULT_TEMP_DIR"; config_get temp_dir main temp_dir "$DEFAULT_TEMP_DIR"
site_url=""; config_get site_url main site_url ''
log_enable="1"; config_get log_enable main log '1'
log_path="$DEFAULT_LOG_PATH"; config_get log_path main log_path "$DEFAULT_LOG_PATH"
token_expires_in="48"; config_get token_expires_in main token_expires_in '48'
jwt_secret=""; config_get jwt_secret main jwt_secret ''

mkdir -p "$data_dir" "$temp_dir" "$(dirname "$log_path")"
touch "$log_path" 2>/dev/null || true

config_json="$data_dir/config.json"
db_file="$data_dir/data.db"
bleve_dir="$data_dir/bleve"

if [ -s "$config_json" ]; then
lua - "$config_json" <<'EOF_OPENLIST_MERGE'
local fs = require "nixio.fs"
local nixio = require "nixio"
local json = require "luci.jsonc"
local uci = require("luci.model.uci").cursor()
local path = arg[1]
local tmp = path .. ".sync." .. tostring(nixio.getpid())
local ok, err = pcall(function()
    local data = assert(json.parse(assert(fs.readfile(path))), "invalid OpenList JSON")
    assert(type(data) == "table", "OpenList config must be an object")
    local function setting(key, fallback)
        local value = uci:get("openlist", "main", key)
        if value == nil then return fallback end
        return value
    end
    data.scheme = data.scheme or {}
    data.log = data.log or {}
    assert(type(data.scheme) == "table" and type(data.log) == "table", "invalid scheme/log object")
    local port = tonumber(setting("port", "5244"))
    local ttl = tonumber(setting("token_expires_in", "48"))
    assert(port and port >= 1 and port <= 65535 and port % 1 == 0, "invalid port")
    assert(ttl and ttl > 0, "invalid token lifetime")
    data.scheme.http_port = port
    data.site_url = setting("site_url", data.site_url or "")
    data.temp_dir = setting("temp_dir", data.temp_dir)
    data.token_expires_in = ttl
    data.log.enable = setting("log", "1") == "1"
    data.log.name = setting("log_path", data.log.name)
    local secret = setting("jwt_secret", "")
    if secret ~= "" then data.jwt_secret = secret end
    assert(fs.writefile(tmp, assert(json.stringify(data))), "cannot write OpenList JSON")
    assert(fs.chmod(tmp, "0600"), "cannot protect OpenList JSON")
    assert(fs.rename(tmp, path), "cannot replace OpenList JSON")
end)
if not ok then
    fs.unlink(tmp)
    io.stderr:write("OpenList config sync failed: " .. tostring(err) .. "\n")
    os.exit(1)
end
EOF_OPENLIST_MERGE
    chmod 600 "$config_json" 2>/dev/null || true
    if [ "$SKIP_FIREWALL_SYNC" != "1" ]; then
        ensure_firewall_rule "$port" "$allow_wan"
    fi
    exit 0
fi

if [ -z "$jwt_secret" ]; then
    jwt_secret="$(load_old_secret "$config_json" 2>/dev/null || true)"
fi
[ -n "$jwt_secret" ] || jwt_secret="$(generate_secret)"

esc_site_url="$(json_escape "$site_url")"
esc_jwt_secret="$(json_escape "$jwt_secret")"
esc_db_file="$(json_escape "$db_file")"
esc_temp_dir="$(json_escape "$temp_dir")"
esc_bleve_dir="$(json_escape "$bleve_dir")"
esc_log_path="$(json_escape "$log_path")"

log_enable_json="true"
[ "$log_enable" = "1" ] || log_enable_json="false"

cat > "$config_json" <<EOF_JSON
{
  "force": false,
  "site_url": "$esc_site_url",
  "cdn": "",
  "jwt_secret": "$esc_jwt_secret",
  "token_expires_in": $token_expires_in,
  "database": {
    "type": "sqlite3",
    "host": "",
    "port": 0,
    "user": "",
    "password": "",
    "name": "",
    "db_file": "$esc_db_file",
    "table_prefix": "x_",
    "ssl_mode": "",
    "dsn": ""
  },
  "meilisearch": {
    "host": "http://localhost:7700",
    "api_key": "",
    "index": "openlist"
  },
  "scheme": {
    "address": "0.0.0.0",
    "http_port": $port,
    "https_port": -1,
