                text("ddnsgo-port","端口 "+port);
                text("ddnsgo-dns","DNS "+(data.dns||"-"));
                setUrl(port);
            })
            .catch(function(){setUrl("9876");});
    }
    refresh();
    window.setInterval(refresh,5000);
})();
