download_mosdns_core() {
    optimize_mosdns_cdn_order
    mkdir -p "$WORKDIR/mosdns"
    zip_path="$WORKDIR/mosdns/$MOSDNS_ASSET_NAME"
    download_from_urls "$zip_path" $MOSDNS_DOWNLOAD_URLS || die "MosDNS 核心下载失败"

    mkdir -p "$WORKDIR/mosdns/unpack"
    ensure_default_feeds
    ensure_opkg_update || die "opkg update 失败，已停止 MosDNS 安装"
    ensure_packages unzip || die "MosDNS 依赖安装失败：unzip"
    if command -v unzip >/dev/null 2>&1; then
        unzip -tq "$zip_path" >"$WORKDIR/mosdns-archive-validate.log" 2>&1 || {
            sed -n '1,120p' "$WORKDIR/mosdns-archive-validate.log" >&2
            die "MosDNS ZIP 校验失败"
        }
        unzip -oq "$zip_path" -d "$WORKDIR/mosdns/unpack" >"$WORKDIR/mosdns-unpack.log" 2>&1 || {
            sed -n '1,120p' "$WORKDIR/mosdns-unpack.log" >&2
            die "MosDNS 解压失败"
        }
    elif busybox unzip -oq "$zip_path" -d "$WORKDIR/mosdns/unpack" >"$WORKDIR/mosdns-unpack.log" 2>&1; then
        :
    else
        sed -n '1,120p' "$WORKDIR/mosdns-unpack.log" >&2
        die "系统缺少 unzip，无法解压 MosDNS 官方发布包"
    fi
    bin=""
    for c in "$WORKDIR/mosdns/unpack/mosdns" "$WORKDIR/mosdns/unpack"/*/mosdns; do
        [ -f "$c" ] && { bin="$c"; break; }
    done
    [ -n "$bin" ] || die "未找到 mosdns 二进制"
    [ -f "$MOSDNS_BIN" ] && backup_file "$MOSDNS_BIN"
    cp "$bin" "$MOSDNS_BIN"; chmod 755 "$MOSDNS_BIN"
}

install_mosdns() {
    require_nradio_oem_appcenter
    case "${MOSDNS_PORT:-553}" in
        ''|*[!0-9]*|0) MOSDNS_PORT='553' ;;
    esac
    log_stage 1 6 "MosDNS 安装"
    download_mosdns_core
    log_stage 2 6 "写入 MosDNS 配置文件"

    mkdir -p "$MOSDNS_CONFIG_DIR" /usr/libexec
    cat > "$MOSDNS_SYNC" <<'EOF_MOSDNS_SYNC'
#!/bin/sh
CFG="/etc/mosdns/config.yaml"
LISTEN_ADDR="$(uci -q get mosdns.main.listen_addr 2>/dev/null || echo 127.0.0.1)"
LISTEN_PORT="$(uci -q get mosdns.main.listen_port 2>/dev/null || echo __MOSDNS_DEFAULT_PORT__)"
DOMESTIC_DNS="$(uci -q get mosdns.main.domestic_dns 2>/dev/null || echo 'https://223.5.5.5/dns-query https://120.53.53.53/dns-query')"
FOREIGN_DNS="$(uci -q get mosdns.main.foreign_dns 2>/dev/null || echo 'https://1.1.1.1/dns-query https://8.8.8.8/dns-query')"
FALLBACK_DNS="$(uci -q get mosdns.main.fallback_dns 2>/dev/null || echo 114.114.114.114:53)"
CACHE_SIZE="$(uci -q get mosdns.main.cache_size 2>/dev/null || echo 10240)"
CACHE_TTL="$(uci -q get mosdns.main.cache_ttl 2>/dev/null || echo 600)"
LOG_FILE="$(uci -q get mosdns.main.log_file 2>/dev/null || echo /var/log/mosdns.log)"
LOG_LEVEL="$(uci -q get mosdns.main.log_level 2>/dev/null || echo info)"
case "$LOG_FILE" in
    /var/log/mosdns.log|/var/log/mosdns/*) ;;
    *) echo "invalid MosDNS log path: $LOG_FILE" >&2; exit 1 ;;
esac
case "$LOG_FILE" in
    *'/../'*|*'/./'*|*'//'|*[!A-Za-z0-9_./-]*)
        echo "unsafe MosDNS log path: $LOG_FILE" >&2
        exit 1
        ;;
esac
mkdir -p "$(dirname "$CFG")"
{
cat <<YAML
log:
  level: ${LOG_LEVEL}
  file: ${LOG_FILE}
plugins:
  - tag: cache
    type: cache
    args:
      size: ${CACHE_SIZE}
      lazy_cache_ttl: ${CACHE_TTL}
  - tag: domestic_dns
    type: forward
    args:
      upstreams:
YAML
for dns in $DOMESTIC_DNS; do echo "        - addr: $dns"; done
cat <<YAML
  - tag: foreign_dns
    type: forward
    args:
      upstreams:
YAML
for dns in $FOREIGN_DNS; do echo "        - addr: $dns"; done
cat <<YAML
  - tag: fallback_dns
    type: forward
    args:
      upstreams:
        - addr: ${FALLBACK_DNS}
  - tag: main_seq
    type: sequence
    args:
      - exec: \$cache
      - matches: has_resp
        exec: accept
      - exec: \$domestic_dns
      - matches: has_resp
        exec: accept
      - exec: \$foreign_dns
      - matches: has_resp
        exec: accept
      - exec: \$fallback_dns
  - tag: main_udp
    type: udp_server
    args:
      entry: main_seq
      listen: ${LISTEN_ADDR}:${LISTEN_PORT}
YAML
} > "$CFG"
EOF_MOSDNS_SYNC
    sed -i "s/__MOSDNS_DEFAULT_PORT__/$MOSDNS_PORT/g" "$MOSDNS_SYNC" 2>/dev/null || true
    chmod 755 "$MOSDNS_SYNC"

    cat > "$MOSDNS_UCI_CONFIG" <<EOF_MOSDNS_UCI
config mosdns 'main'
    option enabled '1'
    option listen_addr '127.0.0.1'
    option listen_port '$MOSDNS_PORT'
    option domestic_dns 'https://223.5.5.5/dns-query https://120.53.53.53/dns-query'
    option foreign_dns 'https://1.1.1.1/dns-query https://8.8.8.8/dns-query'
    option fallback_dns '114.114.114.114:53'
    option cache_size '10240'
    option cache_ttl '600'
    option log_file '/var/log/mosdns.log'
    option log_level 'info'
EOF_MOSDNS_UCI

    log_stage 3 6 "写入 MosDNS 启动脚本"
    cat > "$MOSDNS_INIT" <<'EOF_MOSDNS_INIT'
#!/bin/sh /etc/rc.common
USE_PROCD=1
START=90
STOP=15
SYNC="/usr/libexec/mosdns-sync-config"
BIN="/usr/bin/mosdns"
CFG="/etc/mosdns/config.yaml"
start_service() {
    [ -x "$SYNC" ] || return 1
    "$SYNC" 2>/dev/null || return 1
    [ -x "$BIN" ] || return 1
    [ "$(uci -q get mosdns.main.enabled 2>/dev/null || echo 1)" = "1" ] || return 0
    procd_open_instance
    procd_set_param command "$BIN" start -c "$CFG"
    procd_set_param respawn 3600 5 5
    procd_set_param stdout 1; procd_set_param stderr 1
    procd_close_instance
}
reload_service() { stop; start; }
service_triggers() { procd_add_reload_trigger "mosdns"; }
EOF_MOSDNS_INIT
    chmod 755 "$MOSDNS_INIT"

    log_stage 4 6 "写入 MosDNS OEM 页面、图标并注册应用商店"
    mosdns_polish="/usr/lib/lua/luci/view/nradio_adv/mosdns_polish.htm"
    mkdir -p "$(dirname "$MOSDNS_CONTROLLER")" "$(dirname "$MOSDNS_CBI")" "$(dirname "$MOSDNS_VIEW")"

    cat > "$MOSDNS_CONTROLLER" <<'EOF_MOSDNS_CTRL'
module("luci.controller.nradio_adv.mosdns", package.seeall)
function index()
    entry({"nradioadv","system","mosdns"}, alias("nradioadv","system","mosdns","basic"), _("MosDNS"), 80)
    entry({"nradioadv","system","mosdns","basic"}, cbi("nradio_adv/mosdns_basic"), _("设置"), 10).leaf = true
    entry({"nradioadv","system","mosdns","logs"}, template("nradio_adv/mosdns_logs"), _("运行日志"), 20).leaf = true
    entry({"nradioadv","system","appcenter","mosdns"}, alias("nradioadv","system","mosdns"), nil, nil, true).leaf = true
end
EOF_MOSDNS_CTRL

    cat > "$MOSDNS_CBI" <<'EOF_MOSDNS_CBI'
local m,s,o
m=Map("mosdns", translate("MosDNS"),translate("DNS 分流: <a href='%s'>日志</a>"):format(require("luci.dispatcher").build_url("nradioadv","system","mosdns","logs")))
s=m:section(NamedSection,"main","mosdns",translate("运行设置"))
o=s:option(Flag,"enabled",translate("启用")); o.default=1; o.rmempty=false
o=s:option(Value,"listen_addr",translate("监听地址")); o.default="127.0.0.1"; o.rmempty=false
o=s:option(Value,"listen_port",translate("监听端口")); o.default="__MOSDNS_DEFAULT_PORT__"; o.datatype="port"; o.rmempty=false
s=m:section(NamedSection,"main","mosdns",translate("上游 DNS"))
o=s:option(Value,"domestic_dns",translate("国内 DNS")); o.default="https://223.5.5.5/dns-query https://120.53.53.53/dns-query"
o=s:option(Value,"foreign_dns",translate("国外 DNS")); o.default="https://1.1.1.1/dns-query https://8.8.8.8/dns-query"
o=s:option(Value,"fallback_dns",translate("备用 DNS")); o.default="114.114.114.114:53"
s=m:section(NamedSection,"main","mosdns",translate("缓存"))
o=s:option(Value,"cache_size",translate("条数")); o.default="10240"; o.datatype="uinteger"
o=s:option(Value,"cache_ttl",translate("TTL(秒)")); o.default="600"; o.datatype="uinteger"
s=m:section(NamedSection,"main","mosdns",translate("日志"))
o=s:option(Value,"log_file",translate("日志文件")); o.default="/var/log/mosdns.log"
o.validate=function(self,value)
    local allowed=value=="/var/log/mosdns.log" or value:match("^/var/log/mosdns/[%w%._%-%/]+$")
    if allowed and not value:find("/../",1,true) and not value:find("/./",1,true) and not value:find("//",1,true) then
        return value
    end
    return nil,translate("日志文件只能位于 /var/log/mosdns/，且不能包含路径穿越")
end
o=s:option(ListValue,"log_level",translate("日志级别"))
o:value("debug"); o:value("info"); o:value("warn"); o:value("error"); o.default="info"
m.on_after_commit=function()
    local sys=require("luci.sys")
    if sys.call("/usr/libexec/mosdns-sync-config >/var/log/mosdns-sync.log 2>&1") ~= 0 or sys.call("/etc/init.d/mosdns restart >/dev/null 2>&1") ~= 0 then
        m.message=translate("MosDNS 配置同步或服务重启失败，请检查运行日志")
    end
end
m:append(Template("nradio_adv/mosdns_polish"))
return m
EOF_MOSDNS_CBI
    sed -i "s/__MOSDNS_DEFAULT_PORT__/$MOSDNS_PORT/g" "$MOSDNS_CBI" 2>/dev/null || true

    cat > "$mosdns_polish" <<'EOF_MOSDNS_POLISH'
<style>
/* NRadio MosDNS premium visual finish */
body{background:#0b1220!important;color:#e5edf7!important}
.cbi-map{position:relative;overflow:hidden;border:1px solid rgba(103,232,249,.22)!important;border-radius:18px!important;background:radial-gradient(circle at 12% 0%,rgba(34,211,238,.16),transparent 34%),radial-gradient(circle at 92% 10%,rgba(14,165,233,.10),transparent 30%),linear-gradient(145deg,rgba(15,23,42,.96),rgba(3,7,18,.94))!important;box-shadow:inset 0 1px 0 rgba(255,255,255,.08),0 24px 54px rgba(2,8,23,.30)!important;color:#e5edf7!important}
.cbi-map:before{content:"";position:absolute;left:22px;right:22px;top:0;height:1px;background:linear-gradient(90deg,transparent,rgba(103,232,249,.66),rgba(96,165,250,.32),transparent);pointer-events:none}.cbi-map h2{color:#f8fbff!important;font-weight:900!important;letter-spacing:.01em;text-shadow:0 1px 0 rgba(0,0,0,.28)}.cbi-map-descr{color:#a9bbcf!important}.cbi-section{border:1px solid rgba(148,163,184,.18)!important;border-radius:16px!important;background:rgba(8,15,28,.56)!important;box-shadow:inset 0 1px 0 rgba(255,255,255,.045)!important}.cbi-value{border-bottom-color:rgba(148,163,184,.12)!important}.cbi-value-title{color:#bfd2e6!important;font-weight:800!important}.cbi-value-field,.cbi-value-description{color:#dbe7f4!important}.cbi-input-text,.cbi-input-password,select{border-color:rgba(103,232,249,.24)!important;background:rgba(2,8,23,.72)!important;color:#f8fbff!important;border-radius:10px!important;box-shadow:inset 0 1px 0 rgba(255,255,255,.04)!important}.cbi-input-text:focus,.cbi-input-password:focus,select:focus{border-color:rgba(34,211,238,.58)!important;box-shadow:0 0 0 3px rgba(34,211,238,.13),inset 0 1px 0 rgba(255,255,255,.05)!important;outline:0!important}.cbi-button{border-radius:10px!important;border-color:rgba(103,232,249,.30)!important;background:linear-gradient(180deg,rgba(255,255,255,.055),rgba(255,255,255,.010)),rgba(5,12,22,.70)!important;color:#eef7ff!important;font-weight:800!important;box-shadow:inset 0 1px 0 rgba(255,255,255,.052),0 8px 18px rgba(0,0,0,.14)!important}.cbi-button:hover{border-color:rgba(34,211,238,.54)!important;background:linear-gradient(180deg,rgba(34,211,238,.18),rgba(34,211,238,.045)),rgba(5,12,22,.76)!important;color:#fff!important}.cbi-button-apply{border-color:rgba(34,211,238,.48)!important;background:linear-gradient(135deg,rgba(8,145,178,.36),rgba(59,130,246,.20)),rgba(5,12,22,.76)!important}
.cbi-value-field,.cbi-value-description,.cbi-section-node{min-width:0!important;overflow-wrap:anywhere!important}.cbi-map,.cbi-section,.cbi-button{backdrop-filter:saturate(1.04) blur(3px);-webkit-backdrop-filter:saturate(1.04) blur(3px)}@media(max-width:520px){.cbi-map{border-radius:15px!important}.cbi-section{border-radius:14px!important}.cbi-value-title,.cbi-value-field{display:block!important;width:auto!important}}
</style>
EOF_MOSDNS_POLISH

    cat > "$MOSDNS_VIEW" <<'EOF_MOSDNS_VIEW'
<%+header%>
<style>
/* NRadio MosDNS log visual finish */
body{background:#0b1220!important;color:#e5edf7!important}.cbi-map{overflow:hidden;border-radius:18px!important;border:1px solid rgba(103,232,249,.22)!important;background:radial-gradient(circle at 12% 0%,rgba(34,211,238,.15),transparent 34%),linear-gradient(145deg,rgba(15,23,42,.96),rgba(3,7,18,.94))!important;box-shadow:0 24px 54px rgba(2,8,23,.30)!important}.cbi-map h2{color:#f8fbff!important;font-weight:900!important}.cbi-section{border:1px solid rgba(148,163,184,.18)!important;border-radius:16px!important;background:rgba(8,15,28,.56)!important}.cbi-value-title{color:#bfd2e6!important;font-weight:800!important}.cbi-value-field{color:#dbe7f4!important}.cbi-button{border-radius:10px!important;border-color:rgba(34,211,238,.48)!important;background:linear-gradient(135deg,rgba(8,145,178,.36),rgba(59,130,246,.20)),rgba(5,12,22,.76)!important;color:#eef7ff!important;font-weight:800!important}pre{white-space:pre-wrap;word-break:break-word!important;max-height:70vh;overflow:auto;border:1px solid rgba(103,232,249,.18)!important;border-radius:14px!important;background:#050b16!important;color:#dbeafe!important;padding:14px!important;line-height:1.58!important;box-shadow:inset 0 1px 0 rgba(255,255,255,.035)!important}
.cbi-value-field{min-width:0!important;overflow-wrap:anywhere!important}.cbi-button:focus-visible{outline:0!important;box-shadow:0 0 0 3px rgba(34,211,238,.16),inset 0 1px 0 rgba(255,255,255,.06)!important}pre{min-width:0!important;overflow-wrap:anywhere!important}
</style>
<% local u=require"luci.util"; local c=require"luci.model.uci".cursor(); local d=require"luci.dispatcher"; local fs=require"nixio.fs"
   local pid=u.trim(u.exec("pgrep mosdns 2>/dev/null | head -1"):gsub("[^%d]","")); local running=pid~=""
   local lf=c:get("mosdns","main","log_file") or "/var/log/mosdns.log"; if lf=="" then lf="/var/log/mosdns.log" end
   local allowed=lf=="/var/log/mosdns.log" or lf:match("^/var/log/mosdns/[%w%._%-%/]+$")
   local st=allowed and not lf:find("/../",1,true) and not lf:find("/./",1,true) and not lf:find("//",1,true) and fs.lstat(lf) or nil
   local logtext="日志为空"
   if st and st.type=="reg" then logtext=u.exec("tail -c 1048576 "..u.shellquote(lf).." 2>/dev/null | tail -n 400") or logtext
   elseif st then logtext="拒绝读取：日志路径不是普通文件"
   elseif not allowed then logtext="拒绝读取：日志路径越界"
   end %>
<div class="cbi-map"><h2>MosDNS</h2>
<div class="cbi-section"><div class="cbi-section-node">
<div class="cbi-value"><div class="cbi-value-title">状态</div><div class="cbi-value-field">
<% if running then %>运行中 (PID: <%=pid%>)<% else %>已停止<% end %>
</div></div>
<div class="cbi-value"><div class="cbi-value-field"><a class="cbi-button cbi-button-apply" href="<%=d.build_url("nradioadv","system","mosdns","basic")%>">返回设置</a></div></div>
<div class="cbi-value"><div class="cbi-value-field"><pre style="white-space:pre-wrap;word-break:break-all;max-height:70vh;overflow:auto;background:#0f172a;color:#e2e8f0;padding:12px;border-radius:6px;font-size:13px"><%=u.pcdata(logtext)%></pre></div></div>
</div></div></div>
<%+footer%>
EOF_MOSDNS_VIEW

    chmod 644 "$MOSDNS_CONTROLLER" "$MOSDNS_CBI" "$MOSDNS_VIEW" "$mosdns_polish" 2>/dev/null || true
    verify_file_exists "$mosdns_polish" "MosDNS 页面美化"

    install_mosdns_embedded_icon || die "MosDNS 图标写入失败"

    backup_file "$CFG"
    cleanup_appcenter_entry "$MOSDNS_APP_NAME" "$MOSDNS_APP_NAME" "nradioadv/system/mosdns/basic"
    set_appcenter_entry "$MOSDNS_APP_NAME" "$MOSDNS_APP_NAME" "$MOSDNS_VERSION" "18000000" \
        "$MOSDNS_CONTROLLER" "nradioadv/system/mosdns/basic" "$MOSDNS_ICON_NAME"
    uci commit appcenter || die "MosDNS 应用商店配置提交失败"
    write_plugin_uninstall_assets
    patch_common_template
    refresh_luci_appcenter
    /etc/init.d/uhttpd reload >/dev/null 2>&1 || die "MosDNS 安装后 LuCI 重载失败"

    log_stage 5 6 "启动 MosDNS"
    "$MOSDNS_SYNC" 2>/dev/null || die "MosDNS 配置同步失败"
    enable_init_service_strict "$MOSDNS_INIT" "MosDNS" || die "MosDNS 开机启动配置失败"
    restart_init_service_strict "$MOSDNS_INIT" "MosDNS" || die "MosDNS 启动失败"
    sleep 2
    pgrep mosdns >/dev/null 2>&1 || die "MosDNS 启动后未发现运行进程"
    is_local_port_listening "$MOSDNS_PORT" || die "MosDNS 启动后未监听端口 $MOSDNS_PORT"
    verify_file_exists "$MOSDNS_CONTROLLER" "MosDNS 控制器"
    verify_file_exists "$MOSDNS_CBI" "MosDNS 设置页"
    verify_luci_route nradioadv/system/mosdns/basic "MosDNS"

    log_stage 6 6 "MosDNS 安装完成"
    log "提示: dnsmasq 上游需手动设置为 127.0.0.1#$MOSDNS_PORT"
}

install_ddnsgo() {
    require_nradio_oem_appcenter
    ensure_default_feeds

    mkdir -p "$WORKDIR/ddnsgo"
    ddnsgo_archive="$WORKDIR/ddnsgo/$DDNSGO_ARCHIVE_NAME"
    ddnsgo_unpack="$WORKDIR/ddnsgo/unpack"
    ddnsgo_core_ipk=""
    ddnsgo_luci_ipk=""
    ddnsgo_i18n_ipk=""

    log_stage 1 7 "DDNS-GO GitHub OpenWrt 包安装规划"
    ddnsgo_target_arch="$(get_primary_arch)"
    [ -n "$ddnsgo_target_arch" ] || die "无法识别 opkg 架构，停止安装 DDNS-GO"
    [ "$ddnsgo_target_arch" = "$DDNSGO_PACKAGE_ARCH" ] || die "DDNS-GO 当前集成包适配 $DDNSGO_PACKAGE_ARCH，当前设备为 $ddnsgo_target_arch"
    log "版本: DDNS-GO $DDNSGO_PACKAGE_VERSION / LuCI $DDNSGO_LUCI_VERSION / 中文包 $DDNSGO_I18N_VERSION"
    confirm_or_exit "确认继续安装 DDNS-GO 并修改系统吗？"

    log_stage 2 7 "下载并检查 DDNS-GO OpenWrt 三件套"
    ddnsgo_pkg_urls="$DDNSGO_DOWNLOAD_URLS"
    rank_url_list_hosts "ddnsgo-package" "DDNS-GO OpenWrt 安装包" "$ddnsgo_pkg_urls"
    if [ -n "${RANKED_URL_HOSTS:-}" ]; then
        ddnsgo_pkg_urls="$(reorder_urls_by_host_rank "$ddnsgo_pkg_urls" "$RANKED_URL_HOSTS")"
        log "提示: DDNS-GO 下载主机优先级: $RANKED_URL_HOSTS"
    fi
    log "提示: DDNS-GO 实际下载源顺序: $(summarize_url_hosts $ddnsgo_pkg_urls)"
    ddnsgo_download_stall_time_saved="$DOWNLOAD_STALL_TIME"
    ddnsgo_download_stall_speed_saved="$DOWNLOAD_STALL_SPEED"
    ddnsgo_download_max_time_saved="$DOWNLOAD_MAX_TIME"
    ddnsgo_download_keep_partial_saved="${DOWNLOAD_KEEP_PARTIAL:-0}"
    DOWNLOAD_MAX_TIME="$DDNSGO_PACKAGE_MAX_TIME"
    DOWNLOAD_STALL_TIME="$DDNSGO_PACKAGE_STALL_TIME"
    DOWNLOAD_STALL_SPEED="$DDNSGO_PACKAGE_STALL_SPEED"
    DOWNLOAD_KEEP_PARTIAL=1
    ddnsgo_download_url=""
    if download_from_urls "$ddnsgo_archive" $ddnsgo_pkg_urls; then
        ddnsgo_download_url="$LAST_DOWNLOAD_SOURCE"
    fi
    if [ -z "$ddnsgo_download_url" ]; then
        log "提示: 首轮 DDNS-GO 安装包下载未完成，正在放宽速度阈值后重试..."
        DOWNLOAD_STALL_TIME="$DDNSGO_PACKAGE_RETRY_STALL_TIME"
        DOWNLOAD_STALL_SPEED="$DDNSGO_PACKAGE_RETRY_STALL_SPEED"
        if download_from_urls "$ddnsgo_archive" $ddnsgo_pkg_urls; then
            ddnsgo_download_url="$LAST_DOWNLOAD_SOURCE"
        fi
    fi
    DOWNLOAD_MAX_TIME="$ddnsgo_download_max_time_saved"
    DOWNLOAD_STALL_TIME="$ddnsgo_download_stall_time_saved"
    DOWNLOAD_STALL_SPEED="$ddnsgo_download_stall_speed_saved"
    DOWNLOAD_KEEP_PARTIAL="$ddnsgo_download_keep_partial_saved"
    [ -n "$ddnsgo_download_url" ] || die "无法从可用的 GitHub 地址下载 DDNS-GO OpenWrt 安装包"
    [ -s "$ddnsgo_archive" ] || die "DDNS-GO OpenWrt 安装包下载失败"
    validate_tar_archive "$ddnsgo_archive" "DDNS-GO OpenWrt 安装包" "$WORKDIR/ddnsgo-archive-validate.log"
    ddnsgo_download_host="$(extract_url_host "$ddnsgo_download_url" 2>/dev/null || true)"
    ddnsgo_archive_size="$(ddnsgo_size_value "$ddnsgo_archive" "0")"

    log_stage 3 7 "解包并安装 DDNS-GO 三件套"
    ensure_opkg_update || die "opkg update 失败，已停止 DDNS-GO 安装"
    ddnsgo_extract_need="$(estimate_archive_extract_bytes "$ddnsgo_archive" 2>/dev/null || true)"
    rm -rf "$ddnsgo_unpack"
    mkdir -p "$ddnsgo_unpack"
    ensure_dir_writable "$ddnsgo_unpack" "DDNS-GO 临时解压目录"
    case "$ddnsgo_extract_need" in
        ''|*[!0-9]*) ;;
        *) ensure_free_space_bytes "$ddnsgo_unpack" "$ddnsgo_extract_need" "DDNS-GO 临时解压目录" ;;
    esac
    tar -xzf "$ddnsgo_archive" -C "$ddnsgo_unpack" >/dev/null 2>&1 || die "解压 DDNS-GO OpenWrt 安装包失败"

    for candidate in \
        "$ddnsgo_unpack"/packages_ci/ddns-go_"$DDNSGO_PACKAGE_VERSION"_"$DDNSGO_PACKAGE_ARCH".ipk \
        "$ddnsgo_unpack"/*/ddns-go_"$DDNSGO_PACKAGE_VERSION"_"$DDNSGO_PACKAGE_ARCH".ipk \
        "$ddnsgo_unpack"/*/*/ddns-go_"$DDNSGO_PACKAGE_VERSION"_"$DDNSGO_PACKAGE_ARCH".ipk
    do
        [ -f "$candidate" ] || continue
        ddnsgo_core_ipk="$candidate"
        break
    done
    for candidate in \
        "$ddnsgo_unpack"/packages_ci/luci-app-ddns-go_"$DDNSGO_LUCI_VERSION"_all.ipk \
        "$ddnsgo_unpack"/*/luci-app-ddns-go_"$DDNSGO_LUCI_VERSION"_all.ipk \
        "$ddnsgo_unpack"/*/*/luci-app-ddns-go_"$DDNSGO_LUCI_VERSION"_all.ipk
    do
        [ -f "$candidate" ] || continue
        ddnsgo_luci_ipk="$candidate"
        break
    done
    for candidate in \
        "$ddnsgo_unpack"/packages_ci/luci-i18n-ddns-go-zh-cn_"$DDNSGO_I18N_VERSION"_all.ipk \
        "$ddnsgo_unpack"/packages_ci/luci-i18n-ddns-go-zh-cn*_all.ipk \
        "$ddnsgo_unpack"/*/luci-i18n-ddns-go-zh-cn_"$DDNSGO_I18N_VERSION"_all.ipk \
        "$ddnsgo_unpack"/*/luci-i18n-ddns-go-zh-cn*_all.ipk \
        "$ddnsgo_unpack"/*/*/luci-i18n-ddns-go-zh-cn_"$DDNSGO_I18N_VERSION"_all.ipk \
        "$ddnsgo_unpack"/*/*/luci-i18n-ddns-go-zh-cn*_all.ipk
    do
        [ -f "$candidate" ] || continue
        ddnsgo_i18n_ipk="$candidate"
        break
    done
    [ -n "$ddnsgo_core_ipk" ] || die "解压后未找到 DDNS-GO 核心安装包"
    [ -n "$ddnsgo_luci_ipk" ] || die "解压后未找到 DDNS-GO LuCI 安装包"
    [ -n "$ddnsgo_i18n_ipk" ] || die "解压后未找到 DDNS-GO 中文语言包"
    install_ipk_file "$ddnsgo_core_ipk" "DDNS-GO 核心"
    install_ipk_file "$ddnsgo_luci_ipk" "DDNS-GO LuCI"
    install_ipk_file "$ddnsgo_i18n_ipk" "DDNS-GO 中文语言包"
    ddnsgo_installed_ver="$(get_installed_package_version "$DDNSGO_PACKAGE_NAME" 2>/dev/null || true)"
    [ -n "$ddnsgo_installed_ver" ] || ddnsgo_installed_ver="$DDNSGO_PACKAGE_VERSION"
    ddnsgo_core_size="$(ddnsgo_size_value "$DDNSGO_BIN_PATH" "$DDNSGO_CORE_SIZE")"
    ddnsgo_luci_size="$(ddnsgo_size_value "$ddnsgo_luci_ipk" "$DDNSGO_LUCI_SIZE")"
    ddnsgo_i18n_size="$(ddnsgo_size_value "$ddnsgo_i18n_ipk" "$DDNSGO_I18N_SIZE")"

    log_stage 4 7 "写入 DDNS-GO 默认配置与 OEM 包装页"
    ensure_ddnsgo_config_defaults
    write_ddnsgo_oem_files

    log_stage 5 7 "写入图标、应用商店、多包注册与打开入口"
    backup_file "$CFG"
    ddnsgo_icon_name=""
    if install_ddnsgo_embedded_icon; then
        ddnsgo_icon_name="$DDNSGO_ICON_NAME"
    fi
    set_ddnsgo_appcenter_entry "$ddnsgo_core_size" "$ddnsgo_luci_size" "$ddnsgo_i18n_size" "$ddnsgo_icon_name"
    uci commit appcenter
    write_plugin_uninstall_assets
    patch_common_template
    refresh_luci_appcenter
    /etc/init.d/uhttpd reload >/dev/null 2>&1 || true

    log_stage 6 7 "启动 DDNS-GO 并写入虚拟内存"
    verify_file_exists "$DDNSGO_INIT_FILE" "$DDNSGO_APP_NAME"
    ensure_ddnsgo_config_defaults
    configure_ddnsgo_web_login
    enable_init_service_strict "$DDNSGO_INIT_FILE" "$DDNSGO_APP_NAME" || die "DDNS-GO 开机启动配置失败"
    ddnsgo_restart_log="$WORKDIR/ddnsgo-restart.log"
    if ! "$DDNSGO_INIT_FILE" restart >"$ddnsgo_restart_log" 2>&1; then
        sed -n '1,120p' "$ddnsgo_restart_log" >&2
        die "DDNS-GO 启动失败"
    fi
    sleep 2
    ensure_existing_swap_access "$DDNSGO_APP_NAME"

    log_stage 7 7 "逐项校验 DDNS-GO 文件、服务与应用商店入口"
    opkg status "$DDNSGO_PACKAGE_NAME" >/dev/null 2>&1 || die "DDNS-GO verify failed: missing package $DDNSGO_PACKAGE_NAME"
    opkg status "$DDNSGO_LUCI_PACKAGE_NAME" >/dev/null 2>&1 || die "DDNS-GO verify failed: missing package $DDNSGO_LUCI_PACKAGE_NAME"
    opkg status "$DDNSGO_I18N_PACKAGE_NAME" >/dev/null 2>&1 || die "DDNS-GO verify failed: missing package $DDNSGO_I18N_PACKAGE_NAME"
    verify_file_exists "$DDNSGO_BIN_PATH" "$DDNSGO_APP_NAME"
    verify_file_exists "$DDNSGO_INIT_FILE" "$DDNSGO_APP_NAME"
    verify_file_exists "$DDNSGO_CONFIG_FILE" "$DDNSGO_APP_NAME"
    verify_file_exists "$DDNSGO_CONFIG_YAML" "$DDNSGO_APP_NAME"
    verify_file_exists "$DDNSGO_CONTROLLER" "$DDNSGO_APP_NAME"
    verify_file_exists "$DDNSGO_VIEW" "$DDNSGO_APP_NAME"
    grep -Fq 'scrolling="auto"' "$DDNSGO_VIEW" 2>/dev/null || die "$DDNSGO_APP_NAME 手机 iframe 滚动适配校验失败"
    grep -Fq 'height:100dvh' "$DDNSGO_VIEW" 2>/dev/null || die "$DDNSGO_APP_NAME 手机动态视口适配校验失败"
    verify_file_exists "$APP_ICON_DIR/$DDNSGO_ICON_NAME" "$DDNSGO_APP_NAME"
    verify_appcenter_route "$DDNSGO_APP_NAME" "$DDNSGO_ROUTE"
    verify_luci_route "$DDNSGO_ROUTE" "$DDNSGO_APP_NAME"
    verify_luci_route "$DDNSGO_ROUTE/status" "$DDNSGO_APP_NAME"
    if ! pidof ddns-go >/dev/null 2>&1; then
        ddnsgo_status="$("$DDNSGO_INIT_FILE" status 2>/dev/null || true)"
        [ -n "$ddnsgo_status" ] && log "DDNS-GO 状态: $ddnsgo_status"
        die "DDNS-GO verify failed: service not running"
    fi
    ddnsgo_port="$(uci -q get ddns-go.config.port 2>/dev/null || echo 9876)"
    if command -v netstat >/dev/null 2>&1; then
        netstat -lntp 2>/dev/null | awk -v port="$ddnsgo_port" '$4 ~ (":" port "$") && $0 ~ /ddns-go/ { found = 1 } END { exit(found ? 0 : 1) }' || die "DDNS-GO verify failed: port $ddnsgo_port not listening"
    fi

    log "安装完成"
    log "插件:   $DDNSGO_APP_NAME"
    log "版本:   $ddnsgo_installed_ver"
    log "路由:   $DDNSGO_ROUTE"
    log "端口:   $ddnsgo_port"
    if [ -n "$ddnsgo_download_host" ]; then
        log "下载源: GitHub OpenWrt 包（$ddnsgo_download_host）"
    else
        log "下载源: GitHub OpenWrt 包"
    fi
    log "包大小: $ddnsgo_archive_size bytes"
}

write_mt5700_nradio_controller() {
    mt5700_controller_dir="$(dirname "$MT5700_CONTROLLER")"
    mt5700_controller_tmp="$MT5700_CONTROLLER.nradio.$$"

    mkdir -p "$mt5700_controller_dir" || die "创建 MT5700 WebUI 控制器目录失败"
    [ -f "$MT5700_CONTROLLER" ] && backup_file "$MT5700_CONTROLLER"
    cat > "$mt5700_controller_tmp" <<'EOF_MT5700_NRADIO_CONTROLLER'
module("luci.controller.nradio_adv.mt5700", package.seeall)

-- NRadio MT5700 WebUI redirect v1
local WEB_INDEX = "/www/5700/index.html"

function index()
    local page = entry({"nradioadv", "system", "mt5700"}, call("action_mt5700"), nil, 93)
    page.leaf = true
    page.dependent = false
end

local function render_unavailable()
    local http = require "luci.http"

    http.status(503, "Service Unavailable")
    http.prepare_content("text/html; charset=utf-8")
    http.write([[
<!doctype html>
<html lang="zh-CN">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width,initial-scale=1">
  <title>MT5700 WebUI 暂不可用</title>
  <style>
    html,body{margin:0;min-height:100%;font-family:-apple-system,BlinkMacSystemFont,"Segoe UI",sans-serif;background:#f3f7fb;color:#183047}
    .wrap{min-height:100vh;display:flex;align-items:center;justify-content:center;padding:24px;box-sizing:border-box}
    .card{width:min(520px,100%);padding:28px;border:1px solid #d7e4ee;border-radius:18px;background:#fff;box-shadow:0 18px 50px rgba(38,73,105,.12)}
    h1{margin:0 0 12px;font-size:24px}p{margin:8px 0;line-height:1.7;color:#536b80}
    a{display:inline-block;margin-top:12px;padding:10px 16px;border-radius:10px;background:#1976d2;color:#fff;text-decoration:none}
  </style>
</head>
<body><div class="wrap"><div class="card"><h1>MT5700 WebUI 暂不可用</h1><p>静态页面文件不存在。请从 NRadio 插件脚本重新安装或更新 MT5700 WebUI。</p><a href="/cgi-bin/luci/nradioadv/system/appcenter" target="_top">返回应用商店</a></div></div></body>
</html>
]])
end

function action_mt5700()
    local fs = require "nixio.fs"
    local http = require "luci.http"

    if http.formvalue("dual") == "1" and fs.access("/etc/nradio-mt5700-dual/enabled") then
        local line = http.formvalue("line") or "cpe"
        if line ~= "cpe" and line ~= "cpe1" then
            http.status(400, "Bad Request")
            http.write_json({ success = false, error = "未知线路" })
            return
        end
        local uci = require "luci.model.uci"
        local cur = uci.cursor()
        local ok, runtime = pcall(require("luci.util").ubus, "infocd", "runtime")
        if not ok or type(runtime) ~= "table" or type(runtime.cpe) ~= "table" then
            http.status(503, "Service Unavailable")
            http.write_json({ success = false, error = "线路信息读取失败" })
            return
        end
        local by_name, lines = {}, {}
        for _, item in ipairs(runtime.cpe) do
            if type(item) == "table" and (item.name == "cpe" or item.name == "cpe1") then
                by_name[item.name] = item
            end
        end
        for _, name in ipairs({ "cpe", "cpe1" }) do
            local item = by_name[name]
            if item then
                lines[#lines + 1] = {
                    name = name, available = true,
                    status = tonumber(item.status), mode = item.mode, band = item.band,
                    rsrp = item.rsrp, rsrq = item.rsrq, sinr = item.sinr,
                    temperature = item.model_temp, operator = item.sim_company or item.isp_company,
                    pci = item.pci, arfcn = item.earfcn
                }
            end
        end
        if not by_name[line] and lines[1] then line = lines[1].name end
        local config_name = line == "cpe1" and "at-webserver-cpe1" or "at-webserver"
        http.header("Cache-Control", "no-store")
        http.write_json({ success = true, line = line, lines = lines, timestamp = os.time(), data = {
            port = tonumber(cur:get(config_name, "config", "websocket_port")) or (line == "cpe1" and 8766 or 8765),
            require_auth = (cur:get(config_name, "config", "websocket_auth_key") or "") ~= ""
        } })
        return
    end

    if not fs.access(WEB_INDEX) then
        render_unavailable()
        return
    end

    http.header("Cache-Control", "no-store, no-cache, must-revalidate, max-age=0")
    http.header("Pragma", "no-cache")
    local version = require("luci.model.uci").cursor():get("appcenter", "nradio_mt5700", "version") or "installed"
    version = version:gsub("[^%w._%-]", "")
    http.redirect("/5700/?v=" .. version .. "#/network/info")
end
EOF_MT5700_NRADIO_CONTROLLER
    chmod 644 "$mt5700_controller_tmp" 2>/dev/null || true
    mv "$mt5700_controller_tmp" "$MT5700_CONTROLLER" || die "写入 MT5700 WebUI 控制器失败"
}

patch_mt5700_version_display() {
    # 上游包版本已更新，但页面标题与品牌文案仍可能保留旧版本号。
    sed -i "s/\(MT5700M-CN V\)[0-9][0-9A-Za-z.+-]*/\1$MT5700_UI_VERSION/g" "$MT5700_WEB_ROOT/index.html"
    for mt5700_entry_asset in "$MT5700_WEB_ROOT"/assets/index-*.js; do
        [ -f "$mt5700_entry_asset" ] || continue
        sed -i \
            -e "s/\(5G CPE · V\)[0-9][0-9A-Za-z.+-]*/\1$MT5700_UI_VERSION/g" \
            -e "s/\(5G CPE Management · V\)[0-9][0-9A-Za-z.+-]*/\1$MT5700_UI_VERSION/g" \
            "$mt5700_entry_asset"
    done
    sed -i "s|\(/5700/assets/[^\"?]*\)\(?[^\"]*\)\{0,1\}\"|\1?v=$MT5700_UI_VERSION\"|g" "$MT5700_WEB_ROOT/index.html"
}

patch_mt5700_boot_fallback() {
    mt5700_index="$MT5700_WEB_ROOT/index.html"
    mt5700_fallback_file="$WORKDIR/mt5700/boot-fallback.html"
    mt5700_index_tmp="$MT5700_WEB_ROOT/.index.html.nradio.$$"

    [ -s "$mt5700_index" ] || die "MT5700 WebUI 首页不存在"
    if grep -Fq 'nradio-mt5700-boot-fallback' "$mt5700_index" 2>/dev/null; then
        return 0
    fi

    mkdir -p "$(dirname "$mt5700_fallback_file")" || die "创建 MT5700 WebUI 临时目录失败"
    cat > "$mt5700_fallback_file" <<'EOF_MT5700_BOOT_FALLBACK'
    <div id="root">
      <div id="nradio-mt5700-boot-fallback" role="status" aria-live="polite">
        <div class="nradio-mt5700-boot-card">
          <div class="nradio-mt5700-boot-logo">MT</div>
          <h1>MT5700 WebUI</h1>
          <p id="nradio-mt5700-boot-state">页面正在加载，请稍候…</p>
          <div class="nradio-mt5700-boot-actions">
            <a href="/5700/?retry=1">重新加载</a>
            <a href="/5700/" target="_top">打开独立页面</a>
          </div>
          <noscript><p class="nradio-mt5700-boot-error">浏览器已禁用 JavaScript，MT5700 WebUI 无法启动。</p></noscript>
        </div>
      </div>
    </div>
    <style id="nradio-mt5700-boot-style">
      #nradio-mt5700-boot-fallback{min-height:100vh;display:flex;align-items:center;justify-content:center;padding:24px;box-sizing:border-box;background:linear-gradient(145deg,#eef5fb,#f8fbfd);color:#17324a;font-family:-apple-system,BlinkMacSystemFont,"Segoe UI",sans-serif}
      .nradio-mt5700-boot-card{width:min(520px,100%);padding:30px 26px;text-align:center;border:1px solid #d7e5ef;border-radius:20px;background:#fff;box-shadow:0 20px 55px rgba(41,78,111,.14)}
      .nradio-mt5700-boot-logo{width:68px;height:68px;margin:0 auto 16px;display:grid;place-items:center;border-radius:18px;background:linear-gradient(145deg,#2094e8,#16b8a6);color:#fff;font-size:24px;font-weight:800;letter-spacing:.06em}
      .nradio-mt5700-boot-card h1{margin:0 0 10px;font-size:25px;color:#17324a}.nradio-mt5700-boot-card p{margin:0;color:#587086;line-height:1.7}
      .nradio-mt5700-boot-actions{display:flex;justify-content:center;gap:10px;flex-wrap:wrap;margin-top:20px}.nradio-mt5700-boot-actions a{padding:9px 14px;border-radius:10px;background:#e8f2fa;color:#17659c;text-decoration:none;font-weight:600}.nradio-mt5700-boot-actions a:last-child{background:#1976d2;color:#fff}
      .nradio-mt5700-boot-error{margin-top:16px!important;color:#b5483f!important}
    </style>
    <script id="nradio-mt5700-boot-watchdog">
      window.setTimeout(function(){
        var fallback=document.getElementById("nradio-mt5700-boot-fallback");
        var state=document.getElementById("nradio-mt5700-boot-state");
        if(fallback&&state){state.textContent="页面资源加载超时。可重新加载，或在应用商店外打开独立页面。";state.className="nradio-mt5700-boot-error";}
      },8000);
    </script>
EOF_MT5700_BOOT_FALLBACK

    backup_file "$mt5700_index"
    if ! awk -v fallback_file="$mt5700_fallback_file" '
        BEGIN { replaced = 0 }
        /^[[:space:]]*<div id="root"><\/div>[[:space:]]*$/ {
            while ((getline extra < fallback_file) > 0) print extra
            close(fallback_file)
            replaced = 1
            next
        }
        { print }
        END { if (!replaced) exit 42 }
    ' "$mt5700_index" > "$mt5700_index_tmp"; then
        rm -f "$mt5700_index_tmp" 2>/dev/null || true
        die "MT5700 WebUI 首页结构不匹配，未写入防黑屏内容"
    fi
    chmod 644 "$mt5700_index_tmp" 2>/dev/null || true
    mv "$mt5700_index_tmp" "$mt5700_index" || die "写入 MT5700 WebUI 防黑屏内容失败"
}

write_mt5700_atsd_proxy_program() {
    mkdir -p "$(dirname "$MT5700_ATSD_PROXY_PATH")" || die "创建 MT5700 AT 共享桥目录失败"
    cat > "$MT5700_ATSD_PROXY_PATH" <<'EOF_MT5700_ATSD_PROXY'
#!/usr/bin/lua

local socket = require("socket")
local fs = require("nixio.fs")
local listen_port = tonumber(os.getenv("MT5700_ATSD_PROXY_PORT") or "20250")
local line = os.getenv("MT5700_ATSD_PROXY_LINE") or "cpe"
assert(line == "cpe" or line == "cpe1", "invalid AT line")

local function shell_quote(value)
    return "'" .. value:gsub("'", "'\\''") .. "'"
end

local function normalize_response(response)
    response = (response or ""):gsub("\r\n", "\n"):gsub("\r", "\n"):gsub("\n", "\r\n")
    if response == "" then
        return "ERROR\r\n"
    end
    if response:sub(-2) ~= "\r\n" then
        response = response .. "\r\n"
    end
    return response
end

local function execute_at(command)
    command = command:gsub("^%s+", ""):gsub("%s+$", "")
    local upper = command:upper()
    if upper:sub(1, 2) ~= "AT" and command:lower() ~= "abcd" then
        return "ERROR\r\n"
    end

    local wait_ms = 1500
    if upper:find("^AT%^CELLSCAN") then
        wait_ms = 180000
    end

    local pipe = io.popen(
        "/usr/sbin/atsd_cli -i " .. line .. " -c " .. shell_quote(command) ..
        " -w " .. tostring(wait_ms) .. " -L 1 2>/dev/null",
        "r"
    )
    if not pipe then
        return "ERROR\r\n"
    end
    local response = pipe:read("*a")
    pipe:close()
    return normalize_response(response)
end

-- ATSd owns the modem connection. Its live log contains the unsolicited PDCP
-- reports which atsd_cli command replies omit; never open a second modem port.
local log_path = "/tmp/log/messages"
local function open_reports(at_end)
    local stat = fs.stat(log_path)
    local file = stat and io.open(log_path, "r")
    if not file then return nil end
    return {file = file, inode = stat.ino, offset = file:seek(at_end and "end" or "set", 0), pending = ""}
end

local function read_reports(source)
    local stat = fs.stat(log_path)
    if not stat then return source, "" end
    if not source or source.inode ~= stat.ino or stat.size < source.offset then
        if source then source.file:close() end
        source = open_reports(false)
    end
    if not source then return nil, "" end
    if stat.size - source.offset > 65536 then
        source.offset = math.max(0, stat.size - 16384)
        source.pending = ""
    end
    source.file:seek("set", source.offset)
    local data = source.file:read(65536)
    if not data then return source, "" end
    source.offset = source.file:seek()
    data = source.pending .. data
    local complete = data:match("^(.*\n)") or ""
    source.pending = data:sub(#complete + 1)
    if #source.pending > 16384 then source.pending = "" end
    local report = ""
    for entry in complete:gmatch("[^\n]+") do
        if entry:find("[" .. line .. "]", 1, true) then
            local current = entry:match("(%^PDCPDATAINFO:%s*[%d,]+)")
            if current then report = current .. "\r\n" end
        end
    end
    return source, report
end

local function send_all(client, value)
    client:settimeout(2)
    local sent, err = client:send(value)
    client:settimeout(0.2)
    return sent == #value and not err
end

local server, bind_error = socket.bind("127.0.0.1", listen_port, 4)
if not server then
    error("MT5700 ATSd proxy bind failed: " .. tostring(bind_error))
end
server:settimeout(nil)

while true do
    local client = server:accept()
    if client then
        client:settimeout(0.2)
        local buffer = {}
        local length = 0
        local reports = open_reports(true)
        local next_report = socket.gettime()

        while true do
            local data, receive_error, partial = client:receive(1)
            local byte = data or partial
            if byte and byte ~= "" then
                if byte == "\r" or byte == "\n" then
                    if length > 0 then
                        local command = table.concat(buffer)
                        buffer = {}
                        length = 0
                        local setting = command:upper():match("^%s*AT%^PDCPDATAINFO=([01])")
                        local response
                        if setting == "0" then
                            -- Pages filter their own reports; the shared feed stays alive.
                            response = "OK\r\n"
                        else
                            response = execute_at(command)
                        end
                        if not send_all(client, response) then break end
                    end
                elseif length < 16384 then
                    length = length + 1
                    buffer[length] = byte
                else
                    buffer = {}
                    length = 0
                    if not send_all(client, "ERROR\r\n") then break end
                end
            end
            if receive_error and receive_error ~= "timeout" then break end
            if socket.gettime() >= next_report then
                next_report = socket.gettime() + 0.2
                local payload
                reports, payload = read_reports(reports)
                if payload ~= "" and not send_all(client, payload) then break end
            end
        end
        if reports then reports.file:close() end
        client:close()
    else
        socket.sleep(1)
    end
end
EOF_MT5700_ATSD_PROXY
    chmod 700 "$MT5700_ATSD_PROXY_PATH" || die "设置 MT5700 AT 共享桥权限失败"
}

patch_mt5700_speed_display() {
    # Keep genuine zero-rate samples instead of the upstream last-positive fallback.
    for mt5700_asset in "$MT5700_WEB_ROOT"/assets/index-*.js; do
        [ -f "$mt5700_asset" ] || continue
        /usr/bin/lua - "$mt5700_asset" <<'EOF_MT5700_SPEED_DISPLAY'
local path = arg[1]
local file = assert(io.open(path, "r"))
local text = file:read("*a")
file:close()
local updated, count = text:gsub("([%w_$]+)=([%w_$]+)&&%(%2%.ulPdcpRate>0||%2%.dlPdcpRate>0%)%?%2:[%w_$]+", "%1=%2")
if count > 0 then
    file = assert(io.open(path, "w"))
    assert(file:write(updated))
    file:close()
end
EOF_MT5700_SPEED_DISPLAY
        [ "$?" -eq 0 ] || die "更新 MT5700 网速显示失败"
    done
}

write_mt5700_c2000_atsd_proxy() {
    case "${CURRENT_DETECTED_MODEL:-}" in
        NRadio_C2000MAX|NRadio_C2000Ultra) ;;
        *) return 0 ;;
    esac
    [ -x /usr/sbin/atsd_cli ] || die "当前机型缺少 NROS atsd_cli，无法建立共享 AT 通道"
    [ -x /usr/bin/lua ] || die "当前机型缺少 Lua，无法建立共享 AT 通道"
    /usr/bin/lua -e 'require("socket")' >/dev/null 2>&1 || die "当前机型缺少 LuaSocket，无法建立共享 AT 通道"
    write_mt5700_atsd_proxy_program

    cat > "$MT5700_ATSD_PROXY_INIT" <<'EOF_MT5700_ATSD_PROXY_INIT'
#!/bin/sh /etc/rc.common

START=98
STOP=11
USE_PROCD=1
PROG=/usr/libexec/nradio-mt5700-atsd-proxy.lua

start_service() {
    procd_open_instance
    procd_set_param command /usr/bin/lua "$PROG"
    procd_set_param env MT5700_ATSD_PROXY_PORT=20250
    procd_set_param respawn 3600 5 5
    procd_set_param stdout 1
    procd_set_param stderr 1
    procd_close_instance
}
EOF_MT5700_ATSD_PROXY_INIT
    chmod 755 "$MT5700_ATSD_PROXY_INIT" || die "设置 MT5700 AT 共享桥服务权限失败"

    mt5700_config_backup="$mt5700_workdir/at-webserver.config.before-c2000max"
    cp -p "$MT5700_CONFIG_FILE" "$mt5700_config_backup" || die "备份 MT5700 WebUI 原配置失败"
    uci set at-webserver.config.connection_type='NETWORK' || die "设置 C2000 系列 AT 连接类型失败"
    uci set at-webserver.config.network_host='127.0.0.1' || die "设置 C2000 系列 AT 共享地址失败"
    uci set "at-webserver.config.network_port=$MT5700_ATSD_PROXY_PORT" || die "设置 C2000 系列 AT 共享端口失败"
    uci commit at-webserver || die "保存 C2000 系列 AT 共享配置失败"

    "$MT5700_ATSD_PROXY_INIT" enable || die "MT5700 AT 共享桥开机启动配置失败"
    "$MT5700_ATSD_PROXY_INIT" stop >/dev/null 2>&1 || true
    "$MT5700_ATSD_PROXY_INIT" start || die "MT5700 AT 共享桥启动失败"
    log "适配: C2000MAX/C2000Ultra 使用 NROS atsd_cli 共享 AT 通道（127.0.0.1:$MT5700_ATSD_PROXY_PORT）"
}

write_mt5700_c5800_dual() {
    case "${CURRENT_DETECTED_MODEL:-}" in
        NRadio_C5800-650|NRadio_C5800-688) ;;
        *) return 0 ;;
    esac
    # 单路与双路均按 NROS 线路标识接入，离线状态不等于没有这条线路。
    mt5700_lines_json="$(/usr/bin/lua -e '
local ok, r = pcall(require("luci.util").ubus, "infocd", "runtime")
local found = {}
for _, v in ipairs(ok and type(r) == "table" and type(r.cpe) == "table" and r.cpe or {}) do
    if type(v) == "table" then found[v.name or ""] = true end
end
local names = {}
for _, name in ipairs({"cpe", "cpe1"}) do
    if found[name] then names[#names + 1] = "\"" .. name .. "\"" end
end
io.write("[" .. table.concat(names, ",") .. "]")
' 2>/dev/null)"
    case "$mt5700_lines_json" in
        '["cpe"]'|'["cpe1"]'|'["cpe","cpe1"]') ;;
        *)
            [ -f /etc/nradio-mt5700-dual/enabled ] || return 0
            mt5700_lines_json='[]'
            ;;
    esac

    log "适配: 5800 按实际 CPE / CPE1 显示单线路或双线路"
    mt5700_dual_dir=/etc/nradio-mt5700-dual
    mt5700_dual_bin=/usr/libexec/nradio-mt5700-dual
    mkdir -p "$mt5700_dual_dir" "$mt5700_dual_bin" || die "创建双线路配置目录失败"
    chmod 700 "$mt5700_dual_dir"
    if [ ! -f "$mt5700_dual_dir/before-dual.config" ]; then
        cp -p "$MT5700_CONFIG_FILE" "$mt5700_dual_dir/before-dual.config" || die "保存双线路适配前配置失败"
    fi
    mt5700_main_ws="$(uci -q get at-webserver.config.websocket_port)"
    case "$mt5700_main_ws" in ''|*[!0-9]*) mt5700_main_ws=8765 ;; esac
    [ "$mt5700_main_ws" -ge 1024 ] && [ "$mt5700_main_ws" -lt 65535 ] || mt5700_main_ws=8765
    mt5700_second_ws=$((mt5700_main_ws + 1))
    if [ ! -f /etc/config/at-webserver-cpe1 ]; then
        cp -p "$mt5700_dual_dir/before-dual.config" /etc/config/at-webserver-cpe1 || die "创建副线路配置失败"
        # 首次建立副线路配置时，不复制主线路正在执行的定时锁频计划。
        uci set at-webserver-cpe1.config.schedule_enabled=0
        uci set at-webserver-cpe1.config.log_file=/tmp/mt5700-cpe1.log
    fi
    uci set at-webserver.config.connection_type=NETWORK || die "设置主线路连接失败"
    uci set at-webserver.config.network_host=127.0.0.1
    uci set at-webserver.config.network_port=20250
    uci set "at-webserver.config.websocket_port=$mt5700_main_ws"
    uci commit at-webserver || die "保存主线路配置失败"
    for mt5700_option in enabled=1 connection_type=NETWORK network_host=127.0.0.1 network_port=20251 "websocket_port=$mt5700_second_ws"; do
        uci set "at-webserver-cpe1.config.$mt5700_option" || die "设置副线路配置失败"
    done
    uci commit at-webserver-cpe1 || die "保存副线路配置失败"
    chmod 600 "$mt5700_dual_dir/before-dual.config" /etc/config/at-webserver-cpe1
    write_mt5700_atsd_proxy_program

    # 上游按进程名停止会误杀副实例；双路环境交由 procd 按服务名处理。
    awk '
    /^# BEGIN NRADIO_MT5700_DUAL_RELOAD$/ { skip = 1; next }
    /^# END NRADIO_MT5700_DUAL_RELOAD$/ { skip = 0; next }
    skip { next }
    /^[[:space:]]*killall -q "\$PROG_NAME" 2>\/dev\/null[[:space:]]*$/ {
        print "\tprocd_kill at-webserver"
        next
    }
    { print }
    END {
        print "# BEGIN NRADIO_MT5700_DUAL_RELOAD"
        print "reload_service() {"
        print "    stop"
        print "    start"
        print "}"
        print "# END NRADIO_MT5700_DUAL_RELOAD"
    }' "$MT5700_INIT_FILE" > "$mt5700_workdir/dual-init" || die "写入双线路启停适配失败"
    cp "$mt5700_workdir/dual-init" "$MT5700_INIT_FILE" || die "部署双线路启停适配失败"
    chmod 755 "$MT5700_INIT_FILE"

    # 上游通过 PATH 调用 uci；副实例映射独立包名，配置与未提交变更均隔离。
    cat > "$mt5700_dual_bin/uci" <<'EOF_MT5700_DUAL_UCI'
#!/bin/sh
[ "$NRADIO_MT5700_LINE" = cpe1 ] || exit 2
remaining=$#
while [ "$remaining" -gt 0 ]; do
    value="$1"
    shift
    case "$value" in
        at-webserver|at-webserver.*) value="at-webserver-cpe1${value#at-webserver}" ;;
    esac
    set -- "$@" "$value"
    remaining=$((remaining - 1))
done
output="$(/sbin/uci "$@")"
result=$?
printf '%s\n' "$output" | sed 's/^at-webserver-cpe1\./at-webserver./;s/^at-webserver-cpe1=/at-webserver=/'
exit "$result"
EOF_MT5700_DUAL_UCI
    chmod 755 "$mt5700_dual_bin/uci"
    cat > /etc/init.d/nradio-mt5700-dual <<'EOF_MT5700_DUAL_INIT'
#!/bin/sh /etc/rc.common
START=98
STOP=11
USE_PROCD=1
start_service() {
    [ -f /etc/nradio-mt5700-dual/enabled ] || return 0
    [ "$(/sbin/uci -q get at-webserver.config.enabled)" != 0 ] || return 0
    local line port
    for line in cpe cpe1; do
        port=20250
        [ "$line" = cpe1 ] && port=20251
        procd_open_instance "bridge_$line"
        procd_set_param command /usr/bin/lua /usr/libexec/nradio-mt5700-atsd-proxy.lua
        procd_set_param env "MT5700_ATSD_PROXY_LINE=$line" "MT5700_ATSD_PROXY_PORT=$port"
        procd_set_param respawn 3600 5 5
        procd_set_param stderr 1
        procd_close_instance
    done
    procd_open_instance web_cpe1
    procd_set_param command /usr/bin/at-webserver
    procd_set_param env NRADIO_MT5700_LINE=cpe1 "PATH=/usr/libexec/nradio-mt5700-dual:$PATH"
    procd_set_param file /etc/config/at-webserver-cpe1
    procd_set_param respawn 3600 5 5
    procd_set_param stderr 1
    procd_close_instance
}
service_triggers() {
    procd_add_reload_trigger at-webserver at-webserver-cpe1
}
EOF_MT5700_DUAL_INIT
    chmod 755 /etc/init.d/nradio-mt5700-dual

    # 副实例遵循主实例的 WAN 访问选择；独立命名，避免上游重启时删除。
    uci set firewall.nradio_mt5700_cpe1=rule
    uci set firewall.nradio_mt5700_cpe1.name=nradio_mt5700_cpe1
    uci set firewall.nradio_mt5700_cpe1.src=wan
    uci set firewall.nradio_mt5700_cpe1.proto=tcp
    uci set "firewall.nradio_mt5700_cpe1.dest_port=$mt5700_second_ws"
    mt5700_dual_target=REJECT
    [ "$(uci -q get at-webserver.config.websocket_allow_wan)" = 1 ] && mt5700_dual_target=ACCEPT
    uci set "firewall.nradio_mt5700_cpe1.target=$mt5700_dual_target"
    uci set firewall.nradio_mt5700_cpe1.enabled=1
    uci commit firewall || die "保存双线路服务访问配置失败"

    cat > "$MT5700_WEB_ROOT/nradio-dual-config.js" <<EOF_MT5700_DUAL_CONFIG
window.NRadioMT5700Dual = {cpe:$mt5700_main_ws,cpe1:$mt5700_second_ws,lines:$mt5700_lines_json};
EOF_MT5700_DUAL_CONFIG
    cat > "$MT5700_WEB_ROOT/nradio-dual-ui.js" <<'EOF_MT5700_DUAL_UI'
(function () {
    'use strict';
    var ports = window.NRadioMT5700Dual;
    if (!ports || !ports.cpe || !ports.cpe1) return;
    var available = ['cpe', 'cpe1'].filter(function (name) { return (ports.lines || []).indexOf(name) !== -1; });
    var query = new URL(location.href).searchParams;
    var line = query.get('line');
    if (line !== 'cpe' && line !== 'cpe1') {
        try { line = sessionStorage.getItem('nradio-mt5700-line'); } catch (_) {}
        if (available.indexOf(line) === -1) line = available[0];
    }
    line = line === 'cpe1' ? 'cpe1' : 'cpe';
    try { sessionStorage.setItem('nradio-mt5700-line', line); } catch (_) {}
    var nativeFetch = window.fetch.bind(window);
    var NativeWebSocket = window.WebSocket;
    var api = '/cgi-bin/luci/nradioadv/system/mt5700?dual=1&line=' + line;
    var host = location.hostname.replace(/^\[|\]$/g, '');
    var channelState = '正在连接', activeChannel = null;
    function updateSelection() {
        if (!shadow) return;
        shadow.querySelector('.selected').textContent = available.length ? (available.length > 1 ? '双线路 · 当前管理：' : '单线路 · ') + line.toUpperCase() + ' · ' + channelState : '未检测到线路';
    }
    // 每个页面固定绑定一路；多个标签页、重连、旧的本地连接设置均不会串线。
    window.WebSocket = class extends NativeWebSocket {
        constructor(url, protocols) {
            var target = new URL(url, location.href);
            target.hostname = location.hostname;
            target.port = String(ports[line]);
            if (protocols === undefined) super(target.href); else super(target.href, protocols);
            this.nradioSpeedEnabled = false;
            activeChannel = this;
            channelState = '正在连接';
            updateSelection();
            this.addEventListener('open', function () { if (activeChannel === this) { channelState = '已连接'; updateSelection(); } });
            this.addEventListener('close', function () { if (activeChannel === this) { channelState = '连接已断开'; updateSelection(); } });
            this.addEventListener('message', function (event) {
                if (this.nradioFiltering || typeof event.data !== 'string') return;
                var message;
                try { message = JSON.parse(event.data); } catch (_) { return; }
                var key = null;
                if (message.type === 'pdcp_data' && message.data) {
                    key = [message.data.id, message.data.pduSessionId, message.data.ulPdcpRate, message.data.dlPdcpRate].join(':');
                } else if (message.type === 'raw_data' && typeof message.data === 'string') {
                    var report = message.data.match(/\^PDCPDATAINFO:\s*([\d,]+)/);
                    if (report) {
                        var fields = report[1].split(',');
                        if (fields.length >= 14) key = [fields[0], fields[1], fields[10], fields[11]].join(':');
                    }
                }
                if (key === null) return;
                // The Go backend sends both raw_data and pdcp_data for one report.
                var previous = this.nradioLastReport, now = Date.now();
                var duplicate = previous && previous.key === key && previous.type !== message.type && now - previous.at < 150;
                if (this.nradioSpeedEnabled && !duplicate) {
                    this.nradioLastReport = {key: key, type: message.type, at: now};
                    return;
                }
                event.stopImmediatePropagation();
                if (message.type === 'pdcp_data') return;
                message.data = message.data.replace(/\^PDCPDATAINFO:[^\r\n]*/g, '').trim();
                if (message.data) {
                    this.nradioFiltering = true;
                    try { this.dispatchEvent(new MessageEvent('message', {data: JSON.stringify(message)})); }
                    finally { this.nradioFiltering = false; }
                }
            });
        }
        send(data) {
            var setting = typeof data === 'string' && data.trim().match(/^AT\^PDCPDATAINFO=([01])(?:,\d+)?$/i);
            // Pause only this page. Another tab and NROS keep their shared reports.
            var result = super.send(setting && setting[1] === '0' ? 'AT\r' : data);
            if (setting) this.nradioSpeedEnabled = setting[1] === '1';
            return result;
        }
    };
    window.fetch = function (input, init) {
        var url = new URL(typeof input === 'string' ? input : input.url || String(input), location.href);
        if (url.origin === location.origin && (url.pathname === '/cgi-bin/at-ws-info' || url.pathname === '/5700/config.json')) {
            return nativeFetch(api, Object.assign({}, init, {cache: 'no-store', credentials: 'same-origin'})).then(function (response) {
                if (!response.ok) throw new Error('线路连接配置读取失败');
                return response.json();
            }).then(function (result) {
                if (!result.success) throw new Error('线路连接配置读取失败');
                if (result.line !== line) {
                    switchLine(result.line);
                    throw new Error('正在切换到可用线路');
                }
                var actualPort = Number(result.data.port);
                if (Number.isInteger(actualPort) && actualPort > 0 && actualPort < 65536) ports[line] = actualPort;
                var data = {host: host, port: ports[line], require_auth: result.data.require_auth};
                var payload = url.pathname === '/cgi-bin/at-ws-info' ? {success: true, data: data} : {status: 'true', at: data, require_auth: data.require_auth};
                return new Response(JSON.stringify(payload), {headers: {'Content-Type': 'application/json'}});
            });
        }
        return nativeFetch(input, init);
    };

    var panel, shadow, timer, controller, busy = false, leaving = false;
    var cacheKey = 'nradio-mt5700-signals:' + location.host;
    function metric(value, unit) {
        return value !== null && value !== undefined && String(value).trim() !== '' ? String(value) + unit : '—';
    }
    function switchLine(name) {
        if ((name !== 'cpe' && name !== 'cpe1') || name === line || leaving) return;
        leaving = true;
        if (controller) controller.abort();
        clearTimeout(timer);
        if (shadow) shadow.querySelector('.selected').textContent = '正在切换到 ' + name.toUpperCase() + '…';
        var target = new URL(location.href);
        target.searchParams.set('line', name);
        // 重建 AT 队列和详情状态，旧响应随旧页面销毁。
        location.replace(target.href);
    }
    function updateLines(names) {
        available = names;
        var cards = shadow.querySelector('.cards');
        ['cpe', 'cpe1'].forEach(function (name) {
            var button = shadow.querySelector('[data-line="' + name + '"]');
            if (names.indexOf(name) === -1) {
                if (button) button.remove();
                return;
            }
            if (button) return;
            button = document.createElement('button');
            button.type = 'button';
            button.setAttribute('data-line', name);
            button.setAttribute('aria-pressed', String(line === name));
            button.innerHTML = '<div class="top"><strong>' + name.toUpperCase() + '</strong><span class="state">读取中</span></div><div class="network"></div><div class="signal"></div><div class="extra"></div>';
            button.addEventListener('click', function () { switchLine(name); });
            // CPE1 单线恢复双路后仍保持 CPE、CPE1 顺序。
            if (name === 'cpe') cards.insertBefore(button, cards.firstChild); else cards.appendChild(button);
        });
        cards.style.gridTemplateColumns = names.length > 1 ? 'repeat(2,minmax(0,1fr))' : 'minmax(0,1fr)';
        updateSelection();
    }
    function render(result, cached) {
        if (!shadow) return;
        var items = {};
        (Array.isArray(result.lines) ? result.lines : []).forEach(function (item) {
            if (item.available !== false && (item.name === 'cpe' || item.name === 'cpe1')) items[item.name] = item;
        });
        // 缓存只补数值；线路数量由安装识别或当前成功响应决定。
        if (!cached) updateLines(['cpe', 'cpe1'].filter(function (name) { return !!items[name]; }));
        available.forEach(function (name) {
            var item = items[name] || {};
            var node = shadow.querySelector('[data-line="' + name + '"]');
            var band = metric(item.band, '');
            if (/^\d+$/.test(band)) band = (/NR|5G|SA/i.test(item.mode || '') ? 'N' : /LTE|4G/i.test(item.mode || '') ? 'B' : '') + band;
            node.querySelector('.state').textContent = !items[name] ? '读取中' : item.status === 0 ? '已连接' : item.status == null ? '状态未知' : '未连接';
            node.querySelector('.network').textContent = [item.operator, item.mode, band === '—' ? '' : band].filter(Boolean).join(' · ') || '等待线路信息';
            node.querySelector('.signal').textContent = 'RSRP ' + metric(item.rsrp, ' dBm') + '　SINR ' + metric(item.sinr, ' dB');
            node.querySelector('.extra').textContent = 'RSRQ ' + metric(item.rsrq, ' dB') + '　温度 ' + metric(item.temperature, '°C');
        });
        shadow.querySelector('.stamp').textContent = cached ? '上次读数，正在刷新…' : '更新于 ' + new Date(result.timestamp * 1000).toLocaleTimeString();
    }
    function mount() {
        var content = document.querySelector('.app-content');
        if (!content || leaving) return;
        if (!panel) {
            panel = document.createElement('section');
            panel.id = 'nradio-mt5700-dual';
            panel.style.cssText = 'display:block;flex:0 0 auto;min-width:0;width:100%;margin-bottom:16px';
            shadow = panel.attachShadow({mode: 'open'});
            shadow.innerHTML = '<style>:host{font-family:inherit;color:var(--semi-color-text-0,#18202b)}*{box-sizing:border-box}.heading{display:flex;flex-wrap:wrap;align-items:center;justify-content:space-between;gap:8px;margin-bottom:10px;font-size:14px}.stamp{font-size:12px;color:var(--semi-color-text-2,#667085)}.cards{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:12px}button{font:inherit;text-align:left;cursor:pointer;min-width:0;min-height:44px;padding:12px;border:1px solid var(--semi-color-border,#dce1e7);border-radius:10px;background:var(--semi-color-bg-2,#fff);color:inherit}button[aria-pressed=true]{border-color:#c7000b;box-shadow:inset 0 0 0 1px #c7000b}button:focus-visible{outline:2px solid #1677ff;outline-offset:2px}.top{display:flex;justify-content:space-between;gap:8px;font-size:14px}.state{font-size:12px}.network,.signal,.extra{font-size:12px;line-height:1.6;overflow-wrap:anywhere;margin-top:4px}.extra{color:var(--semi-color-text-2,#667085)}@media(max-width:420px){.cards{gap:8px}button{padding:10px}.signal,.extra{font-size:11px}.top{flex-wrap:wrap}}</style><div class="heading"><strong class="selected"></strong><span class="stamp">正在读取线路信号…</span></div><div class="cards"></div>';
            updateLines(available);
            try {
                var cached = JSON.parse(sessionStorage.getItem(cacheKey) || 'null');
                if (cached && Date.now() - cached.timestamp * 1000 < 60000) render(cached, true);
            } catch (_) {}
        }
        if (panel.parentNode !== content) content.insertBefore(panel, content.firstChild);
    }
    function refresh() {
        clearTimeout(timer);
        if (busy || leaving || document.hidden) return;
        busy = true;
        controller = new AbortController();
        var deadline = setTimeout(function () { controller.abort(); }, 6000);
        nativeFetch(api, {cache: 'no-store', credentials: 'same-origin', signal: controller.signal}).then(function (response) {
            if (!response.ok) throw new Error('信号读取失败');
            return response.json();
        }).then(function (result) {
            if (!result.success || leaving) return;
            mount();
            render(result, false);
            try { sessionStorage.setItem(cacheKey, JSON.stringify(result)); } catch (_) {}
            if (result.line !== line) switchLine(result.line);
        }).catch(function () {
            if (shadow && !leaving) shadow.querySelector('.stamp').textContent = '刷新失败，显示上次读数';
        }).finally(function () {
            clearTimeout(deadline);
            busy = false;
            if (!leaving && !document.hidden) timer = setTimeout(refresh, 5000);
        });
    }
    function start() {
        mount();
        new MutationObserver(mount).observe(document.body, {childList: true, subtree: true});
        refresh();
        document.addEventListener('visibilitychange', function () {
            clearTimeout(timer);
            if (document.hidden) { if (controller) controller.abort(); } else refresh();
        });
    }
    if (document.readyState === 'loading') document.addEventListener('DOMContentLoaded', start, {once: true}); else start();
}());
EOF_MT5700_DUAL_UI
    mt5700_dual_index="$mt5700_workdir/dual-index.html"
    awk -v stamp="$MT5700_UI_VERSION-$mt5700_main_ws-$mt5700_second_ws-$MT5700_NRADIO_ADAPT_VERSION" '
    {
        gsub(/<script src="\/5700\/nradio-dual-(config|ui)\.js[^\"]*"><\/script>/, "")
        gsub(/\.js\?v=[^\"]+/, ".js?v=" stamp)
        if (!added && /<head[^>]*>/) {
            sub(/<head[^>]*>/, "&\n<script src=\"/5700/nradio-dual-config.js?v=" stamp "\"></script>\n<script src=\"/5700/nradio-dual-ui.js?v=" stamp "\"></script>")
            added = 1
        }
        print
    }' "$MT5700_WEB_ROOT/index.html" > "$mt5700_dual_index" || die "写入双线路页面入口失败"
    cp "$mt5700_dual_index" "$MT5700_WEB_ROOT/index.html" || die "部署双线路页面失败"
    chmod 644 "$MT5700_WEB_ROOT/nradio-dual-config.js" "$MT5700_WEB_ROOT/nradio-dual-ui.js" "$MT5700_WEB_ROOT/index.html"
    printf '%s\n' "$MT5700_NRADIO_ADAPT_VERSION" > "$mt5700_dual_dir/enabled"
    /etc/init.d/nradio-mt5700-dual enable || die "启用双线路服务失败"
    /etc/init.d/nradio-mt5700-dual restart || die "启动双线路服务失败"
}

install_mt5700_webui() {
    require_nradio_oem_appcenter

    mt5700_workdir="$WORKDIR/mt5700"
    if [ "${NRADIO_MT5700_ADAPT_ONLY:-0}" = 1 ]; then
        case "${CURRENT_DETECTED_MODEL:-}" in
            NRadio_C5800-650|NRadio_C5800-688) ;;
            *) die "现有双线路适配更新适用于 C5800" ;;
        esac
        [ -x "$MT5700_BIN_PATH" ] && [ -f "$MT5700_WEB_ROOT/index.html" ] &&
            [ -f /etc/nradio-mt5700-dual/enabled ] || die "请先安装 MT5700 WebUI"
        MT5700_PACKAGE_VERSION="$(get_installed_package_version "$MT5700_PACKAGE_NAME")"
        MT5700_UI_VERSION="$(printf '%s' "$MT5700_PACKAGE_VERSION" | sed 's/-r\{0,1\}[0-9][0-9]*$//')"
        mkdir -p "$mt5700_workdir" || die "创建 MT5700 适配工作目录失败"
        patch_mt5700_speed_display
        write_mt5700_nradio_controller
        write_mt5700_c5800_dual
        ubus call service signal '{"name":"at-webserver","signal":15}' >/dev/null || die "重启 MT5700 主线路后端失败"
        log "安装完成: MT5700 双线路适配 $MT5700_NRADIO_ADAPT_VERSION"
        log "网速: CPE / CPE1 独立实时上报，暂停按页面隔离，零速率按实际显示"
        return 0
    fi
    mt5700_artifact="$mt5700_workdir/$MT5700_ARTIFACT_NAME"
    mt5700_unpack="$mt5700_workdir/unpack"
    mt5700_ipk=''

    log "前端: $MT5700_UI_NAME（上游最新成功构建）"
    log "来源: $MT5700_UI_SOURCE_URL"
    confirm_or_exit "确认下载安装 MT5700 WebUI 上游最新版本并接入 NRadio 应用商店吗？"

    mkdir -p "$mt5700_workdir" || die "创建 MT5700 WebUI 工作目录失败"
    log_stage 1 5 "下载 MT5700 WebUI 上游最新成功构建"
    # 滚动地址内容会变化，每次完整下载，避免旧包或旧断点混入新构建。
    if ! DOWNLOAD_KEEP_PARTIAL=0 download_from_urls "$mt5700_artifact" $MT5700_ARTIFACT_URLS; then
        die "无法下载 MT5700 WebUI 最新构建，请稍后重新安装"
    fi

    log_stage 2 5 "解包 MT5700 WebUI IPK"
    rm -rf "$mt5700_unpack"
    mkdir -p "$mt5700_unpack" || die "创建 MT5700 WebUI 解压目录失败"
    unzip -oq "$mt5700_artifact" -d "$mt5700_unpack" >"$mt5700_workdir/unzip.log" 2>&1 || die "解压 MT5700 WebUI 官方构建产物失败"
    for mt5700_candidate in \
        "$mt5700_unpack/${MT5700_PACKAGE_NAME}_"*"_${MT5700_PACKAGE_ARCH}.ipk" \
        "$mt5700_unpack"/*/"${MT5700_PACKAGE_NAME}_"*"_${MT5700_PACKAGE_ARCH}.ipk" \
        "$mt5700_unpack"/*/*/"${MT5700_PACKAGE_NAME}_"*"_${MT5700_PACKAGE_ARCH}.ipk"
    do
        [ -s "$mt5700_candidate" ] || continue
        mt5700_ipk="$mt5700_candidate"
        break
    done
    [ -n "$mt5700_ipk" ] || die "最新构建中未找到 $MT5700_PACKAGE_NAME 的 $MT5700_PACKAGE_ARCH 安装包"
    mt5700_ipk_size="$(get_file_size_bytes "$mt5700_ipk" 2>/dev/null || true)"
    case "$mt5700_ipk_size" in
        ''|*[!0-9]*) mt5700_ipk_size='0' ;;
    esac

    log_stage 3 5 "安装 MT5700 WebUI Go 后端与静态页面"
    install_ipk_file "$mt5700_ipk" "$MT5700_APP_NAME 核心"
    MT5700_PACKAGE_VERSION="$(get_installed_package_version "$MT5700_PACKAGE_NAME")"
    if [ -z "$MT5700_PACKAGE_VERSION" ]; then
        mt5700_ipk_basename="${mt5700_ipk##*/}"
        MT5700_PACKAGE_VERSION="${mt5700_ipk_basename#${MT5700_PACKAGE_NAME}_}"
        MT5700_PACKAGE_VERSION="${MT5700_PACKAGE_VERSION%_${MT5700_PACKAGE_ARCH}.ipk}"
    fi
    MT5700_UI_VERSION="$(printf '%s' "$MT5700_PACKAGE_VERSION" | sed 's/-r\{0,1\}[0-9][0-9]*$//')"
    patch_mt5700_version_display
    patch_mt5700_boot_fallback
    patch_mt5700_speed_display
    write_mt5700_c2000_atsd_proxy
    write_mt5700_c5800_dual

    log_stage 4 5 "写入 NROS 打开入口、图标、应用商店与异步卸载链"
    write_mt5700_nradio_controller
    ensure_app_icon_dir
    cp "$MT5700_WEB_ROOT/icons/logo.png" "$APP_ICON_DIR/$MT5700_ICON_NAME" || die "写入 MT5700 WebUI 应用商店图标失败"
    chmod 644 "$APP_ICON_DIR/$MT5700_ICON_NAME" 2>/dev/null || true
    set_mt5700_appcenter_entry "$mt5700_ipk_size"
    uci commit appcenter || die "MT5700 WebUI 应用商店配置提交失败"
    write_plugin_uninstall_assets
    patch_common_template
    patch_mt5700_appcenter_list_controller
    refresh_mt5700_luci_appcenter
    /etc/init.d/uhttpd reload >/dev/null 2>&1 || die "MT5700 WebUI 安装后 LuCI 重载失败"

    log_stage 5 5 "启动 MT5700 WebUI 后端"
    "$MT5700_INIT_FILE" enable || die "MT5700 WebUI 开机启动配置失败"
    "$MT5700_INIT_FILE" restart || die "MT5700 WebUI 启动失败"

    log "安装完成"
    log "插件:   $MT5700_APP_NAME"
    log "前端:   $MT5700_UI_NAME V$MT5700_UI_VERSION"
    log "后端包: $MT5700_PACKAGE_NAME $MT5700_PACKAGE_VERSION"
    log "路由:   $MT5700_ROUTE -> /5700/?v=$MT5700_UI_VERSION#/network/info"
}

resolve_openbox_storage_paths() {
    local model="${CURRENT_DETECTED_MODEL:-$(detect_current_nradio_model_quiet)}"
    if c2000_storage_swap_model_supported "$model"; then
        OPENBOX_STORAGE_MOUNT="$(detect_c2000max_storage_mount 2>/dev/null || true)"
        [ -n "$OPENBOX_STORAGE_MOUNT" ] || die "请挂载存储卡后安装 Open-Box"
        OPENBOX_INSTALL_ROOT="$OPENBOX_STORAGE_MOUNT/open-box"
    else
        OPENBOX_STORAGE_MOUNT="$ROOTFS_2ND_STORAGE_MOUNT_POINT"
        awk -v m="$OPENBOX_STORAGE_MOUNT" '$2 == m { found=1 } END { exit !found }' /proc/mounts || die "请挂载扩展盘后安装 Open-Box"
        OPENBOX_INSTALL_ROOT="$ROOTFS_2ND_STORAGE_APPS_DIR/open-box"
    fi
}

write_openbox_assets() {
    mkdir -p /usr/libexec /usr/lib/lua/luci/controller/nradio_adv /usr/lib/lua/luci/view/nradio_openbox
    cat > /usr/libexec/nradio-openbox-runtime.lua <<'EOF_OPENBOX_RUNTIME'
-- Private Node loader; system programs keep the firmware's own libraries.
local root = arg[1] or "/opt/open-box"
local function edit(path, transform)
    local f = io.open(path, "rb")
    if not f then return end
    local old = f:read("*a"); f:close()
    local new = transform(old)
    if new ~= old then
        f = assert(io.open(path, "wb")); assert(f:write(new)); f:close()
    end
end
local function replace_block(s, first, last, replacement)
    local a = s:find(first, 1, true)
    local b = a and s:find(last, a + #first, true)
    if a and b then return s:sub(1, a - 1) .. replacement .. s:sub(b) end
    return s
end
local f = io.open(root .. "/node/bin/node", "rb")
if f then
    local h = f:read(64)
    local function uint(s, p, n)
        local v = 0
        for i = n - 1, 0, -1 do v = v * 256 + s:byte(p + i + 1) end
        return v
    end
    if h and h:sub(1, 6) == "\127ELF\2\1" and uint(h, 18, 2) == 183 then
        for i = 0, uint(h, 56, 2) - 1 do
            f:seek("set", uint(h, 32, 8) + i * uint(h, 54, 2))
            local ph = f:read(uint(h, 54, 2))
            if uint(ph, 0, 4) == 3 then
                local offset, size = uint(ph, 8, 8), uint(ph, 32, 8)
                f:seek("set", offset)
                local current = f:read(size):match("^[^%z]+")
                local loader = "/opt/ob-libc.so"
                if current == "/lib/ld-musl-aarch64.so.1" and size > #loader then
                    f:close(); f = assert(io.open(root .. "/node/bin/node", "r+b"))
                    f:seek("set", offset); assert(f:write(loader .. string.rep("\0", size - #loader)))
                end
                break
            end
        end
    end
    f:close()
end
edit(root .. "/panel/server/system/context-real.mjs", function(s)
    s = s:gsub("execFile%(cmd, args, { timeout: timeoutMs },", "const env = { ...process.env }; delete env.LD_LIBRARY_PATH\n      execFile(cmd, args, { timeout: timeoutMs, env },")
    return s
end)
edit(root .. "/panel/server/system/curl-fetch.mjs", function(s)
    return (s:gsub("execFile%('curl', args, { timeout: timeoutMs, maxBuffer: 1024 %* 1024, windowsHide: true },", "const env = { ...process.env }; delete env.LD_LIBRARY_PATH\n  execFile('curl', args, { timeout: timeoutMs, maxBuffer: 1024 * 1024, windowsHide: true, env },"))
end)
edit(root .. "/panel/server/engine/config.mjs", function(s)
    s = s:gsub("interface_name: 'tun0'", "interface_name: 'ob-tun'")
    s = s:gsub("auto_route: true, strict_route:", "auto_route: true, iproute2_rule_index: 9000, strict_route:")
    s = s:gsub("iproute2_rule_index:%s*7000", "iproute2_rule_index: 9000")
    -- NROS fw3 has no nftables auto_redirect support.
    local fw4 = io.open("/sbin/fw4", "rb")
    if fw4 then fw4:close() else
        s = s:gsub("const autoRedirect = Boolean%([^\n]+", "const autoRedirect = false")
    end
    return s
end)
edit(root .. "/panel/server/engine/routing.mjs", function(s)
    return (s:gsub("auto_detect_interface: false, default_mark: 4194304,", "auto_detect_interface: true,"))
end)
edit(root .. "/etc/config.json", function(s)
    local json = require "luci.jsonc"
    local config = json.parse(s)
    if not config then return s end
    for _, inbound in ipairs(config.inbounds or {}) do
        if inbound.type == "tun" then inbound.iproute2_rule_index = 9000 end
    end
    if config.route then
        config.route.auto_detect_interface = true
        if config.route.default_mark == 4194304 then config.route.default_mark = nil end
    end
    return json.stringify(config)
end)
edit("/etc/init.d/openbox-panel", function(s)
    s = s:gsub('ENTRY="%$OPENBOX_ROOT/panel/server/index.mjs"', 'ENTRY="$(readlink -f "$OPENBOX_ROOT/panel/server/index.mjs")"')
    if not s:find("nradio%-openbox%-runtime.lua") then
        s = s:gsub("start_service%(%) {", "start_service() {\n    lua /usr/libexec/nradio-openbox-runtime.lua")
    end
    return s
end)
edit("/etc/init.d/openbox", function(s)
    if not s:find("nradio%-openbox%-wan start") then
        s = s:gsub("start_service%(%) {", "start_service() {\n    /usr/libexec/nradio-openbox-wan start")
        s = s:gsub("\n\topenbox_cleanup\n", "\n\t/usr/libexec/nradio-openbox-wan stop\n\topenbox_cleanup\n")
    end
    return s
end)
edit(root .. "/panel/server/system/component-update.mjs", function(s)
    -- NROS updates use component versions and file presence, without digest checks.
    s = s:gsub("import { createHash } from 'node:crypto'\n", "")
    s = s:gsub("const HASH = [^\n]+\n", "")
    s = replace_block(s, "export const fileHash =", "export const validateManifest", "")
    s = s:gsub(" || !HASH%.test%(c%.sha256%)", "")
    s = s:gsub(" || !HASH%.test%(c%.manifestSha256%)", "")
    s = s:gsub("!c%.files%?%.%[required%]", "!Object.hasOwn(c.files || {}, required)")
    s = s:gsub(" && HASH%.test%(hash%)", "")
    s = s:gsub("c%.asset, c%.sha256, c%.size", "c.asset, '-', c.size")
    s = replace_block(s, "export const componentMatches =", "export const planUpdate", [[export const componentMatches = (root, kind, component) => {
  try {
    if (kind === 'app') return false
    if (kind !== 'geo') {
      const meta = readJson(path.join(root, 'meta.json'))
      const version = kind === 'runtime' ? meta.nodeVersion : meta.singboxVersion
      return version === component.version
        && Object.keys(component.files).every(name => fs.existsSync(path.join(root, name)))
    }
    const dir = path.join(root, GEO_DIR)
    const geo = readJson(path.join(dir, 'manifest.json'))
    if (geo.version !== component.version || geo.schema !== 1) return false
    const files = Object.keys(geo.files || {})
    return files.length > 0 && ['geoip', 'geosite'].every(k => geo.counts?.[k] > 0
      && geo.counts[k] === files.filter(name => name.startsWith(k + '-')).length)
      && files.every(name => GEO_FILE.test(name) && !name.includes('..')
        && fs.existsSync(path.join(dir, name)))
  } catch { return false }
}

]])
    return s
end)
edit(root .. "/panel/server/system/update-components.sh", function(s)
    s = replace_block(s, '    # Names and hashes are validated', '    write_status extracting', '')
    return (s:gsub("版本及文件校验一致", "版本一致且文件存在"))
end)
edit(root .. "/update.sh", function(s)
    -- Probe the package URL itself; missing checksum assets must not block a channel.
    s = replace_block(s, '  probe_url=$(build_url "$SHA_URL")', '\n}\n', [[  probe_url=$(build_url "$ASSET_URL")
  if command -v curl >/dev/null 2>&1; then
    curl -fsSI -L --connect-timeout 4 --max-time 8 "$probe_url" >/dev/null 2>&1
  else
    wget -q --spider -T 8 "$probe_url" >/dev/null 2>&1
  fi]])
    -- The full-package fallback downloads once, then extracts without a hash gate.
    s = replace_block(s, '_dl_round=0\n', 'info "解包..."', [[check_cancel_and_abort
info "下载发布包:$ASSET"
ASSET_DL_URL=$(build_url "$ASSET_URL")
ASSET_TOTAL=$(probe_content_length "$ASSET_DL_URL")
case "$ASSET_TOTAL" in ''|*[!0-9]*) ASSET_TOTAL='' ;; esac
download_with_progress "$ASSET_DL_URL" "$TMP_DL/$ASSET" "$ASSET_TOTAL" || die "下载升级包失败:$ASSET_URL。"
check_cancel_and_abort
write_status extracting "" "" ""

]])
    s = s:gsub('SHA_URL="%$ASSET_URL%.sha256"\n', '')
    s = s:gsub("探测失败%(连接失败、超时,或返回内容不是预期的校验文件%)", "探测失败(连接失败或超时)")
    -- The running updater uses a /tmp copy. Reapply NROS adapters before Node starts.
    s = replace_block(s, "mkdir -p /www/luci-static/resources/view/openbox", 'info "启动面板..."',
        'lua /usr/libexec/nradio-openbox-runtime.lua "$INSTALL_ROOT"\n\n')
    -- Direct updates: retain data/etc; do not create component or init backups.
    s = replace_block(s, 'SWAPPED_NEW=""\n', '# uninstall.sh 随产物分发', [[swap_failed() { die "$1"; }
for comp in $COMPONENTS; do
  rm -rf "$INSTALL_ROOT/$comp" || swap_failed "移除旧组件失败: $comp"
  mv "$STAGE_DIR/$comp" "$INSTALL_ROOT/$comp" || swap_failed "安装组件失败: $comp"
done
mv "$STAGE_DIR/meta.json" "$INSTALL_ROOT/meta.json" || swap_failed "更新版本信息失败"
]])
    s = replace_block(s, 'for _initd in openbox openbox-panel; do', 'cp "$INSTALL_ROOT/openwrt/initd/openbox"', '')
    s = replace_block(s, '# 组件和 init 脚本都换好了', '# ---- swap:end ----', '')
    return s
end)
EOF_OPENBOX_RUNTIME
    cat > /usr/libexec/nradio-openbox-line.lua <<'EOF_OPENBOX_LINE'
local json = require "luci.jsonc"
local function command(text)
    local p = io.popen(text)
    if not p then return "" end
    local value = p:read("*a"); p:close()
    return value
end
local function read(path)
    local f = io.open(path, "rb")
    if not f then return nil end
    local value = f:read("*a"); f:close()
    return value
end
local path = "/opt/open-box/etc/config.json"
local config = json.parse(read(path) or "")
if not config or not config.dns then return end
local device = command("ip -4 route show default"):match("dev%s+([%w_.%-]+)")
local status = json.parse(command("ubus call network.interface dump")) or {}
local server
for _, interface in ipairs(status.interface or {}) do
    if device and interface.up and interface.l3_device == device then
        for _, address in ipairs(interface["dns-server"] or {}) do
            if address:match("^%d+%.%d+%.%d+%.%d+$") and not address:match("^127%.") then
                server = address
                break
            end
        end
    end
    if server then break end
end
server = server or "223.5.5.5"
local changed = false
for _, resolver in ipairs(config.dns.servers or {}) do
    if resolver.tag == "dns-direct" and resolver.type == "udp" and resolver.server ~= server then
        resolver.server = server
        changed = true
    end
end
if not changed then return end
local f = assert(io.open(path, "wb"))
assert(f:write(json.stringify(config))); f:close()
print("Open-Box direct DNS: " .. server .. " via " .. (device or "default"))
if arg[1] == "start" then return end
local services = json.parse(command("ubus call service list")) or {}
for _, instance in pairs((services.openbox or {}).instances or {}) do
    if instance.running then
        if os.execute("/etc/init.d/openbox restart >/dev/null 2>&1") ~= 0 then os.exit(1) end
        -- Release requests still waiting on the previous DNS through AdGuard.
        local adguard_config = read("/etc/AdGuardHome.yaml") or ""
        if adguard_config:find("127.0.0.1:7853", 1, true) then
            for _, adguard in pairs((services.AdGuardHome or {}).instances or {}) do
                local pid = tonumber(adguard.pid)
                if adguard.running and adguard.respawn and pid then
                    os.execute("kill -TERM " .. string.format("%d", pid))
                end
            end
        end
        os.exit(0)
    end
end
EOF_OPENBOX_LINE
    cat > /usr/libexec/nradio-openbox-wan <<'EOF_OPENBOX_WAN'
#!/bin/sh
# FakeIP and the TUN TCP return path precede MWAN; regular traffic keeps its WAN policy.
case "${1:-apply}" in
    start)
        touch /var/run/nradio-openbox-wan.enabled
        # Remove the previous Open-Box outbound mark override when reinstalling.
        ip -4 rule del pref 6999 fwmark 0x400000/0x400000 2>/dev/null || true
        iptables -t mangle -D mwan3_hook -m mark --mark 0x400000/0x40ff00 -j mwan3_rules 2>/dev/null || true
        for source in $(uci -q get nradio_openbox.main.bypass); do
            ip -4 rule del pref 6998 from "$source" lookup main 2>/dev/null || true
            ip -4 rule add pref 6998 from "$source" lookup main
        done ;;
    stop)
        rm -f /var/run/nradio-openbox-wan.enabled
        for source in $(uci -q get nradio_openbox.main.bypass); do
            ip -4 rule del pref 6998 from "$source" lookup main 2>/dev/null || true
        done
        ip -4 rule del pref 7998 to 172.19.0.0/30 lookup 2022 2>/dev/null || true
        ip -4 rule del pref 7999 to 198.19.0.0/16 lookup 2022 2>/dev/null || true
        ip -4 rule del pref 6999 fwmark 0x400000/0x400000 2>/dev/null || true
        iptables -t mangle -D mwan3_hook -m mark --mark 0x400000/0x40ff00 -j mwan3_rules 2>/dev/null || true
        exit 0 ;;
esac
[ -f /var/run/nradio-openbox-wan.enabled ] || exit 0
lua /usr/libexec/nradio-openbox-line.lua "${1:-apply}"
# The system TCP stack's SYN-ACK must return to the TUN peer before MWAN.
ip -4 rule del pref 7998 to 172.19.0.0/30 lookup 2022 2>/dev/null || true
ip -4 rule add pref 7998 to 172.19.0.0/30 lookup 2022
ip -4 rule del pref 7999 to 198.19.0.0/16 lookup 2022 2>/dev/null || true
ip -4 rule add pref 7999 to 198.19.0.0/16 lookup 2022
exit 0
EOF_OPENBOX_WAN
