<!doctype html><html lang="zh-CN"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Open-Box</title>
<style>html,body{height:100%;width:100%;margin:0;background:#f7f9fc;color:#1b3044;font:14px system-ui,sans-serif;overflow:hidden}*{box-sizing:border-box}#panel{position:absolute;inset:0;width:100%;height:100%;border:0;background:#f7f9fc}#message{position:absolute;inset:0;z-index:2;display:flex;flex-direction:column;align-items:center;justify-content:center;gap:14px;background:#f7f9fc;padding:24px;text-align:center}#message[hidden]{display:none}h1{margin:0;font-size:24px}p{margin:0;line-height:1.7;color:#516679}.actions{display:flex;gap:12px;flex-wrap:wrap;justify-content:center}button,a{padding:10px 16px;border:1px solid #bad3dc;border-radius:8px;background:#e7f4f6;color:#174d58;text-decoration:none;font:inherit;cursor:pointer}</style></head>
<body><iframe id="panel" title="Open-Box 管理面板"></iframe><div id="message" role="status"><h1>Open-Box</h1><p id="detail">正在连接管理面板…</p><div class="actions"><button type="button" id="retry">重新加载</button><a id="external" target="_blank" rel="noopener">独立打开</a></div></div>
<script>
(function(){
    'use strict';
    var frame=document.getElementById('panel'),box=document.getElementById('message'),detail=document.getElementById('detail');
    var target=new URL(window.location.href);target.protocol='http:';target.port='2026';target.pathname='/';target.search='';target.hash='';
    document.getElementById('external').href=target.href;
    var timer=null,generation=0,loaded=false,healthy=false;
    function reveal(){if(loaded&&healthy){box.hidden=true;clearTimeout(timer);}}
    function load(){
        var current=++generation;loaded=false;healthy=false;box.hidden=false;detail.textContent='正在连接管理面板…';clearTimeout(timer);
        if(window.location.protocol==='https:'){detail.textContent='请通过“独立打开”访问管理面板。';return;}
        frame.onload=function(){if(current!==generation)return;loaded=true;reveal();};
        frame.onerror=function(){if(current===generation){box.hidden=false;detail.textContent='面板加载失败，请重试或独立打开。';}};
        frame.src=target.href;
        var request=new XMLHttpRequest();request.open('GET',"<%=luci.dispatcher.build_url('nradioadv','system','openbox','status')%>",true);request.timeout=5000;
        request.onload=function(){if(current!==generation)return;try{healthy=request.status===200&&JSON.parse(request.responseText).running===true;}catch(e){healthy=false;}if(healthy)reveal();else detail.textContent='Open-Box 面板尚未就绪，请稍后重试。';};
        request.onerror=request.ontimeout=function(){if(current===generation)detail.textContent='面板状态读取失败，请重试或独立打开。';};request.send();
        timer=setTimeout(function(){if(current===generation&&!box.hidden)detail.textContent='面板加载超时，请重试或独立打开。';},12000);
    }
    document.getElementById('retry').onclick=load;load();
})();
</script></body></html>
EOF_OPENBOX_VIEW
    cat > /usr/libexec/nradio-openbox-uninstall <<'EOF_OPENBOX_UNINSTALL'
#!/bin/sh
root="$(uci -q get nradio_openbox.main.root)"
[ -n "$root" ] || root="$(readlink -f /opt/open-box)"
for service in openbox openbox-panel; do
    [ ! -x "/etc/init.d/$service" ] || {
        "/etc/init.d/$service" stop || exit 1
        "/etc/init.d/$service" disable
    }
done
if opkg status luci-app-nradio-openbox 2>/dev/null | grep -q '^Status:.* installed'; then
    opkg remove luci-app-nradio-openbox || exit 1
fi
case "$root" in
    /mnt/rootfs_2nd_data/nradio-apps/open-box|/mnt/app_data/open-box|/tmp/storage/*/open-box)
        [ -z "$root" ] || rm -rf "$root" || exit 1 ;;
    *) echo '无法定位 Open-Box 安装目录'; exit 1 ;;
esac
for section in openbox_panel openbox_dns openbox_tun_forward openbox_v6block nradio_openbox_wan; do
    uci -q delete "firewall.$section" || true
done
uci commit firewall
/etc/init.d/firewall reload >/dev/null 2>&1 || true
for section in nradio_openbox nradio_openbox_luci; do
    case "$(uci -q get "appcenter.$section.name")" in
        Open-Box|luci-app-nradio-openbox) uci -q delete "appcenter.$section" ;;
    esac
done
uci commit appcenter
[ "$(readlink /opt/open-box)" != "$root" ] || rm -f /opt/open-box
[ "$(readlink /opt/ob-libc.so)" != "$root/compat/ld-musl-aarch64.so.1" ] || rm -f /opt/ob-libc.so
rm -f /etc/init.d/openbox /etc/init.d/openbox-panel /etc/config/nradio_openbox
rm -f /usr/lib/lua/luci/controller/nradio_adv/openbox.lua /usr/lib/lua/luci/view/nradio_openbox/panel.htm
rm -f /usr/libexec/nradio-openbox-runtime.lua /usr/libexec/nradio-openbox-appcenter
rm -f /usr/libexec/nradio-openbox-wan /etc/hotplug.d/iface/99-nradio-openbox-wan
rm -f /usr/libexec/nradio-openbox-line.lua
rm -f /www/luci-static/nradio/images/icon/openbox.svg /tmp/luci-indexcache
rm -f /usr/libexec/nradio-openbox-uninstall
exit 0
EOF_OPENBOX_UNINSTALL
    chmod 755 /etc/init.d/openbox-panel /usr/libexec/nradio-openbox-uninstall
    mkdir -p /www/luci-static/nradio/images/icon
    cat > /www/luci-static/nradio/images/icon/openbox.svg <<'EOF_OPENBOX_ICON'
<svg xmlns="http://www.w3.org/2000/svg" width="64" height="64" viewBox="0 0 64 64"><rect width="64" height="64" rx="14" fill="#e7f4f6"/><path d="m32 8 23 13v24L32 58 9 45V21Z" fill="none" stroke="#24566a" stroke-width="4"/><path d="m9 21 23 14 23-14M32 35v23" fill="none" stroke="#24566a" stroke-width="4"/><circle cx="32" cy="23" r="7" fill="#39bd83"/></svg>
EOF_OPENBOX_ICON
}

install_openbox() {
    local root archive libc_work core_running=0 version=0.1.184
    resolve_openbox_storage_paths
    root="$OPENBOX_INSTALL_ROOT"
    archive="$root/open-box-download.tar.gz"
    libc_work="$root/compat"
    log "Open-Box $version → $root"
    mkdir -p "$root" "$libc_work" /opt
    # Use the complete package: the app-only archive omits panel/server/resources/geodata.
    download_from_urls "$archive" "https://github.com/liandu2024/Open-Box/releases/download/v$version/open-box-v$version-linux-arm64.tar.gz" || die "Open-Box 下载失败"
    download_from_urls "$libc_work/libc.ipk" "https://downloads.openwrt.org/releases/24.10.3/targets/mediatek/filogic/packages/libc_1.2.5-r4_aarch64_cortex-a53.ipk" || die "Open-Box 运行库下载失败"
    if [ -x /etc/init.d/openbox ] && /etc/init.d/openbox running >/dev/null 2>&1; then
        core_running=1
        # Stop the process for replacement without undoing the active DNS settings.
        ubus call service delete '{"name":"openbox"}' >/dev/null 2>&1 || true
    fi
    [ ! -x /etc/init.d/openbox-panel ] || /etc/init.d/openbox-panel stop
    tar -xzf "$archive" -C "$root" || die "Open-Box 解压失败"
    rm -f "$archive"
    tar -xzf "$libc_work/libc.ipk" -C "$libc_work" ./data.tar.gz || die "运行库解压失败"
    tar -xzf "$libc_work/data.tar.gz" -C "$libc_work" ./lib/libc.so || die "运行库解压失败"
    mv -f "$libc_work/lib/libc.so" "$libc_work/ld-musl-aarch64.so.1"
    rm -f "$libc_work/libc.ipk" "$libc_work/data.tar.gz"
    rmdir "$libc_work/lib" 2>/dev/null || true
    ln -sfn "$root" /opt/open-box
    ln -sfn "$libc_work/ld-musl-aarch64.so.1" /opt/ob-libc.so
    touch /etc/config/nradio_openbox
    uci set nradio_openbox.main=openbox
    uci set "nradio_openbox.main.root=$root"
    uci set "nradio_openbox.main.mount=$OPENBOX_STORAGE_MOUNT"
    uci commit nradio_openbox
    write_openbox_assets
    [ -f /etc/init.d/openbox ] || cp "$root/openwrt/initd/openbox" /etc/init.d/openbox
    lua /usr/libexec/nradio-openbox-runtime.lua "$root"
    chmod 755 /etc/init.d/openbox "$root/node/bin/node" "$root/bin/sing-box" "$libc_work/ld-musl-aarch64.so.1"
    /etc/init.d/openbox-panel enable
    /etc/init.d/openbox-panel start
    if [ "$core_running" = 1 ]; then /etc/init.d/openbox start; fi
    write_plugin_uninstall_assets
    patch_common_template
    set_appcenter_entry 'Open-Box' 'luci-app-nradio-openbox' "$version" "$(du -sk "$root" | awk '{print $1}')" '/usr/lib/lua/luci/controller/nradio_adv/openbox.lua' 'nradioadv/system/openbox' 'openbox.svg'
    uci set "appcenter.$pkg_sec.open=1"
    uci commit appcenter
    refresh_luci_appcenter
    log "Open-Box 已安装到 $root；应用商店可打开、卸载。首次使用请在面板完成设置。"
}

generate_openlist_admin_password() {
    if [ -r /dev/urandom ] && command -v od >/dev/null 2>&1; then
        od -An -N16 -tx1 /dev/urandom 2>/dev/null | tr -d ' \n'
        return 0
    fi
    openlist_password_seed="$(date +%s 2>/dev/null || printf now)-$$-$(cat /proc/uptime 2>/dev/null || printf 0)"
    if command -v sha256sum >/dev/null 2>&1; then
        printf '%s' "$openlist_password_seed" | sha256sum | awk '{print substr($1,1,32)}'
    elif command -v md5sum >/dev/null 2>&1; then
        printf '%s' "$openlist_password_seed" | md5sum | awk '{print $1}'
    else
        printf 'OpenList-%s-%s' "$(date +%Y%m%d%H%M%S 2>/dev/null || printf now)" "$$"
    fi
}

install_openlist() {
    require_nradio_oem_appcenter

    openlist_asset_name="$OPENLIST_ASSET_NAME"
    openlist_workdir="$WORKDIR/openlist"
    openlist_c2000max_mode='0'
    if [ "${CURRENT_DETECTED_MODEL:-}" = 'NRadio_C2000MAX' ]; then
        openlist_storage_mount="$(detect_c2000max_storage_mount 2>/dev/null || true)"
        [ -n "$openlist_storage_mount" ] || die "未检测到 C2000MAX 存储卡，无法把 OpenList 下载到存储卡"
        ensure_dir_writable "$openlist_storage_mount" "C2000MAX 存储卡"
        openlist_asset_name="openlist-linux-musl-arm64-lite.tar.gz"
        openlist_workdir="$openlist_storage_mount/nradio-openlist-work.$$"
        OPENLIST_ACTIVE_WORKDIR="$openlist_workdir"
        openlist_c2000max_mode='1'
    fi

    OPENLIST_RESOLVED_ASSET_NAME="$openlist_asset_name"
    OPENLIST_RESOLVED_DOWNLOAD_URLS=''
    mkdir -p "$openlist_workdir"
    ensure_dir_writable "$openlist_workdir" "OpenList 临时工作目录"
    openlist_archive="$openlist_workdir/$openlist_asset_name"
    openlist_unpack="$openlist_workdir/unpack"

    log_stage 1 5 "OpenList GitHub 加速下载规划"
    openlist_official_ping_hosts=""
    openlist_official_probe_urls="$(build_openlist_official_probe_urls)"
    rank_url_list_hosts "openlist-official" "OpenList GitHub 下载源" "$openlist_official_probe_urls"
    openlist_official_ping_hosts="$RANKED_URL_HOSTS"
    [ -n "$openlist_official_ping_hosts" ] || openlist_official_ping_hosts="$OPENLIST_STABLE_HOST_ORDER"
    if [ "${OPENLIST_FAST_DOWNLOAD_MODE:-1}" = '1' ]; then
        log "提示: OpenList 启用快速下载模式，gh-proxy 优先，失败回退官方地址"
    else
        openlist_package_urls="$(build_openlist_download_urls)"
        if [ -n "$openlist_official_ping_hosts" ]; then
            openlist_package_urls="$(reorder_urls_by_host_rank "$openlist_package_urls" "$openlist_official_ping_hosts")"
        fi
        openlist_probe_min_bytes="$(( (OPENCLASH_PACKAGE_PROBE_BYTES + 1) / 2 ))"
        rank_hosts_by_partial_download_probe "openlist-package" "OpenList 官方安装包" "$openlist_package_urls" "$OPENCLASH_PACKAGE_PROBE_BYTES" "$openlist_probe_min_bytes"
        if [ -n "${RANKED_URL_HOSTS:-}" ]; then
            openlist_package_urls="$(reorder_urls_by_host_rank "$openlist_package_urls" "$RANKED_URL_HOSTS")"
            openlist_official_ping_hosts="$RANKED_URL_HOSTS"
        fi
    fi
    openlist_official_ping_hosts="$(printf '%s\n' "$openlist_official_ping_hosts" | sed 's/[[:space:]][[:space:]]*/ /g; s/^[[:space:]]*//; s/[[:space:]]*$//')"
    log "提示: OpenList 下载优先使用 gh-proxy，官方地址和其他镜像作为后备"
    if [ "$openlist_c2000max_mode" = '1' ]; then
        log "提示: 检测到 C2000MAX，OpenList 官方完整包体积较大，低内存设备可能在下载或解压阶段被系统 Killed"
        log "提示: 本次将自动改用 OpenList lite 安装包，并把下载包与解压目录放到存储卡"
        log "提示: C2000MAX 使用存储卡临时目录: $openlist_workdir"
        log "说明: 这样可以减少 /tmp 内存占用，降低因文件过大导致安装失败的概率"
    fi
    confirm_or_exit "确认继续安装 OpenList 并修改系统吗？"

    log_stage 2 5 "通过 GitHub 加速源下载 OpenList 官方安装包"
    openlist_package_urls="$(build_openlist_download_urls)"
    if [ -n "${openlist_official_ping_hosts:-}" ]; then
        openlist_package_urls="$(reorder_urls_by_host_rank "$openlist_package_urls" "$openlist_official_ping_hosts")"
    fi
    log "提示: OpenList 实际下载源顺序: $(summarize_url_hosts $openlist_package_urls)"
    log "提示: OpenList 官方安装包内容较大，下载与断点续传可能耗时较长，请耐心等待"
    openlist_download_stall_time_saved="$DOWNLOAD_STALL_TIME"
    openlist_download_stall_speed_saved="$DOWNLOAD_STALL_SPEED"
    openlist_download_max_time_saved="$DOWNLOAD_MAX_TIME"
    openlist_download_keep_partial_saved="${DOWNLOAD_KEEP_PARTIAL:-0}"
    openlist_download_skip_content_length_saved="${DOWNLOAD_SKIP_CONTENT_LENGTH:-0}"
    DOWNLOAD_MAX_TIME="$OPENLIST_PACKAGE_MAX_TIME"
    DOWNLOAD_STALL_TIME="$OPENLIST_PACKAGE_STALL_TIME"
    DOWNLOAD_STALL_SPEED="$OPENLIST_PACKAGE_STALL_SPEED"
    DOWNLOAD_KEEP_PARTIAL=1
    DOWNLOAD_SKIP_CONTENT_LENGTH=1
    openlist_download_url=""
    if download_openlist_from_urls "$openlist_archive" $openlist_package_urls; then
        openlist_download_url="$LAST_DOWNLOAD_SOURCE"
    fi
    if [ -z "$openlist_download_url" ]; then
        log "提示: 首轮下载未完成，正在放宽速度阈值后重试..."
        DOWNLOAD_STALL_TIME="$OPENLIST_PACKAGE_RETRY_STALL_TIME"
        DOWNLOAD_STALL_SPEED="$OPENLIST_PACKAGE_RETRY_STALL_SPEED"
        if [ "$openlist_c2000max_mode" = '1' ]; then
            rm -f "$openlist_archive" "$openlist_archive.tmp" 2>/dev/null || true
            log "提示: C2000MAX 已清理 OpenList 临时下载文件，将重新完整下载"
        fi
        if download_openlist_from_urls "$openlist_archive" $openlist_package_urls; then
            openlist_download_url="$LAST_DOWNLOAD_SOURCE"
        else
            openlist_download_url=""
        fi
    fi
    DOWNLOAD_MAX_TIME="$openlist_download_max_time_saved"
    DOWNLOAD_STALL_TIME="$openlist_download_stall_time_saved"
    DOWNLOAD_STALL_SPEED="$openlist_download_stall_speed_saved"
    DOWNLOAD_KEEP_PARTIAL="$openlist_download_keep_partial_saved"
    DOWNLOAD_SKIP_CONTENT_LENGTH="$openlist_download_skip_content_length_saved"
    [ -n "$openlist_download_url" ] || die "无法从可用的 GitHub 地址下载 OpenList 官方安装包"
    openlist_download_host="$(extract_url_host "$openlist_download_url" 2>/dev/null || true)"
    openlist_download_size="$(wc -c < "$openlist_archive" | tr -d ' ')"

    log_stage 3 5 "解压安装 OpenList 并写入运行文件"
    validate_tar_archive "$openlist_archive" "OpenList 官方安装包" "$WORKDIR/openlist-archive-validate.log"
    openlist_extract_need="$(estimate_archive_extract_bytes "$openlist_archive" 2>/dev/null || true)"
    rm -rf "$openlist_unpack"
    mkdir -p "$openlist_unpack"
    ensure_dir_writable "$openlist_unpack" "OpenList 临时解压目录"
    resolve_openlist_storage_paths prepare
    log "提示: OpenList 安装根目录: $OPENLIST_ROOT_DIR"
    prepare_openlist_install_dirs
    case "$openlist_extract_need" in
        ''|*[!0-9]*) ;;
        *)
            ensure_free_space_bytes "$openlist_unpack" "$openlist_extract_need" "OpenList 临时解压目录"
            ensure_free_space_bytes "$OPENLIST_ROOT_DIR" "$openlist_extract_need" "$OPENLIST_ROOT_DIR"
            ;;
    esac
    tar -xzf "$openlist_archive" -C "$openlist_unpack" >/dev/null 2>&1 || die "解压 OpenList 官方安装包失败"
    openlist_bin_src=""
    for candidate in "$openlist_unpack"/openlist "$openlist_unpack"/*/openlist "$openlist_unpack"/*/*/openlist; do
        [ -f "$candidate" ] || continue
        openlist_bin_src="$candidate"
        break
    done
    [ -n "$openlist_bin_src" ] || die "解压后未找到 OpenList 可执行文件"

    prepare_openlist_install_dirs
    rm -f "$OPENLIST_LINK_PATH" "$OPENLIST_BIN_PATH" 2>/dev/null || true
    cp "$openlist_bin_src" "$OPENLIST_BIN_PATH"
    chmod 755 "$OPENLIST_BIN_PATH" 2>/dev/null || true
    ln -sf "$OPENLIST_BIN_PATH" "$OPENLIST_LINK_PATH"

    write_openlist_runtime_files
    ensure_openlist_config_defaults
    OPENLIST_SKIP_FIREWALL_SYNC=1 /usr/libexec/openlist-sync-config >"$WORKDIR/openlist-sync.log" 2>&1 || die "生成 OpenList 配置失败：$WORKDIR/openlist-sync.log"
    openlist_effective_data_dir="$(get_openlist_effective_data_dir)"
    openlist_admin_initialized='0'
    openlist_admin_password=''
    if [ ! -s "$openlist_effective_data_dir/data.db" ]; then
        openlist_admin_password="$OPENLIST_DEFAULT_ADMIN_PASSWORD"
        [ -n "$openlist_admin_password" ] || openlist_admin_password="$(generate_openlist_admin_password)"
        [ -n "$openlist_admin_password" ] || die "生成 OpenList 初始管理员密码失败"
        require_private_procfs_for_secret_argv "OpenList 管理员密码" || die "OpenList 管理员密码初始化已停止"
        openlist_admin_log="$WORKDIR/openlist-admin.log"
        (
            cd "$OPENLIST_ROOT_DIR" &&
            ./bin/openlist admin set "$openlist_admin_password" --data "$openlist_effective_data_dir"
        ) >"$openlist_admin_log" 2>&1 || die "初始化 OpenList 管理员密码失败：$openlist_admin_log"
        openlist_admin_initialized='1'
    else
        log "提示: 检测到现有 OpenList 数据库，保留管理员账号与密码"
    fi
    enable_init_service_strict /etc/init.d/openlist "OpenList" || die "OpenList 开机启动配置失败"

    log_stage 4 5 "写入 OEM 页面、图标并注册应用商店"
    log "提示: 正在接入 OEM 应用商店并刷新模板与配置，内容较多时可能持续较长，请耐心等待"
    write_openlist_oem_files
    backup_file "$CFG"
    cleanup_appcenter_entry "OpenList" "OpenList" "nradioadv/system/openlist/basic"
    cleanup_appcenter_entry "OpenList" "openlist" "nradioadv/system/openlist/basic"
    cleanup_appcenter_entry "OpenList" "luci-app-openlist" "admin/services/openlist"
    openlist_icon_name=""
    if install_openlist_embedded_icon; then
        openlist_icon_name="$OPENLIST_ICON_NAME"
    fi
    set_appcenter_entry "OpenList" "OpenList" "$OPENLIST_VERSION" "$openlist_download_size" "/usr/lib/lua/luci/controller/nradio_adv/openlist.lua" "nradioadv/system/openlist/basic" "$openlist_icon_name"
    uci commit appcenter
    write_plugin_uninstall_assets
    patch_common_template
    refresh_luci_appcenter
    /etc/init.d/uhttpd reload >/dev/null 2>&1 || true

    log_stage 5 5 "写入虚拟内存并校验 OpenList 页面与应用商店入口"
    ensure_existing_swap_access "OpenList"
    verify_appcenter_route "OpenList" "nradioadv/system/openlist/basic"
    verify_file_exists "$OPENLIST_BIN_PATH" "OpenList"
    verify_file_exists "$OPENLIST_LINK_PATH" "OpenList"
    verify_file_exists /etc/init.d/openlist "OpenList"
    verify_file_exists /usr/libexec/openlist-sync-config "OpenList"
    verify_file_exists /etc/config/openlist "OpenList"
    verify_file_exists "$openlist_effective_data_dir/config.json" "OpenList"
    verify_file_exists /usr/lib/lua/luci/controller/nradio_adv/openlist.lua "OpenList"
    verify_file_exists /usr/lib/lua/luci/model/cbi/nradio_adv/openlist_basic.lua "OpenList"
    verify_file_exists /usr/lib/lua/luci/view/nradio_adv/openlist_logs.htm "OpenList"
    verify_file_exists /usr/lib/lua/luci/view/nradio_adv/openlist_polish.htm "OpenList 页面美化"
    verify_luci_route nradioadv/system/openlist "OpenList"
    verify_luci_route nradioadv/system/openlist/basic "OpenList"
    verify_luci_route nradioadv/system/openlist/logs "OpenList"

    log "安装完成"
    log "插件:   OpenList"
    log "版本:   $OPENLIST_VERSION"
    log "路由:   nradioadv/system/openlist/basic"
    log "图标:   内置 OpenList SVG"
    if [ -n "$openlist_download_host" ]; then
        log "下载源: GitHub 官方 CDN（$openlist_download_host）"
    else
        log "下载源: GitHub 官方 CDN"
    fi
    if [ "$openlist_admin_initialized" = '1' ]; then
        log "初始账号: admin"
        log "初始密码: $openlist_admin_password"
        log "提示:   初始密码仅在本次安装摘要显示，请立即妥善保存"
    else
        log "管理员: 已保留现有数据库账号与密码"
    fi
    log "说明:   本次安装不会自动启动 OpenList，如需运行请在设置页点“启动/重启服务”"
}

write_zerotier_oem_files() {
    zerotier_polish="/usr/lib/lua/luci/view/nradio_adv/zerotier_polish.htm"
    mkdir -p /usr/lib/lua/luci/controller/nradio_adv /usr/lib/lua/luci/model/cbi/nradio_adv /usr/lib/lua/luci/view/nradio_adv
    backup_file "$ZEROTIER_CONTROLLER"
    backup_file "$ZEROTIER_CBI"
    backup_file "$zerotier_polish"

    cat > "$ZEROTIER_CONTROLLER" <<'EOF_ZEROTIER_CONTROLLER'
module("luci.controller.nradio_adv.zerotier", package.seeall)

function index()
    entry({"nradioadv", "system", "zerotier"}, alias("nradioadv", "system", "zerotier", "basic"), _("ZeroTier"), 92)
    entry({"nradioadv", "system", "zerotier", "basic"}, cbi("nradio_adv/zerotier_basic"), _("设置"), 10).leaf = true
    entry({"nradioadv", "system", "appcenter", "zerotier"}, alias("nradioadv", "system", "zerotier"), nil, nil, true).leaf = true
end
EOF_ZEROTIER_CONTROLLER

    cat > "$ZEROTIER_CBI" <<'EOF_ZEROTIER_CBI'
local sys = require "luci.sys"
local http = require "luci.http"
local dispatcher = require "luci.dispatcher"
local uci = require "luci.model.uci".cursor()
local util = require "luci.util"

m = Map("zerotier", translate("ZeroTier"), translate("ZeroTier OEM 兼容设置页"))

local function get_section()
    local sid
    uci:foreach("zerotier", "zerotier", function(s)
        if not sid then
            sid = s[".name"]
        end
    end)
    if not sid then
        sid = "sample_config"
        uci:set("zerotier", sid, "zerotier")
        uci:set("zerotier", sid, "enabled", "0")
        uci:save("zerotier")
        uci:commit("zerotier")
    end
    return sid
end

local sid = get_section()

s = m:section(NamedSection, sid, "zerotier", "")
s.addremove = false
s.anonymous = true

local status = s:option(DummyValue, "_status", translate("服务状态"))
function status.cfgvalue()
    local running = sys.call("/etc/init.d/zerotier status >/dev/null 2>&1") == 0
    return running and translate("运行中") or translate("未运行")
end

local node = s:option(DummyValue, "_node", translate("节点信息"))
function node.cfgvalue()
    local info = sys.exec("zerotier-cli info 2>/dev/null | tr -d '\\r' | head -n 1") or ""
    info = info:gsub("^%s+", ""):gsub("%s+$", "")
    if info == "" then
        return translate("暂未获取到节点信息")
    end
    return info
end

local nets = s:option(DummyValue, "_nets", translate("已加入网络"))
nets.rawhtml = true
function nets.cfgvalue()
    local info = sys.exec("zerotier-cli listnetworks 2>/dev/null | tr -d '\\r'") or ""
    info = info:gsub("^%s+", ""):gsub("%s+$", "")
    if info == "" then
        return translate("暂无")
    end
    return "<pre style=\"white-space:pre-wrap;word-break:break-all;margin:0;\">" .. util.pcdata(info) .. "</pre>"
end

local restart_btn = s:option(Button, "_restart", translate("启动/重启服务"))
restart_btn.inputtitle = translate("启动/重启 ZeroTier")
restart_btn.inputstyle = "apply"
function restart_btn.write()
    sys.call("/etc/init.d/zerotier enable >/dev/null 2>&1")
    sys.call("/etc/init.d/zerotier restart >/dev/null 2>&1")
    http.redirect(dispatcher.build_url("nradioadv", "system", "zerotier", "basic"))
end

local stop_btn = s:option(Button, "_stop", translate("停止服务"))
stop_btn.inputtitle = translate("停止 ZeroTier")
stop_btn.inputstyle = "reset"
function stop_btn.write()
    sys.call("/etc/init.d/zerotier stop >/dev/null 2>&1")
    http.redirect(dispatcher.build_url("nradioadv", "system", "zerotier", "basic"))
end

enabled = s:option(Flag, "enabled", translate("开机自启"))
enabled.rmempty = false

port = s:option(Value, "port", translate("监听端口"))
port.placeholder = "9993"
port.datatype = "port"
port.rmempty = true

secret = s:option(Value, "secret", translate("节点密钥"))
secret.password = true
secret.rmempty = true

join = s:option(DynamicList, "join", translate("加入网络 ID"))
join.datatype = "and(uciname,rangelength(16,16))"
join.placeholder = "8056c2e21c000001"
join.rmempty = true

note = s:option(DummyValue, "_note", translate("说明"))
note.rawhtml = true
function note.cfgvalue()
    return "<span>保存后如需立即生效，可点击“启动/重启服务”。</span>"
end

m:append(Template("nradio_adv/zerotier_polish"))

return m
EOF_ZEROTIER_CBI

    cat > "$zerotier_polish" <<'EOF_ZEROTIER_POLISH'
<style>
/* NRadio ZeroTier premium visual finish */
body{background:#0b1220!important;color:#e5edf7!important}
.cbi-map{position:relative;overflow:hidden;border:1px solid rgba(147,197,253,.24)!important;border-radius:18px!important;background:radial-gradient(circle at 12% 0%,rgba(96,165,250,.16),transparent 34%),radial-gradient(circle at 92% 10%,rgba(45,212,191,.09),transparent 30%),linear-gradient(145deg,rgba(15,23,42,.96),rgba(3,7,18,.94))!important;box-shadow:inset 0 1px 0 rgba(255,255,255,.08),0 24px 54px rgba(2,8,23,.30)!important;color:#e5edf7!important}
.cbi-map:before{content:"";position:absolute;left:22px;right:22px;top:0;height:1px;background:linear-gradient(90deg,transparent,rgba(147,197,253,.66),rgba(45,212,191,.32),transparent);pointer-events:none}
.cbi-map h2{color:#f8fbff!important;font-weight:900!important;letter-spacing:.01em;text-shadow:0 1px 0 rgba(0,0,0,.28)}
.cbi-map-descr{color:#a9bbcf!important}.cbi-section{border:1px solid rgba(148,163,184,.18)!important;border-radius:16px!important;background:rgba(8,15,28,.56)!important;box-shadow:inset 0 1px 0 rgba(255,255,255,.045)!important}.cbi-value{border-bottom-color:rgba(148,163,184,.12)!important}.cbi-value-title{color:#bfd2e6!important;font-weight:800!important}.cbi-value-field,.cbi-value-description{color:#dbe7f4!important}.cbi-value-field pre{border:1px solid rgba(147,197,253,.18)!important;border-radius:12px!important;background:#050b16!important;color:#dbeafe!important;padding:12px!important;line-height:1.55!important;box-shadow:inset 0 1px 0 rgba(255,255,255,.035)!important}
.cbi-input-text,.cbi-input-password,select{border-color:rgba(147,197,253,.24)!important;background:rgba(2,8,23,.72)!important;color:#f8fbff!important;border-radius:10px!important;box-shadow:inset 0 1px 0 rgba(255,255,255,.04)!important}.cbi-input-text:focus,.cbi-input-password:focus,select:focus{border-color:rgba(96,165,250,.58)!important;box-shadow:0 0 0 3px rgba(96,165,250,.13),inset 0 1px 0 rgba(255,255,255,.05)!important;outline:0!important}.cbi-button{border-radius:10px!important;border-color:rgba(147,197,253,.30)!important;background:linear-gradient(180deg,rgba(255,255,255,.055),rgba(255,255,255,.010)),rgba(5,12,22,.70)!important;color:#eef7ff!important;font-weight:800!important;box-shadow:inset 0 1px 0 rgba(255,255,255,.052),0 8px 18px rgba(0,0,0,.14)!important}.cbi-button:hover{border-color:rgba(96,165,250,.54)!important;background:linear-gradient(180deg,rgba(96,165,250,.18),rgba(96,165,250,.045)),rgba(5,12,22,.76)!important;color:#fff!important}.cbi-button-apply{border-color:rgba(96,165,250,.48)!important;background:linear-gradient(135deg,rgba(59,130,246,.34),rgba(20,184,166,.18)),rgba(5,12,22,.76)!important}
.cbi-value-field,.cbi-value-description,.cbi-section-node{min-width:0!important;overflow-wrap:anywhere!important}.cbi-map,.cbi-section,.cbi-button{backdrop-filter:saturate(1.04) blur(3px);-webkit-backdrop-filter:saturate(1.04) blur(3px)}@media(max-width:520px){.cbi-map{border-radius:15px!important}.cbi-section{border-radius:14px!important}.cbi-value-title,.cbi-value-field{display:block!important;width:auto!important}}
</style>
EOF_ZEROTIER_POLISH

    chmod 644 "$ZEROTIER_CONTROLLER" "$ZEROTIER_CBI" "$zerotier_polish"
}

ensure_zerotier_config_defaults() {
    if [ ! -f /etc/config/zerotier ]; then
        cat > /etc/config/zerotier <<'EOF_ZEROTIER_UCI'
config zerotier 'sample_config'
    option enabled '0'
EOF_ZEROTIER_UCI
    fi

    zerotier_section="$(uci -q show zerotier 2>/dev/null | sed -n 's/^zerotier\.\([^.=]*\)=zerotier$/\1/p' | sed -n '1p')"
    if [ -z "$zerotier_section" ]; then
        zerotier_section='sample_config'
        uci -q set "zerotier.$zerotier_section=zerotier"
    fi
    [ -n "$(uci -q get "zerotier.$zerotier_section.enabled" 2>/dev/null || true)" ] || uci -q set "zerotier.$zerotier_section.enabled=0"
    uci -q commit zerotier >/dev/null 2>&1 || true
}

install_zerotier() {
    require_nradio_oem_appcenter
    ensure_default_feeds
    mkdir -p "$WORKDIR/zerotier"
    zerotier_ipk="$WORKDIR/zerotier/${ZEROTIER_PACKAGE_NAME}.ipk"

    log_stage 1 5 "ZeroTier CDN 探测与安装规划"
    zerotier_meta="$(resolve_package_meta_any_feed "$ZEROTIER_PACKAGE_NAME" 2>/dev/null || true)"
    [ -n "$zerotier_meta" ] || { sed -n '1,80p' "$FEEDS" >&2; die "无法从当前软件源解析 ZeroTier 安装包"; }
    zerotier_feed_name="${zerotier_meta%%|*}"
    zerotier_meta_rest="${zerotier_meta#*|}"
    zerotier_feed_url="${zerotier_meta_rest%%|*}"
    zerotier_meta_rest="${zerotier_meta_rest#*|}"
    zerotier_filename="${zerotier_meta_rest%%|*}"
    zerotier_version="${zerotier_meta_rest##*|}"
    zerotier_package_urls="$(build_package_download_urls_from_meta "$zerotier_feed_url" "$zerotier_filename" 2>/dev/null || true)"
    [ -n "$zerotier_package_urls" ] || die "无法生成 ZeroTier 下载地址"

    rank_url_list_hosts "zerotier" "ZeroTier" "$zerotier_package_urls"
    if [ -n "${RANKED_URL_HOSTS:-}" ]; then
        refine_ranked_hosts_by_http_probe "zerotier" "ZeroTier" "$RANKED_URL_HOSTS" "$zerotier_package_urls"
        zerotier_package_urls="$(reorder_urls_by_host_rank "$zerotier_package_urls" "$RANKED_URL_HOSTS")"
        log "提示: ZeroTier CDN 优先级: $RANKED_URL_HOSTS"
    fi
    zerotier_probe_min_bytes="$(( (OPENCLASH_PACKAGE_PROBE_BYTES + 1) / 2 ))"
    rank_hosts_by_partial_download_probe "zerotier-package" "ZeroTier 安装包" "$zerotier_package_urls" "$OPENCLASH_PACKAGE_PROBE_BYTES" "$zerotier_probe_min_bytes"
    if [ -n "${RANKED_URL_HOSTS:-}" ]; then
        zerotier_package_urls="$(reorder_urls_by_host_rank "$zerotier_package_urls" "$RANKED_URL_HOSTS")"
        log "提示: ZeroTier 安装包 CDN 顺序: $RANKED_URL_HOSTS"
    fi
    log "提示: ZeroTier 当前解析源: $zerotier_feed_name"
    log "下一步将通过 CDN 下载 ZeroTier 安装包，并写入 OEM 应用商店入口"
    confirm_or_exit "确认继续安装 ZeroTier 并修改系统吗？"

    log_stage 2 5 "通过 CDN 下载 ZeroTier 安装包"
    zerotier_download_stall_time_saved="$DOWNLOAD_STALL_TIME"
    zerotier_download_stall_speed_saved="$DOWNLOAD_STALL_SPEED"
    zerotier_download_keep_partial_saved="${DOWNLOAD_KEEP_PARTIAL:-0}"
    DOWNLOAD_STALL_TIME="$ZEROTIER_PACKAGE_STALL_TIME"
    DOWNLOAD_STALL_SPEED="$ZEROTIER_PACKAGE_STALL_SPEED"
    DOWNLOAD_KEEP_PARTIAL=1
    zerotier_download_url=""
    if download_from_urls "$zerotier_ipk" $zerotier_package_urls; then
        zerotier_download_url="$LAST_DOWNLOAD_SOURCE"
    fi
    if [ -z "$zerotier_download_url" ]; then
        log "提示: 首轮 ZeroTier 安装包下载未完成，正在放宽速度阈值后重试..."
        DOWNLOAD_STALL_TIME="$ZEROTIER_PACKAGE_RETRY_STALL_TIME"
        DOWNLOAD_STALL_SPEED="$ZEROTIER_PACKAGE_RETRY_STALL_SPEED"
        if download_from_urls "$zerotier_ipk" $zerotier_package_urls; then
            zerotier_download_url="$LAST_DOWNLOAD_SOURCE"
        fi
    fi
    DOWNLOAD_STALL_TIME="$zerotier_download_stall_time_saved"
    DOWNLOAD_STALL_SPEED="$zerotier_download_stall_speed_saved"
    DOWNLOAD_KEEP_PARTIAL="$zerotier_download_keep_partial_saved"
    [ -n "$zerotier_download_url" ] || die "无法从全部 CDN 地址下载 ZeroTier 安装包"
    [ -s "$zerotier_ipk" ] || die "ZeroTier 安装包下载失败"
    zerotier_download_host="$(extract_url_host "$zerotier_download_url" 2>/dev/null || true)"
    zerotier_download_size="$(wc -c < "$zerotier_ipk" | tr -d ' ')"

    log_stage 3 5 "安装 ZeroTier 核心并准备配置"
    ensure_opkg_update || die "opkg update 失败，已停止 ZeroTier 安装"
    install_ipk_file "$zerotier_ipk" "ZeroTier"
    ensure_zerotier_config_defaults
    [ -n "$zerotier_version" ] || zerotier_version="$(get_installed_package_version zerotier 2>/dev/null || true)"
    [ -n "$zerotier_version" ] || zerotier_version="installed"

    log_stage 4 5 "写入 OEM 页面、图标并注册应用商店"
    write_zerotier_oem_files
    backup_file "$CFG"
    cleanup_appcenter_entry "ZeroTier" "ZeroTier" "$ZEROTIER_ROUTE"
    cleanup_appcenter_entry "ZeroTier" "zerotier" "$ZEROTIER_ROUTE"
    zerotier_icon_name=""
    if install_zerotier_embedded_icon; then
        zerotier_icon_name="$ZEROTIER_ICON_NAME"
    fi
    set_appcenter_entry "ZeroTier" "zerotier" "$zerotier_version" "$zerotier_download_size" "$ZEROTIER_CONTROLLER" "$ZEROTIER_ROUTE" "$zerotier_icon_name"
    zerotier_pkg_sec="$(find_uci_section package "ZeroTier")"
    [ -n "$zerotier_pkg_sec" ] && uci -q set "appcenter.$zerotier_pkg_sec.open=0" >/dev/null 2>&1 || true
    uci commit appcenter
    write_plugin_uninstall_assets
    patch_common_template
    refresh_luci_appcenter
    /etc/init.d/uhttpd reload >/dev/null 2>&1 || true

    log_stage 5 5 "写入虚拟内存并校验 ZeroTier 页面与应用商店入口"
    ensure_existing_swap_access "ZeroTier"
    verify_appcenter_route "ZeroTier" "$ZEROTIER_ROUTE"
    verify_file_exists /etc/init.d/zerotier "ZeroTier"
    verify_file_exists /etc/config/zerotier "ZeroTier"
    verify_file_exists "$ZEROTIER_CONTROLLER" "ZeroTier"
    verify_file_exists "$ZEROTIER_CBI" "ZeroTier"
    verify_file_exists /usr/lib/lua/luci/view/nradio_adv/zerotier_polish.htm "ZeroTier 页面美化"
    verify_luci_route nradioadv/system/zerotier "ZeroTier"
    verify_luci_route nradioadv/system/zerotier/basic "ZeroTier"

    zerotier_installed_ver="$(get_installed_package_version zerotier 2>/dev/null || true)"
    [ -n "$zerotier_installed_ver" ] || zerotier_installed_ver="$zerotier_version"

    log "安装完成"
    log "插件:   ZeroTier"
    log "版本:   $zerotier_installed_ver"
    log "路由:   $ZEROTIER_ROUTE"
    if [ -n "$zerotier_download_host" ]; then
        log "下载源: CDN（$zerotier_download_host）"
    else
        log "下载源: CDN"
    fi
    log "说明:   如需联网请进入设置页填写网络 ID 后点“启动/重启服务”"
}

install_easytier() {
    require_nradio_oem_appcenter
    ensure_default_feeds

    mkdir -p "$WORKDIR/easytier"
    easytier_archive="$WORKDIR/easytier/$EASYTIER_ASSET_NAME"
    easytier_unpack="$WORKDIR/easytier/unpack"
    easytier_core_ipk=""
    easytier_luci_ipk=""
    easytier_i18n_ipk=""
    EASYTIER_RESOLVED_DOWNLOAD_URLS=''

    log_stage 1 5 "$EASYTIER_DISPLAY_NAME GitHub 加速下载规划"
    easytier_official_ping_hosts=""
    rank_url_list_hosts "easytier-official" "$EASYTIER_DISPLAY_NAME GitHub 下载源" "$EASYTIER_GITHUB_OFFICIAL_PROBE_URLS"
    easytier_official_ping_hosts="$RANKED_URL_HOSTS"
    [ -n "$easytier_official_ping_hosts" ] || easytier_official_ping_hosts="$EASYTIER_STABLE_HOST_ORDER"
    easytier_official_ping_hosts="$(printf '%s\n' "$easytier_official_ping_hosts" | sed 's/[[:space:]][[:space:]]*/ /g; s/^[[:space:]]*//; s/[[:space:]]*$//')"
    log "提示: $EASYTIER_DISPLAY_NAME 下载优先使用 gh-proxy，官方地址和其他镜像作为后备"
    confirm_or_exit "确认继续安装 $EASYTIER_DISPLAY_NAME 并修改系统吗？"

    log_stage 2 5 "通过 GitHub 加速源下载 $EASYTIER_DISPLAY_NAME 官方安装包"
    easytier_package_urls="$(build_easytier_download_urls)"
    if [ -n "${easytier_official_ping_hosts:-}" ]; then
        easytier_package_urls="$(reorder_urls_by_host_rank "$easytier_package_urls" "$easytier_official_ping_hosts")"
    fi
    easytier_probe_min_bytes="$(( (OPENCLASH_PACKAGE_PROBE_BYTES + 1) / 2 ))"
    rank_hosts_by_partial_download_probe "easytier-package" "$EASYTIER_DISPLAY_NAME 官方安装包" "$easytier_package_urls" "$OPENCLASH_PACKAGE_PROBE_BYTES" "$easytier_probe_min_bytes"
    if [ -n "${RANKED_URL_HOSTS:-}" ]; then
        easytier_package_urls="$(reorder_urls_by_host_rank "$easytier_package_urls" "$RANKED_URL_HOSTS")"
    fi
    log "提示: $EASYTIER_DISPLAY_NAME 实际下载源顺序: $(summarize_url_hosts $easytier_package_urls)"
    log "提示: $EASYTIER_DISPLAY_NAME 官方安装包内容较大，下载与断点续传可能耗时较长，请耐心等待"
    easytier_download_stall_time_saved="$DOWNLOAD_STALL_TIME"
    easytier_download_stall_speed_saved="$DOWNLOAD_STALL_SPEED"
    easytier_download_max_time_saved="$DOWNLOAD_MAX_TIME"
    easytier_download_keep_partial_saved="${DOWNLOAD_KEEP_PARTIAL:-0}"
    easytier_download_skip_content_length_saved="${DOWNLOAD_SKIP_CONTENT_LENGTH:-0}"
    DOWNLOAD_MAX_TIME="$EASYTIER_PACKAGE_MAX_TIME"
    DOWNLOAD_STALL_TIME="$EASYTIER_PACKAGE_STALL_TIME"
    DOWNLOAD_STALL_SPEED="$EASYTIER_PACKAGE_STALL_SPEED"
    DOWNLOAD_KEEP_PARTIAL=1
    DOWNLOAD_SKIP_CONTENT_LENGTH=1
    easytier_download_url=""
    if download_from_urls "$easytier_archive" $easytier_package_urls; then
        easytier_download_url="$LAST_DOWNLOAD_SOURCE"
    fi
    if [ -z "$easytier_download_url" ]; then
        log "提示: 首轮下载未完成，正在放宽速度阈值后重试..."
        DOWNLOAD_STALL_TIME="$EASYTIER_PACKAGE_RETRY_STALL_TIME"
        DOWNLOAD_STALL_SPEED="$EASYTIER_PACKAGE_RETRY_STALL_SPEED"
        if download_from_urls "$easytier_archive" $easytier_package_urls; then
            easytier_download_url="$LAST_DOWNLOAD_SOURCE"
        fi
    fi
    DOWNLOAD_MAX_TIME="$easytier_download_max_time_saved"
    DOWNLOAD_STALL_TIME="$easytier_download_stall_time_saved"
    DOWNLOAD_STALL_SPEED="$easytier_download_stall_speed_saved"
    DOWNLOAD_KEEP_PARTIAL="$easytier_download_keep_partial_saved"
    DOWNLOAD_SKIP_CONTENT_LENGTH="$easytier_download_skip_content_length_saved"
    [ -n "$easytier_download_url" ] || die "无法从可用的 GitHub 地址下载 $EASYTIER_DISPLAY_NAME 官方安装包"
    [ -s "$easytier_archive" ] || die "$EASYTIER_DISPLAY_NAME 官方安装包下载失败"
    easytier_download_host="$(extract_url_host "$easytier_download_url" 2>/dev/null || true)"
    easytier_download_size="$(wc -c < "$easytier_archive" | tr -d ' ')"

    log_stage 3 5 "解压安装 $EASYTIER_DISPLAY_NAME 并修正 LuCI 控制器"
    ensure_opkg_update || die "opkg update 失败，已停止 $EASYTIER_DISPLAY_NAME 安装"
    ensure_packages kmod-tun unzip || die "$EASYTIER_DISPLAY_NAME 依赖安装失败：kmod-tun/unzip"
    extract_easytier_release_bundle "$easytier_archive" "$easytier_unpack"
    for candidate in \
        "$easytier_unpack"/easytier_"$EASYTIER_VERSION"_"$EASYTIER_PACKAGE_ARCH".ipk \
        "$easytier_unpack"/*/easytier_"$EASYTIER_VERSION"_"$EASYTIER_PACKAGE_ARCH".ipk \
        "$easytier_unpack"/*/*/easytier_"$EASYTIER_VERSION"_"$EASYTIER_PACKAGE_ARCH".ipk
    do
        [ -f "$candidate" ] || continue
        easytier_core_ipk="$candidate"
        break
    done
    for candidate in \
        "$easytier_unpack"/luci-app-easytier_"$EASYTIER_VERSION"_all.ipk \
        "$easytier_unpack"/*/luci-app-easytier_"$EASYTIER_VERSION"_all.ipk \
        "$easytier_unpack"/*/*/luci-app-easytier_"$EASYTIER_VERSION"_all.ipk
    do
        [ -f "$candidate" ] || continue
        easytier_luci_ipk="$candidate"
        break
    done
    for candidate in \
        "$easytier_unpack"/luci-i18n-easytier-zh-cn*_all.ipk \
        "$easytier_unpack"/*/luci-i18n-easytier-zh-cn*_all.ipk \
        "$easytier_unpack"/*/*/luci-i18n-easytier-zh-cn*_all.ipk
    do
        [ -f "$candidate" ] || continue
        easytier_i18n_ipk="$candidate"
        break
    done
    [ -n "$easytier_core_ipk" ] || die "解压后未找到 $EASYTIER_DISPLAY_NAME 核心安装包"
    [ -n "$easytier_luci_ipk" ] || die "解压后未找到 $EASYTIER_DISPLAY_NAME LuCI 安装包"
    log "提示: $EASYTIER_DISPLAY_NAME LuCI 官方包依赖 luci-compat，当前会自动重打包并以本地包无依赖方式安装"
    easytier_luci_fixed_ipk="$WORKDIR/easytier/luci-app-easytier_${EASYTIER_VERSION}_oem.ipk"
    repack_ipk_control "$easytier_luci_ipk" "$easytier_luci_fixed_ipk" "all" "libc, kmod-tun"
    install_ipk_file "$easytier_core_ipk" "$EASYTIER_DISPLAY_NAME 核心"
    install_ipk_file_force_flags_verify "$easytier_luci_fixed_ipk" "$EASYTIER_DISPLAY_NAME LuCI" "$EASYTIER_LUCI_PACKAGE_NAME" "$EASYTIER_CONTROLLER" --nodeps
    if [ -n "$easytier_i18n_ipk" ]; then
        install_ipk_file_force_flags_verify "$easytier_i18n_ipk" "$EASYTIER_DISPLAY_NAME 中文语言包" "$EASYTIER_I18N_PACKAGE_NAME" "/usr/lib/lua/luci/i18n/easytier.zh-cn.lmo" --nodeps --force-overwrite
    else
        log "备注: 未找到 $EASYTIER_DISPLAY_NAME 中文语言包，继续安装"
    fi
    ensure_easytier_config_defaults
    write_easytier_controller_file
    write_easytier_polish_files

    log_stage 4 5 "写入图标、应用商店并接入 EasyTier 打开入口"
    backup_file "$CFG"
    cleanup_appcenter_entry "$EASYTIER_DISPLAY_NAME" "$EASYTIER_PACKAGE_NAME" "$EASYTIER_ROUTE"
    cleanup_appcenter_entry "$EASYTIER_DISPLAY_NAME" "$EASYTIER_LUCI_PACKAGE_NAME" "$EASYTIER_ROUTE"
    cleanup_appcenter_entry "$EASYTIER_PACKAGE_NAME" "$EASYTIER_PACKAGE_NAME" "$EASYTIER_ROUTE"
    cleanup_appcenter_entry "$EASYTIER_LUCI_PACKAGE_NAME" "$EASYTIER_LUCI_PACKAGE_NAME" "$EASYTIER_ROUTE"
    cleanup_appcenter_entry "$EASYTIER_I18N_PACKAGE_NAME" "$EASYTIER_I18N_PACKAGE_NAME" "$EASYTIER_ROUTE"
    easytier_icon_name=""
    if install_easytier_embedded_icon; then
        easytier_icon_name="$EASYTIER_ICON_NAME"
    fi
    easytier_installed_ver="$(get_installed_package_version "$EASYTIER_PACKAGE_NAME" 2>/dev/null || true)"
    [ -n "$easytier_installed_ver" ] || easytier_installed_ver="$EASYTIER_VERSION"
    set_appcenter_entry "$EASYTIER_DISPLAY_NAME" "$EASYTIER_LUCI_PACKAGE_NAME" "$easytier_installed_ver" "$easytier_download_size" "$EASYTIER_CONTROLLER" "$EASYTIER_ROUTE" "$easytier_icon_name"
    easytier_pkg_sec="$(find_uci_section package "$EASYTIER_DISPLAY_NAME")"
    [ -n "$easytier_pkg_sec" ] && uci -q set "appcenter.$easytier_pkg_sec.open=1" >/dev/null 2>&1 || true
    uci commit appcenter
    write_plugin_uninstall_assets
    patch_common_template
    refresh_luci_appcenter
    /etc/init.d/uhttpd reload >/dev/null 2>&1 || true

    log_stage 5 5 "写入虚拟内存并校验 EasyTier 页面与应用商店入口"
    ensure_existing_swap_access "$EASYTIER_DISPLAY_NAME"
    verify_appcenter_route "$EASYTIER_DISPLAY_NAME" "$EASYTIER_ROUTE"
    verify_file_exists /usr/bin/easytier-core "$EASYTIER_DISPLAY_NAME"
    verify_file_exists /usr/bin/easytier-cli "$EASYTIER_DISPLAY_NAME"
    verify_file_exists /usr/bin/easytier-web "$EASYTIER_DISPLAY_NAME"
    verify_file_exists /etc/config/easytier "$EASYTIER_DISPLAY_NAME"
    verify_file_exists /etc/init.d/easytier "$EASYTIER_DISPLAY_NAME"
    verify_file_exists "$EASYTIER_CONTROLLER" "$EASYTIER_DISPLAY_NAME"
    verify_file_exists /usr/lib/lua/luci/model/cbi/easytier.lua "$EASYTIER_DISPLAY_NAME"
    verify_file_exists /usr/lib/lua/luci/view/easytier/easytier_status.htm "$EASYTIER_DISPLAY_NAME"
    verify_file_exists /usr/lib/lua/luci/view/easytier/nradio_polish.htm "$EASYTIER_DISPLAY_NAME 页面美化"
    verify_luci_route "$EASYTIER_ROUTE" "$EASYTIER_DISPLAY_NAME"

    log "安装完成"
    log "插件:   $EASYTIER_DISPLAY_NAME"
    log "版本:   $easytier_installed_ver"
    log "路由:   $EASYTIER_ROUTE"
    if [ -n "$easytier_download_host" ]; then
        log "下载源: GitHub 官方 CDN（$easytier_download_host）"
    else
        log "下载源: GitHub 官方 CDN"
    fi
    log "说明:   如页面未立即刷新，请关闭应用商店弹窗后按 Ctrl+F5 再重新打开 $EASYTIER_DISPLAY_NAME"
}

write_fanctrl_plugin_files() {
    fanctrl_model="${1:-}"
    fanctrl_polish_view="$FANCTRL_VIEW_DIR/polish.htm"
    fanctrl_tempsource='max'
    fanctrl_interval='12'
    fanctrl_smartmin='30'
    fanctrl_smarttemp_low='50'
    fanctrl_smarttemp_mid='60'
    fanctrl_smarttemp_high='70'
    fanctrl_smarttemp_full='80'
    fanctrl_protecttemp='85'
    fanctrl_legacy_mode=''

    case "$fanctrl_model" in
        NRadio_C8-688)
            fanctrl_tempsource='cpu'
            fanctrl_interval='10'
            fanctrl_smartmin='50'
            fanctrl_protecttemp='85'
            ;;
        NRadio_C2000MAX)
            fanctrl_tempsource='max'
            fanctrl_interval='5'
            fanctrl_smartmin='30'
            fanctrl_protecttemp='80'
            ;;
        NRadio_C8-788)
            fanctrl_tempsource='cpu'
            fanctrl_interval='12'
            fanctrl_smartmin='0'
            fanctrl_smarttemp_low='65'
            fanctrl_smarttemp_mid='75'
            fanctrl_smarttemp_high='80'
            fanctrl_smarttemp_full='85'
            fanctrl_protecttemp='85'
            if [ -s "$FANCTRL_CONFIG_FILE" ] && ! uci -q get fanctrl.fanctrl.tempsource >/dev/null 2>&1; then
                fanctrl_legacy_mode="$(uci -q get fanctrl.fanctrl.mode 2>/dev/null || true)"
            fi
            ;;
    esac

    mkdir -p \
        "$(dirname "$FANCTRL_CONTROLLER")" \
        "$(dirname "$FANCTRL_CBI")" \
        "$FANCTRL_VIEW_DIR"
    backup_file "$FANCTRL_CONTROLLER"
    backup_file "$FANCTRL_CBI"
    backup_file "$FANCTRL_TEMP_AJAX_VIEW"
    backup_file "$FANCTRL_TEMP_VIEW"
    backup_file "$fanctrl_polish_view"
    backup_file "$FANCTRL_BIN_PATH"
    backup_file "$FANCTRL_INIT_FILE"
    backup_file "$FANCTRL_CONFIG_FILE"

    # Overlay the limited ROM controller so the dashboard can read the full runtime state.
    cat > "$FANCTRL_CONTROLLER" <<'EOF_FANCTRL_CONTROLLER'
module("luci.controller.nradio_adv.fanctrl", package.seeall)

function index()
    if not nixio.fs.access("/etc/config/fanctrl") then
        return
    end

    local page = entry({"nradioadv", "system", "fanctrl"}, cbi("nradio_adv/fanctrl"), _("FanControl"), 90, true)
    page.show = true
    page.icon = 'nradio-fanctrl'
    entry({"nradioadv", "system", "fanctrl", "temperature"}, call("action_get_temperature"), nil, nil, true).leaf = true
end

local function mode_label(mode)
    if mode == "0" then
        return "关闭"
    elseif mode == "1" then
        return "低速"
    elseif mode == "2" then
        return "中速"
    elseif mode == "3" then
        return "高速"
    end
    return "Smart 智能温控"
end

local function read_int_file(path, divisor)
    local fs = require "nixio.fs"
    local raw = fs.readfile(path) or ""
    local num = tonumber((raw:gsub("%s+", "")) or "") or 0
    if divisor and divisor > 1 and num > 0 then
        num = math.floor(num / divisor)
    end
    return num
end

local function read_cpe_temp()
    local sys = require "luci.sys"
    local raw = sys.exec("/etc/cpetools/quectel.sh -c temp 2>/dev/null") or ""
    return tonumber((raw:gsub("%s+", "")) or "") or 0
end

local function choose_temp(source, cpu_temp, cpe_temp)
    if source == "cpu" then
        return cpu_temp
    elseif source == "cpe" then
        if cpe_temp > 0 then
            return cpe_temp
        end
        return cpu_temp
    end

    if cpe_temp > cpu_temp then
        return cpe_temp
    end
    return cpu_temp
end

local function temp_source_label(source)
    if source == "cpu" then
        return "CPU"
    elseif source == "cpe" then
        return "CPE"
    end
    return "CPU/CPE 取高值"
end

local function valid_hhmm(value)
    if type(value) ~= "string" then
        return false
    end

    local hour, minute = value:match("^(%d%d):(%d%d)$")
    hour = tonumber(hour or "")
    minute = tonumber(minute or "")
    return hour ~= nil and minute ~= nil and hour >= 0 and hour <= 23 and minute >= 0 and minute <= 59
end

local function hhmm_minutes(value)
    local hour, minute = value:match("^(%d%d):(%d%d)$")
    return (tonumber(hour) or 0) * 60 + (tonumber(minute) or 0)
end

local function system_time_reliable()
    return (tonumber(os.date("%Y") or "0") or 0) >= 2024
end

local function schedule_active(start_value, end_value)
    if not system_time_reliable() or not valid_hhmm(start_value) or not valid_hhmm(end_value) then
        return false
    end

    local now = (tonumber(os.date("%H") or "0") or 0) * 60 + (tonumber(os.date("%M") or "0") or 0)
    local start_min = hhmm_minutes(start_value)
    local end_min = hhmm_minutes(end_value)

    if start_min == end_min then
        return false
    elseif start_min < end_min then
        return now >= start_min and now < end_min
    end

    return now >= start_min or now < end_min
end

local function pwm_to_percent(pwm_num)
    if pwm_num >= 255 then
        return "100"
    elseif pwm_num >= 204 then
        return "80"
    elseif pwm_num >= 127 then
        return "50"
    elseif pwm_num >= 76 then
        return "30"
    end
    return "0"
end

function action_get_temperature()
    local fs = require "nixio.fs"
    local data = {}
    local uci = require "luci.model.uci".cursor()

    data.mode = uci:get("fanctrl", "fanctrl", "mode") or "4"
    data.config_mode = data.mode
    data.enabled = uci:get("fanctrl", "fanctrl", "enabled") or "0"
    data.temp_source = uci:get("fanctrl", "fanctrl", "tempsource") or "max"
    data.temp_source_label = temp_source_label(data.temp_source)
    data.interval = uci:get("fanctrl", "fanctrl", "interval") or "12"
    data.protecttemp = uci:get("fanctrl", "fanctrl", "protecttemp") or "85"
    data.schedule_enabled = uci:get("fanctrl", "fanctrl", "schedule_enabled") or "0"
    data.schedule_start = uci:get("fanctrl", "fanctrl", "schedule_start") or "23:00"
    data.schedule_end = uci:get("fanctrl", "fanctrl", "schedule_end") or "07:00"
    data.schedule_mode = uci:get("fanctrl", "fanctrl", "schedule_mode") or "1"
    data.schedule_active = "0"

    if data.schedule_mode ~= "0" and data.schedule_mode ~= "1" and data.schedule_mode ~= "2" and data.schedule_mode ~= "3" and data.schedule_mode ~= "4" then
        data.schedule_mode = "1"
    end

    if data.enabled == "1" and data.schedule_enabled == "1" and schedule_active(data.schedule_start, data.schedule_end) then
        data.schedule_active = "1"
        data.mode = data.schedule_mode
        data.mode_label = "定时 " .. mode_label(data.mode)
    else
        data.mode_label = mode_label(data.mode)
    end

    local pwm_raw = fs.readfile("/sys/devices/platform/pwm-fan/hwmon/hwmon0/pwm1") or ""
    local gpio_raw = fs.readfile("/sys/class/gpio/fan-hw/value") or ""
    local cpu_temp = read_int_file("/sys/class/thermal/thermal_zone0/temp", 1000)
    local cpe_temp = read_cpe_temp()
    local temp_num = choose_temp(data.temp_source, cpu_temp, cpe_temp)
    local pwm_num = tonumber((pwm_raw:gsub("%s+", "")) or "") or 0

    if temp_num > 0 then
        data.temp = tostring(temp_num)
    else
        data.temp = ""
    end

    data.cpu_temp = cpu_temp > 0 and tostring(cpu_temp) or ""
    data.cpe_temp = cpe_temp > 0 and tostring(cpe_temp) or ""
    data.pwm = pwm_num > 0 and tostring(pwm_num) or "0"
    data.gpio = (gpio_raw:gsub("%s+", "")) or ""
    data.fan = pwm_to_percent(pwm_num)
    data.protect_active = (data.enabled == "1" and temp_num >= (tonumber(data.protecttemp) or 85) and data.fan == "100") and "1" or "0"
    if data.protect_active == "1" then data.mode_label = "过热保护" end

    luci.nradio.luci_call_result(data)
end
EOF_FANCTRL_CONTROLLER

    # Overlay the ROM CBI: MAX firmware comments out every control except the master switch.
    cat > "$FANCTRL_CBI" <<'EOF_FANCTRL_CBI'
m = Map("fanctrl", translate("FanSetting"))

s = m:section(NamedSection, "fanctrl", "service")

local function validate_hhmm(self, value)
    if not value or not value:match("^%d%d:%d%d$") then
        return nil, translate("请输入 HH:MM 格式")
    end

    local hour = tonumber(value:sub(1, 2))
    local minute = tonumber(value:sub(4, 5))
    if not hour or not minute or hour > 23 or minute > 59 then
        return nil, translate("请输入 00:00 到 23:59 之间的时间")
    end

    return value
end

enabled = s:option(Flag, "enabled", translate("风扇总开关"))
enabled.rmempty = false
enabled.description = translate("关闭后立即停止风扇；过热保护仅在总开关开启时生效。")

tempdes = s:option(DummyValue, "tempdes", " ")
tempdes.template = "nradio_fanctrl/temperature_ajax"

tempdesdevice = s:option(DummyValue, "tempdesdevice", translate("实时温度"))
tempdesdevice.template = "nradio_fanctrl/temperature"

fandesdevice = s:option(DummyValue, "fandesdevice", translate("实时风速"))
fandesdevice.template = "nradio_fanctrl/temperature"

mode = s:option(ListValue, "mode", translate("运行模式"))
mode:value("0", translate("关闭"))
mode:value("1", translate("低速 30%"))
mode:value("2", translate("中速 50%"))
mode:value("3", translate("高速 80%"))
mode:value("4", translate("Smart 智能温控"))
mode.default = "4"
mode:depends("enabled", "1")
mode.description = translate("Smart 会根据温度曲线自动调速；过热保护优先于所有模式。")

tempsource = s:option(ListValue, "tempsource", translate("温度来源"))
tempsource:value("max", translate("CPU/CPE 取高值"))
tempsource:value("cpu", translate("CPU"))
tempsource:value("cpe", translate("CPE"))
tempsource.default = "max"
tempsource:depends("enabled", "1")
tempsource.description = translate("存在 CPE 温度时可取高值；无 CPE 温度时自动使用 CPU 温度。")

smartmin = s:option(ListValue, "smartmin", translate("Smart 最低风速"))
smartmin:value("0", translate("关闭"))
smartmin:value("30", translate("30%"))
smartmin:value("50", translate("50%"))
smartmin.default = "30"
smartmin:depends({ enabled = "1", mode = "4" })
smartmin.description = translate("低于首个温度阈值时维持的最低风速。")

smarttemp_low = s:option(Value, "smarttemp_low", translate("Smart 30% 温度"))
smarttemp_low.default = "50"
smarttemp_low.datatype = "range(20,100)"
smarttemp_low:depends({ enabled = "1", mode = "4" })

smarttemp_mid = s:option(Value, "smarttemp_mid", translate("Smart 50% 温度"))
smarttemp_mid.default = "60"
smarttemp_mid.datatype = "range(20,105)"
smarttemp_mid:depends({ enabled = "1", mode = "4" })

smarttemp_high = s:option(Value, "smarttemp_high", translate("Smart 80% 温度"))
smarttemp_high.default = "70"
smarttemp_high.datatype = "range(20,110)"
smarttemp_high:depends({ enabled = "1", mode = "4" })

smarttemp_full = s:option(Value, "smarttemp_full", translate("Smart 100% 温度"))
smarttemp_full.default = "80"
smarttemp_full.datatype = "range(20,115)"
smarttemp_full:depends({ enabled = "1", mode = "4" })

protecttemp = s:option(Value, "protecttemp", translate("过热保护温度"))
protecttemp.default = "85"
protecttemp.datatype = "range(40,120)"
protecttemp:depends("enabled", "1")
protecttemp.description = translate("达到该温度后立即强制 100% 风速，优先于定时与手动模式。")

interval = s:option(ListValue, "interval", translate("检测间隔"))
interval:value("5", translate("5s"))
interval:value("10", translate("10s"))
interval:value("12", translate("12s"))
interval:value("15", translate("15s"))
interval:value("30", translate("30s"))
interval.default = "12"
interval:depends("enabled", "1")
interval.description = translate("检测越频繁，风扇响应越快。")

schedule_enabled = s:option(Flag, "schedule_enabled", translate("定时策略"))
schedule_enabled.rmempty = false
schedule_enabled.default = "0"
schedule_enabled.description = translate("开启后，设定时间段内临时使用定时模式；过热保护仍优先。")
schedule_enabled:depends("enabled", "1")

schedule_start = s:option(Value, "schedule_start", translate("开始时间"))
schedule_start.default = "23:00"
schedule_start.placeholder = "23:00"
schedule_start.validate = validate_hhmm
schedule_start:depends({ enabled = "1", schedule_enabled = "1" })

schedule_end = s:option(Value, "schedule_end", translate("结束时间"))
schedule_end.default = "07:00"
schedule_end.placeholder = "07:00"
schedule_end.validate = validate_hhmm
schedule_end:depends({ enabled = "1", schedule_enabled = "1" })

schedule_mode = s:option(ListValue, "schedule_mode", translate("定时期间风扇模式"))
schedule_mode:value("0", translate("关闭"))
schedule_mode:value("1", translate("低速 30%"))
