    cat > /usr/lib/lua/luci/view/nradio_adv/openvpn_full.htm <<'EOF_OPENVPN_FULL_VIEW'
<%+header%>
<%
local dispatcher = require "luci.dispatcher"
local util = require "luci.util"
local function esc(s) return luci.util.pcdata(s or "") end
local current = require("luci.controller.nradio_adv.openvpn_full").current_profile()
local cfg = current.copyable and current.content or ""
local cfg_path = current.config or ""
local cfg_label = current.uci_profile and ("UCI · " .. current.label) or (current.source_config or current.config or "配置未读取")
%>

<%+openvpn/ovpn_css%>

<%+openvpn/navigation%>
<div class="vpn-shell vpn-shell-refined vpn-shell-mk5 is-loading">
  <div class="vpn-statusbar">
    <div class="vpn-toolbar">
      <span id="vpn-health-chip" class="vpn-health-chip">读取状态中</span>
      <span id="vpn-live-ts" class="vpn-inline-note">更新中</span>
      <span id="vpn-instance-label" class="vpn-inline-note"><%=esc(current.label)%></span>
    </div>
    <div class="vpn-actions">
          <form id="vpn-primary-form" method="post" action="#">
            <input id="vpn-primary-instance" type="hidden" name="instance" value="<%=esc(current.instance)%>" />
            <input type="hidden" name="token" value="<%=dispatcher.context.authtoken%>" />
            <input id="vpn-primary-button" class="cbi-button vpn-button-muted" type="submit" value="读取状态中" disabled="disabled" />
          </form>
          <form id="vpn-stop-form" method="post" action="<%=dispatcher.build_url('nradioadv','system','openvpnfull','stop')%>" style="display:none">
            <input id="vpn-stop-instance" type="hidden" name="instance" value="<%=esc(current.instance)%>" />
            <input type="hidden" name="token" value="<%=dispatcher.context.authtoken%>" />
            <input id="vpn-stop-button" class="cbi-button vpn-button-muted" type="submit" value="停止 OpenVPN" />
          </form>
          <button id="vpn-refresh-button" class="cbi-button vpn-button-muted" type="button">刷新状态</button>

    </div>
  </div>
  <p id="vpn-action-hint" class="vpn-note">正在读取连接与配置状态。</p>

  <section data-vpn-view="overview" aria-label="连接概览">
    <div class="vpn-stat-grid">
      <div class="vpn-stat-card">
        <span class="vpn-stat-label">服务状态</span>
        <strong id="vpn-runtime-service" class="vpn-stat-value">-</strong>
        <span id="vpn-runtime-managed" class="vpn-stat-meta">正在读取</span>
      </div>
      <div class="vpn-stat-card">
        <span class="vpn-stat-label">隧道 IP</span>
        <strong id="vpn-stat-tun-ip" class="vpn-stat-value">-</strong>
        <span id="vpn-stat-tun-meta" class="vpn-stat-meta">隧道地址</span>
      </div>
      <div class="vpn-stat-card">
        <span class="vpn-stat-label">配置远端</span>
        <strong id="vpn-stat-remote" class="vpn-stat-value">-</strong>
        <span id="vpn-stat-remote-meta" class="vpn-stat-meta">协议与端口</span>
      </div>
      <div class="vpn-stat-card">
        <span class="vpn-stat-label">在线目标</span>
        <strong id="vpn-stat-health-ratio" class="vpn-stat-value">-</strong>
        <span id="vpn-stat-health-meta" class="vpn-stat-meta">目标探测中</span>
      </div>
    </div>
    <details class="vpn-details">
      <summary>运行与认证详情</summary>
      <div class="vpn-overview-grid">
    <article id="vpn-runtime-card" class="vpn-card vpn-card-runtime">
      <div class="vpn-card-head">
        <div class="vpn-card-title">运行与启动</div>
        <span id="vpn-runtime-badge" class="vpn-card-badge vpn-badge-bad">等待更新</span>
      </div>
      <div class="vpn-kv"><span>可用操作</span><strong id="vpn-runtime-action">-</strong></div>
      <div class="vpn-kv"><span>启动方式</span><strong id="vpn-runtime-mode">-</strong></div>
      <div class="vpn-kv"><span>连接日志</span><strong id="vpn-runtime-log-state" class="vpn-inline-badge vpn-badge-neutral">等待更新</strong></div>
      <div class="vpn-kv"><span>进程状态</span><strong id="vpn-runtime-process">-</strong></div>
      <div id="vpn-runtime-note" class="vpn-card-note">断开后如条件满足，可直接从当前页启动或接管启动。</div>
    </article>
    <article id="vpn-auth-card" class="vpn-card vpn-card-auth">
      <div class="vpn-card-head">
        <div class="vpn-card-title">认证与准备</div>
        <span id="vpn-auth-badge" class="vpn-card-badge vpn-badge-neutral">等待更新</span>
      </div>
      <div class="vpn-kv"><span>账号认证</span><strong id="vpn-auth-userpass">-</strong></div>
      <div class="vpn-kv"><span>认证要求</span><strong id="vpn-auth-requirement">-</strong></div>
      <div class="vpn-kv"><span>证书材料</span><strong id="vpn-auth-cert-material">-</strong></div>
      <div class="vpn-kv"><span>启动条件</span><strong id="vpn-auth-ready">-</strong></div>
      <div class="vpn-kv"><span>TLS 密钥</span><strong id="vpn-auth-tls">-</strong></div>
      <div id="vpn-auth-note" class="vpn-card-note">配置文件和认证材料齐全后，当前页才能直接启动。</div>
    </article>
      </div>
    </details>
    <details class="vpn-details">
      <summary>当前客户端配置</summary>
      <div class="vpn-panel-head">
        <span id="vpn-config-path" data-profile-path="<%=esc(cfg_path)%>"><%=esc(cfg_label)%></span>
        <div class="vpn-actions">
          <button id="vpn-copy-button" class="cbi-button" type="button" aria-disabled="true">复制配置</button>
          <span id="vpn-copy-feedback" class="vpn-copy-feedback" aria-live="polite"></span>
        </div>
      </div>
      <textarea id="vpn-config-copy-source" class="vpn-copy-source" aria-label="待复制配置" tabindex="-1"><%=esc(cfg ~= "" and cfg or "no config")%></textarea>
      <pre id="vpn-config-pre"><%=esc(cfg ~= "" and cfg or "暂无客户端配置")%></pre>
    </details>
  </section>

  <section data-vpn-view="routes" aria-label="路由与映射" hidden>
    <article id="vpn-route-card" class="vpn-card vpn-card-route">
      <div class="vpn-card-head">
        <div class="vpn-card-title">路由与映射</div>
        <span id="vpn-route-badge" class="vpn-card-badge vpn-badge-neutral">等待更新</span>
      </div>
      <div class="vpn-kv"><span>远端目标</span><strong id="vpn-route-count">-</strong></div>
      <div class="vpn-kv"><span>远端在线</span><strong id="vpn-peer-count">-</strong></div>
      <div class="vpn-kv"><span>规则状态</span><strong id="vpn-route-ratio">-</strong></div>
      <div class="vpn-kv"><span>本地映射目标</span><strong id="vpn-map-ip">-</strong></div>
      <div class="vpn-kv"><span>映射规则</span><strong id="vpn-dnat-status" class="vpn-inline-badge vpn-badge-neutral">等待更新</strong></div>
      <div id="vpn-route-note" class="vpn-card-note">各目标的路由、转发与在线状态见下方。</div>
    </article>
    <div id="vpn-route-panel" class="vpn-route-detail">
      <div class="vpn-panel-head">
        <h3>目标检查</h3>
        <span id="vpn-route-meta">基于当前内核状态与目标探测的实时结果。优先看离线和缺规则项。</span>
      </div>
      <div class="vpn-focus-strip vpn-focus-strip-route">
        <span id="vpn-route-strip-count" class="vpn-focus-pill">目标数: -</span>
        <span id="vpn-route-strip-health" class="vpn-focus-pill vpn-focus-pill-muted">规则健康: -</span>
        <span id="vpn-route-strip-dnat" class="vpn-focus-pill vpn-focus-pill-muted">映射: -</span>
      </div>
      <div class="vpn-split-grid">
        <div class="vpn-subcard vpn-subcard-route-targets">
          <div class="vpn-subcard-title">远端目标</div>
          <div id="vpn-route-check-list" class="vpn-check-list">
            <div class="vpn-check-empty">等待更新</div>
          </div>
        </div>

        <div class="vpn-subcard vpn-subcard-route-map">
          <div class="vpn-subcard-title">本地映射</div>
          <div id="vpn-nat-check-list" class="vpn-check-list">
            <div class="vpn-check-empty">等待更新</div>
          </div>
        </div>
      </div>
    </div>
    <details class="vpn-details">
      <summary>隧道与 LAN 接口</summary>
    <div id="vpn-tun-panel" class="vpn-tunnel-detail">
      <div class="vpn-panel-head">
        <h3>隧道信息</h3>
        <span id="vpn-tun-meta">展示 VPN 与 LAN 接口的当前地址信息。</span>
      </div>
      <div class="vpn-split-grid">
        <div class="vpn-subcard vpn-subcard-tun">
          <div id="vpn-tun-title" class="vpn-subcard-title">tun0</div>
          <pre id="vpn-tun-pre">等待更新</pre>
        </div>
        <div class="vpn-subcard vpn-subcard-lan">
          <div id="vpn-lan-title" class="vpn-subcard-title">br-lan</div>
          <pre id="vpn-lan-pre">等待更新</pre>
        </div>
      </div>
    </div>
    </details>
  </section>

  <section data-vpn-view="logs" aria-label="运行日志" hidden>
    <div class="vpn-log-section">
      <div class="vpn-tabbar" role="tablist" aria-label="日志类型">
        <button class="vpn-tab-btn is-active" type="button" data-target="vpn-focus-panel" role="tab" aria-selected="true" aria-controls="vpn-focus-panel">关键日志</button>
        <button class="vpn-tab-btn" type="button" data-target="vpn-runtime-panel" role="tab" aria-selected="false" aria-controls="vpn-runtime-panel">完整日志</button>
      </div>
    <div id="vpn-focus-panel" class="vpn-panel vpn-panel-major vpn-panel-focus is-active" role="tabpanel" aria-hidden="false">
      <div class="vpn-panel-head">
        <h3>关键日志</h3>
        <span id="vpn-focus-meta">优先展示连接、认证、路由相关行。</span>
      </div>
      <div class="vpn-focus-strip">
        <span class="vpn-focus-pill">优先项: TLS / AUTH / tun0</span>
        <span id="vpn-log-event" class="vpn-focus-pill">正在分类日志事件</span>
        <span id="vpn-focus-ts" class="vpn-focus-pill vpn-focus-pill-muted">等待更新</span>
      </div>
      <pre id="vpn-focus-log">等待更新</pre>
    </div>
    <div id="vpn-runtime-panel" class="vpn-panel vpn-panel-runtime" role="tabpanel" aria-hidden="true">
      <div class="vpn-panel-head">
        <h3>运行日志</h3>
        <span id="vpn-runtime-meta">完整日志更适合排查重连、认证和 TLS 问题。</span>
      </div>
      <pre id="vpn-runtime-log">等待更新</pre>
    </div>
    </div>
  </section>
</div>

<script>
(function() {
  var views = document.querySelectorAll('[data-vpn-view]');
  var links = document.querySelectorAll('[data-vpn-nav]');
  function showView() {
    var name = window.location.hash.slice(1);
    if (name !== 'routes' && name !== 'logs') name = 'overview';
    for (var i = 0; i < views.length; i++) {
      views[i].hidden = views[i].getAttribute('data-vpn-view') !== name;
    }
    for (var j = 0; j < links.length; j++) {
      if (links[j].getAttribute('data-vpn-nav') === name) links[j].setAttribute('aria-current', 'page');
      else links[j].removeAttribute('aria-current');
    }
  }
  window.addEventListener('hashchange', showView);
  showView();
})();

function vpnCopyConfig() {
  var copyButton = document.getElementById('vpn-copy-button');
  if (copyButton && copyButton.getAttribute('aria-disabled') === 'true') {
    if (window.vpnShowCopyFeedback) {
      window.vpnShowCopyFeedback('当前没有可复制的配置，请刷新页面确认配置来源。', 'warn');
    }
    return false;
  }
  var source = document.getElementById('vpn-config-copy-source');
  if (!source || !source.value || source.value === 'no config') {
    if (window.vpnShowCopyFeedback) {
      window.vpnShowCopyFeedback('当前没有可复制的配置。', 'warn');
    }
    return false;
  }
  source.style.display = 'block';
  source.select();
  source.setSelectionRange(0, source.value.length);
  try {
    if (navigator.clipboard && navigator.clipboard.writeText) {
      navigator.clipboard.writeText(source.value).then(function() {
        if (window.vpnShowCopyFeedback) {
          window.vpnShowCopyFeedback('已复制当前实例配置', 'ok');
        }
      }).catch(function() {
        document.execCommand('copy');
        if (window.vpnShowCopyFeedback) {
          window.vpnShowCopyFeedback('已复制当前实例配置', 'ok');
        }
      });
    } else {
      document.execCommand('copy');
      if (window.vpnShowCopyFeedback) {
        window.vpnShowCopyFeedback('已复制当前实例配置', 'ok');
      }
    }
  } catch (e) {
    if (window.vpnShowCopyFeedback) {
      window.vpnShowCopyFeedback('浏览器限制，已切到手动复制', 'warn');
    }
    window.prompt('复制配置', source.value);
  }
  source.blur();
  source.style.display = 'none';
  return false;
}

(function() {
  var buttons = document.querySelectorAll('.vpn-tab-btn');
  var panels = document.querySelectorAll('.vpn-panel');

  function activate(targetId) {
    for (var i = 0; i < buttons.length; i++) {
      buttons[i].className = buttons[i].className.replace(/\bis-active\b/g, '').replace(/\s+/g, ' ').replace(/^\s|\s$/g, '');
      buttons[i].setAttribute('aria-selected', 'false');
      if (buttons[i].getAttribute('data-target') === targetId) {
        buttons[i].className += (buttons[i].className ? ' ' : '') + 'is-active';
        buttons[i].setAttribute('aria-selected', 'true');
        buttons[i].setAttribute('tabindex', '0');
      } else {
        buttons[i].setAttribute('tabindex', '-1');
      }
    }
    for (var j = 0; j < panels.length; j++) {
      panels[j].className = panels[j].className.replace(/\bis-active\b/g, '').replace(/\s+/g, ' ').replace(/^\s|\s$/g, '');
      panels[j].setAttribute('aria-hidden', 'true');
      if (panels[j].id === targetId) {
        panels[j].className += (panels[j].className ? ' ' : '') + 'is-active';
        panels[j].setAttribute('aria-hidden', 'false');
      }
    }
  }

  for (var i = 0; i < buttons.length; i++) {
    buttons[i].setAttribute('tabindex', buttons[i].className.indexOf('is-active') >= 0 ? '0' : '-1');
    buttons[i].onclick = function() {
      activate(this.getAttribute('data-target'));
      return false;
    };
    buttons[i].onkeydown = function(ev) {
      ev = ev || window.event;
      var key = ev.key || ev.keyCode;
      if (key !== 'ArrowLeft' && key !== 'ArrowRight' && key !== 37 && key !== 39) {
        return;
      }
      var current = 0;
      for (var j = 0; j < buttons.length; j++) {
        if (buttons[j] === this) {
          current = j;
          break;
        }
      }
      var next = (key === 'ArrowLeft' || key === 37) ? current - 1 : current + 1;
      if (next < 0) {
        next = buttons.length - 1;
      } else if (next >= buttons.length) {
        next = 0;
      }
      activate(buttons[next].getAttribute('data-target'));
      buttons[next].focus();
      if (ev.preventDefault) {
        ev.preventDefault();
      }
      return false;
    };
  }
})();

(function() {
  var copyFeedbackTimer = 0;

  window.vpnShowCopyFeedback = function(message, state) {
    var el = document.getElementById('vpn-copy-feedback');
    if (!el) {
      return;
    }
    if (copyFeedbackTimer) {
      window.clearTimeout(copyFeedbackTimer);
      copyFeedbackTimer = 0;
    }
    el.className = 'vpn-copy-feedback is-visible' + (state ? (' ' + state) : '');
    el.textContent = message || '';
    copyFeedbackTimer = window.setTimeout(function() {
      el.className = 'vpn-copy-feedback';
      el.textContent = '';
    }, 2200);
  };

  var statusUrl = '<%=dispatcher.build_url("nradioadv","system","openvpnfull","status")%>';
  var restartUrl = '<%=dispatcher.build_url("nradioadv","system","openvpnfull","restart")%>';
  var applyCurrentUrl = '<%=dispatcher.build_url("nradioadv","system","openvpnfull","applycurrent")%>';
  var statusBusy = false;
  var lastGoodStatus = null;
  var pendingManualRefresh = false;
  var deepRefreshTimer = 0;

  function esc(text) {
    return String(text == null ? '' : text)
      .replace(/&/g, '&amp;')
      .replace(/</g, '&lt;')
      .replace(/>/g, '&gt;')
      .replace(/"/g, '&quot;')
      .replace(/'/g, '&#39;');
  }

  function setText(id, text) {
    var el = document.getElementById(id);
    if (el) {
      el.textContent = text == null ? '' : String(text);
    }
  }

  function setHtml(id, html) {
    var el = document.getElementById(id);
    if (el) {
      el.innerHTML = html;
    }
  }

  function setClass(id, className) {
    var el = document.getElementById(id);
    if (el) {
      el.className = className;
    }
  }

  function setVisible(id, visible) {
    var el = document.getElementById(id);
    if (el) {
      el.style.display = visible ? '' : 'none';
    }
  }

  function setShellState(stateClass) {
    var shell = document.querySelector('.vpn-shell-refined');
    if (shell) {
      shell.className = 'vpn-shell vpn-shell-refined vpn-shell-mk5' + (stateClass ? (' ' + stateClass) : '');
    }
  }

  function setCardState(id, stateClass) {
    var el = document.getElementById(id);
    if (el) {
      var baseClass = 'vpn-card';
      if (id === 'vpn-runtime-card') {
        baseClass += ' vpn-card-runtime';
      } else if (id === 'vpn-auth-card') {
        baseClass += ' vpn-card-auth';
      } else if (id === 'vpn-route-card') {
        baseClass += ' vpn-card-route';
      }
      el.className = baseClass + (stateClass ? (' ' + stateClass) : '');
    }
  }

  function renderRemoteValue(remote) {
    var text = String(remote == null ? '' : remote).replace(/^\s+|\s+$/g, '');
    if (!text || text === '-') {
      return '-';
    }

    var parts = text.split(/\s+/);
    if (parts.length >= 2 && /^\d{2,5}$/.test(parts[parts.length - 1])) {
      var port = parts.pop();
      var host = parts.join(' ');
      return '<span class="vpn-remote-host">' + esc(host) + '</span><span class="vpn-remote-port">' + esc(port) + '</span>';
    }

    return '<span class="vpn-remote-host">' + esc(text) + '</span>';
  }

  function renderBadges(items) {
    var html = [];
    for (var i = 0; i < items.length; i++) {
      html.push('<span class="vpn-micro-badge ' + esc(items[i].state || 'neutral') + '">' + esc(items[i].label || '-') + '</span>');
    }
    return html.join('');
  }

  function renderRouteChecks(status) {
    var html = [];
    if (!status.route_checks || !status.route_checks.length) {
      setHtml('vpn-route-check-list', '<div class="vpn-check-empty">当前没有检测到远端目标。</div>');
      return;
    }

    var ordered = status.route_checks.slice().sort(function(a, b) {
      var aKind = a.kind === 'host' ? 1 : 0;
      var bKind = b.kind === 'host' ? 1 : 0;
      if (aKind !== bKind) {
        return aKind - bKind;
      }
      var aDeferred = !!(status.probe_deferred || a.probe_deferred);
      var bDeferred = !!(status.probe_deferred || b.probe_deferred);
      if (aDeferred !== bDeferred) {
        return aDeferred ? 1 : -1;
      }
      if (!aDeferred && !bDeferred && !!a.probe_ok !== !!b.probe_ok) {
        return a.probe_ok ? 1 : -1;
      }
      return String(a.target || '').localeCompare(String(b.target || ''));
    });

    var subnetHtml = [];
    var hostHtml = [];

    for (var i = 0; i < ordered.length; i++) {
      var item = ordered[i];
      var probeDeferred = !!(status.probe_deferred || item.probe_deferred);
      var badges = [
        { label: '内核路由', state: item.route_ok ? 'ok' : 'bad' },
        { label: '主规则', state: item.to_rule_ok ? 'ok' : 'bad' },
        { label: 'LAN规则', state: item.iif_rule_ok ? 'ok' : 'bad' },
        { label: probeDeferred ? '待探测' : (item.probe_ok ? '在线' : '离线'), state: probeDeferred ? 'neutral' : (item.probe_ok ? 'ok' : 'bad') }
      ];

      if (item.proxy_required) {
        badges.push({ label: '代理', state: item.proxy_ok ? 'ok' : 'bad' });
      }
      if (item.nat_required) {
        badges.push({ label: 'NAT', state: item.nat_ok ? 'ok' : 'bad' });
      }
      if (item.forward_required) {
        badges.push({ label: '转发', state: item.forward_ok ? 'ok' : 'bad' });
      }
      if (item.enhanced_required) {
        badges.push({ label: '增强', state: item.enhanced_ok ? 'ok' : 'bad' });
      }

      var rowHtml =
        '<div class="vpn-check-row">' +
          '<div class="vpn-check-main">' +
            '<strong>' + esc(item.target) + '</strong>' +
            '<span>via ' + esc(item.via || '-') + ' · ' + (item.mapped ? (item.kind === 'host' ? '主机映射' : '网段映射') : (item.kind === 'host' ? '主机路由' : '网段路由')) + ' · ' + (probeDeferred ? '探测排队 ' : '探测 ') + esc(item.probe_ip || '-') + '</span>' +
          '</div>' +
          '<div class="vpn-check-badges">' + renderBadges(badges) + '</div>' +
        '</div>';

      if (item.kind === 'host') {
        hostHtml.push(rowHtml);
      } else {
        subnetHtml.push(rowHtml);
      }
    }

    html.push('<div class="vpn-check-section"><div class="vpn-check-section-title">网段路由</div>' + (subnetHtml.length ? subnetHtml.join('') : '<div class="vpn-check-empty">当前没有网段路由。</div>') + '</div>');
    html.push('<div class="vpn-check-section"><div class="vpn-check-section-title">主机映射</div>' + (hostHtml.length ? hostHtml.join('') : '<div class="vpn-check-empty">当前没有主机映射。</div>') + '</div>');
    setHtml('vpn-route-check-list', html.join(''));
  }

  function renderNatChecks(status) {
    var mapEnabled = !!status.map_enabled;
    var mapKindLabel = status.map_label || '映射规则';
    var natHtml =
      '<div class="vpn-check-row">' +
        '<div class="vpn-check-main">' +
          '<strong>本地映射目标</strong>' +
          '<span>' + esc(mapEnabled ? status.map_ip : '未启用映射') + '</span>' +
        '</div>' +
        '<div class="vpn-check-badges">' + renderBadges([{ label: status.map_kind === 'subnet' ? '网段' : '主机', state: mapEnabled ? (status.map_ip_ok ? 'ok' : 'bad') : 'neutral' }]) + '</div>' +
      '</div>' +
      '<div class="vpn-check-row">' +
        '<div class="vpn-check-main">' +
          '<strong>' + esc(mapKindLabel) + '</strong>' +
          '<span>检查 PREROUTING / OUTPUT 两条当前内核规则。</span>' +
        '</div>' +
        '<div class="vpn-check-badges">' + renderBadges([
          { label: '入口', state: mapEnabled ? (status.dnat_pre_ok ? 'ok' : 'bad') : 'neutral' },
          { label: '回环', state: mapEnabled ? (status.dnat_out_ok ? 'ok' : 'bad') : 'neutral' }
        ]) + '</div>' +
      '</div>' +
      '<div class="vpn-check-row">' +
        '<div class="vpn-check-main">' +
          '<strong>MASQUERADE</strong>' +
          '<span>当前命中 ' + esc(status.masquerade_hits || 0) + ' 条 ' + esc(status.tun_if || 'tun0') + ' 目的规则。</span>' +
        '</div>' +
        '<div class="vpn-check-badges">' + renderBadges([{ label: 'NAT', state: (status.masquerade_hits || 0) > 0 ? 'ok' : 'neutral' }]) + '</div>' +
      '</div>';

    setHtml('vpn-nat-check-list', natHtml);
  }

  function applyStatus(status) {
    if (!status) {
      return;
    }
    setText('vpn-instance-label', status.instance_label || '当前实例');
    document.getElementById('vpn-primary-instance').value = status.instance || '';
    document.getElementById('vpn-stop-instance').value = status.instance || '';

    var shellState = 'is-empty';
    if (status.connected) {
      if (status.health_class === 'ok') {
        shellState = 'is-ok';
      } else if (status.health_class === 'warn') {
        shellState = 'is-warn';
      } else {
        shellState = 'is-bad';
      }
    } else if (status.activation_ready) {
      shellState = 'is-ready';
    } else if (status.profile_ready) {
      shellState = 'is-profile-ready';
    }
    setShellState(shellState);

    var primaryForm = document.getElementById('vpn-primary-form');
    var primaryButton = document.getElementById('vpn-primary-button');
    var stopForm = document.getElementById('vpn-stop-form');
    if (primaryForm && primaryButton) {
      if (status.connected) {
        if (status.action_kind === 'stable') {
          primaryForm.action = '#';
          primaryButton.value = status.action_label || 'OpenVPN 运行中';
          primaryButton.className = 'cbi-button vpn-button-passive';
          primaryButton.disabled = true;
          primaryButton.title = status.health_class === 'ok' ? '当前连接稳定，无需重连。' : '隧道会话正常，请按目标检查处理路由或远端设备告警。';
          setVisible('vpn-stop-form', true);
        } else {
          primaryForm.action = restartUrl;
          primaryButton.value = status.action_label || '检查后重连 OpenVPN';
          primaryButton.className = 'cbi-button cbi-button-apply';
          primaryButton.disabled = false;
          primaryButton.title = '当前会话日志存在错误；重连会短暂中断现有流量。';
          setVisible('vpn-stop-form', true);
        }
      } else if (status.activation_ready) {
        primaryForm.action = applyCurrentUrl;
        primaryButton.value = status.action_label || (status.uci_managed ? '启动 OpenVPN' : '接管并启动');
        primaryButton.className = 'cbi-button cbi-button-apply';
        primaryButton.disabled = false;
        primaryButton.title = '当前配置和认证材料已齐，可直接启动。';
        setVisible('vpn-stop-form', false);
      } else if (status.profile_ready) {
        primaryForm.action = '#';
        primaryButton.value = status.action_label || '添加认证文件';
        primaryButton.className = 'cbi-button vpn-button-muted';
        primaryButton.disabled = true;
        primaryButton.title = '还缺少认证文件，当前不能直接启动。';
        setVisible('vpn-stop-form', false);
      } else {
        primaryForm.action = '#';
        primaryButton.value = status.action_label || '先写入配置';
        primaryButton.className = 'cbi-button vpn-button-muted';
        primaryButton.disabled = true;
        primaryButton.title = '当前还没有完整配置，请先写入 client.ovpn。';
        setVisible('vpn-stop-form', false);
      }
    }

    setClass('vpn-health-chip', 'vpn-health-chip ' + esc(status.health_class || 'bad'));
    setText('vpn-health-chip', status.status_summary_label || status.health_label || '未连接');
    setText('vpn-live-ts', (status.ts ? ('更新 ' + status.ts) : '更新中'));
    setText('vpn-stat-tun-ip', status.tun_ip || '-');
    setText('vpn-stat-tun-meta', (status.tun_if || 'tun0') + ' 当前地址');
    setHtml('vpn-stat-remote', renderRemoteValue(status.remote || '-'));
    setText('vpn-stat-remote-meta', '协议: ' + (status.proto || '-') + ' · 当前写入的 remote');
    setText('vpn-stat-health-ratio', status.online_ratio || status.online_device_ratio || status.remote_online_ratio || '-');
    setText('vpn-stat-health-meta', status.online_breakdown || '远端目标在线比例');

    var authReady = !!status.activation_ready;
    var runtimeCardState = status.connected ? (status.log_state_ok ? 'is-ok' : 'is-warn') : shellState;
    var authCardState = authReady ? 'is-ok' : (status.profile_ready ? 'is-profile-ready' : 'is-empty');
    var routeCardState = status.route_badge_ok ? 'is-ok' : (((status.route_count || 0) > 0 || status.map_enabled) ? 'is-warn' : 'is-empty');
    setCardState('vpn-runtime-card', runtimeCardState);
    setCardState('vpn-auth-card', authCardState);
    setCardState('vpn-route-card', routeCardState);

    setClass('vpn-runtime-badge', 'vpn-card-badge ' + (status.connected ? 'vpn-badge-ok' : 'vpn-badge-bad'));
    setText('vpn-runtime-badge', status.connected ? '在线' : '离线');
    setText('vpn-runtime-service', status.service_label || status.service_status || 'stopped');
    setText('vpn-runtime-managed', status.managed_label || (status.uci_managed ? (status.uci_enabled ? '已接管' : '已接管未启用') : (status.profile_ready ? '可接管' : '未配置')));
    setText('vpn-runtime-action', status.action_label || '-');
    setText('vpn-runtime-mode', status.mode_label || status.mode || '-');
    setClass('vpn-runtime-log-state', 'vpn-inline-badge ' + (status.log_state_ok ? 'vpn-badge-ok' : 'vpn-badge-bad'));
    setText('vpn-runtime-log-state', status.log_state || '未确认');
    setText('vpn-runtime-process', status.process_summary || status.process_line || '-');

    setClass('vpn-auth-badge', 'vpn-card-badge vpn-badge-' + (status.auth_badge_tone || (authReady ? 'ok' : 'warn')));
    setText('vpn-auth-badge', status.auth_badge_label || (authReady ? '可启动' : '缺认证文件'));
    setText('vpn-auth-userpass', status.auth_ready || '-');
    setText('vpn-auth-requirement', status.auth_requirement_label || '-');
    setText('vpn-auth-cert-material', status.cert_material_label || '-');
    setText('vpn-auth-ready', status.startup_label || (status.activation_ready ? '可启动' : (status.profile_ready ? '待认证文件' : '待配置')));
    setText('vpn-auth-tls', status.tls_label || '-');

    setClass('vpn-route-badge', 'vpn-card-badge ' + (status.route_badge_ok ? 'vpn-badge-ok' : 'vpn-badge-bad'));
    setText('vpn-route-badge', status.route_badge_label || (status.route_badge_ok ? '完整' : '待检查'));
    setText('vpn-route-count', (status.route_count || 0) + ' 条');
    setText('vpn-route-ratio', status.route_rule_ratio || '-');
    setText('vpn-peer-count', status.remote_online_ratio || '-');
    setClass('vpn-dnat-status', 'vpn-inline-badge ' + (status.dnat_ok ? 'vpn-badge-ok' : 'vpn-badge-bad'));
    setText('vpn-dnat-status', status.dnat_status || '未启用');
    setText('vpn-map-ip', status.map_ip || '-');
    setText('vpn-route-note', '下方“目标检查”展示每个目标的详细结果。');

    setText('vpn-action-hint', status.action_hint || '当前页会按配置状态自动切换主操作。');
    setText('vpn-runtime-note', status.runtime_note || '断开后如条件满足，可直接从当前页启动或接管启动。');
    setText('vpn-auth-note', status.auth_note || '配置文件和认证材料齐全后，当前页才能直接启动。');

    var copyButton = document.getElementById('vpn-copy-button');
    if (copyButton) {
      var configPath = document.getElementById('vpn-config-path');
      var sameProfile = configPath && configPath.getAttribute('data-profile-path') === (status.config_path || '');
      if (status.copy_ready && sameProfile) {
        copyButton.className = 'cbi-button vpn-button-muted';
        copyButton.setAttribute('aria-disabled', 'false');
        copyButton.title = '复制当前实例配置';
      } else {
        copyButton.className = 'cbi-button vpn-button-muted is-disabled';
        copyButton.setAttribute('aria-disabled', 'true');
        copyButton.title = sameProfile ? '当前没有可复制的文件配置' : '配置来源已变化，请刷新页面';
      }
    }

    renderRouteChecks(status);
    renderNatChecks(status);

    setText('vpn-focus-meta', (status.log_notice_detail || '优先展示连接、认证、路由相关行。') + (status.ts ? (' · ' + status.ts) : ''));
    setClass('vpn-log-event', 'vpn-focus-pill ' + esc(status.log_notice_tone || 'bad'));
    setText('vpn-log-event', status.log_notice_label || '日志事件待确认');
    setText('vpn-focus-ts', status.ts ? ('最近刷新: ' + status.ts) : '等待刷新');
    setText('vpn-route-strip-count', '目标数: ' + ((status.route_count || 0) + ' 条'));
    setText('vpn-route-strip-health', '规则状态: ' + (status.route_rule_ratio || '-'));
    setText('vpn-route-strip-dnat', '映射: ' + (status.dnat_status || '未启用'));
    setHtml('vpn-focus-log', esc(status.log_focus || 'no focus log')
      .replace(/(Initialization Sequence Completed)/g, '<span class="vpn-log-good">$1</span>')
      .replace(/(TLS Error)/g, '<span class="vpn-log-bad">$1</span>')
      .replace(/(AUTH_FAILED)/g, '<span class="vpn-log-bad">$1</span>')
      .replace(/(error)/gi, '<span class="vpn-log-bad">$1</span>')
      .replace(/(fail)/gi, '<span class="vpn-log-bad">$1</span>')
      .replace(/(warn)/gi, '<span class="vpn-log-warn">$1</span>')
      .replace(/(tun[0-9]+)/g, '<span class="vpn-log-info">$1</span>')
      .replace(/(route)/gi, '<span class="vpn-log-info">$1</span>')
      .replace(/(TLS: soft reset)/gi, '<span class="vpn-log-good">$1</span>')
      .replace(/(tls_process: killed expiring key)/gi, '<span class="vpn-log-good">$1</span>')
      .replace(/(SIGTERM received)/gi, '<span class="vpn-log-warn">$1</span>')
      .replace(/(Closing TUN\/TAP interface)/gi, '<span class="vpn-log-warn">$1</span>'));
    setText('vpn-route-meta', status.probe_deferred ? '路由规则已显示，在线目标正在并行探测。' : '基于当前内核状态与目标探测的实时结果。优先看离线和缺规则项。');
    setText('vpn-runtime-meta', '完整日志更适合排查重连、认证和 TLS 问题。' + (status.ts ? (' · ' + status.ts) : ''));
    setText('vpn-runtime-log', status.log || 'no log');
    setText('vpn-tun-meta', '展示 ' + (status.tun_if || 'tun0') + ' 与 ' + (status.lan_if || 'br-lan') + ' 的当前地址信息。' + (status.ts ? (' · ' + status.ts) : ''));
    setText('vpn-tun-title', status.tun_if || 'tun0');
    setText('vpn-lan-title', status.lan_if || 'br-lan');
    setText('vpn-tun-pre', status.tun || ((status.tun_if || 'tun0') + '-down'));
    setText('vpn-lan-pre', status.lan_addr_dump || ('no ' + (status.lan_if || 'br-lan') + ' data'));
  }

  function applyStatusError(message) {
    setShellState('is-warn');
    setClass('vpn-health-chip', 'vpn-health-chip warn');
    setText('vpn-health-chip', '状态未返回');
    setText('vpn-live-ts', lastGoodStatus && lastGoodStatus.ts ? ('更新 ' + lastGoodStatus.ts) : '等待重试');
    setText('vpn-action-hint', message || '状态读取失败，当前不改动 OpenVPN 运行状态。');
    var primaryForm = document.getElementById('vpn-primary-form');
    var primaryButton = document.getElementById('vpn-primary-button');
    var copyButton = document.getElementById('vpn-copy-button');
    if (primaryForm) primaryForm.action = '#';
    if (primaryButton) {
      primaryButton.value = '状态未确认';
      primaryButton.className = 'cbi-button vpn-button-muted';
      primaryButton.disabled = true;
      primaryButton.title = '状态接口恢复后才允许执行运行操作。';
    }
    setVisible('vpn-stop-form', false);
    if (copyButton) {
      copyButton.className = 'cbi-button vpn-button-muted is-disabled';
      copyButton.setAttribute('aria-disabled', 'true');
      copyButton.title = '状态接口恢复后再复制配置。';
    }
  }

  function refreshStatus(options) {
    options = options || {};
    var fast = !!options.fast;
    if (statusBusy) {
      pendingManualRefresh = true;
      return;
    }

    statusBusy = true;
    pendingManualRefresh = false;
    setText('vpn-live-ts', lastGoodStatus && lastGoodStatus.ts ? ('更新 ' + lastGoodStatus.ts) : '刷新中');
    var xhr = new XMLHttpRequest();
    var completed = false;

    function finishRequest(errorMessage) {
      if (completed) return;
      completed = true;
      statusBusy = false;
      if (errorMessage) applyStatusError(errorMessage);
      if (pendingManualRefresh) {
        pendingManualRefresh = false;
        window.setTimeout(function() { refreshStatus(); }, 80);
      }
    }

    xhr.open('GET', statusUrl + (fast ? ((statusUrl.indexOf('?') === -1 ? '?' : '&') + 'fast=1') : ''), true);
    xhr.timeout = 15000;
    xhr.setRequestHeader('X-Requested-With', 'XMLHttpRequest');
    xhr.onreadystatechange = function() {
      if (xhr.readyState !== 4 || completed) return;

      if (xhr.status >= 200 && xhr.status < 300) {
        try {
          var payload = JSON.parse(xhr.responseText);
          if (payload && payload.ok === false) {
            finishRequest(payload.error || '状态接口返回异常。');
            return;
          }
          lastGoodStatus = payload;
          applyStatus(payload);
          finishRequest();
          if (fast) {
            if (deepRefreshTimer) {
              window.clearTimeout(deepRefreshTimer);
            }
            deepRefreshTimer = window.setTimeout(function() {
              deepRefreshTimer = 0;
              refreshStatus();
            }, 120);
          }
        } catch (e) {
          finishRequest('状态响应无法解析，保留页面不执行操作。');
        }
      } else {
        finishRequest('状态请求失败：HTTP ' + xhr.status);
      }
    };
    xhr.onerror = function() { finishRequest('状态请求网络错误，当前操作已锁定。'); };
    xhr.ontimeout = function() { finishRequest('状态请求超时，当前操作已锁定。'); };
    xhr.onabort = function() { finishRequest('状态请求已中止，当前操作已锁定。'); };
    try {
      xhr.send(null);
    } catch (e) {
      finishRequest('状态请求无法发送，当前操作已锁定。');
    }
  }

  window.vpnManualRefresh = function() {
    refreshStatus({ fast: true });
    return false;
  };

  function bindCommandButtons() {
    var refreshButton = document.getElementById('vpn-refresh-button');
    var copyButton = document.getElementById('vpn-copy-button');
    if (refreshButton) {
      refreshButton.onclick = function() {
        return window.vpnManualRefresh();
      };
    }
    if (copyButton) {
      copyButton.onclick = function() {
        return window.vpnCopyConfig();
      };
    }
  }

  function startStatusRefresh() {
    refreshStatus({ fast: true });
  }

  bindCommandButtons();

  if (window.requestAnimationFrame) {
    window.requestAnimationFrame(function() {
      window.setTimeout(startStatusRefresh, 80);
    });
  } else {
    window.setTimeout(startStatusRefresh, 120);
  }

  window.setInterval(function() {
    refreshStatus();
  }, 8000);
})();
</script>

<%+footer%>
