    : <<'EOF_OPENVPN_LEGACY_UNUSED_CSS_OLD'
<style type="text/css">
    :root {
        --vpn-bg: #070b12;
        --vpn-panel: #101827;
        --vpn-panel-2: #0b1320;
        --vpn-line: rgba(148, 163, 184, 0.20);
        --vpn-line-strong: rgba(125, 211, 252, 0.34);
        --vpn-text: #e5edf7;
        --vpn-muted: #9fb0c5;
        --vpn-soft: rgba(255, 255, 255, 0.055);
        --vpn-state: #22d3ee;
        --vpn-state-rgb: 34, 211, 238;
        --vpn-good: #34d399;
        --vpn-warn: #fbbf24;
        --vpn-bad: #fb7185;
    }
    .vpn-shell,
    .vpn-shell *,
    .cbi-map,
    .cbi-map * {
        box-sizing: border-box;
        letter-spacing: 0;
    }
    .vpn-shell {
        max-width: 1220px;
        margin: 0 auto;
        padding: 0 8px 18px;
        color: var(--vpn-text);
        font-family: "Microsoft YaHei", "Segoe UI", sans-serif;
    }
    .vpn-shell a {
        color: inherit;
    }
    .vpn-shell-mk3 {
        --vpn-state: #22d3ee;
        --vpn-state-rgb: 34, 211, 238;
        border: 1px solid rgba(125, 211, 252, 0.18);
        border-radius: 8px;
        background:
            linear-gradient(180deg, rgba(9, 17, 30, 0.98), rgba(5, 10, 18, 0.99));
        box-shadow: 0 20px 42px rgba(0, 0, 0, 0.30), inset 0 1px 0 rgba(255,255,255,0.04);
    }
    .vpn-shell-mk3.is-ok {
        --vpn-state: #34d399;
