        border: 1px solid rgba(125, 211, 252, 0.20);
        border-radius: 8px;
        background:
            linear-gradient(135deg, rgba(13, 25, 42, 0.98) 0%, rgba(7, 14, 24, 0.99) 62%, rgba(12, 31, 32, 0.96) 100%);
        box-shadow: inset 0 0 0 1px rgba(255,255,255,0.025);
    }
    .vpn-hero-mk3::before,
    .vpn-hero-secondary::before {
        content: "";
