        border: 1px solid rgba(125, 211, 252, 0.13);
        border-radius: 8px;
        background:
            linear-gradient(180deg, rgba(255,255,255,0.045), rgba(255,255,255,0.018));
    }
    .vpn-toolbar {
        display: flex;
        flex-wrap: wrap;
        gap: 8px;
        align-items: center;
        margin: 0 0 14px;
    }
    .vpn-pill,
    .vpn-health-chip,
    .vpn-inline-note,
    .vpn-status-chip,
    .vpn-card-badge,
    .vpn-inline-badge,
    .vpn-panel-live-badge,
