    .vpn-micro-badge {
        display: inline-flex;
        min-height: 34px;
        align-items: center;
        justify-content: center;
        gap: 7px;
        padding: 0 14px;
        border: 1px solid rgba(125, 211, 252, 0.22);
        border-radius: 999px;
        color: #dbeafe;
