    }
    .vpn-hero-summary,
    .vpn-secondary-summary {
        display: grid;
        grid-template-columns: repeat(3, minmax(0, 1fr));
        gap: 10px;
        margin-top: 22px;
    }
    .vpn-hero-summary-item,
    .vpn-secondary-summary span {
        min-width: 0;
        padding: 13px 14px;
        border: 1px solid rgba(125, 211, 252, 0.16);
        border-radius: 8px;
        background: rgba(7, 16, 29, 0.58);
