        text-overflow: ellipsis;
        white-space: nowrap;
    }
    .vpn-command-card {
        min-width: 0;
        padding: 20px;
        border: 1px solid rgba(var(--vpn-state-rgb), 0.24);
        border-radius: 8px;
        background:
            linear-gradient(180deg, rgba(var(--vpn-state-rgb), 0.10), rgba(255,255,255,0.028)),
            rgba(7, 16, 29, 0.70);
        box-shadow: inset 0 1px 0 rgba(255,255,255,0.045);
    }
    .vpn-command-kicker {
        margin: 0 0 12px;
        color: #7dd3fc;
        font-size: 12px;
        font-weight: 900;
