    }
    .vpn-hero-actions .cbi-button,
    .vpn-hero-actions a.cbi-button,
    .vpn-hero-actions button.cbi-button,
    .cbi-map .cbi-button,
    .cbi-map .btn.cbi-button,
    .cbi-map .cbi-button-add,
    .cbi-map .cbi-button-reset {
