    }
    .vpn-shell-mk3 .vpn-tab-btn.is-active {
        background: linear-gradient(135deg, #67e8f9 0%, #38bdf8 50%, #60a5fa 100%);
        color: #06111f;
        box-shadow: 0 14px 24px rgba(34, 211, 238, 0.18);
