write_nradio_sim_name_map_js() {
    sim_name_map_js_dir="${NRADIO_SIM_NAME_MAP_JS%/*}"
    sim_name_map_js_tmp="${NRADIO_SIM_NAME_MAP_JS}.tmp.$$"
    sim_name_map_revision="empty"

    if [ -f "$NRADIO_SIM_NAME_MAP_FILE" ]; then
        sim_name_map_revision="$(cksum "$NRADIO_SIM_NAME_MAP_FILE" 2>/dev/null | awk '{ print $1 "-" $2 }' || true)"
        [ -n "$sim_name_map_revision" ] || sim_name_map_revision="unavailable"
    fi

    mkdir -p "$sim_name_map_js_dir"
    rm -f "$sim_name_map_js_tmp" 2>/dev/null || true
    cat > "$sim_name_map_js_tmp" <<EOF_NRADIO_SIM_NAME_MAP_HEAD
(function (window) {
    'use strict';
    var map = {};
EOF_NRADIO_SIM_NAME_MAP_HEAD

    if [ -f "$NRADIO_SIM_NAME_MAP_FILE" ]; then
        while IFS='|' read -r sim_map_iccid sim_map_name || [ -n "${sim_map_iccid:-}${sim_map_name:-}" ]; do
            sim_map_iccid="$(printf '%s' "$sim_map_iccid" | tr -cd '0-9')"
            sim_map_name="$(printf '%s' "$sim_map_name" | sed 's/^[[:space:]]*//;s/[[:space:]]*$//')"
            case "$sim_map_iccid" in
                ''|*[!0-9]*)
                    continue
                    ;;
            esac
            [ "${#sim_map_iccid}" -ge 18 ] 2>/dev/null || continue
            [ -n "$sim_map_name" ] || continue
            case "$sim_map_name" in
                *"'"*|*"\\"*|*"<"*|*">"*)
                    continue
                    ;;
            esac
            printf "    map['%s'] = '%s';\n" "$sim_map_iccid" "$sim_map_name" >> "$sim_name_map_js_tmp"
        done < "$NRADIO_SIM_NAME_MAP_FILE"
    fi

    cat >> "$sim_name_map_js_tmp" <<EOF_NRADIO_SIM_NAME_MAP_TAIL
    window.NRadioSimNameMap = map;
    window.NRadioSimNameMapVersion = '$NRADIO_OPERATOR_FIX_VERSION';
    window.NRadioSimNameMapRevision = '$sim_name_map_revision';
}(window));
EOF_NRADIO_SIM_NAME_MAP_TAIL
    chmod 644 "$sim_name_map_js_tmp"
    mv -f "$sim_name_map_js_tmp" "$NRADIO_SIM_NAME_MAP_JS"
}

write_nradio_operator_display_fix_js() {
    operator_fix_js_dir="${NRADIO_OPERATOR_FIX_JS%/*}"
    operator_fix_js_tmp="${NRADIO_OPERATOR_FIX_JS}.tmp.$$"
    operator_fix_js_version_tmp="${NRADIO_OPERATOR_FIX_JS}.version.$$"

    mkdir -p "$operator_fix_js_dir"
    rm -f "$operator_fix_js_tmp" "$operator_fix_js_version_tmp" 2>/dev/null || true
    cat > "$operator_fix_js_tmp" <<'EOF_NRADIO_OPERATOR_DISPLAY_FIX'
(function (window) {
    'use strict';

    var VERSION = '__NRADIO_OPERATOR_FIX_VERSION__';
    var INVALID_OPERATOR = /^(?:none|unknown|null|undefined|n\/a|na|-)$/i;
    var INVALID_SIM_NAME = /^(?:none|unknown|null|undefined|n\/a|na|-|nradio)$/i;
    var lastGood = {};
    var lastGoodSimName = {};

    function normalize(value) {
        var text = value === null || typeof value === 'undefined' ? '' : String(value);
        text = text.replace(/^\s+|\s+$/g, '');
        return !text || INVALID_OPERATOR.test(text) ? '' : text;
    }

    function companyFromPlmn(value) {
        var text = normalize(value);
        var plmn;
        var alias;

        if (!text) {
            return '';
        }

        if (/^\d{5,15}$/.test(text)) {
            plmn = text.substr(0, 5);
            switch (plmn) {
                case '46000':
                case '46002':
                case '46004':
                case '46007':
                case '46008':
                    return 'China Mobile';
                case '46001':
                case '46006':
                case '46009':
                    return 'China Unicom';
                case '46003':
                case '46005':
                case '46011':
                case '46012':
                    return 'China Telecom';
                case '46015':
                    return 'China Broadnet';
            }
        }

        alias = text.toUpperCase().replace(/[\s_-]+/g, '');
        if (alias === 'CHNUNICOM' || alias === 'UNICOM') {
            return 'China Unicom';
        }
        if (alias === 'CHNCT' || alias === 'CHNTELECOM' || alias === 'CTCC') {
            return 'China Telecom';
        }
        if (alias === 'CMCC' || alias === 'CHNMOBILE') {
            return 'China Mobile';
        }
        if (alias === 'CHNBROADNET' || alias === 'CBN') {
            return 'China Broadnet';
        }
        return text;
    }

    function storageKey(name) {
        return 'nradio.operator.' + String(name || 'default').replace(/[^A-Za-z0-9_.-]/g, '_');
    }

    function normalizeIccid(value) {
        var iccid = value === null || typeof value === 'undefined' ? '' : String(value);
        iccid = iccid.replace(/\D/g, '');
        return iccid.length >= 18 ? iccid : '';
    }

    function normalizeSimName(value) {
        var text = value === null || typeof value === 'undefined' ? '' : String(value);
        text = text.replace(/^\s+|\s+$/g, '');
        return !text || INVALID_SIM_NAME.test(text) ? '' : text;
    }

    function configuredSimName(iccid) {
        var map = window.NRadioSimNameMap;
        if (!iccid || !map || typeof map !== 'object') {
            return '';
        }
        return normalizeSimName(map[iccid]);
    }

    function simNameStorageKey(name, iccid) {
        var identity = iccid || name || 'default';
        var revision = String(window.NRadioSimNameMapRevision || 'empty');
        return 'nradio.sim-name.' + revision.replace(/[^A-Za-z0-9_.-]/g, '_') + '.' +
            String(identity).replace(/[^A-Za-z0-9_.-]/g, '_');
    }

    function rememberSimName(name, iccid, simName) {
        var key;
        if (!simName) {
            return;
        }
        key = simNameStorageKey(name, iccid);
        lastGoodSimName[key] = simName;
        if (!iccid) {
            return;
        }
        try {
            window.localStorage.setItem(key, simName);
        } catch (ignore) {
        }
    }

    function restoreSimName(name, iccid) {
        var key = simNameStorageKey(name, iccid);
        var simName = lastGoodSimName[key] || '';
        if (simName) {
            return simName;
        }
        if (!iccid) {
            return '';
        }
        try {
            simName = normalizeSimName(window.localStorage.getItem(key));
        } catch (ignore) {
            simName = '';
        }
        if (simName) {
            lastGoodSimName[key] = simName;
        }
        return simName;
    }

    function remember(name, operator) {
        if (!operator) {
            return;
        }
        lastGood[name] = operator;
        try {
            window.sessionStorage.setItem(storageKey(name), operator);
        } catch (ignore) {
        }
    }

    function restore(name) {
        var operator = lastGood[name] || '';
        if (operator) {
            return operator;
        }
        try {
            operator = companyFromPlmn(window.sessionStorage.getItem(storageKey(name)));
        } catch (ignore) {
            operator = '';
        }
        if (operator) {
            lastGood[name] = operator;
        }
        return operator;
    }

    function sanitizeCpeStatus(status) {
        var name;
        var operator;
        var simOperator;
        var networkOperator;
        var iccid;
        var simName;
        var nativeSimName;
        var mappedSimName;

        if (!status || typeof status !== 'object') {
            return;
        }
        name = normalize(status.name) || 'default';
        iccid = normalizeIccid(status.iccid);
        simOperator = companyFromPlmn(status.sim_company) || companyFromPlmn(status.sim_isp);
        networkOperator = companyFromPlmn(status.isp_company) || companyFromPlmn(status.isp);
        operator = simOperator || networkOperator;
        if (operator) {
            remember(name, operator);
        } else {
            operator = restore(name);
        }
        status.sim_company = simOperator || operator || '';
        status.isp_company = networkOperator || operator || '';
        status.sim_isp = status.sim_company;
        status.isp = status.isp_company;

        nativeSimName = normalizeSimName(status.sim_name);
        mappedSimName = configuredSimName(iccid);
        simName = mappedSimName || nativeSimName;
        if (simName) {
            rememberSimName(name, iccid, simName);
        } else {
            simName = restoreSimName(name, iccid);
        }
        status.sim_name = simName || '';
        status.nradio_sim_name_source = mappedSimName ? 'map' :
            (nativeSimName ? 'firmware' : (simName ? 'cache' : ''));
    }

    if (typeof window.format_isp_info === 'function' && !window.format_isp_info.nradioOperatorFix) {
        (function () {
            var originalFormatIsp = window.format_isp_info;
            var fixedFormatIsp = function (simIsp, isp) {
                var primary;
                var fallback;
                var fixedInfo;
                var key;

                if (simIsp && typeof simIsp === 'object') {
                    fixedInfo = {};
                    for (key in simIsp) {
                        if (Object.prototype.hasOwnProperty.call(simIsp, key)) {
                            fixedInfo[key] = simIsp[key];
                        }
                    }
                    primary = companyFromPlmn(simIsp.sim_company) || companyFromPlmn(simIsp.sim_isp);
                    fallback = companyFromPlmn(simIsp.isp_company) || companyFromPlmn(simIsp.isp);
                    fixedInfo.sim_company = primary || fallback || '';
                    fixedInfo.isp_company = fallback || primary || '';
                    if (!normalize(fixedInfo.sim_company_lng)) {
                        fixedInfo.sim_company_lng = fixedInfo.sim_company;
                    }
                    if (!normalize(fixedInfo.isp_company_lng)) {
                        fixedInfo.isp_company_lng = fixedInfo.isp_company;
                    }
                    return originalFormatIsp.call(this, fixedInfo);
                }

                primary = companyFromPlmn(simIsp);
                fallback = companyFromPlmn(isp);
                return originalFormatIsp.call(this, primary || '', fallback || '');
            };
            fixedFormatIsp.nradioOperatorFix = VERSION;
            window.format_isp_info = fixedFormatIsp;
        }());
    }

    if (typeof window.cpe_show === 'function' && !window.cpe_show.nradioOperatorFix) {
        (function () {
            var originalCpeShow = window.cpe_show;
            var fixedCpeShow = function (cpe) {
                var i;
                if (cpe && typeof cpe.length === 'number') {
                    for (i = 0; i < cpe.length; i += 1) {
                        sanitizeCpeStatus(cpe[i]);
                    }
                }
                return originalCpeShow.apply(this, arguments);
            };
            fixedCpeShow.nradioOperatorFix = VERSION;
            window.cpe_show = fixedCpeShow;
        }());
    }

    if (window.document && window.document.documentElement) {
        window.document.documentElement.setAttribute('data-nradio-operator-fix', VERSION);
        window.document.documentElement.setAttribute(
            'data-nradio-sim-name-map-count',
            String(Object.keys(window.NRadioSimNameMap || {}).length)
        );
        window.document.documentElement.setAttribute(
            'data-nradio-sim-name-priority',
            'map,firmware,cache'
        );
        window.document.documentElement.setAttribute(
            'data-nradio-operator-hooks',
            [
                window.format_isp_info && window.format_isp_info.nradioOperatorFix ? 'format' : '',
                window.cpe_show && window.cpe_show.nradioOperatorFix ? 'cpe' : ''
            ].filter(function (item) { return item; }).join(',')
        );
    }

    window.NRadioOperatorDisplayFix = {
        version: VERSION,
        normalize: companyFromPlmn,
        normalizeSimName: normalizeSimName,
        sanitizeCpeStatus: sanitizeCpeStatus
    };
}(window));
EOF_NRADIO_OPERATOR_DISPLAY_FIX
    sed "s/__NRADIO_OPERATOR_FIX_VERSION__/$NRADIO_OPERATOR_FIX_VERSION/g" "$operator_fix_js_tmp" > "$operator_fix_js_version_tmp" \
        || die "写入 LuCI 运营商显示脚本版本失败"
    mv -f "$operator_fix_js_version_tmp" "$operator_fix_js_tmp" \
        || die "替换 LuCI 运营商显示脚本版本失败"
    chmod 644 "$operator_fix_js_tmp"
    mv -f "$operator_fix_js_tmp" "$NRADIO_OPERATOR_FIX_JS"
}

rewrite_nradio_operator_display_view() {
    operator_fix_view_mode="${1:-install}"
    operator_fix_view_tmp="${NRADIO_OPERATOR_FIX_VIEW}.tmp.$$"
    operator_fix_begin_count=0
    operator_fix_end_count=0

    [ -f "$NRADIO_OPERATOR_FIX_VIEW" ] || die "LuCI 首页模板不存在: $NRADIO_OPERATOR_FIX_VIEW"
    grep -Fq 'nradio_status/index_common' "$NRADIO_OPERATOR_FIX_VIEW" 2>/dev/null || die "LuCI 首页模板结构不受支持: $NRADIO_OPERATOR_FIX_VIEW"

    operator_fix_begin_count="$(grep -Fc "$NRADIO_OPERATOR_FIX_MARKER_BEGIN" "$NRADIO_OPERATOR_FIX_VIEW" 2>/dev/null || true)"
    operator_fix_end_count="$(grep -Fc "$NRADIO_OPERATOR_FIX_MARKER_END" "$NRADIO_OPERATOR_FIX_VIEW" 2>/dev/null || true)"
    [ "$operator_fix_begin_count" = "$operator_fix_end_count" ] || die "LuCI 运营商修复标记不完整，拒绝覆盖首页模板"
    [ "$operator_fix_begin_count" -le 1 ] 2>/dev/null || die "LuCI 运营商修复标记重复，拒绝覆盖首页模板"

    rm -f "$operator_fix_view_tmp" 2>/dev/null || true
    awk -v begin="$NRADIO_OPERATOR_FIX_MARKER_BEGIN" \
        -v end="$NRADIO_OPERATOR_FIX_MARKER_END" \
        -v script_src="/luci-static/nradio/js/nradio-operator-display-fix.js" \
        -v map_src="/luci-static/nradio/js/nradio-sim-name-map.js" '
        $0 == begin { skip = 1; next }
        $0 == end { skip = 0; next }
        index($0, script_src) { next }
        index($0, map_src) { next }
        !skip { print }
        END { if (skip) exit 2 }
    ' "$NRADIO_OPERATOR_FIX_VIEW" > "$operator_fix_view_tmp" || {
        rm -f "$operator_fix_view_tmp" 2>/dev/null || true
        die "清理旧 LuCI 运营商修复标记失败"
    }

    if [ "$operator_fix_view_mode" = 'install' ]; then
        cat >> "$operator_fix_view_tmp" <<EOF_NRADIO_OPERATOR_DISPLAY_TAG
$NRADIO_OPERATOR_FIX_MARKER_BEGIN
<script type="text/javascript" src="/luci-static/nradio/js/nradio-sim-name-map.js?v=$NRADIO_OPERATOR_FIX_VERSION"></script>
<script type="text/javascript" src="/luci-static/nradio/js/nradio-operator-display-fix.js?v=$NRADIO_OPERATOR_FIX_VERSION"></script>
$NRADIO_OPERATOR_FIX_MARKER_END
EOF_NRADIO_OPERATOR_DISPLAY_TAG
    fi

    chmod 644 "$operator_fix_view_tmp"
    mv -f "$operator_fix_view_tmp" "$NRADIO_OPERATOR_FIX_VIEW"
}

verify_nradio_operator_display_fix() {
    [ -s "$NRADIO_SIM_NAME_MAP_JS" ] || return 1
    [ -s "$NRADIO_OPERATOR_FIX_JS" ] || return 1
    grep -Fq "window.NRadioSimNameMapVersion = '$NRADIO_OPERATOR_FIX_VERSION';" "$NRADIO_SIM_NAME_MAP_JS" 2>/dev/null || return 1
    grep -Fq 'window.NRadioSimNameMapRevision' "$NRADIO_SIM_NAME_MAP_JS" 2>/dev/null || return 1
    grep -Fq "var VERSION = '$NRADIO_OPERATOR_FIX_VERSION';" "$NRADIO_OPERATOR_FIX_JS" 2>/dev/null || return 1
    grep -Fq 'INVALID_OPERATOR' "$NRADIO_OPERATOR_FIX_JS" 2>/dev/null || return 1
    grep -Fq 'configuredSimName' "$NRADIO_OPERATOR_FIX_JS" 2>/dev/null || return 1
    grep -Fq "nradio_sim_name_source = mappedSimName ? 'map'" "$NRADIO_OPERATOR_FIX_JS" 2>/dev/null || return 1
    grep -Fq "'data-nradio-sim-name-priority'" "$NRADIO_OPERATOR_FIX_JS" 2>/dev/null || return 1
    grep -Fq "'map,firmware,cache'" "$NRADIO_OPERATOR_FIX_JS" 2>/dev/null || return 1
    grep -Fq "typeof simIsp === 'object'" "$NRADIO_OPERATOR_FIX_JS" 2>/dev/null || return 1
    grep -Fq 'if (!iccid)' "$NRADIO_OPERATOR_FIX_JS" 2>/dev/null || return 1
    grep -Fq 'localStorage' "$NRADIO_OPERATOR_FIX_JS" 2>/dev/null || return 1
    grep -Fq 'sessionStorage' "$NRADIO_OPERATOR_FIX_JS" 2>/dev/null || return 1
    [ "$(grep -Fc "$NRADIO_OPERATOR_FIX_MARKER_BEGIN" "$NRADIO_OPERATOR_FIX_VIEW" 2>/dev/null || true)" -eq 1 ] 2>/dev/null || return 1
    [ "$(grep -Fc "$NRADIO_OPERATOR_FIX_MARKER_END" "$NRADIO_OPERATOR_FIX_VIEW" 2>/dev/null || true)" -eq 1 ] 2>/dev/null || return 1
    [ "$(grep -Fc '/luci-static/nradio/js/nradio-operator-display-fix.js' "$NRADIO_OPERATOR_FIX_VIEW" 2>/dev/null || true)" -eq 1 ] 2>/dev/null || return 1
    [ "$(grep -Fc '/luci-static/nradio/js/nradio-sim-name-map.js' "$NRADIO_OPERATOR_FIX_VIEW" 2>/dev/null || true)" -eq 1 ] 2>/dev/null || return 1
    return 0
}

refresh_nradio_operator_display_fix() {
    rm -f /tmp/luci-indexcache /tmp/luci-modulecache/* 2>/dev/null || true
    /etc/init.d/uhttpd reload >/dev/null 2>&1 || true
}

install_nradio_operator_display_fix() {
    require_root
    write_nradio_sim_name_map_js
    write_nradio_operator_display_fix_js
    rewrite_nradio_operator_display_view install
    verify_nradio_operator_display_fix || die "LuCI 运营商与卡名显示修复校验失败"
    refresh_nradio_operator_display_fix
    log "结果:   LuCI 运营商与卡名显示修复已安装或更新"
    log "版本:   $NRADIO_OPERATOR_FIX_VERSION"
    log "卡名:   $NRADIO_SIM_NAME_MAP_FILE"
}

show_nradio_operator_display_fix_status() {
    log "LuCI 运营商与卡名显示修复状态:"
    if verify_nradio_operator_display_fix; then
        log "状态:   PASS 已安装"
        log "版本:   $NRADIO_OPERATOR_FIX_VERSION"
    else
        log "状态:   未安装或文件不完整"
    fi
    log "脚本:   $NRADIO_OPERATOR_FIX_JS"
    log "映射:   $NRADIO_SIM_NAME_MAP_FILE"
    log "映射数: $(nradio_sim_name_map_count)"
    log "映射JS: $NRADIO_SIM_NAME_MAP_JS"
    log "模板:   $NRADIO_OPERATOR_FIX_VIEW"
}

nradio_sim_name_map_count() {
    if [ ! -f "$NRADIO_SIM_NAME_MAP_FILE" ]; then
        printf '0\n'
        return 0
    fi
    awk -F'|' 'NF >= 2 && $1 != "" && $2 != "" { count++ } END { print count + 0 }' "$NRADIO_SIM_NAME_MAP_FILE" 2>/dev/null || printf '0\n'
}

nradio_sim_name_map_lookup() {
    sim_lookup_iccid="$1"
    [ -f "$NRADIO_SIM_NAME_MAP_FILE" ] || return 0
    awk -F'|' -v target="$sim_lookup_iccid" '
        $1 == target {
            sub(/^[^|]*\|/, "")
            print
            exit
        }
    ' "$NRADIO_SIM_NAME_MAP_FILE" 2>/dev/null || true
}

nradio_mask_iccid() {
    printf '%s' "$1" | sed 's/^\([0-9][0-9][0-9][0-9][0-9][0-9]\).*\([0-9][0-9][0-9][0-9][0-9]\)$/\1...\2/'
}

nradio_validate_sim_name() {
    sim_validate_name="$1"
    [ -n "$sim_validate_name" ] || return 1
    [ "${#sim_validate_name}" -le 64 ] 2>/dev/null || return 1
    case "$sim_validate_name" in
        *"|"*|*"'"*|*"\\"*|*"<"*|*">"*)
            return 1
            ;;
    esac
    return 0
}

nradio_normalize_native_sim_name() {
    NRADIO_NATIVE_SIM_NAME="$(printf '%s' "$1" | tr '\r\n' '  ' | sed 's/^[[:space:]]*//; s/[[:space:]]*$//')"
    [ -n "$NRADIO_NATIVE_SIM_NAME" ] || return 1
    sim_native_name_lc="$(printf '%s' "$NRADIO_NATIVE_SIM_NAME" | tr '[:upper:]' '[:lower:]')"
    case "$sim_native_name_lc" in
        none|unknown|null|undefined|n/a|na|-|nradio)
            NRADIO_NATIVE_SIM_NAME=''
            return 1
            ;;
    esac
    return 0
}

nradio_set_sim_name_mapping() {
    sim_set_iccid="$1"
    sim_set_name="$2"
    sim_map_dir="${NRADIO_SIM_NAME_MAP_FILE%/*}"
    sim_map_tmp="${NRADIO_SIM_NAME_MAP_FILE}.tmp.$$"

    case "$sim_set_iccid" in
        ''|*[!0-9]*)
            die "无效 ICCID，拒绝写入卡名映射"
            ;;
    esac
    [ "${#sim_set_iccid}" -ge 18 ] 2>/dev/null || die "ICCID 长度不足，拒绝写入卡名映射"
    [ -z "$sim_set_name" ] || nradio_validate_sim_name "$sim_set_name" || die "卡名包含不支持的字符或超过 64 字符"

    mkdir -p "$sim_map_dir"
    rm -f "$sim_map_tmp" 2>/dev/null || true
    if [ -f "$NRADIO_SIM_NAME_MAP_FILE" ]; then
        awk -F'|' -v target="$sim_set_iccid" '$1 != target { print }' "$NRADIO_SIM_NAME_MAP_FILE" > "$sim_map_tmp"
    else
        : > "$sim_map_tmp"
    fi
    if [ -n "$sim_set_name" ]; then
        printf '%s|%s\n' "$sim_set_iccid" "$sim_set_name" >> "$sim_map_tmp"
    fi
    chmod 600 "$sim_map_tmp"
    mv -f "$sim_map_tmp" "$NRADIO_SIM_NAME_MAP_FILE"
}

configure_nradio_sim_name_mappings() {
    require_root
    command -v ubus >/dev/null 2>&1 || die "缺少 ubus，无法读取当前 SIM"
    command -v jsonfilter >/dev/null 2>&1 || die "缺少 jsonfilter，无法读取当前 SIM"

    sim_runtime_json="$(ubus call infocd runtime 2>/dev/null || true)"
    [ -n "$sim_runtime_json" ] || die "infocd runtime 无返回，无法读取当前 SIM"
    sim_index=0
    sim_found=0
    sim_changed=0

    while [ "$sim_index" -lt 8 ] 2>/dev/null; do
        sim_iface="$(printf '%s\n' "$sim_runtime_json" | jsonfilter -e "@.cpe[$sim_index].name" 2>/dev/null || true)"
        sim_iccid_raw="$(printf '%s\n' "$sim_runtime_json" | jsonfilter -e "@.cpe[$sim_index].iccid" 2>/dev/null || true)"
        sim_iccid="$(printf '%s' "$sim_iccid_raw" | tr -cd '0-9')"
        sim_native_name="$(printf '%s\n' "$sim_runtime_json" | jsonfilter -e "@.cpe[$sim_index].sim_name" 2>/dev/null || true)"
        [ -n "$sim_iface$sim_iccid_raw$sim_native_name" ] || break
        sim_index=$((sim_index + 1))

        sim_native_valid=0
        if nradio_normalize_native_sim_name "$sim_native_name"; then
            sim_native_valid=1
        fi

        if [ -z "$sim_iccid" ] || [ "${#sim_iccid}" -lt 18 ] 2>/dev/null; then
            if [ "$sim_native_valid" -eq 1 ] 2>/dev/null; then
                sim_found=$((sim_found + 1))
                printf '\n接口: %s\n' "${sim_iface:-cpe}"
                printf 'ICCID: 固件未返回有效纯数字值\n'
                printf '固件原生卡名: %s\n' "$NRADIO_NATIVE_SIM_NAME"
                log "无法配置覆盖卡名: ${sim_iface:-cpe} 缺少有效 ICCID；继续使用固件原生卡名"
            fi
            continue
        fi

        sim_found=$((sim_found + 1))
        sim_existing_name="$(nradio_sim_name_map_lookup "$sim_iccid")"

        printf '\n接口: %s\n' "${sim_iface:-cpe}"
        printf 'ICCID: %s\n' "$(nradio_mask_iccid "$sim_iccid")"
        if [ "$sim_native_valid" -eq 1 ] 2>/dev/null; then
            printf '固件原生卡名: %s\n' "$NRADIO_NATIVE_SIM_NAME"
        else
            printf '固件原生卡名: 未返回\n'
        fi
        if [ -n "$sim_existing_name" ]; then
            printf '当前本地覆盖卡名: %s\n' "$sim_existing_name"
        elif [ "$sim_native_valid" -eq 1 ] 2>/dev/null; then
            printf '当前本地覆盖卡名: 未配置（使用固件原生卡名）\n'
        else
            printf '当前本地覆盖卡名: 未配置\n'
        fi
        print_menu_item 1 '鲲鹏寂寞卡'
        print_menu_item 2 '鲲鹏天火卡'
        print_menu_item 3 '鲲鹏神卡'
        print_menu_item 4 '自定义卡名'
        print_menu_item 5 '清除本地覆盖卡名'
        print_menu_item 0 '保留当前配置'
        print_menu_prompt '0-5'
        ui_read_line || die "input cancelled"
        case "$UI_READ_RESULT" in
            0)
                continue
                ;;
            1)
                sim_selected_name='鲲鹏寂寞卡'
                ;;
            2)
                sim_selected_name='鲲鹏天火卡'
                ;;
            3)
                sim_selected_name='鲲鹏神卡'
                ;;
            4)
                printf '请输入卡名（最多 64 字符，不支持 |、引号、反斜杠或尖括号）: '
                ui_read_line || die "input cancelled"
                sim_selected_name="$UI_READ_RESULT"
                nradio_validate_sim_name "$sim_selected_name" || die "卡名为空、过长或包含不支持的字符"
                ;;
            5)
                sim_selected_name=''
                ;;
            *)
                die_menu_input_issue "$UI_READ_RESULT"
                ;;
        esac
        nradio_set_sim_name_mapping "$sim_iccid" "$sim_selected_name"
        sim_changed=$((sim_changed + 1))
        if [ -n "$sim_selected_name" ]; then
            log "已设置: ${sim_iface:-cpe} $(nradio_mask_iccid "$sim_iccid") -> $sim_selected_name"
        else
            log "已清除: ${sim_iface:-cpe} $(nradio_mask_iccid "$sim_iccid")"
        fi
    done

    [ "$sim_found" -gt 0 ] 2>/dev/null || die "未检测到有效 ICCID"
    if [ "$sim_changed" -eq 0 ] 2>/dev/null; then
        log "结果:   未修改卡名映射"
        return 0
    fi

    if [ -s "$NRADIO_OPERATOR_FIX_JS" ] && \
       grep -Fq "$NRADIO_OPERATOR_FIX_MARKER_BEGIN" "$NRADIO_OPERATOR_FIX_VIEW" 2>/dev/null; then
        write_nradio_sim_name_map_js
        verify_nradio_operator_display_fix || die "卡名映射更新后校验失败"
        refresh_nradio_operator_display_fix
    else
        log "提示:   映射已保存；安装显示修复后生效"
    fi
    log "结果:   卡名映射已更新，共 $(nradio_sim_name_map_count) 条"
}

uninstall_nradio_operator_display_fix() {
    require_root
    printf '确认移除 LuCI 运营商与卡名显示修复？[y/N]: '
    ui_read_line || die "input cancelled"
    case "$UI_READ_RESULT" in
        y|Y|yes|YES)
            ;;
        *)
            log "已取消"
            return 0
            ;;
    esac

    if [ -f "$NRADIO_OPERATOR_FIX_VIEW" ]; then
        rewrite_nradio_operator_display_view remove
    fi
    rm -f "$NRADIO_OPERATOR_FIX_JS" "$NRADIO_SIM_NAME_MAP_JS" 2>/dev/null || true
    refresh_nradio_operator_display_fix
    log "结果:   LuCI 运营商与卡名显示修复已移除（卡名配置已保留）"
}

run_nradio_operator_display_selfcheck() {
    operator_fix_failures=0

    selfcheck_print_header "LuCI 运营商与卡名显示"
    if [ ! -e "$NRADIO_OPERATOR_FIX_JS" ] && \
       ! grep -Fq "$NRADIO_OPERATOR_FIX_MARKER_BEGIN" "$NRADIO_OPERATOR_FIX_VIEW" 2>/dev/null; then
        log "summary:  SKIP (optional feature not installed)"
        set_last_selfcheck_status SKIP 0 0
        return 0
    fi

    if verify_nradio_operator_display_fix; then
        log "脚本:   PASS $NRADIO_OPERATOR_FIX_VERSION"
        log "注入:   PASS 首页标签唯一"
        log "运营商: PASS 旧双参数/新状态对象 -> isp/PLMN -> session cache"
        log "卡名:   PASS firmware -> ICCID map -> valid-ICCID persistent cache"
    else
        log "状态:   FAIL 文件、版本或首页注入不完整"
        operator_fix_failures=1
    fi

    if [ "$operator_fix_failures" -gt 0 ]; then
        log "summary:  FAIL ($operator_fix_failures fail)"
        set_last_selfcheck_status FAIL "$operator_fix_failures" 0
    else
        log "summary:  PASS"
        set_last_selfcheck_status PASS 0 0
    fi
}

manage_nradio_operator_display_fix() {
    while :; do
        print_menu_header '设备维护 > 运营商与卡名显示'
        print_menu_item 1 '安装或更新修复'
        print_menu_item 2 '查看修复状态'
        print_menu_item 3 '移除修复'
        print_menu_item 4 '配置当前 SIM 卡名'
        print_menu_item 0 '返回上级'
        print_menu_prompt '0-4'
        read_category_choice
        case "$UI_READ_RESULT" in
            0)
                return 0
                ;;
            1)
                install_nradio_operator_display_fix
                record_action_history "5 > 9 > 1" "LuCI 运营商显示修复安装或更新" "PASS" "$BACKUP_DIR"
                MENU_ACTION_COMPLETED='1'
                return 0
                ;;
            2)
                show_nradio_operator_display_fix_status
                MENU_ACTION_COMPLETED='1'
                return 0
                ;;
            3)
                uninstall_nradio_operator_display_fix
                record_action_history "5 > 9 > 3" "LuCI 运营商显示修复移除" "PASS" "$BACKUP_DIR"
                MENU_ACTION_COMPLETED='1'
                return 0
                ;;
            4)
                configure_nradio_sim_name_mappings
                record_action_history "5 > 9 > 4" "LuCI SIM 卡名映射配置" "PASS" "$BACKUP_DIR"
                MENU_ACTION_COMPLETED='1'
                return 0
                ;;
            *)
                die_menu_input_issue "$UI_READ_RESULT"
                ;;
        esac
    done
}

write_nradio_home_temperature_switch_js() {
    home_temp_js_tmp="${NRADIO_HOME_TEMP_JS}.tmp.$$"

    mkdir -p "$(dirname "$NRADIO_HOME_TEMP_JS")" || die "创建 LuCI 首页温度脚本目录失败"
    rm -f "$home_temp_js_tmp" 2>/dev/null || true
    cat > "$home_temp_js_tmp" <<EOF_NRADIO_HOME_TEMPERATURE_SWITCH
(function (window, document) {
    'use strict';

    var VERSION = '$NRADIO_HOME_TEMP_VERSION';
    var cpuTemperature = '';
    var cpuPercent = '';
    var memoryPercent = '';
    var temperatureModes = Object.create(null);
    var temperatureStates = Object.create(null);
    var installed = false;
    var installAttempts = 0;
    var runtimeUrl = findRuntimeUrl();
    var runtimeRequest = null;
    var runtimeRequestSequence = 0;
    var runtimeAppliedSequence = 0;
    var runtimeRevision = 0;
    var runtimeUpdatedAt = 0;
    var storageKey = 'nradio.home-temperature.modes.v1';

    function restoreTemperatureModes() {
        var saved;
        var name;
        try {
            saved = JSON.parse(window.localStorage.getItem(storageKey) || '{}');
            if (!saved || typeof saved !== 'object') {
                return;
            }
            for (name in saved) {
                if (Object.prototype.hasOwnProperty.call(saved, name) &&
                    (saved[name] === 'cpu' || saved[name] === 'cpe')) {
                    temperatureModes[name] = saved[name];
                }
            }
        } catch (error) {
            // Storage may be unavailable; the current page still keeps its choice.
        }
    }

    function saveTemperatureModes() {
        try {
            window.localStorage.setItem(storageKey, JSON.stringify(temperatureModes));
        } catch (error) {
            // Switching does not depend on browser storage being writable.
        }
    }

    function findRuntimeUrl() {
        var script = document.currentScript;
        var scripts;
        var index;
        var source;
        var url;
        if (script) {
            url = script.getAttribute('data-runtime-url');
            if (url) {
                return String(url);
            }
        }
        scripts = document.getElementsByTagName('script');
        for (index = scripts.length - 1; index >= 0; index -= 1) {
            source = String(scripts[index].getAttribute('src') || '');
            if (source.indexOf('/nradio-home-temperature-switch.js') !== -1) {
                url = scripts[index].getAttribute('data-runtime-url');
                return url ? String(url) : '';
            }
        }
        return '';
    }

    function refreshRuntimeNow() {
        var request;
        var sequence;
        var revision;
        var separator;
        var requestUrl;

        if (!runtimeUrl || typeof window.XMLHttpRequest !== 'function') {
            return;
        }
        if (runtimeRequest && runtimeRequest.readyState !== 4) {
            return;
        }

        sequence = runtimeRequestSequence + 1;
        runtimeRequestSequence = sequence;
        revision = runtimeRevision;
        separator = runtimeUrl.indexOf('?') === -1 ? '?' : '&';
        requestUrl = runtimeUrl + separator + '_nrht=' +
            String(new Date().getTime()) + '-' + String(sequence);
        request = new window.XMLHttpRequest();
        runtimeRequest = request;
        request.onreadystatechange = function () {
            var data;
            if (request.readyState !== 4) {
                return;
            }
            if (runtimeRequest === request) {
                runtimeRequest = null;
            }
            if (request.status < 200 || request.status >= 300 ||
                sequence < runtimeAppliedSequence || revision !== runtimeRevision) {
                return;
            }
            try {
                data = JSON.parse(request.responseText || '{}');
            } catch (error) {
                return;
            }
            if (!data || !data.result) {
                return;
            }
            runtimeAppliedSequence = sequence;
            if (typeof window.stats_info === 'function') {
                window.stats_info(data);
            }
        };
        request.onerror = request.ontimeout = request.onabort = function () {
            if (runtimeRequest === request) {
                runtimeRequest = null;
            }
        };
        try {
            request.open('GET', requestUrl, true);
            request.timeout = 8000;
            request.send(null);
        } catch (error) {
            if (runtimeRequest === request) {
                runtimeRequest = null;
            }
        }
    }

    function installSpeedRefresh() {
        var originalSpeedShow = window.speed_show;
        var samples = Object.create(null);
        var jquery = window.jQuery;
        var staleAfter = 4000;

        if (window.low_cpu || typeof originalSpeedShow !== 'function' ||
            typeof window.get_speed_data !== 'function' || typeof jquery !== 'function' ||
            typeof window.nradio_rate_format !== 'function') {
            return;
        }

        function sampleTime() {
            return window.performance && typeof window.performance.now === 'function' ?
                window.performance.now() : new Date().getTime();
        }

        function renderSpeed(wanItem, sample) {
            var prefix = '.box_wans_' + wanItem.name;
            var up = window.nradio_rate_format(sample.upRate).split(' ');
            var down = window.nradio_rate_format(sample.downRate).split(' ');
            jquery(prefix + ' .speedup_data').text(up[0]);
            jquery(prefix + ' .speedup_unit').text(up[1] || 'bps');
            jquery(prefix + ' .speeddown_data').text(down[0]);
            jquery(prefix + ' .speeddown_unit').text(down[1] || 'bps');
            wanItem.ulbytes = sample.upload;
            wanItem.dlbytes = sample.download;
        }

        // The OEM ready handler uses this interval to start its existing timer.
        window.speed_interval = 1;
        window.speed_show = function (wanItem, uploadBytes, downloadBytes, interval) {
            var now = sampleTime();
            var upload = Number(uploadBytes);
            var download = Number(downloadBytes);
            var sample;
            var elapsed;
            if (!wanItem) {
                return originalSpeedShow.apply(this, arguments);
            }
            if (uploadBytes == null || downloadBytes == null ||
                !isFinite(upload) || !isFinite(download) || upload < 0 || download < 0) {
                return;
            }
            sample = samples[wanItem.name];
            if (!sample || upload < sample.upload || download < sample.download || now < sample.at) {
                sample = { upload: upload, download: download, at: now, upRate: 0, downRate: 0 };
                samples[wanItem.name] = sample;
            } else if (upload !== sample.upload || download !== sample.download) {
                elapsed = (now - sample.at) / 1000;
                if (elapsed <= 0) {
                    return;
                }
                sample.upRate = (upload - sample.upload) * 8 / elapsed;
                sample.downRate = (download - sample.download) * 8 / elapsed;
                sample.upload = upload;
                sample.download = download;
                sample.at = now;
            } else if (now - sample.at >= staleAfter) {
                sample.upRate = 0;
                sample.downRate = 0;
            }
            // infocd returns the same cached counters between its 2-second
            // samples. Keep the last measured rate and its original baseline.
            sample.seen = now;
            renderSpeed(wanItem, sample);
        };

        window.reset_box_speed = function (wans) {
            var now = sampleTime();
            var index;
            var item;
            var sample;
            for (index = 0; index < wans.length; index += 1) {
                item = wans[index];
                sample = samples[item.name];
                if (item.disabled === '1') {
                    delete samples[item.name];
                    originalSpeedShow.call(window, item, 0, 0, 1);
                } else if (sample) {
                    if (now - sample.seen >= staleAfter) {
                        sample.upRate = 0;
                        sample.downRate = 0;
                    }
                    // Runtime/layout refreshes must not clear active rates.
                    renderSpeed(item, sample);
                } else {
                    originalSpeedShow.call(window, item, 0, 0, 1);
                }
            }
        };

        function sampleNow() {
            window.get_speed_data();
        }
        if (document.readyState === 'loading') {
            document.addEventListener('DOMContentLoaded', function () {
                window.setTimeout(sampleNow, 0);
            }, false);
        } else {
            window.setTimeout(sampleNow, 0);
            window.setTimeout(sampleNow, 1000);
        }
    }

    function validTemperature(value) {
        var number;
        if (value === null || value === undefined || value === '') {
            return '';
        }
        number = Number(value);
        if (!isFinite(number) || number <= 0 || number > 300) {
            return '';
        }
        return Math.round(number);
    }

    function validPercent(value) {
        var number;
        if (value === null || value === undefined || value === '') {
            return '';
        }
        number = Number(value);
        if (!isFinite(number) || number < 0 || number > 100) {
            return '';
        }
        return Math.round(number);
    }

    function rememberCpe(status) {
        var name;
        if (!status || typeof status !== 'object') {
            return;
        }
        name = String(status.name || '');
        if (!name) {
            return;
        }
        temperatureStates[name] = {
            modelTemperature: validTemperature(
                status.model_temp !== undefined ? status.model_temp : status.temperature
            ),
            nrcap: String(status.nrcap === undefined ? '' : status.nrcap),
            disabled: String(status.disabled === undefined ? '' : status.disabled)
        };
    }

    function captureRuntime(data) {
        var result;
        var globalInfo;
        var cpes;
        var index;
        var fallbackCpu;

        if (!data || !data.result) {
            return;
        }
        runtimeRevision += 1;
        runtimeUpdatedAt = new Date().getTime();
        result = data.result;
        globalInfo = result.global || {};
        cpuPercent = validPercent(globalInfo.cpu_percent);
        memoryPercent = validPercent(globalInfo.mem_percent);
        cpuTemperature = validTemperature(globalInfo.device_temp);
        if (cpuTemperature === '') {
            fallbackCpu = validTemperature(globalInfo.cpu_temp);
            cpuTemperature = fallbackCpu;
        }

        cpes = result.cpe;
        if (!cpes || typeof cpes !== 'object') {
            return;
        }
        // Each CPE list is a snapshot. Retain source preferences separately,
        // but discard runtime entries for lines absent from this response.
        temperatureStates = Object.create(null);
        if (typeof cpes.length === 'number') {
            for (index = 0; index < cpes.length; index += 1) {
                rememberCpe(cpes[index]);
            }
            return;
        }
        for (index in cpes) {
            if (Object.prototype.hasOwnProperty.call(cpes, index)) {
                rememberCpe(cpes[index]);
            }
        }
    }

    function temperatureAvailable(value) {
        return value !== '' && value !== null && value !== undefined;
    }

    function isSecondary5G(name) {
        return String(name || '') === 'cpe1';
    }

    function secondary5GIsOnlyEnabledLine(name) {
        var stateName;
        var state;
        var foundSecondary = false;
        if (!isSecondary5G(name)) {
            return false;
        }
        for (stateName in temperatureStates) {
            if (!Object.prototype.hasOwnProperty.call(temperatureStates, stateName)) {
                continue;
            }
            state = temperatureStates[stateName] || {};
            if (state.disabled === '1') {
                continue;
            }
            if (stateName !== name) {
                return false;
            }
            foundSecondary = true;
        }
        return foundSecondary;
    }

    function secondary5GIsFixed(name) {
        return isSecondary5G(name) && !secondary5GIsOnlyEnabledLine(name);
    }

    function effectiveMode(name) {
        var state = temperatureStates[name] || {};
        var requested = temperatureModes[name];
        if (secondary5GIsFixed(name)) {
            return 'cpe';
        }
        if (isSecondary5G(name) && requested !== 'cpu' && requested !== 'cpe' &&
            temperatureAvailable(state.modelTemperature)) {
            return 'cpe';
        }
        if (requested === 'cpu' && temperatureAvailable(cpuTemperature)) {
            return 'cpu';
        }
        if (requested === 'cpe' && temperatureAvailable(state.modelTemperature)) {
            return 'cpe';
        }
        if (temperatureAvailable(cpuTemperature)) {
            return 'cpu';
        }
        if (temperatureAvailable(state.modelTemperature)) {
            return 'cpe';
        }
        return requested === 'cpe' ? 'cpe' : 'cpu';
    }

    function synchronizeLegacyTemperatureModes() {
        var legacyModes = window.nr_temp_modes;
        var name;
        if (!legacyModes || typeof legacyModes !== 'object') {
            return;
        }
        for (name in temperatureStates) {
            if (Object.prototype.hasOwnProperty.call(temperatureStates, name)) {
                legacyModes[name] = effectiveMode(name);
            }
        }
    }

    function cpeTemperatureLabel(state) {
        return state && (state.nrcap === '0' || state.nrcap === '') ? '4G温度' : '5G温度';
    }

    function updateTemperatureButton(button, name, mode, label, active, disabled) {
        button.type = 'button';
        button.className = 'nr-home-temp-choice' + (active && !disabled ? ' active' : '');
        button.setAttribute('data-name', name);
        button.setAttribute('data-mode', mode);
        button.setAttribute('aria-pressed', active && !disabled ? 'true' : 'false');
        button.setAttribute('aria-disabled', disabled ? 'true' : 'false');
        button.title = label + (disabled ? '：暂无数据' : '');
        button.setAttribute('aria-label', button.title);
        button.disabled = disabled;
        if (button.getAttribute('data-temperature-label') !== label) {
            button.textContent = mode === 'cpu' ? 'CPU' : label.slice(0, 2);
            button.setAttribute('data-temperature-label', label);
        }
    }

    function markTemperatureCard(node) {
        var card = node.parentNode;
        var classes;
        var group;
        while (card && card !== document) {
            classes = ' ' + (card.className || '') + ' ';
            if (classes.indexOf(' pc_box ') !== -1 && classes.indexOf(' pc_box1 ') !== -1) {
                card.setAttribute('data-nradio-home-temp-card', '1');
                group = card.parentNode;
                if (group && (' ' + (group.className || '') + ' ').indexOf(' speedflow_combine_box ') !== -1) {
                    group.setAttribute('data-nradio-home-temp-grid', '1');
                }
                return;
            }
            card = card.parentNode;
        }
    }

    function renderTemperatureLabel(node, name, mode, state) {
        var switcher = node.nradioTemperatureSwitcher;
        var buttons;
        var index = 0;
        var cpuDisabled = !temperatureAvailable(cpuTemperature);
        var cpeDisabled = !temperatureAvailable(state.modelTemperature);
        var secondaryFixed = secondary5GIsFixed(name);
        markTemperatureCard(node);
        if (!switcher) {
            switcher = document.createElement('span');
            switcher.className = 'nr-home-temp-switch';
            switcher.setAttribute('data-temperature-name', name);
            switcher.setAttribute('role', 'group');
            switcher.setAttribute('aria-label', '温度来源');
            node.nradioTemperatureSwitcher = switcher;
        }
        buttons = switcher.querySelectorAll('button');
        if (buttons.length !== (secondaryFixed ? 1 : 2)) {
            while (switcher.firstChild) {
                switcher.removeChild(switcher.firstChild);
            }
            if (!secondaryFixed) {
                switcher.appendChild(document.createElement('button'));
            }
            switcher.appendChild(document.createElement('button'));
            buttons = switcher.querySelectorAll('button');
        }
        if (!secondaryFixed) {
            updateTemperatureButton(buttons[index], name, 'cpu', 'CPU温度',
                mode === 'cpu', cpuDisabled);
            index += 1;
        }
        updateTemperatureButton(buttons[index], name, 'cpe',
            secondaryFixed ? '5G温度' : cpeTemperatureLabel(state),
            mode === 'cpe', cpeDisabled);
        if (node.firstChild !== switcher) {
            while (node.firstChild) {
                node.removeChild(node.firstChild);
            }
            node.appendChild(switcher);
        }
    }

    function formattedTemperature(value) {
        if (typeof window.format_temp_val === 'function') {
            return window.format_temp_val(value);
        }
        return temperatureAvailable(value) ? String(value) + '℃' : '-';
    }

    function formattedTemperatureDescription(value) {
        if (!temperatureAvailable(value)) {
            return '暂无温度数据';
        }
        if (typeof window.format_temp_des === 'function') {
            return window.format_temp_des(value);
        }
        return '';
    }

    function renderUsageValue(root, selector, value) {
        var nodes = root.querySelectorAll(selector);
        var text = value === '' ? '-' : String(value) + '%';
        var index;
        for (index = 0; index < nodes.length; index += 1) {
            nodes[index].textContent = text;
        }
    }

    function renderUsageDescription(root, selector, value, formatter) {
        var nodes = root.querySelectorAll(selector);
        var text = value === '' || typeof formatter !== 'function' ? '' : formatter(value);
        var index;
        for (index = 0; index < nodes.length; index += 1) {
            nodes[index].textContent = text;
        }
    }

    function renderPrimaryLineUsage() {
        var primaryBoxes = document.getElementsByClassName('box_wans_cpe');
        var index;

        for (index = 0; index < primaryBoxes.length; index += 1) {
            renderUsageValue(primaryBoxes[index], '.cpu_data', cpuPercent);
            renderUsageValue(primaryBoxes[index], '.mem_data', memoryPercent);
            renderUsageDescription(primaryBoxes[index], '.cpu_des', cpuPercent, window.format_cpu_val);
            renderUsageDescription(primaryBoxes[index], '.mem_des', memoryPercent, window.format_mem_val);
        }
    }

    function renderTemperatureGauge(gauge, id, value) {
        // The OEM gauge drops updates during animation. Settle its previous
        // value before updating, then draw the selected source synchronously.
        if (gauge && typeof gauge.drawProgressAnimate === 'function') {
            gauge.animation = false;
            gauge.percentage = gauge.progress;
            gauge.isEnd = true;
        }
        gauge = window.canvas_val_show(
            gauge, id, value, 125, window.temp_range, window.temp_lang, '℃'
        );
        if (gauge && typeof gauge.drawProgressAnimate === 'function') {
            gauge.animation = false;
            gauge.drawProgressAnimate();
        }
        return gauge;
    }

    function renderVisibleTemperatureGauge(gauge, id, value, mode) {
        var node = document.getElementById(id);
        var cached;
        var canvas;
        if (!node) {
            return gauge;
        }
        cached = node.nradioTemperatureGaugeState;
        if (document.hidden || !node.getClientRects().length) {
            if (cached) {
                cached.visible = false;
            }
            return gauge;
        }
        canvas = node.querySelector('canvas');
        // A recreated card must own its gauge, even if the WAN item still
        // references the canvas from the removed card.
        if (!canvas || (gauge && gauge.ctx && gauge.ctx.canvas !== canvas)) {
            gauge = null;
        }
        if (cached && cached.visible && cached.gauge === gauge &&
            cached.canvas === canvas && cached.value === value && cached.mode === mode &&
            cached.width === node.offsetWidth && cached.height === node.offsetHeight) {
            return gauge;
        }
        gauge = renderTemperatureGauge(gauge, id, value);
        node.nradioTemperatureGaugeState = {
            gauge: gauge,
            canvas: node.querySelector('canvas'),
            value: value,
            mode: mode,
            width: node.offsetWidth,
            height: node.offsetHeight,
            visible: true
        };
        return gauge;
    }

    function updateTemperatureGauge(name, value, mode) {
        var wanItem;
        var singleId = 'tempprogress-container-' + name + 'single';
        var multiId = 'tempprogress-container-' + name + 'multi';

        if (typeof window.get_wans_item !== 'function' ||
            typeof window.canvas_val_show !== 'function' ||
            !window.wans_data) {
            return;
        }
        wanItem = window.get_wans_item(name, window.wans_data);
        if (!wanItem) {
            return;
        }
        wanItem.arcProgressTempSingle = renderVisibleTemperatureGauge(
            wanItem.arcProgressTempSingle, singleId, value, mode
        );
        wanItem.arcProgressTempMulti = renderVisibleTemperatureGauge(
            wanItem.arcProgressTempMulti, multiId, value, mode
        );
    }

    function renderTemperature(name) {
        var state = temperatureStates[name] || {modelTemperature: '', nrcap: '', disabled: ''};
        var mode = effectiveMode(name);
        var value = mode === 'cpu' ? cpuTemperature : state.modelTemperature;
        var boxes = document.getElementsByClassName('box_wans_' + name);
        var boxIndex;
        var nodeIndex;
        var labels;
        var values;
        var descriptions;

        for (boxIndex = 0; boxIndex < boxes.length; boxIndex += 1) {
            labels = boxes[boxIndex].querySelectorAll('.rtemp_label');
            for (nodeIndex = 0; nodeIndex < labels.length; nodeIndex += 1) {
                renderTemperatureLabel(labels[nodeIndex], name, mode, state);
            }
            values = boxes[boxIndex].querySelectorAll('.model_temp');
            for (nodeIndex = 0; nodeIndex < values.length; nodeIndex += 1) {
                values[nodeIndex].textContent = formattedTemperature(value);
            }
            descriptions = boxes[boxIndex].querySelectorAll('.temp_des');
            for (nodeIndex = 0; nodeIndex < descriptions.length; nodeIndex += 1) {
                descriptions[nodeIndex].textContent = formattedTemperatureDescription(value);
            }
        }
        updateTemperatureGauge(name, value, mode);
    }

    function renderAllTemperatures() {
        var name;
        var count = 0;
        for (name in temperatureStates) {
            if (Object.prototype.hasOwnProperty.call(temperatureStates, name)) {
                renderTemperature(name);
                count += 1;
            }
        }
        if (document.documentElement) {
            document.documentElement.setAttribute('data-nradio-home-temperature-switch', VERSION);
            document.documentElement.setAttribute('data-nradio-home-temperature-count', String(count));
        }
    }

    function installStyle() {
        var style;
        if (document.getElementById('nr-home-temperature-switch-style')) {
            return;
        }
        style = document.createElement('style');
        style.id = 'nr-home-temperature-switch-style';
        style.textContent =
            'body [data-nradio-home-temp-card]>.panel-heading{padding:8px 8px 0}' +
            '[data-nradio-home-temp-card]>.panel-heading>.row{margin:0}' +
            '[data-nradio-home-temp-card]>.panel-heading>.row>div{display:flex;flex-direction:column;align-items:center;gap:4px;width:100%;padding:0}' +
            '[data-nradio-home-temp-card] .pre_info{font-size:12px;line-height:18px;min-height:18px}' +
            '[data-nradio-home-temp-card] .pre_info:empty{display:none}' +
            '[data-nradio-home-temp-card] .rtemp_label{display:block;width:100%;max-width:100%;text-align:center;line-height:0}' +
            '[data-nradio-home-temp-card] .model_temp{font-variant-numeric:tabular-nums}' +
            '.nr-home-temp-switch{display:inline-grid;grid-auto-flow:column;grid-auto-columns:minmax(0,1fr);align-items:stretch;gap:8px;width:96px;max-width:100%;box-sizing:border-box;padding:0;border:0;border-radius:0;background:transparent;vertical-align:top}' +
            '.nr-home-temp-switch>.nr-home-temp-choice{display:grid;grid-template-rows:20px;align-content:center;justify-items:center;min-width:0;box-sizing:border-box;appearance:none;-webkit-appearance:none;border:0;border-bottom:2px solid transparent;border-radius:0;background:transparent;color:#99aab4;cursor:pointer;font-family:inherit;font-size:12px;font-weight:500;line-height:20px;height:28px;min-height:28px;margin:0;padding:3px 6px;outline:none;box-shadow:none;white-space:nowrap;touch-action:manipulation;transition:border-color .15s,color .15s}' +
            '.nr-home-temp-switch>.nr-home-temp-choice.active{border-bottom-color:#71c3cc;color:#c6eff2}' +
            '.nr-home-temp-switch>.nr-home-temp-choice:hover:not(:disabled){color:#d3f4f6}' +
            '.nr-home-temp-switch>.nr-home-temp-choice:focus{outline:none;box-shadow:none}' +
            '.nr-home-temp-switch>.nr-home-temp-choice:focus-visible{box-shadow:inset 0 0 0 2px #78cdd5}' +
            '.nr-home-temp-choice:disabled{cursor:not-allowed;opacity:.45}' +
            '@media(max-width:767px){' +
            'body [data-nradio-home-temp-grid]{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:12px;float:none;width:100%;height:auto;min-height:0;margin:0 0 20px}' +
            'body [data-nradio-home-temp-grid]>.pc_box{float:none;width:auto;min-width:0;height:auto;min-height:159px;margin:0;box-sizing:border-box}' +
            '[data-nradio-home-temp-card]>.panel-body{padding:0 8px 8px}' +
            '[data-nradio-home-temp-card] [id^="tempprogress-container-"]{width:100%;max-width:130px;margin:0 auto!important}' +
            '[data-nradio-home-temp-card] canvas{display:block;max-width:100%;height:auto!important;margin:0 auto}' +
            '.nr-home-temp-switch{width:112px}' +
            '.nr-home-temp-switch>.nr-home-temp-choice{height:44px;min-height:44px;padding:4px 2px}' +
            '}';
        (document.head || document.documentElement).appendChild(style);
    }

    function findTemperatureButton(target) {
        while (target && target !== document) {
            if (target.nodeType === 1 &&
                (' ' + target.className + ' ').indexOf(' nr-home-temp-choice ') !== -1) {
                return target;
            }
            target = target.parentNode;
        }
        return null;
    }

    function handleTemperatureClick(event) {
        var button = findTemperatureButton(event.target);
        var name;
        var mode;
        if (!button || button.disabled) {
            return;
        }
        name = String(button.getAttribute('data-name') || '');
        mode = String(button.getAttribute('data-mode') || '');
        if (!name || (mode !== 'cpu' && mode !== 'cpe')) {
            return;
        }
        event.preventDefault();
        event.stopPropagation();
        if (temperatureModes[name] === mode) {
            return;
        }
        temperatureModes[name] = mode;
        saveTemperatureModes();
        if (window.nr_temp_modes && typeof window.nr_temp_modes === 'object') {
            window.nr_temp_modes[name] = effectiveMode(name);
        }
        renderTemperature(name);
        if (new Date().getTime() - runtimeUpdatedAt >= 5000) {
            refreshRuntimeNow();
        }
    }

    function installTemperatureSwitch() {
        var originalStatsInfo;
        var wrappedStatsInfo;

        if (installed) {
            return;
        }
        originalStatsInfo = window.stats_info;
        if (typeof originalStatsInfo !== 'function') {
            installAttempts += 1;
            if (installAttempts <= 40) {
                window.setTimeout(installTemperatureSwitch, 50);
            } else if (document.documentElement) {
                document.documentElement.setAttribute('data-nradio-home-temperature-switch', 'unsupported');
            }
            return;
        }

        restoreTemperatureModes();
        wrappedStatsInfo = function (data) {
            var focused = findTemperatureButton(document.activeElement);
            var result;
            var originalCanvasValShow = window.canvas_val_show;
            captureRuntime(data);
            synchronizeLegacyTemperatureModes();
            // Defer only managed temperature gauges during the OEM refresh.
            // Paint once below, after it has finished changing card visibility.
            if (typeof originalCanvasValShow === 'function') {
                window.canvas_val_show = function (gauge, id) {
                    var match = /^tempprogress-container-(.+)(single|multi)$/.exec(String(id));
                    if (match && Object.prototype.hasOwnProperty.call(temperatureStates, match[1])) {
                        return gauge;
                    }
                    return originalCanvasValShow.apply(this, arguments);
                };
            }
            try {
                result = originalStatsInfo.apply(this, arguments);
            } finally {
                window.canvas_val_show = originalCanvasValShow;
            }
            renderPrimaryLineUsage();
            renderAllTemperatures();
            if (focused && document.documentElement.contains(focused) &&
                document.activeElement !== focused &&
                (!document.activeElement || document.activeElement === document.body)) {
                focused.focus();
            }
            return result;
        };
        wrappedStatsInfo.nradioHomeTemperatureSwitch = VERSION;
        window.stats_info = wrappedStatsInfo;
        document.addEventListener('click', handleTemperatureClick, true);
        window.addEventListener('resize', renderAllTemperatures, false);
        document.addEventListener('visibilitychange', renderAllTemperatures, false);
        installStyle();
        installSpeedRefresh();
        installed = true;
        window.NRadioHomeTemperatureSwitch = {
            version: VERSION,
            render: renderAllTemperatures,
            refresh: refreshRuntimeNow
        };
        if (document.documentElement) {
            document.documentElement.setAttribute('data-nradio-home-temperature-switch', VERSION);
        }
        window.setTimeout(refreshRuntimeNow, 0);
    }

