game_accel_require_appcenter() {
    require_nradio_oem_appcenter
}

game_accel_set_appcenter_entry() {
    ga_app_name="$1"
    ga_pkg_name="$2"
    ga_version="$3"
    ga_size="$4"
    ga_route="$5"
    ga_controller="$6"
    ga_icon="$7"

    if is_c2000pro_appcenter_environment; then
        ensure_c2000pro_appcenter_config || true
    fi

    cleanup_appcenter_entry "$ga_app_name" "$ga_pkg_name" "$ga_route"
    ga_pkg_sec="$(uci add appcenter package)"
    ga_list_sec="$(uci add appcenter package_list)"

    uci set "appcenter.$ga_pkg_sec.name=$ga_app_name"
    uci set "appcenter.$ga_pkg_sec.version=$ga_version"
    uci set "appcenter.$ga_pkg_sec.size=$ga_size"
    uci set "appcenter.$ga_pkg_sec.status=1"
    uci set "appcenter.$ga_pkg_sec.has_luci=1"
    uci set "appcenter.$ga_pkg_sec.open=1"
    uci set "appcenter.$ga_pkg_sec.icon=$ga_icon"

    uci set "appcenter.$ga_list_sec.name=$ga_app_name"
    uci set "appcenter.$ga_list_sec.pkg_name=$ga_pkg_name"
    uci set "appcenter.$ga_list_sec.parent=$ga_app_name"
    uci set "appcenter.$ga_list_sec.size=$ga_size"
    uci set "appcenter.$ga_list_sec.luci_module_file=$ga_controller"
    uci set "appcenter.$ga_list_sec.luci_module_route=$ga_route"
    uci set "appcenter.$ga_list_sec.version=$ga_version"
    uci set "appcenter.$ga_list_sec.has_luci=1"
    uci set "appcenter.$ga_list_sec.type=1"
    uci set "appcenter.$ga_list_sec.icon=$ga_icon"
    uci -q commit appcenter >/dev/null 2>&1 || true
}

docker_require_supported_model() {
    case "${CURRENT_DETECTED_MODEL:-}" in
        NRadio_C5800-650|NRadio_C5800-688|NRadio_C8-688|NRadio_C2000Ultra)
            return 0
            ;;
    esac
    die "Docker 仅支持 NRadio_C5800-650 / NRadio_C5800-688 / NRadio_C8-688 / NRadio_C2000Ultra，当前机型：${CURRENT_DETECTED_MODEL:-unknown}"
}

docker_prepare_storage() {
    local docker_storage_mount docker_storage_apps_dir docker_storage_label
    local docker_mount_fstype docker_mount_options docker_expected_root docker_existing_root
    local docker_link_root docker_link_target docker_manifest_root docker_uci_root docker_daemon_root

    if [ "${CURRENT_DETECTED_MODEL:-}" = 'NRadio_C2000Ultra' ]; then
        docker_storage_mount="$(detect_c2000max_storage_mount 2>/dev/null || true)"
        [ -n "$docker_storage_mount" ] || die "Docker 安装需要已挂载的 SD 存储卡"
        docker_mount_fstype="$(awk -v m="$docker_storage_mount" '$2 == m { print $3; exit }' /proc/mounts 2>/dev/null || true)"
        docker_mount_options="$(awk -v m="$docker_storage_mount" '$2 == m { print $4; exit }' /proc/mounts 2>/dev/null || true)"
        case "$docker_mount_fstype" in
            ext2|ext3|ext4|f2fs|btrfs|xfs) ;;
            *) die "Docker 存储卡文件系统不支持：${docker_mount_fstype:-unknown}，需要支持 Unix 权限和链接的文件系统" ;;
        esac
        case ",$docker_mount_options," in
            *,noexec,*) die "Docker 存储卡以 noexec 挂载，无法运行卡上的程序：$docker_storage_mount" ;;
        esac
        docker_storage_apps_dir="$docker_storage_mount/nradio-apps"
        docker_storage_label='SD 存储卡'
        docker_expected_root="$docker_storage_apps_dir/docker"

        docker_link_root=''
        if [ -L /usr/bin/docker ]; then
            docker_link_target="$(readlink -f /usr/bin/docker 2>/dev/null || readlink /usr/bin/docker 2>/dev/null || true)"
            case "$docker_link_target" in
                */nradio-apps/docker/opt/usr/bin/docker)
                    docker_link_root="${docker_link_target%/opt/usr/bin/docker}"
                    ;;
            esac
        fi
        docker_manifest_root=''
        if [ -s "$DOCKER_PAYLOAD_MANIFEST" ]; then
            docker_manifest_root="$(awk -F'|' '$1 == "root" { print $2; exit }' "$DOCKER_PAYLOAD_MANIFEST" 2>/dev/null || true)"
        fi
        for docker_existing_root in "$docker_link_root" "$docker_manifest_root"; do
            [ -z "$docker_existing_root" ] || [ "$docker_existing_root" = "$docker_expected_root" ] ||
                die "Docker 原目录为 $docker_existing_root，当前存储卡路径为 $docker_expected_root；请先挂载原存储卡"
        done
        docker_uci_root="$(uci -q get dockerd.globals.data_root 2>/dev/null || true)"
        docker_daemon_root="$(sed -n 's/.*"data-root"[[:space:]]*:[[:space:]]*"\([^"]*\)".*/\1/p' /etc/docker/daemon.json 2>/dev/null | sed -n '1p' || true)"
        for docker_existing_root in "$docker_uci_root" "$docker_daemon_root"; do
            [ -z "$docker_existing_root" ] || [ "$docker_existing_root" = "$docker_expected_root/data" ] ||
                die "Docker 已配置的数据目录为 $docker_existing_root，当前存储卡路径为 $docker_expected_root/data；请先核对原存储卡"
        done
    else
        storage_expand_require_active
        docker_storage_mount="$ROOTFS_2ND_STORAGE_MOUNT_POINT"
        docker_storage_apps_dir="$ROOTFS_2ND_STORAGE_APPS_DIR"
        docker_storage_label='扩展盘'
    fi

    docker_avail_kib="$(get_mount_available_kib "$docker_storage_mount" 2>/dev/null || true)"
    case "$docker_avail_kib" in
        ''|*[!0-9]*)
            die "Docker 存储盘空间读取失败：$docker_storage_mount"
            ;;
    esac
    docker_avail_mib=$((docker_avail_kib / 1024))
    [ "$docker_avail_mib" -ge "$DOCKER_MIN_FREE_MIB" ] 2>/dev/null || die "Docker 存储盘可用空间不足：需要 ${DOCKER_MIN_FREE_MIB}M，当前 ${docker_avail_mib}M"

    DOCKER_ROOT="$docker_storage_apps_dir/docker"
    DOCKER_DATA_ROOT="$DOCKER_ROOT/data"
    DOCKER_PACKAGE_DIR="$DOCKER_ROOT/packages"
    DOCKER_OPKG_CACHE="$DOCKER_ROOT/opkg-cache"
    DOCKER_TMP_DIR="$DOCKER_ROOT/tmp"
    DOCKER_LOG_DIR="$DOCKER_ROOT/log"
    DOCKER_OPT_DIR="$DOCKER_ROOT/opt"
    WORKDIR="$DOCKER_ROOT/work.$$"
    log "$docker_storage_label: $docker_storage_mount，可用 ${docker_avail_mib}M"
    log "Docker: $DOCKER_ROOT"
}

docker_create_storage_dirs() {
    local docker_storage_mount docker_storage_apps_dir docker_path docker_mount_real docker_root_real docker_real_path
    docker_storage_mount="${DOCKER_ROOT%/nradio-apps/docker}"
    docker_storage_apps_dir="$docker_storage_mount/nradio-apps"

    if [ "${CURRENT_DETECTED_MODEL:-}" = 'NRadio_C2000Ultra' ]; then
        awk -v m="$docker_storage_mount" '$1 ~ /^\/dev\/mmcblk[0-9]+p[0-9]+$/ && $2 == m { found=1 } END { exit !found }' /proc/mounts 2>/dev/null ||
            die "Docker 安装需要 SD 存储卡保持挂载：$docker_storage_mount"
        for docker_path in "$docker_storage_apps_dir" "$DOCKER_ROOT" "$DOCKER_DATA_ROOT" "$DOCKER_PACKAGE_DIR" "$DOCKER_OPKG_CACHE" "$DOCKER_TMP_DIR" "$DOCKER_LOG_DIR" "$DOCKER_OPT_DIR" "$WORKDIR"; do
            [ ! -L "$docker_path" ] || die "Docker 存储路径不能是软链接：$docker_path"
        done
    fi
    mkdir -p "$DOCKER_DATA_ROOT" "$DOCKER_PACKAGE_DIR" "$DOCKER_OPKG_CACHE" "$DOCKER_TMP_DIR" "$DOCKER_LOG_DIR" "$DOCKER_OPT_DIR" "$WORKDIR" || die "创建 Docker 存储盘目录失败"

    if [ "${CURRENT_DETECTED_MODEL:-}" = 'NRadio_C2000Ultra' ]; then
        docker_mount_real="$(readlink -f "$docker_storage_mount" 2>/dev/null || true)"
        docker_root_real="$(readlink -f "$DOCKER_ROOT" 2>/dev/null || true)"
        [ -n "$docker_mount_real" ] && [ "$docker_root_real" = "$docker_mount_real/nradio-apps/docker" ] || die "Docker 存储目录未落在 SD 存储卡上"
        for docker_path in "$DOCKER_DATA_ROOT" "$DOCKER_PACKAGE_DIR" "$DOCKER_OPKG_CACHE" "$DOCKER_TMP_DIR" "$DOCKER_LOG_DIR" "$DOCKER_OPT_DIR" "$WORKDIR"; do
            docker_real_path="$(readlink -f "$docker_path" 2>/dev/null || true)"
            [ "$docker_real_path" = "$docker_root_real/${docker_path##*/}" ] || die "Docker 子目录未落在 SD 存储卡上：$docker_path"
        done
    fi
    ensure_dir_writable "$DOCKER_ROOT" "$DOCKER_ROOT"
    ensure_dir_writable "$DOCKER_PACKAGE_DIR" "$DOCKER_PACKAGE_DIR"
    ensure_dir_writable "$DOCKER_TMP_DIR" "$DOCKER_TMP_DIR"
    ensure_dir_writable "$DOCKER_DATA_ROOT" "$DOCKER_DATA_ROOT"
    if [ "${CURRENT_DETECTED_MODEL:-}" = 'NRadio_C2000Ultra' ]; then
        chmod 755 "$docker_storage_apps_dir" "$DOCKER_ROOT" "$DOCKER_DATA_ROOT" 2>/dev/null || true
    else
        chmod 755 "$docker_storage_mount" "$docker_storage_apps_dir" "$DOCKER_ROOT" "$DOCKER_DATA_ROOT" 2>/dev/null || true
    fi
}

docker_resolve_feed_index_file() {
    docker_feed_name="$1"
    docker_feed_url="$2"
    docker_feed_idx="$WORKDIR/feed-index/${docker_feed_name}.Packages"
    docker_local_feed_idx=""

    docker_local_feed_idx="$(find_local_feed_index_file "$docker_feed_name" 2>/dev/null || true)"
    if [ -n "$docker_local_feed_idx" ] && [ -s "$docker_local_feed_idx" ]; then
        printf '%s\n' "$docker_local_feed_idx"
        return 0
    fi

    if [ -s "$docker_feed_idx" ] && feed_index_is_plain_packages "$docker_feed_idx"; then
        printf '%s\n' "$docker_feed_idx"
        return 0
    fi

    download_feed_index_file "$docker_feed_name" "$docker_feed_url"
}

docker_get_feed_package_field() {
    docker_feed_name="$1"
    docker_package_name="$2"
    docker_field_name="$3"

    docker_feed_url="$(get_feed_url "$docker_feed_name")"
    [ -n "$docker_feed_url" ] || return 1
    docker_feed_idx="$(docker_resolve_feed_index_file "$docker_feed_name" "$docker_feed_url" 2>/dev/null || true)"
    [ -n "$docker_feed_idx" ] || return 1
    read_feed_package_field_from_index "$docker_feed_idx" "$docker_package_name" "$docker_field_name"
}

docker_resolve_package_meta_any_feed() {
    docker_package_name="$1"
    docker_feed_names="$(awk '$1=="src/gz" {print $2}' "$FEEDS" 2>/dev/null)"

    for docker_feed_name in $docker_feed_names; do
        [ -n "$docker_feed_name" ] || continue
        docker_feed_url="$(get_feed_url "$docker_feed_name")"
        [ -n "$docker_feed_url" ] || continue
        docker_filename="$(docker_get_feed_package_field "$docker_feed_name" "$docker_package_name" Filename 2>/dev/null || true)"
        [ -n "$docker_filename" ] || continue
        docker_version="$(docker_get_feed_package_field "$docker_feed_name" "$docker_package_name" Version 2>/dev/null || true)"
        printf '%s|%s|%s|%s\n' "$docker_feed_name" "$docker_feed_url" "$docker_filename" "$docker_version"
        return 0
    done

    return 1
}

docker_download_package_ipk_from_feeds() {
    docker_pkg="$1"
    docker_meta="$(docker_resolve_package_meta_any_feed "$docker_pkg" 2>/dev/null || true)"
    [ -n "$docker_meta" ] || return 1

    IFS='|' read -r docker_feed_name docker_feed_url docker_filename docker_version <<EOF_DOCKER_META
$docker_meta
EOF_DOCKER_META

    docker_ipk_name="$(basename "$docker_filename")"
    docker_out="$DOCKER_PACKAGE_DIR/$docker_ipk_name"
    if [ -s "$docker_out" ]; then
        printf '%s\n' "$docker_out"
        return 0
    fi

    docker_urls="$(build_package_download_urls_from_meta "$docker_feed_url" "$docker_filename" 2>/dev/null || true)"
    [ -n "$docker_urls" ] || return 1
    download_from_urls "$docker_out" $docker_urls >/dev/null || return 1
    printf '%s\n' "$docker_out"
}

docker_package_depends_any_feed() {
    docker_pkg="$1"
    docker_meta="$(docker_resolve_package_meta_any_feed "$docker_pkg" 2>/dev/null || true)"
    [ -n "$docker_meta" ] || return 1
    docker_feed_name="${docker_meta%%|*}"
    docker_depends="$(docker_get_feed_package_field "$docker_feed_name" "$docker_pkg" Depends 2>/dev/null || true)"
    [ -n "$docker_depends" ] || return 0
    printf '%s\n' "$docker_depends" | tr ',' '\n' | while IFS= read -r docker_dep; do
        docker_dep="$(printf '%s\n' "$docker_dep" | sed 's/(.*//; s/|.*//; s/^[[:space:]]*//; s/[[:space:]]*$//')"
        [ -n "$docker_dep" ] || continue
        case "$docker_dep" in
            kernel|libc|libgcc|libpthread|librt|libstdcpp|kmod-*) continue ;;
        esac
        printf '%s\n' "$docker_dep"
    done
}

docker_package_queue_has() {
    docker_need="$1"
    docker_list="$2"
    printf '%s\n' "$docker_list" | grep -Fxq "$docker_need"
}

docker_download_package_closure() {
    docker_queue="$(printf '%s\n' docker dockerd containerd runc cgroupfs-mount)"
    docker_done_pkgs=""
    docker_downloaded_paths=""
    docker_guard=0

    while [ -n "$docker_queue" ]; do
        docker_pkg="$(printf '%s\n' "$docker_queue" | sed -n '1p')"
        docker_queue="$(printf '%s\n' "$docker_queue" | sed '1d')"
        [ -n "$docker_pkg" ] || continue
        docker_package_queue_has "$docker_pkg" "$docker_done_pkgs" && continue
        docker_done_pkgs="$(printf '%s\n%s\n' "$docker_done_pkgs" "$docker_pkg" | sed '/^$/d')"

        case "$docker_pkg" in
            kernel|libc|libgcc|libpthread|librt|libstdcpp|kmod-*)
                continue
                ;;
        esac

        docker_ipk_path="$(docker_download_package_ipk_from_feeds "$docker_pkg" 2>/dev/null || true)"
        [ -n "$docker_ipk_path" ] || {
            case "$docker_pkg" in
                docker|dockerd|containerd|runc)
                    die "当前软件源无法解析 Docker 必需包：$docker_pkg"
                    ;;
                *)
                    continue
                    ;;
            esac
        }
        docker_downloaded_paths="$docker_downloaded_paths $docker_ipk_path"

        docker_deps="$(docker_package_depends_any_feed "$docker_pkg" 2>/dev/null || true)"
        for docker_dep in $docker_deps; do
            [ -n "$docker_dep" ] || continue
            docker_package_queue_has "$docker_dep" "$docker_done_pkgs" && continue
            docker_package_queue_has "$docker_dep" "$docker_queue" && continue
            docker_queue="$(printf '%s\n%s\n' "$docker_queue" "$docker_dep" | sed '/^$/d')"
        done

        docker_guard=$((docker_guard + 1))
        [ "$docker_guard" -le 160 ] || die "Docker 依赖解析超过上限，已停止"
    done

    printf '%s\n' "$docker_downloaded_paths"
}

docker_extract_ipk_data_to_opt() {
    docker_ipk_path="$1"
    docker_pkg_dir="$WORKDIR/ipk.$(basename "$docker_ipk_path" .ipk)"
    rm -rf "$docker_pkg_dir" 2>/dev/null || true
    mkdir -p "$docker_pkg_dir"
    tar -xzf "$docker_ipk_path" -C "$docker_pkg_dir" >/dev/null 2>&1 || die "解包 ipk 失败：$docker_ipk_path"
    if [ -f "$docker_pkg_dir/data.tar.gz" ]; then
        tar -xzf "$docker_pkg_dir/data.tar.gz" -C "$DOCKER_OPT_DIR" >/dev/null 2>&1 || die "解压 data.tar.gz 失败：$docker_ipk_path"
    elif [ -f "$docker_pkg_dir/data.tar.xz" ]; then
        tar -xJf "$docker_pkg_dir/data.tar.xz" -C "$DOCKER_OPT_DIR" >/dev/null 2>&1 || die "解压 data.tar.xz 失败：$docker_ipk_path"
    else
        die "ipk 缺少 data.tar.gz/data.tar.xz：$docker_ipk_path"
    fi
}

docker_payload_symlink_allowed() {
    case "$1" in
        /usr/bin/docker|/usr/bin/dockerd|/usr/sbin/dockerd|\
        /usr/bin/containerd|/usr/bin/containerd-shim|\
        /usr/bin/containerd-shim-runc-v1|/usr/bin/containerd-shim-runc-v2|\
        /usr/bin/ctr|/usr/bin/runc|/usr/sbin/runc|\
        /usr/bin/docker-init|/usr/bin/docker-proxy|/usr/bin/tini)
            return 0
            ;;
    esac
    return 1
}

docker_payload_copy_allowed() {
    case "$1" in
        /usr/bin/btrfs|/usr/bin/btrfs-map-logical|/usr/bin/btrfs-select-super|\
        /usr/bin/cgroupfs-mount|/usr/bin/cgroupfs-umount|\
        /usr/bin/containerd-stress|/usr/bin/dnet|\
        /usr/bin/findmnt|/usr/bin/mountpoint|\
        /etc/init.d/dockerd|/etc/init.d/cgroupfs-mount)
            return 0
            ;;
    esac
    return 1
}

docker_payload_manifest_path_allowed() {
    case "$1" in
        /lib/*|/usr/lib/*)
            return 0
            ;;
    esac
    docker_payload_symlink_allowed "$1" && return 0
    docker_payload_copy_allowed "$1" && return 0
    return 1
}

docker_payload_digest() {
    docker_digest_path="$1"
    [ -f "$docker_digest_path" ] || return 1

    if command -v sha256sum >/dev/null 2>&1; then
        docker_digest_value="$(sha256sum "$docker_digest_path" 2>/dev/null | awk '{print $1; exit}')"
        [ -n "$docker_digest_value" ] || return 1
        printf 'sha256:%s\n' "$docker_digest_value"
        return 0
    fi
    if command -v cksum >/dev/null 2>&1; then
        docker_digest_value="$(cksum "$docker_digest_path" 2>/dev/null | awk '{print $1 ":" $2; exit}')"
        [ -n "$docker_digest_value" ] || return 1
        printf 'cksum:%s\n' "$docker_digest_value"
        return 0
    fi
    return 1
}

docker_payload_digest_for_expected() {
    docker_digest_path="$1"
    docker_expected_digest="$2"
    [ -f "$docker_digest_path" ] || return 1

    case "$docker_expected_digest" in
        sha256:*)
            command -v sha256sum >/dev/null 2>&1 || return 1
            docker_digest_value="$(sha256sum "$docker_digest_path" 2>/dev/null | awk '{print $1; exit}')"
            [ -n "$docker_digest_value" ] || return 1
            printf 'sha256:%s\n' "$docker_digest_value"
            ;;
        cksum:*)
            command -v cksum >/dev/null 2>&1 || return 1
            docker_digest_value="$(cksum "$docker_digest_path" 2>/dev/null | awk '{print $1 ":" $2; exit}')"
            [ -n "$docker_digest_value" ] || return 1
            printf 'cksum:%s\n' "$docker_digest_value"
            ;;
        *)
            return 1
            ;;
    esac
}

docker_payload_manifest_prepare() {
    ensure_state_dir
    mkdir -p "$WORKDIR" >/dev/null 2>&1 || die "创建 Docker 清单工作目录失败"
    if [ ! -f "$DOCKER_PAYLOAD_MANIFEST" ] || [ "$(sed -n '1p' "$DOCKER_PAYLOAD_MANIFEST" 2>/dev/null || true)" != 'NRADIO_DOCKER_PAYLOAD_MANIFEST=1' ]; then
        docker_manifest_tmp="$WORKDIR/docker-payload-manifest.prepare.$$"
        printf '%s\n' 'NRADIO_DOCKER_PAYLOAD_MANIFEST=1' > "$docker_manifest_tmp" || die "创建 Docker 系统文件清单失败"
        mv -f "$docker_manifest_tmp" "$DOCKER_PAYLOAD_MANIFEST" || die "写入 Docker 系统文件清单失败"
    fi

    if [ -n "${DOCKER_ROOT:-}" ]; then
        docker_manifest_tmp="$WORKDIR/docker-payload-manifest.root.$$"
        awk -F'|' '$1 != "root" { print }' "$DOCKER_PAYLOAD_MANIFEST" > "$docker_manifest_tmp" || {
            rm -f "$docker_manifest_tmp" 2>/dev/null || true
            die "更新 Docker 存储根清单失败"
        }
        printf 'root|%s|\n' "$DOCKER_ROOT" >> "$docker_manifest_tmp" || {
            rm -f "$docker_manifest_tmp" 2>/dev/null || true
            die "记录 Docker 存储根失败"
        }
        mv -f "$docker_manifest_tmp" "$DOCKER_PAYLOAD_MANIFEST" || die "提交 Docker 存储根清单失败"
    fi
    chmod 600 "$DOCKER_PAYLOAD_MANIFEST" 2>/dev/null || true
}

docker_payload_manifest_reset() {
    ensure_state_dir
    mkdir -p "$WORKDIR" >/dev/null 2>&1 || die "创建 Docker 清单工作目录失败"
    docker_manifest_tmp="$WORKDIR/docker-payload-manifest.reset.$$"
    printf '%s\n' 'NRADIO_DOCKER_PAYLOAD_MANIFEST=1' > "$docker_manifest_tmp" || die "重建 Docker 系统文件清单失败"
    [ -n "${DOCKER_ROOT:-}" ] && printf 'root|%s|\n' "$DOCKER_ROOT" >> "$docker_manifest_tmp"
    mv -f "$docker_manifest_tmp" "$DOCKER_PAYLOAD_MANIFEST" || die "提交 Docker 系统文件清单失败"
    chmod 600 "$DOCKER_PAYLOAD_MANIFEST" 2>/dev/null || true
}

docker_payload_manifest_matches_path() {
    docker_match_path="$1"
    [ -s "$DOCKER_PAYLOAD_MANIFEST" ] || return 1

    while IFS='|' read -r docker_match_mode docker_record_path docker_expected; do
        [ "$docker_record_path" = "$docker_match_path" ] || continue
        case "$docker_match_mode" in
            link)
                [ -L "$docker_match_path" ] || continue
                [ "$(readlink "$docker_match_path" 2>/dev/null || true)" = "$docker_expected" ] && return 0
                ;;
            copy)
                [ -f "$docker_match_path" ] || continue
                docker_actual="$(docker_payload_digest_for_expected "$docker_match_path" "$docker_expected" 2>/dev/null || true)"
                [ -n "$docker_actual" ] && [ "$docker_actual" = "$docker_expected" ] && return 0
                ;;
        esac
    done < "$DOCKER_PAYLOAD_MANIFEST"
    return 1
}

docker_payload_manifest_record() {
    docker_record_mode="$1"
    docker_record_path="$2"
    docker_record_evidence="$3"

    docker_payload_manifest_prepare
    docker_manifest_tmp="$WORKDIR/docker-payload-manifest.record.$$"
    awk -F'|' -v record_path="$docker_record_path" 'NR == 1 || $1 == "root" || $2 != record_path { print }' "$DOCKER_PAYLOAD_MANIFEST" > "$docker_manifest_tmp" || {
        rm -f "$docker_manifest_tmp" 2>/dev/null || true
        die "更新 Docker 系统文件清单失败：$docker_record_path"
    }
    printf '%s|%s|%s\n' "$docker_record_mode" "$docker_record_path" "$docker_record_evidence" >> "$docker_manifest_tmp" || {
        rm -f "$docker_manifest_tmp" 2>/dev/null || true
        die "记录 Docker 系统文件失败：$docker_record_path"
    }
    mv -f "$docker_manifest_tmp" "$DOCKER_PAYLOAD_MANIFEST" || die "提交 Docker 系统文件清单失败：$docker_record_path"
    chmod 600 "$DOCKER_PAYLOAD_MANIFEST" 2>/dev/null || true
}

docker_payload_path_owned_by_other_opkg() {
    docker_owned_path="$1"
    for docker_pkg_list in /usr/lib/opkg/info/*.list; do
        [ -f "$docker_pkg_list" ] || continue
        docker_pkg_list_name="$(basename "$docker_pkg_list")"
        case "$docker_pkg_list_name" in
            docker.list|dockerd.list|containerd.list|runc.list|cgroupfs-mount.list|tini.list|docker-init.list|docker-proxy.list|nradio-docker.list)
                continue
                ;;
        esac
        grep -Fxq "$docker_owned_path" "$docker_pkg_list" 2>/dev/null && return 0
    done
    return 1
}

docker_cleanup_legacy_payloads_for_install() {
    [ -d "$DOCKER_OPT_DIR" ] || return 0

    find "$DOCKER_OPT_DIR" -type f 2>/dev/null | while IFS= read -r docker_legacy_src; do
        [ -n "$docker_legacy_src" ] || continue
        docker_legacy_rel="${docker_legacy_src#$DOCKER_OPT_DIR/}"
        docker_legacy_dst="/$docker_legacy_rel"
        docker_payload_manifest_path_allowed "$docker_legacy_dst" || continue
        docker_payload_path_owned_by_other_opkg "$docker_legacy_dst" && continue

        case "$docker_legacy_dst" in
            /lib/*|/usr/lib/*)
                if [ -e "/rom$docker_legacy_dst" ] || [ -L "/rom$docker_legacy_dst" ]; then
                    continue
                fi
                ;;
        esac

        if [ -L "$docker_legacy_dst" ]; then
            case "$(readlink "$docker_legacy_dst" 2>/dev/null || true)" in
                "$DOCKER_OPT_DIR"/*)
                    rm -f "$docker_legacy_dst" 2>/dev/null || die "清理旧 Docker 链接失败：$docker_legacy_dst"
                    ;;
            esac
        elif [ -f "$docker_legacy_dst" ] && cmp -s "$docker_legacy_src" "$docker_legacy_dst"; then
            rm -f "$docker_legacy_dst" 2>/dev/null || die "清理旧 Docker 系统文件失败：$docker_legacy_dst"
        fi
    done
}

docker_cleanup_recorded_payloads_for_install() {
    [ -s "$DOCKER_PAYLOAD_MANIFEST" ] || return 0

    while IFS='|' read -r docker_cleanup_mode docker_cleanup_path docker_cleanup_expected; do
        case "$docker_cleanup_mode" in
            link|copy) ;;
            *) continue ;;
        esac
        [ -n "$docker_cleanup_path" ] || continue
        docker_payload_manifest_path_allowed "$docker_cleanup_path" || continue
        if docker_payload_path_owned_by_other_opkg "$docker_cleanup_path"; then
            log "提示: Docker 清单路径现由其他 opkg 软件包接管，保留不删：$docker_cleanup_path"
            continue
        fi
        case "$docker_cleanup_mode" in
            link)
                [ -L "$docker_cleanup_path" ] || continue
                [ "$(readlink "$docker_cleanup_path" 2>/dev/null || true)" = "$docker_cleanup_expected" ] || continue
                ;;
            copy)
                [ -f "$docker_cleanup_path" ] || continue
                docker_cleanup_actual="$(docker_payload_digest_for_expected "$docker_cleanup_path" "$docker_cleanup_expected" 2>/dev/null || true)"
                [ -n "$docker_cleanup_actual" ] && [ "$docker_cleanup_actual" = "$docker_cleanup_expected" ] || continue
                ;;
        esac
        rm -f "$docker_cleanup_path" 2>/dev/null || die "清理旧 Docker 系统文件失败：$docker_cleanup_path"
    done < "$DOCKER_PAYLOAD_MANIFEST"

    docker_payload_manifest_reset
}

docker_restore_system_busybox_command() {
    docker_cmd_name="$1"
    docker_cmd_path="/usr/bin/$docker_cmd_name"
    [ -L "$docker_cmd_path" ] || return 0
    case "$(readlink "$docker_cmd_path" 2>/dev/null || true)" in
        "$DOCKER_OPT_DIR"/*)
            rm -f "$docker_cmd_path" 2>/dev/null || true
            if [ -x "/bin/$docker_cmd_name" ]; then
                ln -s "/bin/$docker_cmd_name" "$docker_cmd_path" 2>/dev/null || true
            elif [ -x /bin/busybox ]; then
                ln -s /bin/busybox "$docker_cmd_path" 2>/dev/null || true
            fi
            ;;
    esac
}

docker_restore_rom_backed_lib() {
    docker_lib_path="$1"
    [ -L "$docker_lib_path" ] || return 0
    case "$(readlink "$docker_lib_path" 2>/dev/null || true)" in
        "$DOCKER_OPT_DIR"/*)
            if [ -f "/rom$docker_lib_path" ]; then
                rm -f "$docker_lib_path" 2>/dev/null || true
                cp "/rom$docker_lib_path" "$docker_lib_path" || die "恢复系统库失败：$docker_lib_path"
                chmod 644 "$docker_lib_path" 2>/dev/null || true
            else
                rm -f "$docker_lib_path" 2>/dev/null || true
            fi
            ;;
    esac
}

docker_restore_polluted_system_paths() {
    docker_restore_system_busybox_command mount
    docker_restore_system_busybox_command umount

    for docker_lib_path in \
        /usr/lib/libattr.so.1.1.2448 \
        /usr/lib/libblkid.so.1.1.0 \
        /usr/lib/libmount.so.1.1.0 \
        /usr/lib/libsmartcols.so.1.1.0 \
        /usr/lib/libuuid.so.1.3.0 \
        /usr/lib/libz.so /usr/lib/libz.so.1 /usr/lib/libz.so.1.2.11; do
        docker_restore_rom_backed_lib "$docker_lib_path"
    done
}

docker_install_one_payload_file() {
    docker_src="$1"
    docker_rel="${docker_src#$DOCKER_OPT_DIR/}"
    docker_dst="/$docker_rel"
    docker_dst_dir="$(dirname "$docker_dst")"
    docker_payload_install_mode=""

    case "$docker_dst" in
        /lib/*|/usr/lib/*)
            if [ -e "/rom$docker_dst" ] || [ -L "/rom$docker_dst" ]; then
                return 0
            fi
            docker_payload_install_mode="copy"
            ;;
        /bin/*|/sbin/*|/usr/bin/*|/usr/sbin/*|/etc/init.d/*)
            if docker_payload_symlink_allowed "$docker_dst"; then
                docker_payload_install_mode="link"
            elif docker_payload_copy_allowed "$docker_dst"; then
                docker_payload_install_mode="copy"
            else
                return 0
            fi
            ;;
        *)
            return 0
            ;;
    esac

    mkdir -p "$docker_dst_dir"
    if [ -e "$docker_dst" ] || [ -L "$docker_dst" ]; then
        docker_existing_owned='0'
        if docker_payload_manifest_matches_path "$docker_dst"; then
            docker_existing_owned='1'
        elif [ -L "$docker_dst" ]; then
            case "$(readlink "$docker_dst" 2>/dev/null || true)" in
                "$DOCKER_OPT_DIR"/*) docker_existing_owned='1' ;;
            esac
        fi
        if [ "$docker_existing_owned" != '1' ]; then
            log "提示: 保留非本脚本管理的现有文件，跳过 Docker 覆盖：$docker_dst"
            return 0
        fi
        rm -f "$docker_dst" 2>/dev/null || true
    fi
    case "$docker_payload_install_mode" in
        link)
            docker_payload_manifest_record link "$docker_dst" "$docker_src"
            ln -sf "$docker_src" "$docker_dst" || die "创建 Docker 入口链接失败：$docker_dst -> $docker_src"
            chmod +x "$docker_src" 2>/dev/null || true
            ;;
        copy)
            docker_copy_digest="$(docker_payload_digest "$docker_src" 2>/dev/null || true)"
            [ -n "$docker_copy_digest" ] || die "计算 Docker 源文件校验值失败：$docker_src"
            docker_payload_manifest_record copy "$docker_dst" "$docker_copy_digest"
            cp "$docker_src" "$docker_dst" || {
                rm -f "$docker_dst" 2>/dev/null || true
                die "写入 Docker 依赖文件失败：$docker_dst"
            }
            case "$docker_dst" in
                /bin/*|/sbin/*|/usr/bin/*|/usr/sbin/*|/usr/libexec/*|/etc/init.d/*)
                    chmod 755 "$docker_dst" 2>/dev/null || true
                    ;;
                /lib/*|/usr/lib/*)
                    chmod 644 "$docker_dst" 2>/dev/null || true
                    ;;
            esac
            docker_copy_actual="$(docker_payload_digest "$docker_dst" 2>/dev/null || true)"
            if [ -z "$docker_copy_actual" ] || [ "$docker_copy_actual" != "$docker_copy_digest" ]; then
                rm -f "$docker_dst" 2>/dev/null || true
                die "Docker 系统文件写入校验失败：$docker_dst"
            fi
            ;;
    esac
}

docker_install_payload_tree_to_system() {
    docker_restore_polluted_system_paths
    docker_payload_manifest_prepare
    for docker_rel_dir in bin sbin usr/bin usr/sbin usr/lib usr/libexec lib etc/init.d; do
        [ -d "$DOCKER_OPT_DIR/$docker_rel_dir" ] || continue
        find "$DOCKER_OPT_DIR/$docker_rel_dir" -type f 2>/dev/null | while IFS= read -r docker_src; do
            [ -n "$docker_src" ] || continue
            docker_install_one_payload_file "$docker_src"
        done
    done
}

docker_cleanup_overlay_failed_files() {
    docker_cleanup_recorded_payloads_for_install
    docker_cleanup_legacy_payloads_for_install
    for docker_path in \
        /usr/bin/docker \
        /usr/bin/dockerd \
        /usr/sbin/dockerd \
        /usr/bin/containerd \
        /usr/bin/containerd-shim \
        /usr/bin/containerd-shim-runc-v1 \
        /usr/bin/containerd-shim-runc-v2 \
        /usr/bin/ctr \
        /usr/bin/runc \
        /usr/sbin/runc; do
        [ -e "$docker_path" ] || [ -L "$docker_path" ] || continue
        docker_cleanup_owned='0'
        if docker_payload_manifest_matches_path "$docker_path"; then
            docker_cleanup_owned='1'
        elif [ -L "$docker_path" ]; then
            case "$(readlink "$docker_path" 2>/dev/null || true)" in
                "$DOCKER_OPT_DIR"/*) docker_cleanup_owned='1' ;;
            esac
        fi
        if [ "$docker_cleanup_owned" = '1' ]; then
            rm -f "$docker_path" 2>/dev/null || true
        else
            log "提示: 保留非本脚本管理的现有 Docker 命令：$docker_path"
        fi
    done
    # Existing opkg records belong to opkg, even when a command was preserved above.
    rm -rf /tmp/nradio-docker-* 2>/dev/null || true
}

docker_opkg_supports_cache() {
    opkg --help 2>&1 | grep -q -- "--cache"
}

docker_opkg_cached() {
    export TMPDIR="$DOCKER_TMP_DIR"
    if docker_opkg_supports_cache; then
        opkg --cache "$DOCKER_OPKG_CACHE" "$@"
    else
        opkg "$@"
    fi
}

docker_ensure_opkg_update() {
    ensure_default_feeds
    if docker_opkg_cached update > "$DOCKER_LOG_DIR/opkg.update.log" 2>&1; then
        log "软件源: opkg update 完成"
        return 0
    fi
    sed -n '1,120p' "$DOCKER_LOG_DIR/opkg.update.log" >&2 || true
    die "opkg update 失败"
}

docker_install_packages_to_expand_disk() {
    export TMPDIR="$DOCKER_TMP_DIR"
    docker_ensure_opkg_update
    log "缓存:   Docker package cache = $DOCKER_PACKAGE_DIR"
    log "缓存:   Docker workdir = $WORKDIR"
    docker_cleanup_overlay_failed_files
    docker_restore_polluted_system_paths
    docker_package_paths="$(docker_download_package_closure)" || die "Docker 包下载失败"
    [ -n "$docker_package_paths" ] || die "Docker 包下载失败"

    rm -rf "$DOCKER_OPT_DIR/bin" "$DOCKER_OPT_DIR/sbin" "$DOCKER_OPT_DIR/usr" "$DOCKER_OPT_DIR/lib" "$DOCKER_OPT_DIR/etc/init.d" 2>/dev/null || true
    mkdir -p "$DOCKER_OPT_DIR"
    for docker_ipk_path in $docker_package_paths; do
        docker_extract_ipk_data_to_opt "$docker_ipk_path"
    done
    docker_install_payload_tree_to_system

    [ -x /etc/init.d/cgroupfs-mount ] && /etc/init.d/cgroupfs-mount start >/dev/null 2>&1 || true
    log "安装:   Docker 包内容已解到存储盘，必要入口和依赖写入系统盘"
}

docker_configure_storage() {
    mkdir -p "$DOCKER_DATA_ROOT" /etc/docker
    chmod 700 "$DOCKER_DATA_ROOT" 2>/dev/null || true

    if command -v uci >/dev/null 2>&1; then
        [ -f /etc/config/dockerd ] || printf "config globals 'globals'\n" > /etc/config/dockerd
        backup_file /etc/config/dockerd
        uci -q set dockerd.globals=globals >/dev/null 2>&1 || true
        uci -q set "dockerd.globals.data_root=$DOCKER_DATA_ROOT" >/dev/null 2>&1 || true
        uci -q set "dockerd.globals.log_level=warn" >/dev/null 2>&1 || true
        uci -q set "dockerd.globals.iptables=0" >/dev/null 2>&1 || true
        uci -q commit dockerd >/dev/null 2>&1 || true
    fi

    backup_file /etc/docker/daemon.json
    cat > /etc/docker/daemon.json <<EOF_DOCKER_DAEMON
{
  "data-root": "$DOCKER_DATA_ROOT",
  "storage-driver": "vfs",
  "iptables": false,
  "bridge": "none",
  "log-driver": "json-file",
  "log-opts": {
    "max-size": "2m",
    "max-file": "3"
  }
}
EOF_DOCKER_DAEMON

    log "配置:   Docker data-root = $DOCKER_DATA_ROOT"
}

docker_service_running() {
    if [ -x /etc/init.d/dockerd ]; then
        /etc/init.d/dockerd status >/dev/null 2>&1 && return 0
    fi
    pidof dockerd >/dev/null 2>&1
}

docker_start_service() {
    [ -x /etc/init.d/dockerd ] || die "缺少 /etc/init.d/dockerd"
    /etc/init.d/dockerd disable >/dev/null 2>&1 || true
    /etc/init.d/dockerd enable >/dev/null 2>&1 || die "dockerd 设置开机启动失败"
    docker_rc_link=''
    for docker_rc_candidate in /etc/rc.d/S[0-9][0-9]dockerd; do
        [ -L "$docker_rc_candidate" ] || continue
        docker_rc_link="$docker_rc_candidate"
        break
    done
    [ -n "$docker_rc_link" ] || die "dockerd 未生成有效的 /etc/rc.d 启动链接"
    if /etc/init.d/dockerd restart > "$DOCKER_LOG_DIR/dockerd.restart.log" 2>&1; then
        sleep 3
        return 0
    fi
    sed -n '1,160p' "$DOCKER_LOG_DIR/dockerd.restart.log" >&2 || true
    die "dockerd 启动失败"
}

write_docker_luci_controller() {
    mkdir -p "$(dirname "$DOCKER_CONTROLLER")"
    backup_file "$DOCKER_CONTROLLER"
    cat > "$DOCKER_CONTROLLER" <<'EOF_DOCKER_CONTROLLER'
module("luci.controller.nradio_adv.docker", package.seeall)

local fs = require "nixio.fs"
local nixio = require "nixio"

local function trim(s)
    return (s or ""):gsub("^%s+", ""):gsub("%s+$", "")
end

local function shell_quote(s)
    s = tostring(s or "")
    return "'" .. s:gsub("'", "'\\''") .. "'"
end

local function command_output(cmd)
    local fp = io.popen(cmd .. " 2>/dev/null")
    if not fp then return "" end
    local data = fp:read("*a") or ""
    fp:close()
    return trim(data)
end

local function command_result(cmd)
    local fp = io.popen(cmd .. " 2>&1")
    if not fp then return "", false end
    local data = fp:read("*a") or ""
    local a, b, c = fp:close()
    return trim(data), a == true or a == 0 or (b == "exit" and c == 0)
end

local function first_lines(data, limit)
    local lines = {}
    for line in tostring(data or ""):gmatch("[^\r\n]+") do
        if #lines >= limit then break end
        lines[#lines + 1] = line
    end
    return table.concat(lines, "\n")
end

local function query_error(output, running, label)
    if not running then return "Docker daemon 已停止" end
    return output ~= "" and first_lines(output, 3) or (label .. "读取失败")
end

local function exec_ok(cmd)
    local a, b, c = os.execute(cmd .. " >/dev/null 2>&1")
    if a == true or a == 0 then return true end
    if b == "exit" and c == 0 then return true end
    return false
end

local function write_json(data)
    local http = require "luci.http"
    http.prepare_content("application/json")
    if type(http.write_json) == "function" then
        http.write_json(data)
        return
    end
    local ok, jsonc = pcall(require, "luci.jsonc")
    if ok and jsonc and type(jsonc.stringify) == "function" then
        http.write(jsonc.stringify(data))
    else
        http.write("{\"ok\":false,\"error\":\"json writer unavailable\"}")
    end
end

local function docker_data_root()
    local root = command_output("uci -q get dockerd.globals.data_root")
    if root ~= "" then return root end
    local daemon_root = command_output("sed -n 's/.*\"data-root\"[[:space:]]*:[[:space:]]*\"\\([^\"]*\\)\".*/\\1/p' /etc/docker/daemon.json | sed -n '1p'")
    if daemon_root ~= "" then return daemon_root end
    local linked_root = command_output("readlink -f /usr/bin/docker"):match("^(.-)/opt/usr/bin/docker$")
    if linked_root and linked_root:match("/nradio%-apps/docker$") then return linked_root .. "/data" end
    return ""
end

local function service_running()
    if exec_ok("/etc/init.d/dockerd status") then return true end
    return exec_ok("pidof dockerd")
end

local function wait_for_service(expected)
    for _ = 1, 4 do
        local running = service_running()
        if running == expected then return running end
        os.execute("sleep 1 >/dev/null 2>&1")
    end
    return service_running()
end

local function action_log_path()
    local root = docker_data_root()
    local base = root:gsub("/data$", "")
    if base == root or base == "" then return "/tmp/nradio-docker-ui-action.log" end
    os.execute("mkdir -p " .. shell_quote(base .. "/log") .. " >/dev/null 2>&1")
    return base .. "/log/ui-action.log"
end

local function request_value(name)
    local http = require "luci.http"
    return trim(http.formvalue(name) or "")
end

local function completed_action(cmd, success_msg)
    local log_path = action_log_path()
    local request_log = log_path .. "." .. tostring(nixio.getpid()) .. "." .. tostring(os.time())
    local a, b, c = os.execute("(" .. cmd .. ") > " .. shell_quote(request_log) .. " 2>&1")
    local ok = a == true or a == 0 or (b == "exit" and c == 0)
    local error_text = ok and nil or command_output("tail -n 40 " .. shell_quote(request_log))
    os.execute("cp " .. shell_quote(request_log) .. " " .. shell_quote(log_path) .. " >/dev/null 2>&1")
    os.remove(request_log)
    return {
        ok = ok,
        completed = true,
        msg = ok and success_msg or "operation failed",
        error = error_text,
        log = log_path
    }
end

function index()
    local function post_entry(path, handler)
        local node = entry(path, call(handler), nil)
        node.leaf = true
        node.post = true
    end

    local page = entry({"nradioadv", "system", "docker"}, template("nradio_adv/docker"), _("Docker"), 90)
    page.dependent = false
    page.leaf = false
    local app_page = entry({"nradioadv", "system", "appcenter", "docker"}, alias("nradioadv", "system", "docker"), nil, nil, true)
    app_page.leaf = false
    entry({"nradioadv", "system", "docker", "status"}, call("action_status"), nil).leaf = true
    post_entry({"nradioadv", "system", "docker", "start"}, "action_start")
    post_entry({"nradioadv", "system", "docker", "stop"}, "action_stop")
    post_entry({"nradioadv", "system", "docker", "restart"}, "action_restart")
    post_entry({"nradioadv", "system", "docker", "pull"}, "action_pull")
    post_entry({"nradioadv", "system", "docker", "run"}, "action_run")
    post_entry({"nradioadv", "system", "docker", "container"}, "action_container")
    entry({"nradioadv", "system", "docker", "logs"}, call("action_logs"), nil).leaf = true
    entry({"nradioadv", "system", "docker", "inspect"}, call("action_inspect"), nil).leaf = true
    post_entry({"nradioadv", "system", "docker", "image"}, "action_image")
    post_entry({"nradioadv", "system", "docker", "prune"}, "action_prune")
    post_entry({"nradioadv", "system", "docker", "network"}, "action_network")
    post_entry({"nradioadv", "system", "docker", "volume"}, "action_volume")
end

function action_status()
    local root = docker_data_root()
    local root_q = shell_quote(root)
    local running = service_running()
    local containers, containers_ok = command_result("docker ps -a --size --format '{{.ID}}\t{{.Names}}\t{{.Image}}\t{{.Status}}\t{{.Ports}}\t{{.Size}}'")
    local images, images_ok = command_result("docker images --format '{{.Repository}}:{{.Tag}}\t{{.ID}}\t{{.Size}}\t{{.CreatedSince}}'")
    local networks, networks_ok = command_result("docker network ls --format '{{.ID}}\t{{.Name}}\t{{.Driver}}\t{{.Scope}}'")
    local volumes, volumes_ok = command_result("docker volume ls --format '{{.Name}}\t{{.Driver}}\t{{.Mountpoint}}'")
    local stats, stats_ok = command_result("docker stats --no-stream --format '{{.Name}}\t{{.CPUPerc}}\t{{.MemUsage}}\t{{.NetIO}}\t{{.BlockIO}}'")
    write_json({
        ok = true,
        running = running,
        docker = command_output("docker --version"),
        dockerd = command_output("dockerd --version"),
        data_root = root,
        data_root_exists = fs.access(root) and true or false,
        storage = command_output("df -hP " .. root_q .. " | awk 'NR==2{print $2\" total / \"$4\" free / \"$5\" used\"}'"),
        containers = containers_ok and first_lines(containers, 81) or "",
        containers_error = containers_ok and nil or query_error(containers, running, "容器列表"),
        images = images_ok and first_lines(images, 81) or "",
        images_error = images_ok and nil or query_error(images, running, "镜像列表"),
        networks = networks_ok and first_lines(networks, 81) or "",
        networks_error = networks_ok and nil or query_error(networks, running, "网络列表"),
        volumes = volumes_ok and first_lines(volumes, 81) or "",
        volumes_error = volumes_ok and nil or query_error(volumes, running, "卷列表"),
        stats = stats_ok and first_lines(stats, 81) or "",
        stats_error = stats_ok and nil or query_error(stats, running, "资源数据"),
        disk = command_output("docker system df"),
        logs = command_output("tail -n 80 " .. shell_quote(action_log_path())),
        info = command_output("docker info 2>/dev/null | sed -n '1,42p'")
    })
end

function action_start()
    local output, command_ok = command_result("/etc/init.d/dockerd start")
    local running = wait_for_service(true)
    write_json({ ok = command_ok and running, completed = true, running = running, error = command_ok and (running and nil or "daemon 未进入运行状态") or (output ~= "" and output or "启动命令执行失败") })
end

function action_stop()
    local output, command_ok = command_result("/etc/init.d/dockerd stop")
    local running = wait_for_service(false)
    write_json({ ok = command_ok and not running, completed = true, running = running, error = command_ok and (running and "daemon 仍在运行" or nil) or (output ~= "" and output or "停止命令执行失败") })
end

function action_restart()
    local output, command_ok = command_result("/etc/init.d/dockerd restart")
    local running = wait_for_service(true)
    write_json({ ok = command_ok and running, completed = true, running = running, error = command_ok and (running and nil or "daemon 未进入运行状态") or (output ~= "" and output or "重启命令执行失败") })
end

function action_pull()
    local image = request_value("image")
    if image == "" then write_json({ ok = false, error = "image required" }); return end
    write_json(completed_action("docker pull " .. shell_quote(image), "pull completed"))
end

function action_run()
    local image = request_value("image")
    local name = request_value("name")
    local ports = request_value("ports")
    local volumes = request_value("volumes")
    local envs = request_value("envs")
    local restart = request_value("restart")
    local network = request_value("network")
    local privileged = request_value("privileged")
    local command = request_value("command")
    local cmd = "docker run -d"

    if image == "" then write_json({ ok = false, error = "image required" }); return end
    if name ~= "" then cmd = cmd .. " --name " .. shell_quote(name) end
    if restart ~= "" and restart ~= "no" then cmd = cmd .. " --restart " .. shell_quote(restart) end
    if network ~= "" then cmd = cmd .. " --network " .. shell_quote(network) end
    if privileged == "1" then cmd = cmd .. " --privileged" end
    for line in ports:gmatch("[^\r\n]+") do line = trim(line); if line ~= "" then cmd = cmd .. " -p " .. shell_quote(line) end end
    for line in volumes:gmatch("[^\r\n]+") do line = trim(line); if line ~= "" then cmd = cmd .. " -v " .. shell_quote(line) end end
    for line in envs:gmatch("[^\r\n]+") do line = trim(line); if line ~= "" then cmd = cmd .. " -e " .. shell_quote(line) end end
    if command ~= "" then cmd = cmd .. " --entrypoint /bin/sh" end
    cmd = cmd .. " " .. shell_quote(image)
    if command ~= "" then cmd = cmd .. " -c " .. shell_quote(command) end
    write_json(completed_action(cmd, "container created"))
end

function action_container()
    local id = request_value("id")
    local op = request_value("op")
    local cmd = nil
    if id == "" then write_json({ ok = false, error = "container id required" }); return end
    if op == "start" then cmd = "docker start " .. shell_quote(id)
    elseif op == "stop" then cmd = "docker stop " .. shell_quote(id)
    elseif op == "restart" then cmd = "docker restart " .. shell_quote(id)
    elseif op == "pause" then cmd = "docker pause " .. shell_quote(id)
    elseif op == "unpause" then cmd = "docker unpause " .. shell_quote(id)
    elseif op == "kill" then cmd = "docker kill " .. shell_quote(id)
    elseif op == "remove" then cmd = "docker rm -f " .. shell_quote(id)
    else write_json({ ok = false, error = "unsupported op" }); return end
    write_json(completed_action(cmd, op .. " completed"))
end

function action_logs()
    local id = request_value("id")
    if id == "" then write_json({ ok = false, error = "container id required" }); return end
    local logs, ok = command_result("docker logs --tail 120 " .. shell_quote(id))
    write_json({ ok = ok, logs = ok and logs or "", error = ok and nil or logs })
end

function action_inspect()
    local id = request_value("id")
    if id == "" then write_json({ ok = false, error = "id required" }); return end
    local inspect, ok = command_result("docker inspect " .. shell_quote(id))
    write_json({ ok = ok, inspect = ok and first_lines(inspect, 220) or "", error = ok and nil or inspect })
end

function action_image()
    local id = request_value("id")
    local op = request_value("op")
    if id == "" then write_json({ ok = false, error = "image id required" }); return end
    if op == "remove" then
        write_json(completed_action("docker rmi -f " .. shell_quote(id), "image removed"))
        return
    end
    write_json({ ok = false, error = "unsupported op" })
end

function action_prune()
    local target = request_value("target")
    local cmd = nil
    if target == "containers" then cmd = "docker container prune -f"
    elseif target == "images" then cmd = "docker image prune -af"
    elseif target == "networks" then cmd = "docker network prune -f"
    elseif target == "volumes" then cmd = "docker volume prune -f"
    elseif target == "system_volumes" then cmd = "docker system prune -af --volumes"
    elseif target == "system" then cmd = "docker system prune -af"
    else write_json({ ok = false, error = "unsupported prune target" }); return end
    write_json(completed_action(cmd, "prune completed"))
end

function action_network()
    local name = request_value("name")
    local driver = request_value("driver")
    local op = request_value("op")
    if name == "" then write_json({ ok = false, error = "network name required" }); return end
    if driver == "" then driver = "bridge" end
    if op == "create" then
        write_json(completed_action("docker network create -d " .. shell_quote(driver) .. " " .. shell_quote(name), "network created"))
        return
    elseif op == "remove" then
        write_json(completed_action("docker network rm " .. shell_quote(name), "network removed"))
        return
    end
    write_json({ ok = false, error = "unsupported op" })
end

function action_volume()
    local name = request_value("name")
    local op = request_value("op")
    if name == "" then write_json({ ok = false, error = "volume name required" }); return end
    if op == "create" then
        write_json(completed_action("docker volume create " .. shell_quote(name), "volume created"))
        return
    elseif op == "remove" then
        write_json(completed_action("docker volume rm " .. shell_quote(name), "volume removed"))
        return
    end
    write_json({ ok = false, error = "unsupported op" })
end
EOF_DOCKER_CONTROLLER
    chmod 644 "$DOCKER_CONTROLLER" 2>/dev/null || true
}

write_docker_luci_view() {
    mkdir -p "$(dirname "$DOCKER_VIEW")"
    backup_file "$DOCKER_VIEW"
    cat > "$DOCKER_VIEW" <<'EOF_DOCKER_VIEW'
<%+header%>
<style>
