qiyou_write_uninstall_helper() {
    mkdir -p /usr/libexec
    cat > /usr/libexec/nradio-qiyou-uninstall <<'EOF_QIYOU_UNINSTALL'
#!/bin/sh
set -eu
APP_NAME="奇游联机宝"
PKG_NAME="nradio-qiyou"
APP_ROUTE="nradioadv/system/qiyou"
APP_CONTROLLER="/usr/lib/lua/luci/controller/nradio_adv/qiyou.lua"
APP_VIEW="/usr/lib/lua/luci/view/nradiobridge_qiyou/qiyou.htm"
APP_ICON="/www/luci-static/nradio/images/icon/qiyou.svg"
delete_sections() {
    st="$1"; fn="$2"; fv="$3"
    [ -n "$fv" ] || return 0
    uci -X show appcenter 2>/dev/null | while IFS= read -r line; do
        case "$line" in
            "appcenter.@${st}"*".${fn}='${fv}'"|"appcenter.cfg"*".${fn}='${fv}'")
                sec="${line#appcenter.}"; sec="${sec%%.*}"; printf '%s\n' "$sec" ;;
        esac
    done | sort -u | while IFS= read -r sec; do
        [ -n "$sec" ] && uci -q delete "appcenter.$sec" >/dev/null 2>&1 || true
    done
}
/etc/qy/qy_acc.sh stop >/dev/null 2>&1 || true
[ -x /tmp/qy/init.sh ] && /tmp/qy/init.sh stop >/dev/null 2>&1 || true
killall -9 qy_proxy qy_mosq qy_acc >/dev/null 2>&1 || true
rm -rf /tmp/qy /etc/qy 2>/dev/null || { echo "删除奇游运行目录失败" >&2; exit 1; }
rm -f /tmp/qyplug.sh /tmp/qyplug.ret /tmp/qyplug.pid /tmp/qyplug.get /tmp/qiyou-install.sh 2>/dev/null || { echo "删除奇游临时文件失败" >&2; exit 1; }
rm -f /etc/init.d/qy_acc.boot /etc/rc.d/S99qy_acc.boot 2>/dev/null || { echo "删除奇游启动项失败" >&2; exit 1; }
rm -f "$APP_CONTROLLER" "$APP_VIEW" "$APP_ICON" 2>/dev/null || { echo "删除奇游页面文件失败" >&2; exit 1; }
delete_sections package name "$APP_NAME"
delete_sections package name "$PKG_NAME"
delete_sections package_list name "$APP_NAME"
delete_sections package_list pkg_name "$PKG_NAME"
delete_sections package_list parent "$APP_NAME"
delete_sections package_list luci_module_route "$APP_ROUTE"
uci -q commit appcenter >/dev/null 2>&1 || { echo "提交应用商店配置失败" >&2; exit 1; }
rm -f /tmp/luci-indexcache /tmp/infocd/cache/appcenter 2>/dev/null || true
rm -f /tmp/luci-modulecache/* 2>/dev/null || true
/etc/init.d/infocd restart >/dev/null 2>&1 || true
/etc/init.d/appcenter restart >/dev/null 2>&1 || true
/etc/init.d/uhttpd reload >/dev/null 2>&1 || { echo "重载 uhttpd 失败" >&2; exit 1; }
[ ! -e /etc/qy ] && [ ! -e /tmp/qy ] && [ ! -e /etc/init.d/qy_acc.boot ] || { echo "奇游卸载后仍有核心文件残留" >&2; exit 1; }
pidof qy_proxy qy_mosq qy_acc >/dev/null 2>&1 && { echo "奇游卸载后仍有进程运行" >&2; exit 1; }
exit 0
EOF_QIYOU_UNINSTALL
    chmod 755 /usr/libexec/nradio-qiyou-uninstall
}

qiyou_valid_identity_mac() {
    case "${1:-}" in
        [0-9A-F][02468ACE]:[0-9A-F][0-9A-F]:[0-9A-F][0-9A-F]:[0-9A-F][0-9A-F]:[0-9A-F][0-9A-F]:[0-9A-F][0-9A-F]) ;;
        *) return 1 ;;
    esac
    [ "$1" != '00:00:00:00:00:00' ]
}

qiyou_detect_identity() {
    QIYOU_IDENTITY_RAW_MODEL="$(cat /tmp/sysinfo/model 2>/dev/null | sed -n '1p')"
    QIYOU_IDENTITY_BOARD="$(cat /tmp/sysinfo/board_name 2>/dev/null | sed -n '1p')"
    QIYOU_IDENTITY_HOSTNAME="$(cat /proc/sys/kernel/hostname 2>/dev/null | sed -n '1p')"

    case "$QIYOU_IDENTITY_RAW_MODEL/$QIYOU_IDENTITY_BOARD" in
        HC-WT9126/*) QIYOU_IDENTITY_MODEL='C5800-688' ;;
        HC-WT9120/*) QIYOU_IDENTITY_MODEL='C5800-650' ;;
        HC-WT9302/*|*/HCMT7987-NAND) QIYOU_IDENTITY_MODEL='C8-788' ;;
        HC-WT9500/*) QIYOU_IDENTITY_MODEL='C2000Ultra' ;;
        HC-WT9303/*) QIYOU_IDENTITY_MODEL='C2000MAX' ;;
        HC-WT9111/*|NRADIO-WT9111/*) QIYOU_IDENTITY_MODEL='NBCPE' ;;
        *UDX710*|*udx710*|*RG200U-CN*) QIYOU_IDENTITY_MODEL='C2000Pro' ;;
        */HCMT7981-EMMC) QIYOU_IDENTITY_MODEL='C5800-688' ;;
        */HCMT7987-SNSD) QIYOU_IDENTITY_MODEL='C2000' ;;
        *)
            QIYOU_IDENTITY_MODEL="$QIYOU_IDENTITY_RAW_MODEL"
            [ -n "$QIYOU_IDENTITY_MODEL" ] || QIYOU_IDENTITY_MODEL="$QIYOU_IDENTITY_BOARD"
            [ -n "$QIYOU_IDENTITY_MODEL" ] || QIYOU_IDENTITY_MODEL='未知机型'
            ;;
    esac
    QIYOU_IDENTITY_DEVICE_NAME="NRadio $QIYOU_IDENTITY_MODEL"

    QIYOU_IDENTITY_INTERFACE=''
    QIYOU_IDENTITY_MAC=''
    for qy_identity_ifname in br-lan br0 eth0; do
        [ -r "/sys/class/net/$qy_identity_ifname/address" ] || continue
        qy_identity_mac="$(cat "/sys/class/net/$qy_identity_ifname/address" 2>/dev/null | sed -n '1p' | sed 's/^[[:space:]]*//;s/[[:space:]]*$//' | tr 'a-f' 'A-F')"
        qiyou_valid_identity_mac "$qy_identity_mac" || continue
        QIYOU_IDENTITY_MAC="$qy_identity_mac"
        QIYOU_IDENTITY_INTERFACE="$qy_identity_ifname"
        break
    done

    qy_identity_prefix="$(sed -n 's/^NAME=//p' /tmp/qy/etc/PKG_INFO 2>/dev/null | sed -n '1p' | sed 's/^[[:space:]]*//;s/[[:space:]]*$//')"
    [ -n "$qy_identity_prefix" ] || qy_identity_prefix="$(sed -n 's/^BRAND=//p' /tmp/qy/etc/PKG_INFO 2>/dev/null | sed -n '1p' | sed 's/^[[:space:]]*//;s/[[:space:]]*$//')"
    qy_identity_prefix="$(printf '%s' "${qy_identity_prefix:-SYS}" | tr -cd 'A-Za-z0-9_-')"
    [ -n "$qy_identity_prefix" ] || qy_identity_prefix='SYS'
    qy_identity_prefix="$(printf '%s' "$qy_identity_prefix" | tr 'a-z' 'A-Z')"
    qy_identity_compact_mac="$(printf '%s' "$QIYOU_IDENTITY_MAC" | tr -d ':')"
    if [ -n "$qy_identity_compact_mac" ]; then
        QIYOU_IDENTITY_DEVICE_ID="${qy_identity_prefix}_${qy_identity_compact_mac}"
    else
        QIYOU_IDENTITY_DEVICE_ID=''
    fi
}

qiyou_write_controller() {
    mkdir -p /usr/lib/lua/luci/controller/nradio_adv
    cat > /usr/lib/lua/luci/controller/nradio_adv/qiyou.lua <<'EOF_QIYOU_CONTROLLER'
module("luci.controller.nradio_adv.qiyou", package.seeall)
function index()
    local page = entry({"nradioadv", "system", "qiyou"}, template("nradiobridge_qiyou/qiyou"), _("QiYou"), 90)
    page.show = true
    entry({"nradioadv", "system", "qiyou", "status"}, call("action_status"), nil).leaf = true
    local uninstall_page = entry({"nradioadv", "system", "qiyou", "uninstall"}, call("action_uninstall"), nil)
    uninstall_page.leaf = true
    uninstall_page.post = true
end
local function trim(v) v=tostring(v or ""); local o=v:gsub("^%s+",""):gsub("%s+$",""); return o end
local function readfile(p) local f=io.open(p,"r"); if not f then return "" end; local d=f:read("*a") or ""; f:close(); return d end
local function exec(c) return trim(require("luci.sys").exec(c.." 2>/dev/null")) end
local function write_json(data)
    local h=require "luci.http"
    local ok,jsonc=pcall(require,"luci.jsonc")
    h.prepare_content("application/json")
    if type(h.write_json)=="function" then
        h.write_json(data)
    elseif ok and jsonc and type(jsonc.stringify)=="function" then
        h.write(jsonc.stringify(data or {}))
    else
        h.write("{}")
    end
end
local function pkg_info()
    local info={}
    for line in readfile("/tmp/qy/etc/PKG_INFO"):gmatch("[^\r\n]+") do
        local k,v=line:match("^([A-Z0-9_]+)=(.*)$")
        if k then info[k]=v end
    end
    return info
end
local function identity_mac()
    local paths={"/sys/class/net/br-lan/address","/sys/class/net/br0/address","/sys/class/net/eth0/address"}
    for _,path in ipairs(paths or {}) do
        local value=trim(readfile(path):match("^[^\r\n]*") or ""):upper()
        if value:match("^%x%x:%x%x:%x%x:%x%x:%x%x:%x%x$") and
            value~="00:00:00:00:00:00" and tonumber(value:sub(1,2),16)%2==0 then
            return value,path
        end
    end
    return "",""
end
local function friendly_model(raw_model,board)
    local raw=trim(raw_model)
    local key=raw:upper()
    local board_key=trim(board):upper()
    if key=="HC-WT9126" then return "C5800-688" end
    if key=="HC-WT9120" then return "C5800-650" end
    if key=="HC-WT9302" or board_key=="HCMT7987-NAND" then return "C8-788" end
    if key=="HC-WT9500" then return "C2000Ultra" end
    if key=="HC-WT9303" then return "C2000MAX" end
    if key=="HC-WT9111" or key=="NRADIO-WT9111" then return "NBCPE" end
    if key:find("UDX710",1,true) or key:find("RG200U-CN",1,true) or board_key:find("UDX710",1,true) then return "C2000Pro" end
    if board_key=="HCMT7981-EMMC" then return "C5800-688" end
    if board_key=="HCMT7987-SNSD" then return "C2000" end
    if raw~="" then return raw end
    if trim(board)~="" then return trim(board) end
    return "未知机型"
end
local function qiyou_identity(info)
    local raw_model=trim(readfile("/tmp/sysinfo/model"))
    local board=trim(readfile("/tmp/sysinfo/board_name"))
    local hostname=trim(readfile("/proc/sys/kernel/hostname"))
    local mac,mac_path=identity_mac()
    local compact=mac:gsub(":","")
    local prefix=trim(info.NAME)
    if prefix=="" then prefix=trim(info.BRAND) end
    prefix=prefix:upper():gsub("[^A-Z0-9_%-]","")
    if prefix=="" then prefix="SYS" end
    local device_id=compact~="" and prefix.."_"..compact or ""
    local ifname=mac_path:match("/net/([^/]+)/address$") or ""
    local model=friendly_model(raw_model,board)
    return {
        raw_model=raw_model,board=board,hostname=hostname,model=model,
        device_name="NRadio "..model,lan_mac=mac,identity_interface=ifname,
        qiyou_device_id=device_id,qiyou_name=info.NAME or "",qiyou_brand=info.BRAND or ""
    }
end
function action_status()
    local fs=require "nixio.fs"
    local installed=fs.access("/etc/qy/qy_acc.sh") and true or false
    local info=pkg_info()
    local status="NOT_INSTALLED"
    if installed then status=exec("/etc/qy/qy_acc.sh status"); if status=="" then status="UNKNOWN" end end
    local qy_acc=exec("pidof qy_acc")
    local qy_mosq=exec("pidof qy_mosq")
    local qy_proxy=exec("pidof qy_proxy")
    local identity=qiyou_identity(info)
    write_json({
        installed=installed,status=status,ret=trim(readfile("/tmp/qyplug.ret")),
        mode=info.MODE or "",version=info.VERSION or "",date=info.DATE or "",pver=info.PVER or "",
        device_name=identity.device_name,qiyou_device_id=identity.qiyou_device_id,
        lan_mac=identity.lan_mac,identity_interface=identity.identity_interface,
        raw_model=identity.raw_model,board=identity.board,hostname=identity.hostname,
        qiyou_name=identity.qiyou_name,qiyou_brand=identity.qiyou_brand,
        qy_acc=qy_acc~="",qy_mosq=qy_mosq~="",qy_proxy=qy_proxy~="",
        qy_acc_pid=qy_acc,qy_mosq_pid=qy_mosq,qy_proxy_pid=qy_proxy,
        proxy_conn=tonumber(exec("netstat -tunap | grep qy_proxy | grep ESTABLISHED | wc -l")) or 0,
        proxy_listen=exec("netstat -lntup | grep qy_proxy | head -n 1"),
        cloud_conn=tonumber(exec("netstat -tunap | grep qy_acc | grep ESTABLISHED | wc -l")) or 0
    })
end
function action_uninstall()
    local rc=os.execute("/usr/libexec/nradio-qiyou-uninstall >/dev/null 2>&1")
    if rc==0 then
        write_json({ok=true,msg="奇游联机宝卸载完成"})
    else
        write_json({ok=false,msg="奇游联机宝卸载失败，请使用总脚本查看错误"})
    end
end
EOF_QIYOU_CONTROLLER
    chmod 644 /usr/lib/lua/luci/controller/nradio_adv/qiyou.lua 2>/dev/null || true
}

qiyou_write_view() {
    mkdir -p /usr/lib/lua/luci/view/nradiobridge_qiyou
    cat > /usr/lib/lua/luci/view/nradiobridge_qiyou/qiyou.htm <<'EOF_QIYOU_VIEW'
<%+header%>
<style>
html,body{width:100%!important;max-width:none!important;margin:0!important;background:#0b121d!important;overflow-x:hidden}.container.body-container:not(.visible-xs-block),.main,.main-content,#maincontent{width:100%!important;max-width:none!important;min-width:0!important;margin:0!important;padding:0!important}.qy-wrap{width:100%;max-width:none;min-height:100vh;padding:34px 40px 42px;color:#eef8ff;background:radial-gradient(circle at 14% 8%,rgba(56,189,248,.18),transparent 30%),linear-gradient(135deg,#081522,#102b40 58%,#0a1420);box-sizing:border-box}.qy-head{display:flex;align-items:center;justify-content:space-between;gap:18px;margin-bottom:22px}.qy-title{font-size:32px;font-weight:900}.qy-sub{margin-top:8px;color:#b8d7ea;font-size:14px}.qy-pill{display:inline-flex;align-items:center;gap:9px;border:1px solid rgba(125,211,252,.36);border-radius:999px;padding:10px 15px;background:rgba(14,165,233,.14);font-weight:900}.qy-dot{width:9px;height:9px;border-radius:50%;background:#94a3b8;box-shadow:0 0 10px currentColor}.qy-dot.boosting{background:#22c55e;color:#22c55e}.qy-dot.running{background:#38bdf8;color:#38bdf8}.qy-dot.off{background:#f97316;color:#f97316}.qy-grid{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:18px;margin:22px 0 26px}.qy-card{border:1px solid rgba(255,255,255,.12);border-radius:14px;padding:20px 22px;background:linear-gradient(145deg,rgba(255,255,255,.085),rgba(255,255,255,.035));box-shadow:inset 0 1px 0 rgba(255,255,255,.08),0 18px 36px rgba(0,0,0,.20)}.qy-label{color:#9ec6da;font-size:13px;font-weight:900}.qy-value{margin-top:10px;font-size:26px;font-weight:900;color:#fff;word-break:break-all}.qy-card.qy-device-card{border-color:rgba(34,197,94,.34);background:radial-gradient(circle at 12% 0%,rgba(34,197,94,.17),transparent 52%),linear-gradient(145deg,rgba(255,255,255,.095),rgba(255,255,255,.038))}.qy-card.qy-device-card .qy-value{color:#dcfce7}.qy-row{display:grid;grid-template-columns:240px 1fr;gap:14px;padding:14px 0;border-bottom:1px solid rgba(255,255,255,.08);color:#cfe7f5}.qy-k{color:#9ec6da;font-weight:900}.qy-v{font-weight:900;word-break:break-all}.qy-actions{display:flex;gap:12px;flex-wrap:wrap;margin-top:22px}.qy-btn{border:1px solid rgba(125,211,252,.36);border-radius:10px;background:rgba(14,165,233,.17);color:#eef8ff;font-weight:900;padding:11px 18px;cursor:pointer}.qy-btn.danger{border-color:rgba(248,113,113,.48);background:rgba(239,68,68,.18)}.qy-note{margin-top:18px;color:#b8d7ea;line-height:1.7;font-size:13px}@media(max-width:1100px){.qy-grid{grid-template-columns:repeat(2,minmax(0,1fr))}}@media(max-width:900px){.qy-wrap{padding:24px 18px 30px}.qy-grid{grid-template-columns:1fr}.qy-row{grid-template-columns:1fr}.qy-head{align-items:flex-start;flex-direction:column}}
/* NRadio QiYou premium visual finish */.qy-wrap{position:relative;overflow:hidden}.qy-wrap:before{content:"";position:absolute;left:34px;right:34px;top:0;height:1px;background:linear-gradient(90deg,transparent,rgba(125,211,252,.68),rgba(34,197,94,.36),transparent);pointer-events:none}.qy-head,.qy-grid,.qy-card,.qy-actions,.qy-note{position:relative;z-index:1}.qy-title{text-shadow:0 1px 0 rgba(0,0,0,.32),0 0 24px rgba(56,189,248,.10)}.qy-sub{color:#c0d7e8}.qy-pill{box-shadow:inset 0 1px 0 rgba(255,255,255,.08),0 12px 26px rgba(2,8,23,.20);backdrop-filter:blur(10px) saturate(1.06);-webkit-backdrop-filter:blur(10px) saturate(1.06)}.qy-card{border-color:rgba(125,211,252,.20);background:radial-gradient(circle at 14% 0%,rgba(56,189,248,.12),transparent 44%),linear-gradient(145deg,rgba(255,255,255,.095),rgba(255,255,255,.038));box-shadow:inset 0 1px 0 rgba(255,255,255,.10),0 22px 42px rgba(0,0,0,.24)}.qy-card:hover{border-color:rgba(125,211,252,.32);box-shadow:inset 0 1px 0 rgba(255,255,255,.12),0 24px 46px rgba(0,0,0,.26)}.qy-label{color:#b9dff1}.qy-value{text-shadow:0 1px 0 rgba(0,0,0,.34)}.qy-row{border-bottom-color:rgba(255,255,255,.10)}.qy-btn{box-shadow:inset 0 1px 0 rgba(255,255,255,.08),0 10px 22px rgba(2,8,23,.18)}.qy-btn:focus-visible{outline:0;box-shadow:0 0 0 3px rgba(56,189,248,.18),inset 0 1px 0 rgba(255,255,255,.08),0 10px 22px rgba(2,8,23,.18)}.qy-btn:hover{border-color:rgba(125,211,252,.56);background:linear-gradient(180deg,rgba(14,165,233,.24),rgba(14,165,233,.10))}.qy-btn.danger:hover{border-color:rgba(248,113,113,.66);background:linear-gradient(180deg,rgba(239,68,68,.26),rgba(239,68,68,.12))}.qy-head,.qy-grid,.qy-card,.qy-row,.qy-v,.qy-value{min-width:0;overflow-wrap:anywhere}.qy-card,.qy-pill,.qy-btn{backdrop-filter:saturate(1.04) blur(3px);-webkit-backdrop-filter:saturate(1.04) blur(3px)}@media(max-width:520px){.qy-title{font-size:26px}.qy-card{border-radius:13px}.qy-actions{align-items:stretch;flex-direction:column}.qy-btn{width:100%}}
</style>
<div class="qy-wrap"><div class="qy-head"><div><div class="qy-title">奇游联机宝</div><div class="qy-sub">显示当前路由器的机型、LAN MAC 与本机设备码；绑定和选择游戏在奇游联机宝 App 内完成。</div></div><div class="qy-pill"><span id="qy-dot" class="qy-dot"></span><span id="qy-status">读取中</span></div></div><div class="qy-grid"><div class="qy-card qy-device-card"><div class="qy-label">设备名称</div><div id="qy-device-name" class="qy-value">-</div></div><div class="qy-card"><div class="qy-label">插件状态</div><div id="qy-main" class="qy-value">-</div></div><div class="qy-card"><div class="qy-label">实际代理连接</div><div id="qy-proxy-conn" class="qy-value">-</div></div><div class="qy-card"><div class="qy-label">云端连接</div><div id="qy-cloud-conn" class="qy-value">-</div></div></div><div class="qy-card"><div class="qy-row"><div class="qy-k">本机设备码</div><div id="qy-device-id" class="qy-v">-</div></div><div class="qy-row"><div class="qy-k">LAN MAC / 识别接口</div><div id="qy-lan-mac" class="qy-v">-</div></div><div class="qy-row"><div class="qy-k">硬件型号 / 板型</div><div id="qy-model" class="qy-v">-</div></div><div class="qy-row"><div class="qy-k">主机名</div><div id="qy-hostname" class="qy-v">-</div></div><div class="qy-row"><div class="qy-k">安装返回</div><div id="qy-ret" class="qy-v">-</div></div><div class="qy-row"><div class="qy-k">qy_acc</div><div id="qy-acc" class="qy-v">-</div></div><div class="qy-row"><div class="qy-k">qy_mosq</div><div id="qy-mosq" class="qy-v">-</div></div><div class="qy-row"><div class="qy-k">qy_proxy</div><div id="qy-proxy" class="qy-v">-</div></div><div class="qy-row"><div class="qy-k">包信息</div><div id="qy-pkg" class="qy-v">-</div></div><div class="qy-row"><div class="qy-k">代理监听</div><div id="qy-listen" class="qy-v">-</div></div></div><div class="qy-actions"><button type="button" class="qy-btn" onclick="qyRefresh()">刷新状态</button><button type="button" class="qy-btn danger" onclick="qyUninstall()">卸载奇游联机宝</button></div><div class="qy-note"><strong>识别说明：</strong>本机设备码由包前缀和完整 LAN MAC 组成，用于区分路由器；MAC 不变时设备码保持不变。奇游 App 的绑定码以 App 实际显示为准。<br><strong>状态解释：</strong>BOOSTING 表示正在加速；RUNNING 表示插件在线但未开启加速；实际代理连接不是连接路由器的设备数。</div></div>
<script>
var qyBase='<%=url("nradioadv/system/qiyou")%>';var qyToken='<%=require("luci.dispatcher").context.authtoken%>';function qyText(id,text){var el=document.getElementById(id);if(el)el.textContent=text||'-';}function qyBool(v,p){return v?('运行中'+(p?' / '+p:'')):'未运行';}function qyApply(d){var st=d.status||'UNKNOWN';var dot=document.getElementById('qy-dot');qyText('qy-status',st);qyText('qy-device-name',d.device_name||'NRadio 未知机型');qyText('qy-device-id',d.qiyou_device_id||'未获取有效 LAN MAC');qyText('qy-lan-mac',[d.lan_mac,d.identity_interface].filter(Boolean).join(' / ')||'-');qyText('qy-model',[d.raw_model,d.board].filter(Boolean).join(' / ')||'-');qyText('qy-hostname',d.hostname||'-');qyText('qy-main',st==='BOOSTING'?'正在加速':(st==='RUNNING'?'插件在线':st));qyText('qy-proxy-conn',String(d.proxy_conn||0));qyText('qy-cloud-conn',String(d.cloud_conn||0));qyText('qy-ret',d.ret||'-');qyText('qy-acc',qyBool(d.qy_acc,d.qy_acc_pid));qyText('qy-mosq',qyBool(d.qy_mosq,d.qy_mosq_pid));qyText('qy-proxy',qyBool(d.qy_proxy,d.qy_proxy_pid));qyText('qy-pkg',[d.mode,d.version,d.date].filter(Boolean).join(' / ')||'-');qyText('qy-listen',d.proxy_listen||'-');if(dot){dot.className='qy-dot '+(st==='BOOSTING'?'boosting':(st==='RUNNING'?'running':'off'));}}function qyRefresh(){var x=new XMLHttpRequest();x.open('GET',qyBase+'/status?_='+Date.now(),true);x.onreadystatechange=function(){if(x.readyState===4){try{qyApply(JSON.parse(x.responseText||'{}'));}catch(e){qyText('qy-status','读取失败');}}};x.send(null);}function qyUninstall(){if(!confirm('确认卸载奇游联机宝并移除应用商店入口吗？'))return;var x=new XMLHttpRequest();x.open('POST',qyBase+'/uninstall',true);x.onreadystatechange=function(){if(x.readyState===4)alert('已开始卸载，稍后刷新应用商店。');};x.setRequestHeader('Content-Type','application/x-www-form-urlencoded');x.send('token='+encodeURIComponent(qyToken));}qyRefresh();setInterval(qyRefresh,5000);
</script>
<script>
function qyUninstall(){
  if(!confirm('确认卸载奇游联机宝并移除应用商店入口吗？'))return;
  var x=new XMLHttpRequest();
  x.open('POST',qyBase+'/uninstall',true);
  x.onreadystatechange=function(){
    if(x.readyState!==4)return;
    var d={};try{d=JSON.parse(x.responseText||'{}');}catch(e){}
    if(x.status>=200&&x.status<300&&d.ok){alert(d.msg||'奇游联机宝卸载完成');location.href='<%=url("nradioadv/system/appcenter")%>';}
    else alert((d&&d.msg)||'奇游联机宝卸载失败');
  };
  x.setRequestHeader('Content-Type','application/x-www-form-urlencoded');
  x.send('token='+encodeURIComponent(qyToken));
}
</script>
<%+footer%>
EOF_QIYOU_VIEW
    chmod 644 /usr/lib/lua/luci/view/nradiobridge_qiyou/qiyou.htm 2>/dev/null || true
}

qiyou_verify_identity_assets() {
    [ -s "$QIYOU_CONTROLLER" ] || die "奇游设备识别控制器写入失败: $QIYOU_CONTROLLER"
    [ -s "$QIYOU_VIEW" ] || die "奇游设备识别页面写入失败: $QIYOU_VIEW"
    grep -q 'qiyou_device_id=identity.qiyou_device_id' "$QIYOU_CONTROLLER" 2>/dev/null || die "奇游控制器缺少设备 ID 输出"
    grep -q 'id="qy-device-name"' "$QIYOU_VIEW" 2>/dev/null || die "奇游页面缺少设备名称卡片"
    grep -q 'id="qy-lan-mac"' "$QIYOU_VIEW" 2>/dev/null || die "奇游页面缺少 LAN MAC 信息"
}

qiyou_install_assets() {
    qiyou_assets_log="${1:-写入奇游应用商店接入文件}"
    log "$qiyou_assets_log"
    qiyou_write_icon
    qiyou_write_uninstall_helper
    write_plugin_uninstall_assets
    qiyou_write_controller
    qiyou_write_view
    qiyou_verify_identity_assets
    game_accel_set_appcenter_entry "奇游联机宝" "nradio-qiyou" "$(qiyou_version)" "$(qiyou_size)" "nradioadv/system/qiyou" "/usr/lib/lua/luci/controller/nradio_adv/qiyou.lua" "qiyou.svg"
    refresh_luci_appcenter
}

qiyou_install_integrated() {
    game_accel_require_appcenter
    confirm_or_exit "确认安装奇游联机宝官方脚本并接入 NRadio 应用商店吗？"
    command -v opkg >/dev/null 2>&1 || die "系统没有 opkg，无法按奇游官方方式安装依赖"
    log "[1/4] 下载奇游官方安装脚本"
    download_file "$QIYOU_INSTALLER_URL" "/tmp/qiyou-install.sh" || die "下载奇游入口脚本失败"
    grep -q 'qyplug.sh' /tmp/qiyou-install.sh 2>/dev/null || die "奇游入口脚本内容异常，已停止执行"
    sh -n /tmp/qiyou-install.sh >/dev/null 2>&1 || die "奇游入口脚本语法异常，已停止执行"
    log "[2/4] 安装奇游依赖"
    ensure_opkg_update || die "opkg update 失败，已停止奇游依赖安装"
    opkg install curl kmod-tun ip-full || die "安装 curl/kmod-tun/ip-full 失败"
    log "[3/4] 执行奇游官方安装脚本"
    sh /tmp/qiyou-install.sh || die "奇游官方安装脚本执行失败"
    sleep 2
    [ -f /etc/qy/qy_acc.sh ] || die "奇游安装后未发现 /etc/qy/qy_acc.sh"
    qiyou_install_assets "[4/4] 写入奇游应用商店接入文件"
    qiyou_show_status
    log "完成：奇游联机宝已接入 NRadio 应用商店"
}

qiyou_show_status() {
    qiyou_detect_identity
    log "奇游状态:"
    if [ -x /etc/qy/qy_acc.sh ]; then
        qy_status_text="$(/etc/qy/qy_acc.sh status 2>/dev/null || true)"
        [ -n "$qy_status_text" ] && log "$qy_status_text" || true
    else
        log "NOT_INSTALLED"
    fi
    log "安装返回: $(cat /tmp/qyplug.ret 2>/dev/null || true)"
    log "qy_acc: $(pidof qy_acc 2>/dev/null || printf '-')"
    log "qy_mosq: $(pidof qy_mosq 2>/dev/null || printf '-')"
    log "qy_proxy: $(pidof qy_proxy 2>/dev/null || printf '-')"
    log "设备名称: $QIYOU_IDENTITY_DEVICE_NAME"
    log "本机设备码: ${QIYOU_IDENTITY_DEVICE_ID:-未获取（没有有效的 LAN MAC）}"
    log "LAN MAC: ${QIYOU_IDENTITY_MAC:-未知} / ${QIYOU_IDENTITY_INTERFACE:-未知接口}"
    log "硬件型号: ${QIYOU_IDENTITY_RAW_MODEL:-未知} / ${QIYOU_IDENTITY_BOARD:-未知}"
    [ -f /tmp/qy/etc/PKG_INFO ] && cat /tmp/qy/etc/PKG_INFO || true
}

qiyou_refresh_identity_assets() {
    game_accel_require_appcenter
    [ -f /etc/qy/qy_acc.sh ] || die "尚未安装奇游联机宝，无法刷新设备识别页面"
    qiyou_install_assets "刷新奇游设备识别与应用商店页面"
    qiyou_show_status
    log "完成：奇游插件页已更新当前路由器的设备名称与完整设备码"
}

qiyou_uninstall_integrated() {
    confirm_or_exit "确认卸载奇游联机宝并移除应用商店入口吗？"
    [ -x /usr/libexec/nradio-qiyou-uninstall ] || qiyou_write_uninstall_helper
    /usr/libexec/nradio-qiyou-uninstall
    log "已执行奇游联机宝卸载流程"
}

leigod_installed() {
    [ -d /usr/sbin/leigod ] && ls /usr/sbin/leigod/acc-gw.router.* >/dev/null 2>&1
}

leigod_version() {
    lg_version=''
    if [ -f /usr/sbin/leigod/acc_version.ini ]; then
        lg_version="$(awk -F= '/version|VERSION|Ver|VER/ {print $2; exit}' /usr/sbin/leigod/acc_version.ini 2>/dev/null | sed 's/^[[:space:]]*//;s/[[:space:]]*$//')"
    fi
    if [ -z "$lg_version" ] && [ -f /usr/sbin/leigod/plugin_common.sh ]; then
        lg_version="$(grep -m 1 '^download_base_url=' /usr/sbin/leigod/plugin_common.sh 2>/dev/null | sed 's/^download_base_url=//' | sed 's/"//g')"
    fi
    [ -n "$lg_version" ] || lg_version='LeigodAcc'
    printf '%s\n' "$lg_version"
}

leigod_size() {
    lg_size="$(du -sk /usr/sbin/leigod 2>/dev/null | awk '{print $1}')"
    [ -n "$lg_size" ] || lg_size='0'
    printf '%s\n' "$lg_size"
}

leigod_write_icon() {
    mkdir -p "$APP_ICON_DIR"
    cat > "$APP_ICON_DIR/leigod.svg" <<'EOF_LEIGOD_ICON'
<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 128 128" role="img" aria-label="Leigod"><defs><linearGradient id="lg-bg" x1="18" y1="10" x2="110" y2="118" gradientUnits="userSpaceOnUse"><stop stop-color="#f7fbff"/><stop offset="1" stop-color="#d7ecff"/></linearGradient><linearGradient id="lg-bolt" x1="48" y1="20" x2="83" y2="108" gradientUnits="userSpaceOnUse"><stop stop-color="#f59e0b"/><stop offset=".5" stop-color="#f97316"/><stop offset="1" stop-color="#ef4444"/></linearGradient><filter id="lg-shadow" x="-30%" y="-30%" width="160%" height="160%"><feDropShadow dx="0" dy="6" stdDeviation="7" flood-color="#0f172a" flood-opacity=".22"/></filter></defs><rect x="14" y="14" width="100" height="100" rx="24" fill="url(#lg-bg)" filter="url(#lg-shadow)"/><path d="M70 16 32 74h27l-8 38 45-63H68l2-33Z" fill="url(#lg-bolt)"/><path d="M72 28 47 66h22l-4 22 22-31H65l7-29Z" fill="#fff" opacity=".42"/><path d="M31 83c9 9 21 14 34 14 14 0 27-6 36-16" fill="none" stroke="#38bdf8" stroke-width="7" stroke-linecap="round" opacity=".78"/></svg>
EOF_LEIGOD_ICON
    chmod 644 "$APP_ICON_DIR/leigod.svg" 2>/dev/null || true
}

leigod_write_uninstall_helper() {
    mkdir -p /usr/libexec
    cat > /usr/libexec/nradio-leigod-uninstall <<'EOF_LEIGOD_UNINSTALL'
#!/bin/sh
set -eu
APP_NAME="雷神加速器"
PKG_NAME="nradio-leigod"
APP_ROUTE="nradioadv/system/leigod"
APP_CONTROLLER="/usr/lib/lua/luci/controller/nradio_adv/leigod.lua"
APP_VIEW="/usr/lib/lua/luci/view/nradiobridge_leigod/leigod.htm"
APP_VIEW_DIR="${APP_VIEW%/*}"
APP_ICON="/www/luci-static/nradio/images/icon/leigod.svg"
LEIGOD_DIR="/usr/sbin/leigod"
LEIGOD_INIT="/etc/init.d/acc"
delete_sections() {
    st="$1"; fn="$2"; fv="$3"
    [ -n "$fv" ] || return 0
    uci -X show appcenter 2>/dev/null | while IFS= read -r line; do
        case "$line" in
            "appcenter.@${st}"*".${fn}='${fv}'"|"appcenter.cfg"*".${fn}='${fv}'")
                sec="${line#appcenter.}"; sec="${sec%%.*}"; printf '%s\n' "$sec" ;;
        esac
    done | sort -u | while IFS= read -r sec; do
        [ -n "$sec" ] && uci -q delete "appcenter.$sec" >/dev/null 2>&1 || true
    done
}
if [ -x "$LEIGOD_INIT" ]; then
    "$LEIGOD_INIT" disable >/dev/null 2>&1 || true
    "$LEIGOD_INIT" stop >/dev/null 2>&1 || true
fi
if [ -f "$LEIGOD_DIR/leigod_uninstall.sh" ]; then
    ( cd "$LEIGOD_DIR" && sh ./leigod_uninstall.sh ) || { echo "雷神官方卸载器执行失败，已保留现场" >&2; exit 1; }
fi
killall acc-gw.router.arm64 acc-gw.router.aarch64 acc_upgrade_monitor >/dev/null 2>&1 || true
rm -rf "$LEIGOD_DIR" /tmp/acc "$APP_VIEW_DIR" 2>/dev/null || { echo "删除雷神目录失败" >&2; exit 1; }
rm -f "$LEIGOD_INIT" /etc/config/accelerator /etc/config/accelerator.ini /etc/config/acc_version.ini /tmp/leigod-plugin-install.sh 2>/dev/null || { echo "删除雷神配置失败" >&2; exit 1; }
delete_sections package name "$APP_NAME"
delete_sections package name "$PKG_NAME"
delete_sections package_list name "$APP_NAME"
delete_sections package_list pkg_name "$PKG_NAME"
delete_sections package_list parent "$APP_NAME"
delete_sections package_list luci_module_route "$APP_ROUTE"
uci -q commit appcenter >/dev/null 2>&1 || { echo "提交应用商店配置失败" >&2; exit 1; }
rm -f "$APP_CONTROLLER" "$APP_VIEW" "$APP_ICON" /usr/libexec/nradio-leigod-uninstall 2>/dev/null || { echo "删除雷神页面文件失败" >&2; exit 1; }
rm -f /tmp/luci-indexcache /tmp/infocd/cache/appcenter 2>/dev/null || true
rm -f /tmp/luci-modulecache/* 2>/dev/null || true
/etc/init.d/infocd restart >/dev/null 2>&1 || true
/etc/init.d/appcenter restart >/dev/null 2>&1 || true
/etc/init.d/uhttpd reload >/dev/null 2>&1 || { echo "重载 uhttpd 失败" >&2; exit 1; }
[ ! -e "$LEIGOD_DIR" ] && [ ! -e "$LEIGOD_INIT" ] || { echo "雷神卸载后仍有核心文件残留" >&2; exit 1; }
exit 0
EOF_LEIGOD_UNINSTALL
    chmod 755 /usr/libexec/nradio-leigod-uninstall
}

leigod_write_controller() {
    mkdir -p /usr/lib/lua/luci/controller/nradio_adv
    cat > /usr/lib/lua/luci/controller/nradio_adv/leigod.lua <<'EOF_LEIGOD_CONTROLLER'
module("luci.controller.nradio_adv.leigod", package.seeall)
function index()
    local page=entry({"nradioadv","system","leigod"},template("nradiobridge_leigod/leigod"),_("LeigodAcc"),91)
    page.show=true
    entry({"nradioadv","system","leigod","status"},call("action_status"),nil).leaf=true
    local uninstall_page=entry({"nradioadv","system","leigod","uninstall"},call("action_uninstall"),nil)
    uninstall_page.leaf=true
    uninstall_page.post=true
end
local function trim(v) v=tostring(v or ""); local o=v:gsub("^%s+",""):gsub("%s+$",""); return o end
local function exec(c) return trim(require("luci.sys").exec(c.." 2>/dev/null")) end
local function has_file(p) return require("nixio.fs").access(p) and true or false end
local function write_json(data)
    local h=require "luci.http"
    local ok,jsonc=pcall(require,"luci.jsonc")
    h.prepare_content("application/json")
    if type(h.write_json)=="function" then
        h.write_json(data)
    elseif ok and jsonc and type(jsonc.stringify)=="function" then
        h.write(jsonc.stringify(data or {}))
    else
        h.write("{}")
    end
end
local function listen_line(port) return exec("netstat -lntup | grep ':"..port.." ' | head -n 1") end
local function conn_count(pattern) return tonumber(exec("netstat -tunap | grep "..pattern.." | grep ESTABLISHED | wc -l")) or 0 end
local function detect_mode()
    local tun=exec("uci -q get accelerator.base.tun")
    if tun=="1" then return "TUN" elseif tun=="0" then return "Tproxy" end
    if exec("grep -q -- '--mode tun' /etc/init.d/acc && echo yes || echo no")=="yes" then return "TUN" end
    if has_file("/etc/init.d/acc") then return "Tproxy" end
    return "UNKNOWN"
end
local function tail_log()
    local log=exec("ls -t /tmp/acc/log/acc_Game.log /tmp/acc/acc-gw.log-* 2>/dev/null | head -n 1")
    if log=="" then return "" end
    return exec("tail -n 12 "..log)
end
function action_status()
    local installed=has_file("/usr/sbin/leigod/acc-gw.router.arm64") or has_file("/usr/sbin/leigod/acc-gw.router.aarch64") or exec("ls /usr/sbin/leigod/acc-gw.router.* 2>/dev/null | head -n 1")~=""
    local acc_pid=exec("pidof acc-gw.router.arm64")
    if acc_pid=="" then acc_pid=exec("pidof acc-gw.router.aarch64") end
    if acc_pid=="" then acc_pid=exec("ps | grep 'acc-gw.router' | grep -v grep | awk '{print $1}'") end
    local acc_runner_pid=exec("ps | grep 'acc-gw.router' | grep ' -r acc ' | grep -v grep | awk '{print $1}'")
    local init_exists=has_file("/etc/init.d/acc")
    local service_enabled=false
    if init_exists then service_enabled=exec("/etc/init.d/acc enabled && echo yes || echo no")=="yes" end
    write_json({
        installed=installed,service_enabled=service_enabled,service_running=acc_pid~="",accelerating=acc_runner_pid~="",
        init_exists=init_exists,acc_pid=acc_pid,acc_runner_pid=acc_runner_pid,upgrade_pid=exec("pidof acc_upgrade_monitor"),
        web5588=listen_line("5588")~="",web5588_line=listen_line("5588"),
        port10001=listen_line("10001")~="",port10001_line=listen_line("10001"),
        udp6066=exec("netstat -lunp | grep ':6066 ' | head -n 1")~="",udp6066_line=exec("netstat -lunp | grep ':6066 ' | head -n 1"),
        mode=detect_mode(),acc_conn=conn_count("acc-gw.router"),log_tail=tail_log()
    })
end
function action_uninstall()
    local rc=os.execute("/usr/libexec/nradio-leigod-uninstall >/dev/null 2>&1")
    if rc==0 then
        write_json({ok=true,msg="雷神加速器卸载完成"})
    else
        write_json({ok=false,msg="雷神加速器卸载失败，请使用总脚本查看错误"})
    end
end
EOF_LEIGOD_CONTROLLER
    chmod 644 /usr/lib/lua/luci/controller/nradio_adv/leigod.lua 2>/dev/null || true
}

