maintenance_test_menu() {
    while :; do
        submenu_feature=''
        if is_current_model_ak798; then
            CURRENT_HOME_TEMP_MENU_PATH='5 > 2'
            print_menu_header '主菜单 > 设备维护与检测'
            print_menu_note 'AK68-798'
            print_menu_item 1 '统一体检增强版'
            print_menu_item 2 'LuCI 首页 CPU 温度显示'
            print_menu_item 11 '硬件加速管理'
            print_menu_item 0 '返回上级'
            print_menu_prompt '0-2 / 11'
            read_category_choice
            case "$UI_READ_RESULT" in
                0|12) return 0 ;;
                1) run_menu_feature 13; return 0 ;;
                2) run_menu_feature 27; return 0 ;;
                11) run_menu_feature 33 || return $?; [ "${MENU_ACTION_COMPLETED:-0}" = 1 ] && return 0; continue ;;
                *) die_menu_input_issue "$UI_READ_RESULT" ;;
            esac
        fi
        if is_current_model_c8_788; then
            CURRENT_HOME_TEMP_MENU_PATH='5 > 5'
            print_menu_header '主菜单 > 设备维护与检测'
            print_menu_note 'C8-788'
            print_menu_item 1 '统一体检增强版'
            print_menu_item 2 '风扇控制' 'C8-688 / C8-788 / C2000MAX'
            print_menu_item 3 '哈基米傻瓜分流助手'
            print_menu_item 4 '哈基米依赖检查修复'
            print_menu_item 5 '首页 CPU / 5G 温度切换'
            print_menu_item 11 '硬件加速管理'
            print_menu_item 0 '返回上级'
            print_menu_prompt '0-5 / 11'
            read_category_choice
            case "$UI_READ_RESULT" in
                0|12) return 0 ;;
                1) submenu_feature='13' ;;
                2) submenu_feature='14' ;;
                3) submenu_feature='19' ;;
                4) submenu_feature='23' ;;
                5) submenu_feature='27' ;;
                11) submenu_feature='33' ;;
                *) die_menu_input_issue "$UI_READ_RESULT" ;;
            esac
            if [ "$submenu_feature" = 33 ]; then
                run_menu_feature 33 || return $?
                [ "${MENU_ACTION_COMPLETED:-0}" = 1 ] || continue
            else
                run_menu_feature "$submenu_feature"
            fi
            return 0
        fi

        maintenance_next_choice=1
        print_menu_header '主菜单 > 设备维护与检测'
        maintenance_health_choice=$maintenance_next_choice
        print_menu_item "$maintenance_health_choice" '统一体检增强版'
        maintenance_next_choice=$((maintenance_next_choice + 1))
        maintenance_fan_choice=$maintenance_next_choice
        print_menu_item "$maintenance_fan_choice" '风扇控制' 'C8-688 / C8-788 / C2000MAX'
        maintenance_next_choice=$((maintenance_next_choice + 1))
        maintenance_split_choice=$maintenance_next_choice
        print_menu_item "$maintenance_split_choice" '哈基米傻瓜分流助手'
        maintenance_next_choice=$((maintenance_next_choice + 1))
        maintenance_emmc_choice=$maintenance_next_choice
        print_menu_item "$maintenance_emmc_choice" 'eMMC 存储扩展'
        maintenance_next_choice=$((maintenance_next_choice + 1))

        maintenance_aggregation_choice=''
        if nradio_5g_aggregation_model_supported; then
            maintenance_aggregation_choice=$maintenance_next_choice
            print_menu_item "$maintenance_aggregation_choice" '5G 聚合修复检查'
            maintenance_next_choice=$((maintenance_next_choice + 1))
        fi

        maintenance_dependency_choice=$maintenance_next_choice
        print_menu_item "$maintenance_dependency_choice" '哈基米依赖检查修复'
        maintenance_next_choice=$((maintenance_next_choice + 1))
        maintenance_toolbox_choice=$maintenance_next_choice
        print_menu_item "$maintenance_toolbox_choice" '封版工具箱'
        maintenance_next_choice=$((maintenance_next_choice + 1))
        maintenance_operator_choice=$maintenance_next_choice
        print_menu_item "$maintenance_operator_choice" '运营商与卡名显示修复'
        maintenance_next_choice=$((maintenance_next_choice + 1))
        maintenance_temperature_choice=$maintenance_next_choice
        print_menu_item "$maintenance_temperature_choice" '首页 CPU / 5G 温度切换'
        maintenance_next_choice=$((maintenance_next_choice + 1))

        maintenance_monitoring_choice=''
        if nradio_cpe_monitoring_model_supported; then
            maintenance_monitoring_choice=$maintenance_next_choice
            print_menu_item "$maintenance_monitoring_choice" '5G 连接监听'
            maintenance_next_choice=$((maintenance_next_choice + 1))
        fi

        maintenance_hwaccel_choice=11
        print_menu_item "$maintenance_hwaccel_choice" '硬件加速管理'
        maintenance_return_choice=12
        print_menu_item 0 '返回上级'
        if [ "$maintenance_next_choice" -eq 11 ]; then
            print_menu_prompt '0-11'
        else
            print_menu_prompt "0-$((maintenance_next_choice - 1)) / 11"
        fi
        read_category_choice
        if [ "$UI_READ_RESULT" = '0' ] || [ "$UI_READ_RESULT" = "$maintenance_return_choice" ]; then
            return 0
        elif [ "$UI_READ_RESULT" = "$maintenance_health_choice" ]; then
            submenu_feature='13'
        elif [ "$UI_READ_RESULT" = "$maintenance_fan_choice" ]; then
            submenu_feature='14'
        elif [ "$UI_READ_RESULT" = "$maintenance_split_choice" ]; then
            submenu_feature='19'
        elif [ "$UI_READ_RESULT" = "$maintenance_emmc_choice" ]; then
            submenu_feature='20'
        elif [ -n "$maintenance_aggregation_choice" ] && [ "$UI_READ_RESULT" = "$maintenance_aggregation_choice" ]; then
            submenu_feature='21'
        elif [ "$UI_READ_RESULT" = "$maintenance_dependency_choice" ]; then
            submenu_feature='23'
        elif [ "$UI_READ_RESULT" = "$maintenance_toolbox_choice" ]; then
            submenu_feature='24'
        elif [ "$UI_READ_RESULT" = "$maintenance_operator_choice" ]; then
            submenu_feature='26'
        elif [ "$UI_READ_RESULT" = "$maintenance_temperature_choice" ]; then
            submenu_feature='27'
            CURRENT_HOME_TEMP_MENU_PATH="5 > $maintenance_temperature_choice"
        elif [ -n "$maintenance_monitoring_choice" ] && [ "$UI_READ_RESULT" = "$maintenance_monitoring_choice" ]; then
            submenu_feature='29'
            CURRENT_CPE_MONITORING_MENU_PATH="5 > $maintenance_monitoring_choice"
        elif [ "$UI_READ_RESULT" = "$maintenance_hwaccel_choice" ]; then
            submenu_feature='33'
        else
            die_menu_input_issue "$UI_READ_RESULT"
        fi
        if [ "$submenu_feature" = 33 ]; then
            run_menu_feature 33 || return $?
            [ "${MENU_ACTION_COMPLETED:-0}" = 1 ] || continue
        else
            run_menu_feature "$submenu_feature"
        fi
        return 0
    done
}

main_menu() {
    local menu_choice_prompt
    choice="${1:-}"
    require_root
    acquire_script_lock
    require_startup_disclaimer_acceptance_once
    prime_startup_disclaimer_model || true
    CURRENT_DETECTED_NROS_REVISION="$(detect_nros_revision 2>/dev/null || true)"
    print_main_menu_header

    if [ -n "$choice" ]; then
        MENU_ACTION_COMPLETED='0'
        case "$choice" in 1|2|3|4) require_nradio_menu_environment ;; esac
        if is_current_model_ak798; then
            case "$choice" in
                0|4|5) ;;
                *) die "AK68-798 当前开放分类 4（轻量应用商店）与 5（统一体检）" ;;
            esac
        fi
        if is_current_model_c8_788; then
            case "$choice" in
                0|1|3|4|5) ;;
                *) die "NRadio_C8-788 为小容量 NAND 受限机型；当前功能分类已禁用" ;;
            esac
        fi
        case "$choice" in
            0)
                return 0
                ;;
            1)
                common_plugin_menu
                ;;
            2)
                network_route_menu
                ;;
            3)
                game_accelerator_menu
                ;;
            4)
                appcenter_polish_menu
                ;;
            5)
                maintenance_test_menu
                ;;
            *)
                die_menu_input_issue "$choice"
                ;;
        esac
        return 0
    fi

    while :; do
        print_menu_header '主菜单'
        if is_current_model_ak798; then
            print_menu_item 4 '应用商店与页面'
            print_menu_item 5 '设备维护与检测'
            menu_choice_prompt='0 / 4 / 5'
        elif is_current_model_c8_788; then
            print_menu_item 1 '常用插件' '仅哈基米'
            print_menu_item 3 '游戏加速器'
            print_menu_item 4 '应用商店与页面'
            print_menu_item 5 '设备维护与检测'
            menu_choice_prompt='0 / 1 / 3 / 4 / 5'
        else
            print_menu_item 1 '常用插件'
            print_menu_item 2 'VPN 与组网'
            print_menu_item 3 '游戏加速器'
            print_menu_item 4 '应用商店与页面'
            print_menu_item 5 '设备维护与检测'
            menu_choice_prompt='0-5'
        fi
        print_menu_item 0 '退出'
        print_menu_prompt "$menu_choice_prompt"
        read_category_choice
        MENU_ACTION_COMPLETED='0'

        case "$UI_READ_RESULT" in 1|2|3|4) require_nradio_menu_environment ;; esac
        if is_current_model_ak798; then
            case "$UI_READ_RESULT" in
                0|4|5) ;;
                *) die_menu_input_issue "$UI_READ_RESULT" ;;
            esac
        fi
        if is_current_model_c8_788; then
            case "$UI_READ_RESULT" in
                0|1|3|4|5) ;;
                *) die_menu_input_issue "$UI_READ_RESULT" ;;
            esac
        fi

        case "$UI_READ_RESULT" in
            0)
                return 0
                ;;
            1)
                common_plugin_menu
                ;;
            2)
                network_route_menu
                ;;
            3)
                game_accelerator_menu
                ;;
            4)
                appcenter_polish_menu
                ;;
            5)
                maintenance_test_menu
                ;;
            *)
                die_menu_input_issue "$UI_READ_RESULT"
                ;;
        esac

        [ "${MENU_ACTION_COMPLETED:-0}" = '1' ] && return 0
    done
}

if [ "${1:-}" = '--verify-argon8080-code' ]; then
    require_root
    verify_argon_8080_code
    exit 0
fi

if [ "${1:-}" = '--install-argon8080' ]; then
    require_root
    acquire_script_lock
    require_nradio_menu_environment
    install_argon_8080 --yes
    exit 0
fi

if [ "${1:-}" = '--sync-luci8080' ]; then
    require_root
    acquire_script_lock
    sync_openwrt_luci_8080_plugins
    exit 0
fi

if [ "${1:-}" = '--repair-adguard-autostart' ]; then
    require_root
    acquire_script_lock
    ensure_adguard_autostart || die "AdGuardHome 开机启动修复失败"
    if ! /etc/init.d/AdGuardHome running >/dev/null 2>&1; then
        /etc/init.d/AdGuardHome start || die "AdGuardHome 启动失败"
    fi
    exit 0
fi

if [ "${1:-}" = '--repair-adguard-popup' ]; then
    require_root
    require_nradio_oem_appcenter
    write_adguard_wrapper_files
    patch_common_template
    refresh_luci_appcenter
    verify_luci_route admin/services/AdGuardHome "AdGuardHome"
    verify_luci_route admin/services/AdGuardHome/overview "AdGuardHome"
    verify_luci_route admin/services/AdGuardHome/settings "AdGuardHome"
    verify_luci_route admin/services/AdGuardHome/base "AdGuardHome"
    verify_luci_route admin/services/AdGuardHome/manual "AdGuardHome"
    verify_luci_route admin/services/AdGuardHome/log "AdGuardHome"
    log "AdGuardHome LuCI 与应用商店弹窗修复完成"
    exit 0
fi

main_menu "$@"
